/* =========================================================================
 * MOCK EXAM — 2 sets, structurally separate from QUIZ (no overlap)
 * ========================================================================= */
_mock.push(
  { ja: "模試A（基礎〜標準）", en: "Mock A (Basic–Standard)", questions: [
    { id: "mA1", diff: 1, q: { ja: "限界利益率30%、固定費900万のBEP（Break-Even Point）売上高は。", en: "CM ratio 30%, fixed ¥9M. BEP (Break-Even Point) sales?" },
      choices: [{ ja: "3,000万円", en: "¥30M" }, { ja: "2,700万円", en: "¥27M" }, { ja: "1,200万円", en: "¥12M" }, { ja: "300万円", en: "¥3M" }], ans: 0,
      exp: { ja: "900万÷0.30＝3,000万円。", en: "9M ÷ 0.30 = ¥30M." } },
    { id: "mA2", diff: 2, q: { ja: "全部原価計算で在庫が増加した期、直接原価計算と比べ営業利益は。", en: "When inventory rises, absorption vs. variable costing profit is?" },
      choices: [{ ja: "全部原価計算の方が大きい", en: "Higher under absorption" }, { ja: "直接原価計算の方が大きい", en: "Higher under variable" }, { ja: "同額", en: "Equal" }, { ja: "常にゼロ", en: "Always zero" }], ans: 0,
      exp: { ja: "在庫増で固定費が在庫に繰延べられ、全部原価計算の利益が大きくなる。", en: "Rising inventory defers fixed cost into stock, raising absorption profit." } },
    { id: "mA3", diff: 1, q: { ja: "ABCで配賦基準となるものはどれか。", en: "What is the allocation basis in ABC?" },
      choices: [{ ja: "コストドライバー", en: "Cost driver" }, { ja: "売上総利益", en: "Gross profit" }, { ja: "総資産", en: "Total assets" }, { ja: "株価", en: "Stock price" }], ans: 0,
      exp: { ja: "ABCは活動量を測るコストドライバーで間接費を配賦する。", en: "ABC allocates overhead via activity-measuring cost drivers." } },
    { id: "mA4", diff: 2, q: { ja: "埋没原価の扱いとして正しいのは。", en: "Correct treatment of a sunk cost?" },
      choices: [{ ja: "意思決定で無視する", en: "Ignore it" }, { ja: "必ず回収する", en: "Recover it" }, { ja: "全額費用化する", en: "Expense fully now" }, { ja: "限界利益に加える", en: "Add to CM" }], ans: 0,
      exp: { ja: "埋没原価は変更不能で将来意思決定に無関連。", en: "Sunk costs are unchangeable and irrelevant to future decisions." } },
    { id: "mA5", diff: 2, q: { ja: "CCC（Cash Conversion Cycle）が短いほど示すものは。", en: "A shorter CCC (Cash Conversion Cycle) indicates?" },
      choices: [{ ja: "運転資金効率が良い", en: "Better working-capital efficiency" }, { ja: "負債が多い", en: "More debt" }, { ja: "粗利が低い", en: "Lower margin" }, { ja: "在庫が多い", en: "More inventory" }], ans: 0,
      exp: { ja: "CCCが短い＝現金回収が速く運転資金効率が高い。", en: "Shorter CCC means faster cash recovery and better working-capital efficiency." } },
    {"id":"mA6","diff":2,"q":{"ja":"限界利益率40%、固定費1,200万のとき、営業利益300万を得る売上高は。","en":"CM ratio 40%, fixed ¥12M. Sales for ¥3M operating profit?"},"choices":[{"ja":"3,750万円","en":"¥37.5M"},{"ja":"3,000万円","en":"¥30M"},{"ja":"1,500万円","en":"¥15M"},{"ja":"4,500万円","en":"¥45M"}],"ans":0,"exp":{"ja":"(1,200+300)÷0.40＝3,750万円。","en":"(12M + 3M) ÷ 0.40 = ¥37.5M."}},{"id":"mA7","diff":1,"q":{"ja":"次のうち変動費に分類されるのは。","en":"Which is a variable cost?"},"choices":[{"ja":"出来高に応じた材料費","en":"Output-based material cost"},{"ja":"月額固定の設備リース料","en":"Fixed monthly equipment lease"},{"ja":"本社建物の火災保険料","en":"Fire insurance on the head office"},{"ja":"正社員の月額基本給","en":"Monthly base salary of regular staff"}],"ans":0,"exp":{"ja":"材料費は操業度に比例して動く変動費。賃借料・固定給・定額償却は固定費。","en":"Material cost scales with activity (variable); rent, salaries, and SL depreciation are fixed."}},{"id":"mA8","diff":2,"q":{"ja":"貢献利益方式P/Lで固定製造原価はどう扱われるか。","en":"How is fixed mfg overhead treated in a contribution-margin P/L?"},"choices":[{"ja":"期間費用として一括控除","en":"Deducted as a period cost"},{"ja":"製品原価に算入し在庫へ","en":"Capitalized into inventory"},{"ja":"売上に加算","en":"Added to sales"},{"ja":"無視する","en":"Ignored"}],"ans":0,"exp":{"ja":"直接原価計算では固定製造原価を期間費用として扱い、限界利益の下で一括控除する。","en":"Under direct costing, fixed mfg overhead is a period cost, deducted below contribution margin."}},{"id":"mA9","diff":2,"q":{"ja":"標準原価の価格差異が不利となる典型要因は。","en":"Typical cause of an unfavorable price variance?"},"choices":[{"ja":"購入単価が標準より高かった","en":"Purchase rate above standard"},{"ja":"実際の材料消費量が標準を上回った","en":"Actual material usage exceeded standard"},{"ja":"作業能率が計画より向上した","en":"Work efficiency improved over plan"},{"ja":"生産数量が予算を下回った","en":"Production volume fell short of budget"}],"ans":0,"exp":{"ja":"価格差異は(標準@−実際@)×実際数量。実際単価が標準より高いと不利差異。","en":"Price variance = (std − actual rate) × actual qty; a higher actual rate is unfavorable."}},{"id":"mA10","diff":1,"q":{"ja":"予算編成で『トップダウン』が指すものは。","en":"What does 'top-down' budgeting mean?"},"choices":[{"ja":"経営層が目標を提示し各部門へ展開","en":"Leadership sets targets, cascaded down"},{"ja":"各現場が見積りを積み上げて全社予算を編成","en":"Each site builds estimates up into the company-wide budget"},{"ja":"部門間で予算を相互に調整して決定する","en":"Budgets are set by mutual adjustment across departments"},{"ja":"前年度実績に一定率を乗じて算定する","en":"Computed by applying a fixed rate to last year's actuals"}],"ans":0,"exp":{"ja":"トップダウンは経営層が全社目標を示し各部門へ割り当てる方式。対するボトムアップは現場積上げ。","en":"Top-down: leadership sets company targets allocated to units; bottom-up builds from the floor."}}
  ]},
  { ja: "模試B（標準〜応用）", en: "Mock B (Standard–Advanced)", questions: [
    { id: "mB1", diff: 3, q: { ja: "EVAが正となる条件は。", en: "When is EVA positive?" },
      choices: [{ ja: "ROIC＞WACC", en: "ROIC > WACC" }, { ja: "売上増", en: "Sales grow" }, { ja: "負債減", en: "Debt falls" }, { ja: "黒字", en: "Net income positive" }], ans: 0,
      exp: { ja: "EVA＝投下資本×(ROIC−WACC)。資本コスト超で正。", en: "EVA = capital × (ROIC − WACC); positive only above the cost of capital." } },
    { id: "mB2", diff: 3, q: { ja: "ボトルネック下の製品優先順位の基準は。", en: "Priority criterion under a bottleneck?" },
      choices: [{ ja: "制約資源単位あたり限界利益", en: "CM per unit of the constraint" }, { ja: "製品単位あたり売上", en: "Sales per unit" }, { ja: "固定費配賦額", en: "Fixed cost allocated" }, { ja: "在庫回転率", en: "Inventory turnover" }], ans: 0,
      exp: { ja: "制約1単位あたり限界利益が最大の製品を優先する。", en: "Prioritize the highest CM per unit of the bottleneck." } },
    { id: "mB3", diff: 2, q: { ja: "変動予算の比較対象は。", en: "A flexible budget is compared at?" },
      choices: [{ ja: "実際操業度ベースの予算", en: "Budget at actual activity" }, { ja: "固定金額", en: "A fixed amount" }, { ja: "前年実績", en: "Prior-year actual" }, { ja: "競合の予算", en: "Competitor budget" }], ans: 0,
      exp: { ja: "変動予算は実際操業度に組み替えた予算と実績を比較する。", en: "A flexible budget compares actuals to a budget flexed to actual activity." } },
    { id: "mB4", diff: 3, q: { ja: "3表モデルの循環参照が起きる代表箇所は。", en: "Typical circular reference in a 3-statement model?" },
      choices: [{ ja: "支払利息と負債残高", en: "Interest and debt balance" }, { ja: "売上と数量", en: "Sales and volume" }, { ja: "定額償却", en: "SL depreciation" }, { ja: "税率", en: "Tax rate" }], ans: 0,
      exp: { ja: "利息↔負債↔現金の相互依存で循環参照が生じる。", en: "Interest ↔ debt ↔ cash interdependence creates circularity." } },
    { id: "mB5", diff: 2, q: { ja: "ROE（Return on Equity）のデュポン分解に含まれないのは。", en: "NOT a DuPont component of ROE (Return on Equity)?" },
      choices: [{ ja: "流動比率", en: "Current ratio" }, { ja: "純利益率", en: "Net margin" }, { ja: "総資産回転率", en: "Asset turnover" }, { ja: "財務レバレッジ", en: "Leverage" }], ans: 0,
      exp: { ja: "ROE＝純利益率×総資産回転率×レバレッジ。流動比率は含まない。", en: "ROE = net margin × asset turnover × leverage; current ratio is not part of it." } },
    {"id":"mB6","diff":3,"q":{"ja":"遊休能力がない状態で特別注文を受ける際、必ず考慮すべきは。","en":"With NO idle capacity, what must a special order include?"},"choices":[{"ja":"通常販売を諦める機会費用","en":"Opportunity cost of lost regular sales"},{"ja":"既に支出済みの埋没した過去原価","en":"Already-incurred sunk past costs"},{"ja":"配賦済みの固定製造間接費","en":"Already-allocated fixed manufacturing overhead"},{"ja":"取得原価の減価償却累計額","en":"Accumulated depreciation on acquisition cost"}],"ans":0,"exp":{"ja":"能力に余裕がなければ、特別注文を受けると通常販売を失う。その機会費用を関連原価に加える。","en":"Without spare capacity, taking the order sacrifices regular sales; add that opportunity cost as relevant."}},{"id":"mB7","diff":3,"q":{"ja":"ROICツリーで『投下資本回転率』を高める打ち手は。","en":"Which lever raises capital turnover in the ROIC tree?"},"choices":[{"ja":"運転資本(在庫・売掛)の圧縮","en":"Shrink working capital (inventory, AR)"},{"ja":"設備投資を拡大して固定資産を積み増す","en":"Expand capex to build up fixed assets"},{"ja":"売上原価率を下げて利益率を高める","en":"Cut the cost ratio to lift margin"},{"ja":"有利子負債を返済し金利負担を減らす","en":"Repay debt to cut interest burden"}],"ans":0,"exp":{"ja":"回転率＝売上÷投下資本。運転資本や遊休設備を圧縮すれば分母が下がり回転率が上がる。","en":"Turnover = sales ÷ invested capital; cutting working capital or idle assets lowers the denominator."}},{"id":"mB8","diff":2,"q":{"ja":"原価企画(ターゲットコスティング)で許容原価を求める式は。","en":"Allowable cost formula in target costing?"},"choices":[{"ja":"目標価格 − 目標利益","en":"Target price − target profit"},{"ja":"標準原価と目標利益の合計額","en":"Standard cost plus target profit"},{"ja":"実際原価に一定利益率を乗じる","en":"Actual cost times a fixed margin"},{"ja":"見積原価から予定値引を控除","en":"Estimated cost less planned discounts"}],"ans":0,"exp":{"ja":"許容原価＝目標価格−目標利益。市場が決める価格から逆算し、設計段階で原価を作り込む。","en":"Allowable cost = target price − target profit; back-solved from a market price and built in at design."}},{"id":"mB9","diff":3,"q":{"ja":"ローリング予測が固定年次予算より優れる点は。","en":"An advantage of rolling forecasts over a fixed annual budget?"},"choices":[{"ja":"常に先12〜18カ月の視界を保つ","en":"Always keeps a 12–18 month horizon"},{"ja":"年度末まで当初前提を固定して据え置ける","en":"Lets you fix the original assumptions until year-end"},{"ja":"更新作業が年一回で済み運用負荷が軽い","en":"Only one update a year, keeping the workload light"},{"ja":"年度内の予算消化を促す効果がある","en":"Encourages spending down the budget within the year"}],"ans":0,"exp":{"ja":"ローリング予測は毎期更新し常に先12〜18カ月を見るため、期末に視界が狭まる固定予算の弱点を補う。","en":"Rolling forecasts update each period and keep a 12–18 month view, offsetting the fixed budget's shrinking horizon."}},{"id":"mB10","diff":2,"q":{"ja":"先行指標(leading KPI)の例として適切なのは。","en":"Which is a leading KPI?"},"choices":[{"ja":"商談パイプライン件数","en":"Sales pipeline count"},{"ja":"確定した当期の営業利益","en":"Booked operating profit for the period"},{"ja":"期末に集計した市場シェア","en":"Market share tallied at year-end"},{"ja":"計上済みの当期純利益","en":"Recorded net income"}],"ans":0,"exp":{"ja":"先行指標は結果が出る前に動かせる原因系。商談数は将来売上の先行シグナル。売上・利益・シェアは遅行指標。","en":"Leading KPIs are actionable causes before results land; pipeline leads future sales. Revenue, profit, and share are lagging."}}
  ]},
  {"ja":"模試C（横断・実務）","en":"Mock C (Cross-topic / Applied)","questions":[{"id":"mC1","diff":2,"q":{"ja":"売上6,000万、変動費3,600万、固定費1,800万。営業利益は。","en":"Sales ¥60M, VC ¥36M, fixed ¥18M. Operating profit?"},"choices":[{"ja":"600万円","en":"¥6M"},{"ja":"2,400万円","en":"¥24M"},{"ja":"1,800万円","en":"¥18M"},{"ja":"3,000万円","en":"¥30M"}],"ans":0,"exp":{"ja":"限界利益＝6,000−3,600＝2,400万。営業利益＝2,400−1,800＝600万。","en":"CM = 60−36 = 24M; operating profit = 24 − 18 = ¥6M."}},{"id":"mC2","diff":3,"q":{"ja":"固定費の割合が大きいほど高くなる指標は。","en":"Which rises with a higher fixed-cost proportion?"},"choices":[{"ja":"経営レバレッジ係数(DOL)","en":"Degree of operating leverage"},{"ja":"売上に対する変動費率(変動費÷売上)","en":"Variable cost ratio (variable cost ÷ sales)"},{"ja":"限界利益率(売上に対する限界利益)","en":"Contribution margin ratio (CM ÷ sales)"},{"ja":"自己資本比率(財務の安全性)","en":"Equity ratio (financial safety)"}],"ans":0,"exp":{"ja":"DOL＝限界利益÷営業利益。固定費が大きいほど営業利益が小さくDOLが高い＝利益の感応度大。","en":"DOL = CM ÷ operating profit; more fixed cost shrinks operating profit, raising DOL and profit sensitivity."}},{"id":"mC3","diff":2,"q":{"ja":"製品Aの限界利益率50%、製品Bは30%。固定費一定で利益を最大化するには。","en":"Product A CM 50%, B 30%, fixed constant. To maximize profit?"},"choices":[{"ja":"高限界利益率のAへミックスシフト","en":"Shift mix toward high-CM A"},{"ja":"低限界利益率のBへ販売構成をシフトする","en":"Shift the sales mix toward low-CM B"},{"ja":"両製品を一律に同じ割合で減産する","en":"Cut output of both products by the same rate"},{"ja":"販売価格を引き下げて販売数量を伸ばす","en":"Lower prices to grow unit volume"}],"ans":0,"exp":{"ja":"固定費一定なら、限界利益率の高い製品の構成比を高めるほど全体の限界利益＝利益が増える。","en":"With fixed cost constant, shifting mix to higher-CM products raises total contribution and profit."}},{"id":"mC4","diff":3,"q":{"ja":"労務費の作業時間差異が不利となる主因は。","en":"Main cause of an unfavorable labor efficiency variance?"},"choices":[{"ja":"実際作業時間が標準より長い","en":"Actual hours exceed standard"},{"ja":"実際の賃率が標準賃率を上回った","en":"The actual wage rate exceeded standard"},{"ja":"材料の実際購入単価が上昇した","en":"The actual material purchase price rose"},{"ja":"作業能率が向上し標準時間を下回った","en":"Efficiency improved, coming in under standard hours"}],"ans":0,"exp":{"ja":"作業時間差異＝(標準時間−実際時間)×標準賃率。実際時間が長いと不利。生産性・段取りが要因。","en":"Efficiency variance = (std − actual hours) × std rate; longer actual hours are unfavorable — productivity/setup driven."}},{"id":"mC5","diff":2,"q":{"ja":"ABCが従来配賦より精度を増す典型的状況は。","en":"When does ABC beat traditional allocation most?"},"choices":[{"ja":"間接費が大きく多品種少量生産","en":"High overhead, high-variety low-volume"},{"ja":"間接費が小さく単一製品を大量生産する","en":"Low overhead with single-product mass production"},{"ja":"製造間接費がほとんど生じない事業","en":"A business with almost no manufacturing overhead"},{"ja":"在庫を持たない少品種の受注生産","en":"Low-variety make-to-order with no inventory"}],"ans":0,"exp":{"ja":"間接費が大きく品種が多いほど単一基準配賦の歪みが大きく、ABCの活動基準が効く。","en":"The larger the overhead and product variety, the greater the single-base distortion, so ABC helps most."}},{"id":"mC6","diff":3,"q":{"ja":"NOPAT 600、投下資本5,000、WACC 10%のEVAは。","en":"NOPAT 600, invested capital 5,000, WACC 10%. EVA?"},"choices":[{"ja":"+100","en":"+100"},{"ja":"+600","en":"+600"},{"ja":"−500","en":"−500"},{"ja":"0","en":"0"}],"ans":0,"exp":{"ja":"資本コスト＝5,000×10%＝500。EVA＝600−500＝+100（価値創造）。","en":"Capital charge = 5,000×10% = 500; EVA = 600 − 500 = +100 (value creating)."}},{"id":"mC7","diff":2,"q":{"ja":"予実の数量差異を求める式は。","en":"Formula for the volume (quantity) variance?"},"choices":[{"ja":"(実際数量−予算数量)×予算単価","en":"(actual − budget qty) × budget price"},{"ja":"(実際単価−予算単価)×実際数量","en":"(actual − budget price) × actual qty"},{"ja":"実際売上−予算売上","en":"Actual − budget sales"},{"ja":"売上÷数量","en":"Sales ÷ qty"}],"ans":0,"exp":{"ja":"数量差異＝(実際数量−予算数量)×予算単価。価格差異は(実際単価−予算単価)×実際数量。","en":"Volume variance = (actual − budget qty) × budget price; price variance = (actual − budget price) × actual qty."}},{"id":"mC8","diff":3,"q":{"ja":"制約資源(ボトルネック)が1時間あたり、製品X限界利益1,200円/時、製品Y 900円/時。優先すべきは。","en":"Per bottleneck hour: X earns ¥1,200 CM/hr, Y ¥900/hr. Prioritize?"},"choices":[{"ja":"製品X","en":"Product X"},{"ja":"製品Y","en":"Product Y"},{"ja":"どちらでも同じ","en":"Indifferent"},{"ja":"両方停止","en":"Stop both"}],"ans":0,"exp":{"ja":"制約1単位(時間)あたり限界利益が高いXを優先するとボトルネックの利益貢献が最大化する。","en":"Prioritize X with the higher CM per unit of the constraint to maximize the bottleneck's profit contribution."}},{"id":"mC9","diff":2,"q":{"ja":"ゼロベース予算(ZBB)の特徴は。","en":"A feature of zero-based budgeting (ZBB)?"},"choices":[{"ja":"全費用をゼロから正当化","en":"Justify every cost from zero"},{"ja":"前年予算に一定率を上乗せする","en":"Add a fixed percentage to last year's budget"},{"ja":"売上高だけを管理対象とする","en":"Manage only sales figures"},{"ja":"過去の実績を前提に据え置く","en":"Carry prior actuals forward as the baseline"}],"ans":0,"exp":{"ja":"ZBBは前年を前提とせず、各費用をゼロから必要性を正当化して積み上げる。費用見直しに有効だが負荷大。","en":"ZBB justifies each cost from zero rather than basing it on last year — effective for cost review but labor-intensive."}},{"id":"mC10","diff":3,"q":{"ja":"ROICがWACCを下回り続ける事業についての評価は。","en":"A business with ROIC persistently below WACC is?"},"choices":[{"ja":"価値を破壊している(再構築/撤退の検討)","en":"Destroying value (consider restructure/exit)"},{"ja":"黒字を確保している限り資本効率に問題はない","en":"As long as it is profitable, capital efficiency is fine"},{"ja":"成長投資を続ければ自然に採算が改善する","en":"Continued growth investment will improve returns on its own"},{"ja":"資本コストを上回り価値を創造している状態","en":"A state of earning above cost of capital and creating value"}],"ans":0,"exp":{"ja":"ROIC<WACCは資本コストを賄えず価値破壊。成長は損失を拡大しうる。再構築・資本再配分・撤退を検討する。","en":"ROIC < WACC fails to cover the cost of capital — value destruction; growth can worsen it. Consider restructuring, reallocation, or exit."}}]},
);

/* =========================================================================
/* =========================================================================
 * CALC PRACTICE
 * ========================================================================= */
_calc.push(
  { id: "c1", dom: "cvp", diff: 2,
    q: { ja: "売上6,000万、変動費3,600万、固定費1,800万。①限界利益率 ②BEP（Break-Even Point）売上高 ③安全余裕率を求めよ。", en: "Sales ¥60M, VC ¥36M, fixed ¥18M. Find (1) CM ratio, (2) BEP (Break-Even Point) sales, (3) margin of safety." },
    sol: { ja: "①限界利益＝6,000−3,600＝2,400万。限界利益率＝2,400/6,000＝40%\n②BEP＝1,800÷0.40＝4,500万円\n③安全余裕率＝(6,000−4,500)/6,000＝25%", en: "(1) CM = 60−36 = 24M; ratio = 24/60 = 40%\n(2) BEP = 18 ÷ 0.40 = ¥45M\n(3) MoS = (60−45)/60 = 25%" } },
  { id: "c2", dom: "cvp", diff: 3,
    q: { ja: "製品X(限界利益率50%)と製品Y(限界利益率30%)を売上比3:2で販売。固定費2,100万のときBEP（Break-Even Point）売上高は。", en: "Product X (CM 50%) and Y (CM 30%) sold 3:2 by sales. Fixed ¥21M. Find BEP (Break-Even Point) sales." },
    sol: { ja: "加重平均限界利益率＝0.5×(3/5)＋0.3×(2/5)＝0.30＋0.12＝0.42（42%）\nBEP＝2,100÷0.42＝5,000万円", en: "Weighted CM ratio = 0.5×0.6 + 0.3×0.4 = 0.42 (42%)\nBEP = 21 ÷ 0.42 = ¥50M" } },
  { id: "c3", dom: "cost", diff: 2,
    q: { ja: "標準直接材料費：標準単価200円/kg、標準2kg/個。実際：単価210円、消費2.1kg/個、生産1,000個。価格差異と数量差異を求めよ。", en: "Std material: ¥200/kg, 2kg/unit. Actual: ¥210/kg, 2.1kg/unit, 1,000 units. Find price and quantity variances." },
    sol: { ja: "実際消費量＝2.1×1,000＝2,100kg\n価格差異＝(200−210)×2,100＝−21,000円（不利）\n数量差異＝(2,000−2,100)×200＝−20,000円（不利）", en: "Actual qty = 2.1×1,000 = 2,100kg\nPrice variance = (200−210)×2,100 = −¥21,000 (unfavorable)\nQuantity variance = (2,000−2,100)×200 = −¥20,000 (unfavorable)" } },
  { id: "c4", dom: "kpi", diff: 3,
    q: { ja: "純利益率5%、総資産回転率1.5回、財務レバレッジ2.0倍のときROE（Return on Equity）を求めよ。", en: "Net margin 5%, asset turnover 1.5×, leverage 2.0×. Find ROE (Return on Equity)." },
    sol: { ja: "ROE＝5%×1.5×2.0＝15%", en: "ROE = 5% × 1.5 × 2.0 = 15%" } },
  { id: "c5", dom: "kpi", diff: 2,
    q: { ja: "DIO（Days Inventory Outstanding）=50日、DSO（Days Sales Outstanding）=40日、DPO（Days Payable Outstanding）=30日。CCC（Cash Conversion Cycle）を求めよ。", en: "DIO (Days Inventory Outstanding) 50, DSO (Days Sales Outstanding) 40, DPO (Days Payable Outstanding) 30. Find CCC (Cash Conversion Cycle)." },
    sol: { ja: "CCC＝50＋40−30＝60日", en: "CCC = 50 + 40 − 30 = 60 days" } },
  { id: "c6", dom: "decision", diff: 2,
    q: { ja: "遊休能力あり。特別注文1,000個、提示価格700円。単位変動費500円、単位固定費150円。受注すべきか。", en: "Idle capacity. Special order 1,000 units at ¥700. Unit VC ¥500, unit fixed ¥150. Accept?" },
    sol: { ja: "固定費は埋没。単位限界利益＝700−500＝200円。増分利益＝200×1,000＝20万円。受注すべき。", en: "Fixed cost is sunk. Unit CM = 700−500 = ¥200; incremental profit = ¥200×1,000 = ¥200,000. Accept." } },
  {"id":"c7","dom":"cvp","diff":2,"q":{"ja":"【目標利益達成の必要売上】固定費1,800万、限界利益率40%、目標営業利益600万。必要売上高を求めよ。","en":"[Sales for target profit] Fixed cost 18M, CM ratio 40%, target operating profit 6M. Find required sales."},"sol":{"ja":"1. 必要限界利益＝固定費＋目標利益: 1,800 + 600 = 2,400万\n2. 必要売上＝必要限界利益÷限界利益率: 2,400 ÷ 0.40 = 6,000万\n\n答え: 必要売上高 = 6,000万","en":"1. Required CM = fixed + target: 18M + 6M = 24M\n2. Sales = CM ÷ CM ratio: 24M ÷ 0.40 = 60M\n\nAnswer: Required sales = 60M"}},{"id":"c8","dom":"cvp","diff":3,"q":{"ja":"【安全余裕率と経営レバレッジ】売上6,000万、BEP売上4,500万、限界利益2,400万、営業利益600万。安全余裕率と経営レバレッジ係数(DOL)を求めよ。","en":"[Margin of safety & DOL] Sales 60M, BEP sales 45M, contribution 24M, operating profit 6M. Find margin of safety and the degree of operating leverage."},"sol":{"ja":"1. 安全余裕率＝(売上−BEP)÷売上: (6,000−4,500)÷6,000 = 25%\n2. DOL＝限界利益÷営業利益: 2,400 ÷ 600 = 4.0倍\n\n含意: 売上が1%増えると営業利益は約4%増える（固定費が大きいほどDOLは高い）。\n\n答え: 安全余裕率25%・DOL=4.0倍","en":"1. Margin of safety = (Sales − BEP)/Sales: (60−45)/60 = 25%\n2. DOL = contribution ÷ operating profit: 24 ÷ 6 = 4.0×\n\nMeaning: a 1% sales rise lifts operating profit ≈4% (higher fixed cost → higher DOL).\n\nAnswer: MoS 25%, DOL 4.0×"}},{"id":"c9","dom":"cost","diff":3,"q":{"ja":"【材料費差異の分解】標準: @200円×2kg/個。実際: @210円×2.1kg/個、生産1,000個。価格差異と数量差異に分解せよ。","en":"[Materials variance split] Standard @200×2kg/unit. Actual @210×2.1kg/unit, 1,000 units. Split into price and quantity variances."},"sol":{"ja":"実際数量＝2.1×1,000＝2,100kg、標準数量＝2×1,000＝2,000kg\n1. 価格差異＝(標準@−実際@)×実際数量: (200−210)×2,100 = −21,000円(不利)\n2. 数量差異＝(標準数量−実際数量)×標準@: (2,000−2,100)×200 = −20,000円(不利)\n3. 総差異: −41,000円(不利)\n\n答え: 価格差異−21,000・数量差異−20,000（ともに不利）","en":"Actual qty = 2.1×1,000 = 2,100kg; standard qty = 2,000kg\n1. Price variance = (std − actual rate)×actual qty: (200−210)×2,100 = −21,000 (unfav)\n2. Quantity variance = (std − actual qty)×std rate: (2,000−2,100)×200 = −20,000 (unfav)\n3. Total: −41,000 (unfav)\n\nAnswer: Price −21,000, Quantity −20,000 (both unfavorable)"}},{"id":"c10","dom":"abc","diff":3,"q":{"ja":"【ABCの配賦】段取活動費が総額120万、年間段取回数が合計300回。製品Aは段取40回。製品Aへ配賦される段取コストを求めよ。","en":"[ABC allocation] Setup activity cost 1.2M total, 300 setups/year total. Product A uses 40 setups. Find the setup cost allocated to A."},"sol":{"ja":"1. 段取1回あたりレート: 1,200,000 ÷ 300回 = 4,000円/回\n2. 製品Aへの配賦: 4,000 × 40回 = 160,000円\n\n含意: 従来の操業度配賦なら少量品Aは過小評価されがち。ABCは段取という活動量で跡づけ、真の負担を見せる。\n\n答え: 製品Aの段取コスト = 16万円","en":"1. Rate per setup: 1,200,000 ÷ 300 = 4,000/setup\n2. Allocated to A: 4,000 × 40 = 160,000\n\nMeaning: volume-based costing would undercost low-volume A; ABC traces it by setups, revealing the true burden.\n\nAnswer: A's setup cost = 160,000"}},{"id":"c11","dom":"decision","diff":3,"q":{"ja":"【内外製(make or buy)】部品を自製すると変動費800円/個、自製専用設備の回避可能固定費が年20万。外注は950円/個。年間需要2,000個。自製と外注どちらが有利か。","en":"[Make or buy] Make: variable 800/unit + avoidable fixed 200k/yr. Buy: 950/unit. Annual demand 2,000. Which is better?"},"sol":{"ja":"自製総額: 800×2,000 + 200,000 = 1,600,000 + 200,000 = 1,800,000円\n外注総額: 950×2,000 = 1,900,000円\n差額: 外注−自製 = 100,000円 → 自製が有利\n\n注意: 回避不能な固定費(埋没)は両案共通なので除外。設備を他用途に使える場合はその機会費用も加味する。\n\n答え: 自製が年10万円有利","en":"Make: 800×2,000 + 200,000 = 1,800,000\nBuy: 950×2,000 = 1,900,000\nDifference: 100,000 in favor of make.\n\nNote: unavoidable (sunk) fixed costs are common to both and excluded; if the equipment has an alternative use, add its opportunity cost.\n\nAnswer: Make is better by 100,000/yr"}},{"id":"c12","dom":"decision","diff":3,"q":{"ja":"【追加加工の判断】中間品の現状売価1,200円。追加加工で売価1,700円になるが、追加変動費が400円/個かかる。追加加工すべきか。","en":"[Process further] Intermediate sells at 1,200. Further processing yields 1,700 but adds 400/unit variable cost. Process further?"},"sol":{"ja":"増分収益: 1,700 − 1,200 = 500円/個\n増分費用: 400円/個\n増分利益: 500 − 400 = +100円/個 → 追加加工が有利\n\n注意: 中間品までに既にかけた原価(結合原価)は埋没で判断に無関係。判断は『追加』の収益と費用だけ。\n\n答え: 追加加工すべき(+100円/個)","en":"Incremental revenue: 1,700 − 1,200 = 500/unit\nIncremental cost: 400/unit\nIncremental profit: +100/unit → process further.\n\nNote: costs already incurred to the intermediate (joint cost) are sunk and irrelevant; decide on incremental revenue and cost only.\n\nAnswer: Process further (+100/unit)"}},{"id":"c13","dom":"kpi","diff":3,"q":{"ja":"【EVA(経済的付加価値)】NOPAT 500、投下資本4,000、WACC 8%。EVAを求め、価値創造の有無を判定せよ。","en":"[EVA] NOPAT 500, invested capital 4,000, WACC 8%. Compute EVA and judge value creation."},"sol":{"ja":"1. 資本コスト額: 4,000 × 8% = 320\n2. EVA = NOPAT − 資本コスト額: 500 − 320 = +180\n参考: ROIC = 500÷4,000 = 12.5% > WACC 8% → スプレッド+4.5%\n\n含意: EVAが正＝資本コストを上回って稼いでおり価値創造。負ならROIC<WACCで価値破壊。\n\n答え: EVA = +180(価値創造)","en":"1. Capital charge: 4,000 × 8% = 320\n2. EVA = NOPAT − charge: 500 − 320 = +180\nCheck: ROIC = 500/4,000 = 12.5% > WACC 8% → spread +4.5%\n\nMeaning: positive EVA means earning above the cost of capital — value creation; negative means ROIC<WACC, value destruction.\n\nAnswer: EVA = +180 (value creating)"}},{"id":"c14","dom":"fpa","diff":2,"q":{"ja":"【予実差異の要因分解】売上予算が@500×1,000個＝50万。実績は@480×1,100個＝52.8万。売上差異を価格差異と数量差異に分解せよ。","en":"[Sales variance bridge] Budget @500×1,000 = 500k. Actual @480×1,100 = 528k. Split the sales variance into price and volume."},"sol":{"ja":"総差異: 528,000 − 500,000 = +28,000(有利)\n1. 数量差異＝(実際数量−予算数量)×予算単価: (1,100−1,000)×500 = +50,000(有利)\n2. 価格差異＝(実際単価−予算単価)×実際数量: (480−500)×1,100 = −22,000(不利)\n検算: +50,000 − 22,000 = +28,000 ✓\n\n含意: 数量は伸びたが値引きで単価が落ちた、と要因が言語化できる。FP&Aの予実説明の型。\n\n答え: 数量差異+50,000・価格差異−22,000（純+28,000）","en":"Total: 528,000 − 500,000 = +28,000 (fav)\n1. Volume variance = (actual − budget qty)×budget price: (1,100−1,000)×500 = +50,000 (fav)\n2. Price variance = (actual − budget price)×actual qty: (480−500)×1,100 = −22,000 (unfav)\nCheck: +50,000 − 22,000 = +28,000 ✓\n\nMeaning: volume grew but discounting cut price — the FP&A variance-explanation template.\n\nAnswer: Volume +50,000, Price −22,000 (net +28,000)"}}
,
  {"id":"c15","dom":"cvp","diff":2,"q":{"ja":"【BEP販売数量】単価1,000円、単位変動費600円、固定費80万円。損益分岐点の販売数量を求めよ。","en":"[BEP in units] Price ¥1,000, unit VC ¥600, fixed ¥800k. Find break-even units."},"sol":{"ja":"1. 単位限界利益: 1,000 − 600 = 400円\n2. BEP数量＝固定費÷単位限界利益: 800,000 ÷ 400 = 2,000個\n\n答え: 2,000個","en":"1. Unit CM: 1,000 − 600 = ¥400\n2. BEP units = fixed ÷ unit CM: 800,000 ÷ 400 = 2,000\n\nAnswer: 2,000 units"}},{"id":"c16","dom":"cost","diff":3,"q":{"ja":"【労務費差異の分解】標準: @1,500円×3時間/個。実際: @1,560円×3.2時間/個、生産500個。賃率差異と作業時間差異を求めよ。","en":"[Labor variance split] Standard @1,500×3h/unit. Actual @1,560×3.2h/unit, 500 units. Find rate and efficiency variances."},"sol":{"ja":"実際時間＝3.2×500＝1,600時間、標準時間＝3×500＝1,500時間\n1. 賃率差異＝(標準@−実際@)×実際時間: (1,500−1,560)×1,600 = −96,000円(不利)\n2. 作業時間差異＝(標準時間−実際時間)×標準@: (1,500−1,600)×1,500 = −150,000円(不利)\n3. 総差異: −246,000円(不利)\n\n答え: 賃率差異−96,000・作業時間差異−150,000（ともに不利）","en":"Actual hours = 3.2×500 = 1,600; standard = 1,500\n1. Rate variance = (std − actual rate)×actual hrs: (1,500−1,560)×1,600 = −96,000 (unfav)\n2. Efficiency variance = (std − actual hrs)×std rate: (1,500−1,600)×1,500 = −150,000 (unfav)\n3. Total: −246,000 (unfav)\n\nAnswer: Rate −96,000, Efficiency −150,000 (both unfavorable)"}},{"id":"c17","dom":"kpi","diff":3,"q":{"ja":"【ROICの分解】NOPAT 480、売上6,000、投下資本4,000。NOPATマージンと投下資本回転率に分解し、ROICを求めよ。","en":"[ROIC decomposition] NOPAT 480, sales 6,000, invested capital 4,000. Split into margin and turnover; find ROIC."},"sol":{"ja":"1. NOPATマージン＝NOPAT÷売上: 480 ÷ 6,000 = 8%\n2. 投下資本回転率＝売上÷投下資本: 6,000 ÷ 4,000 = 1.5回\n3. ROIC＝マージン×回転率: 8% × 1.5 = 12%（検算: 480÷4,000=12% ✓）\n\n答え: マージン8%・回転1.5回・ROIC=12%","en":"1. NOPAT margin = NOPAT ÷ sales: 480 ÷ 6,000 = 8%\n2. Capital turnover = sales ÷ invested capital: 6,000 ÷ 4,000 = 1.5×\n3. ROIC = margin × turnover: 8% × 1.5 = 12% (check: 480 ÷ 4,000 = 12% ✓)\n\nAnswer: Margin 8%, turnover 1.5×, ROIC 12%"}},{"id":"c18","dom":"decision","diff":3,"q":{"ja":"【受注可否（遊休能力あり）】特別注文2,000個、提示単価680円。単位変動費500円、配賦済み単位固定費160円。受注の可否と増分利益を求めよ。","en":"[Accept order, idle capacity] Special order 2,000 units at ¥680. Unit VC ¥500, allocated unit fixed ¥160. Accept? Find incremental profit."},"sol":{"ja":"1. 固定費は埋没（遊休能力ありで追加発生なし）→無視\n2. 単位限界利益: 680 − 500 = 180円\n3. 増分利益: 180 × 2,000 = 360,000円 > 0 → 受注すべき\n\n答え: 受注すべき。増分利益＝36万円","en":"1. Fixed cost is sunk (idle capacity, no extra) → ignore\n2. Unit CM: 680 − 500 = ¥180\n3. Incremental profit: 180 × 2,000 = ¥360,000 > 0 → accept\n\nAnswer: Accept; incremental profit ¥360,000"}},{"id":"c19","dom":"budget","diff":2,"q":{"ja":"【変動予算】予算は固定費500＋変動費@30/個。実際操業度1,200個での変動予算許容額を求めよ。","en":"[Flexible budget] Budget = fixed 500 + variable @30/unit. Find the flexible-budget allowance at actual 1,200 units."},"sol":{"ja":"1. 変動費分: 30 × 1,200 = 36,000\n2. 変動予算許容額＝固定費＋変動費: 500の単位に注意し、固定500(千円等の単位前提)＋36,000…\n→ 数値例として固定費500＋(30×1,200)=500＋36,000=36,500\n\n答え: 変動予算許容額 = 36,500（固定500＋変動36,000）。これと実際を比較して予算差異を測る。","en":"1. Variable portion: 30 × 1,200 = 36,000\n2. Flexible-budget allowance = fixed + variable = 500 + 36,000 = 36,500\n\nAnswer: Allowance = 36,500 (fixed 500 + variable 36,000); compare to actual to measure the budget variance."}},{"id":"c20","dom":"fpa","diff":3,"q":{"ja":"【ローリング予測の着地】上期実績が計画比+5%（計画3,000→実績3,150）。下期は計画3,400を据置く。通期着地見通しと対計画差を求めよ。","en":"[Rolling forecast landing] H1 actual +5% vs plan (plan 3,000 → actual 3,150). H2 plan 3,400 held. Find full-year landing and variance vs plan."},"sol":{"ja":"1. 通期計画: 3,000 + 3,400 = 6,400\n2. 着地見通し: 実績3,150 + 下期3,400 = 6,550\n3. 対計画差: 6,550 − 6,400 = +150（+2.3%）\n\n含意: 上期の上振れがそのまま通期着地を押し上げる。下期前提の見直し余地も検討する。\n\n答え: 着地6,550・対計画+150","en":"1. Full-year plan: 3,000 + 3,400 = 6,400\n2. Landing: actual 3,150 + H2 3,400 = 6,550\n3. Variance vs plan: 6,550 − 6,400 = +150 (+2.3%)\n\nMeaning: the H1 beat carries into the landing; also reconsider H2 assumptions.\n\nAnswer: Landing 6,550, +150 vs plan"}}
);

