        sol: { ja: "完済年数＝債務÷年間弁済額\n＝6億÷8,000万\n＝7.5年\n答え: 約7.5年", en: "Years = debt ÷ annual repayment\n= 600M ÷ 80M\n= 7.5 years\nAnswer: ~7.5 years" },
