      {
        id: "s13c16", dom: "plan", diff: 3,
        q: { ja: "5年計画：営業利益を初年度△5,000万円から毎年3,000万円ずつ改善。黒字化する年度は。", en: "5-yr plan: operating profit starts −¥50M, improving ¥30M/yr. Which year turns profitable?" },
        sol: { ja: "1年目△5,000万\n2年目△5,000+3,000＝△2,000万\n3年目△2,000+3,000＝+1,000万\n答え: 3年目に黒字化（+1,000万円）", en: "Y1 −50M\nY2 −50M+30M = −20M\nY3 −20M+30M = +10M\nAnswer: profitable in Year 3 (+¥10M)" },
      },
      {
        id: "s13c17", dom: "stake", diff: 2,
        q: { ja: "債権額：A行3億・B行2億・C行1億（計6億）。プロラタ（比例）で総額1億8,000万円を弁済。各行の弁済額は。", en: "Claims: Bank A ¥300M, B ¥200M, C ¥100M (¥600M total). Pro-rata repayment of ¥180M. Each bank's amount?" },
        sol: { ja: "弁済率＝1億8,000万/6億＝30%\nA＝3億×30%＝9,000万円\nB＝2億×30%＝6,000万円\nC＝1億×30%＝3,000万円\n答え: A9,000万・B6,000万・C3,000万円", en: "Rate = 180M/600M = 30%\nA = 300M×30% = ¥90M\nB = 200M×30% = ¥60M\nC = 100M×30% = ¥30M\nAnswer: A ¥90M, B ¥60M, C ¥30M" },
      },
      {
        id: "s13c18", dom: "cause", diff: 3,
        q: { ja: "撤退判断：ある事業は売上2億・変動費1億6,000万・個別固定費6,000万・共通費配賦2,000万。限界利益と、撤退で改善する損益（回避可能費用ベース）は。", en: "Exit test: a unit has sales ¥200M, variable ¥160M, direct fixed ¥60M, allocated overhead ¥20M. Contribution margin, and P&L effect of exit (avoidable-cost basis)?" },
        sol: { ja: "限界利益＝2億−1億6,000万＝4,000万円\n個別固定費6,000万は回避可能\n撤退で失う限界利益4,000万、回避できる固定費6,000万\n純効果＝−4,000万＋6,000万＝+2,000万円改善\n（共通費配賦2,000万は撤退しても残るため無関連）\n答え: 限界利益4,000万円。撤退で損益は2,000万円改善（個別固定費が限界利益を上回るため撤退が合理的）", en: "CM = 200M − 160M = ¥40M\nDirect fixed ¥60M is avoidable\nExit loses CM ¥40M, avoids fixed ¥60M\nNet = −40M + 60M = +¥20M improvement\n(Allocated overhead ¥20M remains—irrelevant)\nAnswer: CM ¥40M; exit improves P&L by ¥20M (direct fixed exceeds CM, so exit is rational)" },
      },
      {
        id: "s13c19", dom: "operational", diff: 2,
        q: { ja: "人員100名・平均人件費600万円。20%削減し、削減の6割が翌年から通年で効く場合、翌年の人件費削減額は。", en: "100 staff at ¥6M avg; cut 20%; 60% of the cut takes full-year effect next year. Next-year saving?" },
        sol: { ja: "削減人数＝100×20%＝20名\n満年ベース削減＝20×600万＝1億2,000万円\n翌年通年効果＝1億2,000万×60%＝7,200万円\n答え: 翌年の人件費削減額 7,200万円", en: "Cut = 100×20% = 20 staff\nFull-year saving = 20×6M = ¥120M\nNext-year effect = 120M×60% = ¥72M\nAnswer: ¥72M next-year saving" },
      },
      {
        id: "s13c20", dom: "financial", diff: 3,
        q: { ja: "継続価値(事業のDCF)3億5,000万円 vs 清算価値2億円。債務総額5億円。再生と清算のどちらが債権者の回収を最大化するか、回収率で比較せよ。", en: "Going-concern (DCF) value ¥350M vs liquidation value ¥200M; total debt ¥500M. Which maximizes creditor recovery—compare recovery rates." },
        sol: { ja: "再生(継続価値)回収率＝3.5億/5億＝70%\n清算回収率＝2億/5億＝40%\n70%＞40%\n答え: 再生の方が回収率70%>清算40%。事業継続(再生)が債権者の回収を最大化する", en: "Restructuring recovery = 350M/500M = 70%\nLiquidation recovery = 200M/500M = 40%\n70% > 40%\nAnswer: restructuring (70%) beats liquidation (40%)—going concern maximizes creditor recovery" },
      }
