  _calc.push(
    {
      id: "s17c01",
      dom: "deal",
      diff: 3,
      q: { ja: "エクイティブリッジ。合意EV（Enterprise Value） 800。純有利子負債250、デットライク(未払退職金等)30、余剰現金40、NWC（Net Working Capital）不足によるマイナス調整20。株式対価は？", en: "Equity bridge. Agreed EV (Enterprise Value) 800. Net debt 250, debt-like items 30, surplus cash 40, negative NWC (Net Working Capital) adjustment 20. Equity consideration?" },
      sol: { ja: "株式対価=EV−純負債−デットライク＋余剰現金−NWC調整\\n=800−250−30＋40−20=540。\\n各調整の定義（何を負債/現金扱いにするか）が交渉の争点。", en: "Equity = EV − net debt − debt-like + surplus cash − NWC adj\\n=800−250−30+40−20=540.\\nDefining each adjustment is the negotiation battleground." },
    },
    {
      id: "s17c02",
      dom: "deal",
      diff: 3,
      q: { ja: "value creation bridge。取得EBITDA（Earnings Before Interest, Taxes, Depreciation and Amortization） 60・取得倍率8x（EV480・エクイティ180・純負債300）。Exit EBITDA 90・倍率9x、純負債150。EBITDA成長/倍率/デレバレッジの寄与とMOIC（Multiple on Invested Capital）は？", en: "Value creation bridge. Entry EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 60 at 8x (EV480, equity180, net debt300). Exit EBITDA 90 at 9x, net debt150. Contributions and MOIC (Multiple on Invested Capital)?" },
      sol: { ja: "Exit EV=90×9=810、エクイティ=810−150=660。\\n①EBITDA成長=(90−60)×8=+240\\n②倍率=90×(9−8)=+90\\n③デレバレッジ=300−150=+150\\n合計+480(180→660)。MOIC=660/180≈3.67x。", en: "Exit EV=810, equity=660.\\n(1) EBITDA growth=(90−60)×8=+240\\n(2) Multiple=90×1=+90\\n(3) Deleveraging=+150\\nTotal +480 (180→660). MOIC≈3.67x." },
    },
    {
      id: "s17c03",
      dom: "capalloc",
      diff: 3,
      q: { ja: "資本配分の限界比較。余剰資本100。用途別の限界リターン: 成長投資14%、アドオンM&A 11%、自社株買い(株価が本源価値比15%割安)、負債返済(税引後金利4%)。WACC10%。価値を生む順は？", en: "Marginal allocation. Surplus 100. Marginal returns: growth 14%, add-on M&A 11%, buyback (share 15% below intrinsic), debt paydown (after-tax 4%). WACC (Weighted Average Cost of Capital) 10%. Value-creating ranking?" },
      sol: { ja: "WACC10%超が価値創出。\\n成長14%>アドオン11%>WACC10%は価値創出。\\n自社株買いは割安15%分の1株価値上昇＝実質的に高リターン。\\n負債返済4%<WACCは価値中立〜低（財務健全性目的）。\\n順:割安な自社株買い/成長投資→アドオン→(返済は規律・耐性目的)。", en: "Uses above 10% WACC create value.\\nGrowth 14% > add-on 11% > 10%; both create value.\\nBuyback at 15% discount adds per-share value (effectively high return).\\nDebt paydown 4% < WACC is value-neutral (for resilience).\\nRank: undervalued buyback/growth → add-on → (paydown for discipline)." },
    },
    {
      id: "s17c04",
      dom: "growth",
      diff: 3,
      q: { ja: "DCF（Discounted Cash Flow）簡易。FCF（Free Cash Flow）が毎年40で永久成長2%、WACC10%。企業価値(EV)は？さらに純負債120・株数10万株なら1株価値は？", en: "Simple DCF (Discounted Cash Flow). FCF (Free Cash Flow) 40 growing 2% forever, WACC (Weighted Average Cost of Capital) 10%. EV (Enterprise Value)? With net debt 120 and 100k shares, value per share?" },
      sol: { ja: "EV=FCF×(1+g)/(WACC−g)=40×1.02/(0.10−0.02)=40.8/0.08=510。\\nエクイティ=510−120=390。\\n1株価値=390/10万株=0.0039(百万)=3,900円相当。", en: "EV=40×1.02/(0.10−0.02)=510.\\nEquity=510−120=390.\\nPer share=390/100k=0.0039 (in millions) ≈ 3,900 per share." },
    },
    {
      id: "s17c05",
      dom: "growth",
      diff: 3,
      q: { ja: "ROIC（Return on Invested Capital）-WACC（Weighted Average Cost of Capital）スプレッドと成長価値。ROIC15%、WACC10%、再投資率(成長への投下)60%。持続成長率と、成長が価値を生むかの判定は？", en: "ROIC (Return on Invested Capital)-WACC (Weighted Average Cost of Capital) spread and growth value. ROIC 15%, WACC 10%, reinvestment rate 60%. Sustainable growth and does growth create value?" },
      sol: { ja: "持続成長率=ROIC×再投資率=15%×60%=9%。\\nスプレッド=ROIC−WACC=+5%>0。\\nスプレッドが正なので、再投資による成長は価値を創出する（成長するほど価値増）。", en: "g=ROIC×reinvestment=15%×60%=9%.\\nSpread=ROIC−WACC=+5%>0.\\nPositive spread means reinvested growth creates value." },
    },
    {
      id: "s17c06",
      dom: "risk",
      diff: 3,
      q: { ja: "金利上昇の連鎖。純負債500(全額変動金利)、EBITDA150。金利が3%→6%へ上昇。支払利息の増加額、ICR（Interest Coverage Ratio）の変化(利息以外一定)、コベナンツ下限3.0xとの関係は？", en: "Rate-rise cascade. Net debt 500 (all floating), EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 150. Rate 3%→6%. Extra interest, ICR (Interest Coverage Ratio) change (else constant), and vs 3.0x floor?" },
      sol: { ja: "利息: 500×3%=15 → 500×6%=30(+15)。\\nICR: 150/15=10.0x → 150/30=5.0x。\\nいずれも下限3.0x超で抵触せず。ただしFCFは利息増15だけ悪化し返済余力が低下。ヘッジ検討。", en: "Interest: 15 → 30 (+15).\\nICR: 10.0x → 5.0x.\\nBoth clear the 3.0x floor; but FCF worsens by 15, cutting paydown capacity. Consider hedging." },
    },
    {
      id: "s17c07",
      dom: "risk",
      diff: 3,
      q: { ja: "ストレステスト。基準EBITDA200。景気後退で売上−20%・変動費率一定・固定費120は不変。ストレス下のEBITDA（Earnings Before Interest, Taxes, Depreciation and Amortization）は(基準は売上500・変動費180・固定費120)？", en: "Stress test. Base EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 200. Recession cuts revenue 20%, variable-cost ratio constant, fixed cost 120 unchanged. Stressed EBITDA (base: revenue 500, variable 180, fixed 120)?" },
      sol: { ja: "変動費率=180/500=36%。\\nストレス売上=500×0.8=400。\\n変動費=400×36%=144。\\nEBITDA=400−144−120=136(基準200から−64)。\\n固定費の重さで利益が大きく振れる（オペレーティングレバレッジ）。", en: "Variable ratio=180/500=36%.\\nStressed revenue=400. Variable=144.\\nEBITDA=400−144−120=136 (−64 from 200).\\nFixed costs amplify the swing (operating leverage)." },
    },
    {
      id: "s17c08",
      dom: "perf",
      diff: 3,
      q: { ja: "差異分析(価格・数量)。予算:数量1000・単価50=売上50000。実績:数量900・単価54=売上48600。売上差異を価格差異と数量差異に分解せよ。", en: "Variance (price/volume). Budget: 1000 units × 50 = 50,000. Actual: 900 × 54 = 48,600. Decompose the revenue variance." },
      sol: { ja: "総差異=48600−50000=−1400。\\n数量差異=(900−1000)×50=−5000(不利)。\\n価格差異=900×(54−50)=+3600(有利)。\\n合計−5000+3600=−1400で一致。数量減を価格改善が一部相殺。", en: "Total variance=−1400.\\nVolume variance=(900−1000)×50=−5000 (unfavorable).\\nPrice variance=900×(54−50)=+3600 (favorable).\\nSum=−1400. Price partly offsets volume loss." },
    },
    {
      id: "s17c09",
      dom: "capalloc",
      diff: 3,
      q: { ja: "自社株買いの1株価値。株価900、本源価値1000。時価総額900億(1億株)、100億で自社株買い。買戻株数と、残存株主の1株本源価値の変化(総本源価値=1000億)は？", en: "Buyback per-share value. Price 900, intrinsic 1000. Cap 90.0bn (100m shares), buy back 10.0bn. Shares repurchased and change in intrinsic value per remaining share (total intrinsic 100.0bn)?" },
      sol: { ja: "買戻株数=100億/900=約1,111万株。残存=約8,889万株。\\n買戻後の総本源価値=1000億−100億(現金流出)=900億。\\n1株本源価値=900億/8,889万株≈1,013円(買戻前1,000円)。\\n割安(900<1000)で買ったため残存株主の1株価値が上昇。", en: "Repurchased=10.0bn/900≈11.11m; remaining≈88.89m.\\nPost intrinsic total=100.0bn−10.0bn=90.0bn.\\nPer share=90.0bn/88.89m≈1,013 (was 1,000).\\nBuying below intrinsic (900<1000) lifts remaining holders' per-share value." },
    },
    {
      id: "s17c10",
      dom: "deal",
      diff: 3,
      q: { ja: "税務ステップアップの価値。資産譲渡で税務簿価が300ステップアップ、10年定額償却、税率30%。追加タックスシールドのPV(割引率8%、年金係数6.71)は？株式譲渡と比べた買い手の価値差は？", en: "Step-up value. Asset deal steps up basis by 300, 10y straight-line, tax 30%. PV of extra tax shield (rate 8%, annuity factor 6.71)? Buyer value vs a share deal?" },
      sol: { ja: "年間追加償却=300/10=30。年間TS=30×30%=9。\\nPV=9×6.71≈60.4。\\n買い手は資産譲渡でこの約60の税務価値を追加で得る(株式譲渡では基本得られない)。価格交渉で反映余地。", en: "Annual depreciation=30; annual tax shield=9.\\nPV=9×6.71≈60.4.\\nThe buyer gains ~60 of tax value in an asset deal (not in a share deal), a factor in pricing." },
    },
    {
      id: "s17c11",
      dom: "cfo",
      diff: 3,
      q: { ja: "統合的な資本配分の意思決定。FCF200。維持設備投資50、価値を生む成長投資枠80(ROIC13%,WACC10%)、負債返済で下げたい額30、残りを株主還元。株主還元に回せる額は？", en: "Integrated allocation. FCF (Free Cash Flow) 200. Maintenance capex 50, value-creating growth capex 80 (ROIC13%,WACC10%), desired debt paydown 30, rest to shareholders. Amount for shareholder returns?" },
      sol: { ja: "株主還元=FCF−維持投資−成長投資−負債返済\\n=200−50−80−30=40。\\n成長投資はROIC13%>WACC10%で価値創出のため優先。残余40を配当/自社株買いへ(株価が割安なら自社株買い優先)。", en: "Returns=200−50−80−30=40.\\nGrowth capex (ROIC13%>WACC10%) is prioritized as value-creating.\\nThe residual 40 goes to dividends/buybacks (buybacks preferred if undervalued)." },
    },
    {
      id: "s17c12",
      dom: "growth",
      diff: 3,
      q: { ja: "リアルオプション(段階投資)。パイロット15。成功確率50%なら本格投資後NPV（Net Present Value）+120、失敗なら中止でNPV0。パイロットの期待価値と、即時一括投資NPV−10との比較は？", en: "Real option (staging). Pilot 15. 50% success → scale-up NPV (Net Present Value) +120; failure → stop, NPV 0. Expected value of the pilot vs an immediate lump-sum NPV of −10?" },
      sol: { ja: "パイロット期待値=−15＋0.5×120＋0.5×0=−15＋60=+45。\\n一括投資は−10で価値破壊だが、段階投資なら+45で価値創出。\\n下方を限定しつつ上方を残す柔軟性が価値の源泉。", en: "Pilot EV=−15+0.5×120+0.5×0=+45.\\nLump-sum is −10 (value-destroying), but staging yields +45.\\nCapping downside while keeping upside creates the value." },
    },
    {
      id: "s17c13",
      dom: "perf",
      diff: 3,
      q: { ja: "貢献利益と追加受注。通常価格100、変動費60、固定費は既に回収済み。特別注文が単価70で200個。受注すべきか、増分利益は？", en: "Contribution and special order. Regular price 100, variable cost 60, fixed costs already covered. Special order of 200 units at 70. Accept? Incremental profit?" },
      sol: { ja: "特別注文の貢献利益=(70−60)×200=+2000。\\n固定費は既に回収済みで増分費用は変動費のみ→単価70>変動費60なので受注すべき。\\n増分利益=+2000(通常市場を侵食しない前提)。", en: "Contribution=(70−60)×200=+2000.\\nFixed costs are sunk; incremental cost is only variable. Since 70>60, accept.\\nIncremental profit=+2000 (assuming no cannibalization)." },
    },
    {
      id: "s17c14",
      dom: "risk",
      diff: 3,
      q: { ja: "ヘッジの効果。輸出企業、想定為替110円/ドルで売上1000万ドル。円高で100円になると円建て売上は？50%を110円でヘッジ済みなら円建て売上は？", en: "Hedge effect. Exporter, budget 110 JPY/USD on USD 10m sales. If yen strengthens to 100, JPY revenue? If 50% hedged at 110?" },
      sol: { ja: "無ヘッジ: 1000万×100=10億円(想定11億から−1億)。\\n50%ヘッジ: 500万×110＋500万×100=5.5億＋5.0億=10.5億円。\\nヘッジで円高の悪影響を半減(−1億→−0.5億)。", en: "Unhedged: 10m×100=1.00bn JPY (−0.1bn vs 1.1bn budget).\\n50% hedged: 5m×110+5m×100=0.55bn+0.50bn=1.05bn.\\nHedging halves the FX hit (−0.1bn → −0.05bn)." },
    },
    {
      id: "s17c15",
      dom: "stakeholder",
      diff: 3,
      q: { ja: "重要性の定量目安。売上20000、当期純利益800。未修正の誤謬が56。純利益に対する比率と重要性の可能性は？質的考慮も一言。", en: "Quantitative materiality. Revenue 20000, net income 800. Uncorrected error 56. Ratio to net income and likely materiality? Note qualitative factors." },
      sol: { ja: "純利益比=56/800=7%。\\n一般に純利益の5%超は量的重要とされ、7%は重要性ありと判断されうる。\\nさらに、赤字転落・傾向反転・法令違反等の質的要因があれば金額が小さくても重要となる。", en: "Ratio=56/800=7%.\\nOver ~5% of net income is often material, so 7% likely is.\\nQualitative factors (turning to a loss, trend reversal, legal breach) can make even small amounts material." },
    },
    {
      id: "s17c16",
      dom: "cfo",
      diff: 3,
      q: { ja: "レバレッジとリターン増幅。EV500をエクイティ200・負債300(税引後金利5%)で取得。EV（Enterprise Value）が横ばい、純負債を300→150に返済。エクイティ価値とMOIC（Multiple on Invested Capital）は？レバレッジの効果を一言。", en: "Leverage and return amplification. EV (Enterprise Value) 500 with equity 200, debt 300 (after-tax 5%). EV flat, net debt 300→150. Equity value and MOIC (Multiple on Invested Capital)? Comment on leverage." },
      sol: { ja: "エクイティ=EV−純負債=500−150=350。MOIC=350/200=1.75x。\\nEV横ばいでも、レバレッジ下でのデレバレッジがエクイティ価値を200→350に増幅。\\n反面、EVが下落する局面では損失も増幅される(両刃)。", en: "Equity=500−150=350. MOIC=350/200=1.75x.\\nEven with flat EV, deleveraging amplifies equity from 200 to 350.\\nBut if EV fell, losses would also be amplified (double-edged)." },
    },
    {
      id: "s17c17",
      dom: "capalloc",
      diff: 3,
      q: { ja: "TSR分解。1年でEPS（Earnings Per Share）が100→112(+12%)、株価収益率(PER)が10x→10.5x、配当利回り3%。株主総利回り(TSR)の概算内訳は？", en: "TSR decomposition. Over 1 year EPS (Earnings Per Share) 100→112 (+12%), P/E 10x→10.5x, dividend yield 3%. Approximate TSR breakdown?" },
      sol: { ja: "株価=EPS×PER: 100×10=1000 → 112×10.5=1176(+17.6%)。\\nうちEPS成長寄与≈+12%、PER拡大寄与≈+5%。\\nTSR≈株価上昇17.6%＋配当利回り3%≈20.6%。\\n利益成長・マルチプル・配当の3源泉に分解できる。", en: "Price=EPS×P/E: 1000 → 1176 (+17.6%).\\nEPS growth ≈+12%, multiple expansion ≈+5%.\\nTSR≈17.6%+3% dividend≈20.6%.\\nThree sources: earnings growth, multiple, and dividend." },
    },
    {
      id: "s17c18",
      dom: "cfo",
      diff: 3,
      q: { ja: "統合ケース(総まとめ)。買収候補: EBITDA100、提示EV（Enterprise Value）/EBITDA（Earnings Before Interest, Taxes, Depreciation and Amortization） 9x。シナジー年15(税引後、EV評価9x)。統合コスト一時30。買収EV、シナジーの価値、一時費用控除後の正味価値創出、そしてROIC（Return on Invested Capital）>WACC（Weighted Average Cost of Capital）判定(WACC10%、投下=買収EV)の考え方は？", en: "Integrated case. Target EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 100, offered 9x EV (Enterprise Value)/EBITDA. Synergy 15/yr (after-tax, valued 9x). One-off integration 30. Deal EV, synergy value, net value after one-off, and ROIC (Return on Invested Capital)>WACC (Weighted Average Cost of Capital) check (WACC10%, invested=deal EV)?" },
      sol: { ja: "買収EV=100×9=900。\\nシナジー価値=15×9=135。一時費用控除後の正味創出=135−30=105。\\n投下900に対する年間シナジー15＝約1.7%の追加リターンは単独では低いが、対象の既存キャッシュ創出＋シナジーで総合ROICがWACC10%を上回るかで判定。\\n過払い(高倍率)はのれん減損リスク、規律ある価格とシナジー実現が鍵。", en: "Deal EV=900. Synergy value=135; net after one-off=135−30=105.\\nSynergy alone (15 on 900 ≈1.7%) is thin; judge total ROIC (target's own cash + synergy) vs 10% WACC.\\nOverpaying risks goodwill impairment; disciplined pricing and synergy delivery are key." },
    },
  );
