  _calc.push(
    {
      id: "s18c01",
      dom: "mnacase",
      diff: 3,
      q: { ja: "【ケース:買収判断】対象EBITDA（Earnings Before Interest, Taxes, Depreciation and Amortization） 80、提示EV（Enterprise Value）/EBITDA 9x。実現可能シナジー年12(税引後)。買収EVと、投下(EV)に対するシナジー利回り、そして総合ROIC（Return on Invested Capital）がWACC10%を上回るかの考え方は(対象の既存税引後利益48)？", en: "[Case: acquire?] Target EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 80, offered 9x. Realizable synergy 12/yr (after-tax). Deal EV (Enterprise Value), synergy yield on invested EV, and how to judge total ROIC (Return on Invested Capital) vs 10% WACC (Weighted Average Cost of Capital) (target's existing after-tax profit 48)?" },
      sol: { ja: "買収EV=80×9=720。\\nシナジー利回り=12/720≈1.7%(単独では薄い)。\\n総合ROIC=(既存税引後48＋シナジー12)/720=60/720≈8.3%。\\n8.3%<WACC10%なので、この価格では価値創出に不足。価格引下げ・シナジー上積み・成長前提が必要。", en: "Deal EV=720. Synergy yield=12/720≈1.7% (thin alone).\\nTotal ROIC=(48+12)/720=60/720≈8.3%.\\n8.3%<10% WACC → insufficient at this price; need lower price, more synergy, or growth." },
    },
    {
      id: "s18c02",
      dom: "mnacase",
      diff: 3,
      q: { ja: "【ケース:エクイティ対価】合意EV（Enterprise Value） 600。純有利子負債200、デットライク40、余剰現金30、NWC（Net Working Capital）不足調整−15。株式対価は？売り手が『デットライク』を否定できれば対価はいくらになるか？", en: "[Case: equity price] Agreed EV (Enterprise Value) 600. Net debt 200, debt-like 40, surplus cash 30, NWC (Net Working Capital) shortfall −15. Equity price? If the seller disputes the debt-like item, new price?" },
      sol: { ja: "株式対価=600−200−40＋30−15=375。\\nデットライク40を否定できれば=600−200−0＋30−15=415(+40)。\\n各調整の定義が価格に直結するため交渉の争点となる。", en: "Equity=600−200−40+30−15=375.\\nWithout the debt-like 40: 600−200+30−15=415 (+40).\\nEach adjustment definition directly moves price—hence the negotiation." },
    },
    {
      id: "s18c03",
      dom: "pecase",
      diff: 3,
      q: { ja: "【ケース:PE（Private Equity）リターン分解】取得EBITDA（Earnings Before Interest, Taxes, Depreciation and Amortization） 50・8x(EV400・エクイティ150・純負債250)。5年後EBITDA 80・9x、純負債120。EBITDA成長/倍率/デレバレッジの寄与、Exitエクイティ、MOIC（Multiple on Invested Capital）は？", en: "[Case: PE (Private Equity) returns] Entry EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 50 at 8x (EV400, equity150, net debt250). Year 5: EBITDA 80 at 9x, net debt 120. Contributions, exit equity, MOIC (Multiple on Invested Capital)?" },
      sol: { ja: "Exit EV=80×9=720、エクイティ=720−120=600。\\n①EBITDA成長=(80−50)×8=+240\\n②倍率=80×(9−8)=+80\\n③デレバレッジ=250−120=+130\\n合計+450(150→600)。MOIC=600/150=4.0x。", en: "Exit EV=720, equity=600.\\n(1) EBITDA growth=+240\\n(2) Multiple=+80\\n(3) Deleveraging=+130\\nTotal +450 (150→600). MOIC=4.0x." },
    },
    {
      id: "s18c04",
      dom: "pecase",
      diff: 3,
      q: { ja: "【ケース:Exit IRR（Internal Rate of Return）】投下エクイティ150、Exit回収600、保有5年。MOIC（Multiple on Invested Capital）とおおよそのIRRは？保有が7年に延びると同じMOICでIRRはどう変わるか？", en: "[Case: exit IRR (Internal Rate of Return)] Invested equity 150, exit 600, 5-year hold. MOIC (Multiple on Invested Capital) and approx IRR? If the hold extends to 7 years at the same MOIC, how does IRR change?" },
      sol: { ja: "MOIC=600/150=4.0x。\\n5年IRR=4^(1/5)−1≈32%。\\n7年IRR=4^(1/7)−1≈22%。\\n同じMOICでも保有が長いほどIRRは低下。時間はPEリターンの敵。", en: "MOIC=4.0x. 5-yr IRR=4^(1/5)−1≈32%.\\n7-yr IRR=4^(1/7)−1≈22%.\\nSame MOIC, longer hold → lower IRR; time erodes PE returns." },
    },
    {
      id: "s18c05",
      dom: "turnaround",
      diff: 3,
      q: { ja: "【ケース:再生の損益分岐】売上500・変動費300・固定費180で営業赤字。固定費を40削減し変動費率を維持。新BEP（Break-Even Point）売上と、売上が460に落ちても黒字を保てるか？", en: "[Case: turnaround break-even] Revenue 500, variable 300, fixed 180 (operating loss). Cut fixed by 40, keep variable ratio. New break-even revenue, and can it stay profitable if revenue falls to 460?" },
      sol: { ja: "変動費率=300/500=60%、貢献利益率=40%。\\n新固定費=140。BEP=140/0.40=350。\\n売上460>BEP350なので黒字。営業利益=460×40%−140=44。\\n固定費削減でBEPを下げ、下方耐性を高めた。", en: "Variable ratio=60%, contribution margin=40%.\\nNew fixed=140. BEP=140/0.40=350.\\nRevenue 460>350 → profitable. Operating profit=460×40%−140=44.\\nCutting fixed cost lowered BEP and improved resilience." },
    },
    {
      id: "s18c06",
      dom: "turnaround",
      diff: 3,
      q: { ja: "【ケース:運転資本の現金解放】売上原価730/年、在庫200(DIO?)。在庫を150に、売掛DSO（Days Sales Outstanding）を75日から60日に短縮(売上1095)。解放される現金合計は？", en: "[Case: NWC (Net Working Capital) cash release] COGS 730/yr, inventory 200 (DIO?). Cut inventory to 150 and DSO (Days Sales Outstanding) from 75 to 60 days (revenue 1095). Total cash freed?" },
      sol: { ja: "DIO=200/730×365=100日。在庫削減200→150で現金+50。\\n売掛=1095/365×日数: 75日→225、60日→180、削減で現金+45。\\n合計解放=50+45=95。再生の資金繰りを大きく改善。", en: "DIO=100 days. Inventory 200→150 frees +50.\\nAR: 75d→225, 60d→180 → frees +45.\\nTotal freed=95, materially easing liquidity." },
    },
    {
      id: "s18c07",
      dom: "growthcase",
      diff: 3,
      q: { ja: "【ケース:新規参入の意思決定】新市場のNPV（Net Present Value）+30(WACC10%)。ただし成功確率60%、失敗なら−50。パイロット投資10で確度を見極めてから本格投資できる。パイロットの期待価値と一括投資の期待値を比較せよ。", en: "[Case: entry decision] New-market NPV (Net Present Value) +30 (WACC10%) if success (60%), else −50. A pilot of 10 lets you learn before scaling. Compare pilot EV (Enterprise Value) vs lump-sum EV." },
      sol: { ja: "一括投資の期待値=0.6×30＋0.4×(−50)=18−20=−2(価値破壊)。\\nパイロット: 失敗なら中止(0)。期待値=−10＋0.6×30＋0.4×0=−10＋18=+8。\\n段階投資で下方を限定し、一括の−2を+8に転換。", en: "Lump-sum EV=0.6×30+0.4×(−50)=−2 (value-destroying).\\nPilot (stop on failure)=−10+0.6×30+0.4×0=+8.\\nStaging caps downside, turning −2 into +8." },
    },
    {
      id: "s18c08",
      dom: "growthcase",
      diff: 3,
      q: { ja: "【ケース:成長の価値】ROIC15%、WACC10%、再投資率50%。持続成長率は？スプレッドがゼロ(ROIC（Return on Invested Capital）=WACC（Weighted Average Cost of Capital）=10%)なら成長は価値を生むか？", en: "[Case: value of growth] ROIC15%, WACC10%, reinvestment 50%. Sustainable growth? If the spread is zero (ROIC (Return on Invested Capital)=WACC (Weighted Average Cost of Capital)=10%), does growth create value?" },
      sol: { ja: "持続成長率=ROIC×再投資率=15%×50%=7.5%。\\nスプレッド=+5%>0なので成長は価値創出。\\nスプレッドがゼロなら、成長しても価値は増えない(価値中立)。成長は手段であり目的でない。", en: "g=15%×50%=7.5%. Spread +5%>0 → growth creates value.\\nIf the spread is zero, growth adds no value (value-neutral). Growth is a means, not the goal." },
    },
    {
      id: "s18c09",
      dom: "capitalcase",
      diff: 3,
      q: { ja: "【ケース:自社株買いの是非】株価800・本源価値1000。時価総額800億(1億株)、80億で自社株買い。買戻株数と、残存株主の1株本源価値(総本源価値1000億)は？", en: "[Case: buyback?] Price 800, intrinsic 1000. Cap 80.0bn (100m shares), buy back 8.0bn. Shares repurchased and remaining holders' intrinsic per share (total intrinsic 100.0bn)?" },
      sol: { ja: "買戻株数=80億/800=1,000万株。残存=9,000万株。\\n買戻後総本源価値=1000億−80億=920億。\\n1株本源価値=920億/9,000万≈1,022円(買戻前1,000円)。\\n割安(800<1000)で買ったため残存株主価値が上昇。", en: "Repurchased=8.0bn/800=10m; remaining=90m.\\nPost intrinsic=100.0bn−8.0bn=92.0bn.\\nPer share=92.0bn/90m≈1,022 (was 1,000).\\nBuying below intrinsic lifts remaining holders' value." },
    },
    {
      id: "s18c10",
      dom: "capitalcase",
      diff: 3,
      q: { ja: "【ケース:レバレッジと金利】純負債400(変動金利)、EBITDA150。金利3%→6%。支払利息の増加、ICR（Interest Coverage Ratio）の変化(利息以外一定)、コベナンツ下限4.0xに抵触するか？", en: "[Case: leverage & rates] Net debt 400 (floating), EBITDA150. Rate 3%→6%. Extra interest, ICR (Interest Coverage Ratio) change (else constant), and does it breach a 4.0x floor?" },
      sol: { ja: "利息: 400×3%=12 → 400×6%=24(+12)。\\nICR: 150/12=12.5x → 150/24=6.25x。\\nいずれも下限4.0x超で抵触せず。ただしFCFは利息増12だけ悪化。ヘッジや返済加速で耐性維持。", en: "Interest: 12 → 24 (+12). ICR: 12.5x → 6.25x.\\nBoth clear the 4.0x floor; but FCF worsens by 12. Hedge or accelerate paydown." },
    },
    {
      id: "s18c11",
      dom: "crisiscase",
      diff: 3,
      q: { ja: "【ケース:ストレステスト】基準売上600・変動費360・固定費150(EBITDA90)。景気後退で売上−25%、変動費率一定、固定費不変。ストレス下EBITDA（Earnings Before Interest, Taxes, Depreciation and Amortization）と基準からの下落幅は？", en: "[Case: stress test] Base revenue 600, variable 360, fixed 150 (EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 90). Recession cuts revenue 25%, variable ratio constant, fixed unchanged. Stressed EBITDA and drop from base?" },
      sol: { ja: "変動費率=360/600=60%。ストレス売上=600×0.75=450。\\n変動費=450×60%=270。EBITDA=450−270−150=30。\\n基準90から−60(約−67%)。固定費の重さで利益が大きく振れる(オペレーティングレバレッジ)。", en: "Variable ratio=60%. Stressed revenue=450, variable=270.\\nEBITDA=450−270−150=30, down 60 from 90 (~−67%).\\nFixed costs amplify the swing (operating leverage)." },
    },
    {
      id: "s18c12",
      dom: "crisiscase",
      diff: 3,
      q: { ja: "【ケース:ヘッジ判断】輸出企業、想定110円/ドルで売上2000万ドル。円高100円で円建て売上は？60%を110円でヘッジ済みなら円建て売上と、無ヘッジ比の改善額は？", en: "[Case: hedge] Exporter budgets 110 JPY/USD on USD 20m. Yen strengthens to 100: JPY revenue? If 60% hedged at 110, JPY revenue and improvement vs unhedged?" },
      sol: { ja: "無ヘッジ=2000万×100=20億円(想定22億から−2億)。\\n60%ヘッジ=1200万×110＋800万×100=13.2億＋8.0億=21.2億円。\\n無ヘッジ比+1.2億。ヘッジで円高影響を大幅緩和。", en: "Unhedged=2000万×100=2.00bn (−0.2bn vs 2.2bn budget).\\n60% hedged=12m×110+8m×100=1.32bn+0.80bn=2.12bn.\\n+0.12bn vs unhedged; hedging cushions the FX hit." },
    },
    {
      id: "s18c13",
      dom: "cfocase",
      diff: 3,
      q: { ja: "【ケース:資本配分】FCF250。維持設備投資60、価値ある成長投資枠90(ROIC14%,WACC10%)、目標デレバレッジ40、残余を株主還元。株主還元額は？成長投資を優先する根拠は？", en: "[Case: allocation] FCF250. Maintenance capex 60, value-creating growth capex 90 (ROIC14%,WACC10%), target deleveraging 40, rest to shareholders. Return amount and rationale for prioritizing growth?" },
      sol: { ja: "株主還元=250−60−90−40=60。\\n成長投資はROIC14%>WACC10%(スプレッド+4%)で価値創出のため優先。\\n残余60を配当/自社株買いへ(株価割安なら自社株買い優先)。", en: "Returns=250−60−90−40=60.\\nGrowth capex (ROIC14%>WACC10%, +4% spread) is prioritized as value-creating.\\nResidual 60 to dividends/buybacks (buyback if undervalued)." },
    },
    {
      id: "s18c14",
      dom: "cfocase",
      diff: 3,
      q: { ja: "【ケース:TSR分解】1年でEPS（Earnings Per Share） 200→224(+12%)、PER（Price-to-Earnings Ratio） 12x→12.6x、配当利回り2.5%。株価上昇率とTSR概算、内訳(EPS成長/倍率/配当)は？", en: "[Case: TSR] EPS (Earnings Per Share) 200→224 (+12%), P/E 12x→12.6x, dividend yield 2.5% over one year. Price change, approx TSR, and breakdown (growth/multiple/dividend)?" },
      sol: { ja: "株価=EPS×PER: 200×12=2400 → 224×12.6=2822(+17.6%)。\\nEPS成長寄与≈+12%、倍率拡大≈+5%。\\nTSR≈株価17.6%＋配当2.5%≈20.1%。\\n利益成長・倍率・配当の3源泉に分解できる。", en: "Price: 2400 → 2822 (+17.6%). EPS growth ≈+12%, multiple ≈+5%.\\nTSR≈17.6%+2.5%≈20.1%.\\nThree sources: earnings growth, multiple, dividend." },
    },
    {
      id: "s18c15",
      dom: "mnacase",
      diff: 3,
      q: { ja: "【ケース:税務ストラクチャー】資産譲渡で税務簿価が250ステップアップ、10年定額償却、税率30%。追加タックスシールドのPV(割引率8%、年金係数6.71)は？株式譲渡と比べた買い手の追加価値は？", en: "[Case: tax structure] Asset deal steps up basis by 250, 10y straight-line, tax 30%. PV of extra tax shield (rate 8%, annuity factor 6.71)? Extra buyer value vs a share deal?" },
      sol: { ja: "年間追加償却=250/10=25。年間TS=25×30%=7.5。\\nPV=7.5×6.71≈50.3。\\n買い手は資産譲渡でこの約50の税務価値を追加で得る。価格交渉での配分余地となる。", en: "Annual depreciation=25; annual tax shield=7.5. PV=7.5×6.71≈50.3.\\nThe buyer gains ~50 of tax value in an asset deal—a factor in pricing." },
    },
    {
      id: "s18c16",
      dom: "turnaround",
      diff: 3,
      q: { ja: "【ケース:債務再編】純負債500、EBITDA100(レバレッジ5.0x)。債権者と交渉し負債の20%(100)を株式化(DES)。再編後の純負債・レバレッジと、財務健全性への効果は？", en: "[Case: restructuring] Net debt 500, EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 100 (leverage 5.0x). Negotiate a debt-for-equity swap of 20% (100). Post-restructuring net debt, leverage, and effect?" },
      sol: { ja: "DES後純負債=500−100=400。レバレッジ=400/100=4.0x(5.0→4.0x)。\\n利払い負担が軽減しFCF・カバレッジが改善、破綻リスクが低下。\\n一方、既存株主は希薄化する(株式発行)。", en: "Post-DES net debt=400. Leverage=4.0x (from 5.0x).\\nLower interest improves FCF/coverage and cuts distress risk.\\nBut existing shareholders are diluted by the new equity." },
    },
    {
      id: "s18c17",
      dom: "pecase",
      diff: 3,
      q: { ja: "【ケース:アドオンの倍率希薄化】プラットEBITDA（Earnings Before Interest, Taxes, Depreciation and Amortization） 20を10xで保有(EV200)。EBITDA 5のアドオンを6xで取得。買収後の連結EBITDA・EV（Enterprise Value）・平均取得倍率は？Exit倍率10xなら創出EVは？", en: "[Case: add-on arbitrage] Platform EBITDA (Earnings Before Interest, Taxes, Depreciation and Amortization) 20 at 10x (EV200). Buy an add-on with EBITDA 5 at 6x. Post consolidated EBITDA, EV (Enterprise Value), blended multiple? If exit at 10x, EV created?" },
      sol: { ja: "アドオンEV=5×6=30。連結EBITDA=25、連結EV(取得)=200+30=230、平均倍率=230/25=9.2x。\\nExit倍率10xなら Exit EV=25×10=250。創出EV=250−230=+20(倍率アービトラージ)。", en: "Add-on EV=30. Consolidated EBITDA=25, invested EV=230, blended=9.2x.\\nAt 10x exit: EV=250. Value created=250−230=+20 (multiple arbitrage)." },
    },
    {
      id: "s18c18",
      dom: "cfocase",
      diff: 3,
      q: { ja: "【ケース:総合判断】買収候補: EBITDA100、提示9x。シナジー年15(税引後)。統合コスト一時30。同時に手元流動性が薄い。CFO（Chief Financial Officer）として、買収EV（Enterprise Value）・シナジー価値(EV評価9x)・一時費用控除後の正味創出を算出し、実行前に確認すべき最重要点を一言で。", en: "[Case: integrated call] Target EBITDA100 at 9x. Synergy 15/yr (after-tax). One-off integration 30. Liquidity is thin. As CFO (Chief Financial Officer), compute deal EV (Enterprise Value), synergy value (at 9x), net value after one-off, and state the single most important pre-deal check." },
      sol: { ja: "買収EV=100×9=900。シナジー価値=15×9=135。正味創出=135−30=105。\\n数値上は価値創出だが、手元流動性が薄い中で900の資金調達を行えば財務耐性が低下。\\n最重要確認: 資金調達後もレバレッジ・流動性がリスク許容内か(生存を損なわないか)。ROIC>WACCの検証と併せ判断する。", en: "Deal EV=900. Synergy value=135. Net created=135−30=105.\\nValue-positive on paper, but funding 900 with thin liquidity weakens resilience.\\nKey check: does post-financing leverage/liquidity stay within risk tolerance (survival intact)? Judge alongside ROIC>WACC." },
    },
  );
