      saf: { role: "全アプリ共通の安全フィルタ・PII検知。", tech: "入出力検査の共通サービス化、ポリシー一元管理。", biz: "各アプリ任せは必ず穴が出る。中央集権化が監査対応の近道。", qa: "部門ごとの基準差は？（→共通の床＋部門別の追加ポリシー）", cost: "重複開発の排除。N個のアプリ×個別実装をやめる。", roleEn: "Shared safety filters / PII detection for all apps.", techEn: "I/O inspection as a shared service, centralized policy.", bizEn: "Per-app DIY always leaves holes; centralizing eases audits.", qaEn: "Different standards per department? (→ a shared floor + per-department add-on policy)", costEn: "Eliminates duplicated development across N apps." },
      app: { role: "各部門のAIアプリ・エージェントが基盤を共用。", tech: "SDK/API標準化、テンプレート配布。", biz: "2つ目以降のユースケースを1/5のコストで出せる状態を作る。", qa: "プラットフォーム化に踏み切る目安は？（→ユースケース3つ目が経験則）", cost: "重複投資の排除がプラットフォームROIの源泉。", roleEn: "Departmental AI apps/agents sharing the platform.", techEn: "SDK/API standardization, template distribution.", bizEn: "Get the second-and-later use cases out at 1/5 the cost.", qaEn: "When do you commit to a platform? (→ rule of thumb: the third use case)", costEn: "Eliminating duplicated investment is the platform's ROI source." },
      gw: { role: "全LLMトラフィックの単一入口。", tech: "レート制御、リトライ、フェイルオーバー、監査ログ。", biz: "シャドーAI対策。「統制」と「利活用促進」を両立させる要の一枚。", qa: "ゲートウェイをSPOFにしない設計は？（→多AZ、直結へのデグレード運転）", cost: "全トラフィックの可視化が原価配賦と交渉の前提になる。", roleEn: "The single entry point for all LLM traffic.", techEn: "Rate control, retries, failover, audit log.", bizEn: "Shadow-AI defense; the keystone balancing governance and enablement.", qaEn: "How to keep the gateway from being a SPOF? (→ multi-AZ, degrade to direct connection)", costEn: "Visibility over all traffic underpins cost allocation and negotiation." },
      rtr: { role: "難易度・コスト・速度でモデルを自動選択。", tech: "ルール→分類器→学習型へ段階進化。", biz: "「フロンティア一択」を卒業させ原価を3〜7割圧縮する中枢。", qa: "ルーティング誤りの検知は？（→エスカレーション再試行＋品質サンプリング）", cost: "小型モデル優先ルーティングの実装先はここ。", roleEn: "Auto-selects models by difficulty, cost, and speed.", techEn: "Rules → classifier → learned router, evolving in stages.", bizEn: "Graduates you from 'always frontier'; cuts cost 30–70%.", qaEn: "How to detect routing errors? (→ escalation retry + quality sampling)", costEn: "This is where small-model-first routing is implemented." },
      prv: { role: "ベンダーAPI差異を吸収する抽象層。", tech: "統一スキーマ設計、機能差のエスケープハッチ。", biz: "ロックイン回避＝価格交渉力。マルチクラウド資格の見せ場。", qa: "抽象化しすぎの弊害は？（→各社固有機能が死ぬ。逃げ道を設計に残す）", cost: "乗り換え自由度そのものが単価交渉の武器になる。", roleEn: "An abstraction layer absorbing vendor API differences.", techEn: "Unified schema, escape hatches for feature gaps.", bizEn: "Avoiding lock-in = pricing power; a showcase for multi-cloud skills.", qaEn: "Downside of over-abstracting? (→ vendor-specific features die; keep escape hatches)", costEn: "Freedom to switch is itself a lever in unit-price negotiation." },
      ext: { role: "Bedrock/Vertex/Azure OpenAI等のマネージドAPI。", tech: "リージョン・データレジデンシ・SLAの比較選定。", biz: "規制産業ではデータ所在が採用の決定打。企業研究タブと接続。", qa: "3社マネージドの思想の違いを一言で？（面接頻出。自分の言葉を用意）", cost: "従量課金はピーク・実験用途に充てる。", roleEn: "Managed APIs like Bedrock/Vertex/Azure OpenAI.", techEn: "Region, data residency, and SLA comparison.", bizEn: "In regulated industries, data location decides adoption; ties to Companies tab.", qaEn: "One-line difference in the three managed philosophies? (common interview Q — prepare your own words)", costEn: "Use pay-as-you-go for peaks and experiments." },
      gpu: { role: "OSSモデル等の自社ホスト推論。", tech: "量子化・連続バッチング等の推論最適化。", biz: "Build vs Buyの本丸。損益分岐点の試算を示せると一段上に見える。", qa: "セルフホストが正当化される条件は？（→大量安定トラフィック×データ主権×単価）", cost: "予約容量の極致。稼働率が採算の全てを決める。", roleEn: "Self-hosted inference of OSS models, etc.", techEn: "Quantization, continuous batching, and other inference optimizations.", bizEn: "The heart of Build vs Buy; showing break-even math looks a level above.", qaEn: "When is self-hosting justified? (→ large stable traffic × data sovereignty × unit cost)", costEn: "The extreme of reserved capacity; utilization decides all economics." },
      qta: { role: "テナント・アプリ別の利用上限とレート制御。", tech: "トークン計測、タグ付け、階層別リミット、アドミッション制御。", biz: "1アプリの暴走から全社を守る統制。マルチテナント設計の一丁目一番地。", qa: "ノイジーネイバー問題への対処は？（→階層別リミット＋優先度キュー＋隔離）", cost: "利用量の可視化だけで無駄な呼び出しが1〜2割減る。", roleEn: "Per-tenant/app usage limits and rate control.", techEn: "Token metering, tagging, tiered limits, admission control.", bizEn: "Protects the whole company from one app's runaway; multi-tenant fundamentals.", qaEn: "How to handle the noisy-neighbor problem? (→ tiered limits + priority queues + isolation)", costEn: "Usage visibility alone cuts wasteful calls by 10–20%." },
      obs: { role: "全社横断の品質・性能・コスト監視。", tech: "統一トレーシング、SLO、異常検知。", biz: "経営会議に「AIの健康状態」を1枚で出せる状態を作る。", qa: "何をSLOに置く？（→レイテンシp95、品質サンプル合格率、回答単価）", cost: "監視自体もLLM費を食う。サンプリング率で制御。", roleEn: "Company-wide quality, performance, and cost monitoring.", techEn: "Unified tracing, SLOs, anomaly detection.", bizEn: "Get to where you can show 'AI's health' on one page to the exec meeting.", qaEn: "What do you put in an SLO? (→ p95 latency, quality-sample pass rate, cost per answer)", costEn: "Monitoring also consumes LLM cost; control via sampling rate." },
      gov: { role: "モデル台帳・リスク分類・規制対応（EU AI Act等）。", tech: "モデルカード、用途別リスク評価、監査証跡。", biz: "規制対応を「ブレーキ」でなく「参入資格」として語れると経営に刺さる。", qa: "高リスク用途の判定軸は？（→影響の不可逆性×自動化度）", cost: "罰金・事業停止リスクの期待値で投資を正当化する。", roleEn: "Model registry, risk classification, regulatory compliance (EU AI Act, etc.).", techEn: "Model cards, per-use risk assessment, audit trail.", bizEn: "Framing compliance as 'entry qualification,' not a 'brake,' resonates with execs.", qaEn: "Axes for judging high-risk use? (→ irreversibility of impact × degree of automation)", costEn: "Justify investment via the expected value of fines / shutdown risk." }
