    details: {
      reg: { role: "モデル重みの配布・バージョン管理・ウォームアップ。", tech: "重みの事前ロード、ウォームプール維持。", biz: "「モデル切替に何分かかるか」は障害復旧時間に直結。地味だが本番の生命線。", qa: "コールドスタート対策は？（→ウォームプール、重みの事前配置、段階切替）", cost: "待機GPUは固定費。可用性要件との交換で決める。", roleEn: "The model registry/weights being served.", techEn: "Versioning, weight loading, format (safetensors).", bizEn: "The asset. Version discipline prevents 'which model answered?' chaos.", qaEn: "Why version models? (→ reproducibility and safe rollback)", costEn: "Storage is cheap; ambiguity about deployed versions is expensive." },
      kvc: { role: "生成済みトークンの注意状態を再利用し再計算を回避。", tech: "PagedAttention的なページ管理、プレフィックス共有。", biz: "プロンプトキャッシュ割引の物理的正体。仕組みを語れると単なる利用者と差がつく。", qa: "KVキャッシュのサイズは何で決まる？（→層数×ヘッド数×系列長×バッチ、精度）", cost: "システムプロンプト共通化＝プレフィックス共有でメモリと単価が同時に下がる。", roleEn: "KV cache holding attention state of generated tokens.", techEn: "Paged attention, memory management, cache reuse.", bizEn: "The physical reality behind 'prompt cache' discounts.", qaEn: "What is the KV cache? (→ stored attention state that avoids recomputation)", costEn: "The main GPU-memory consumer; paging it improves throughput." },
      qtz: { role: "FP16→INT8/INT4等へ精度を落としメモリと帯域を圧縮。", tech: "重み量子化、アクティベーション量子化、精度検証セット。", biz: "「品質1〜2%と引き換えに必要GPU半減」＝経営が理解できる技術トレードオフの好例。", qa: "量子化で何が劣化しやすい？（→数値推論・長文整合。用途別に検証してから適用）", cost: "小型・低コスト版を自ら作り出す装置。蒸留と並ぶ量産化の手段。", roleEn: "Quantizes weights to shrink memory/bandwidth.", techEn: "INT8/INT4, calibration, per-task validation.", bizEn: "Not a 'quality' story — a 'how many GPUs' story.", qaEn: "What does quantization buy? (→ fewer GPUs; validate quality per task)", costEn: "Halving precision can halve GPU count; verify accuracy per use case." },
      cli: { role: "SSEストリーミングで体感速度を確保する受け手。", tech: "トークン逐次表示、途中キャンセル、再接続。", biz: "体感＝TTFT、原価＝スループット。指標を分けて語れると会話が締まる。", qa: "TTFTとTPOTの違いは？（→初トークンまでの時間と、以降の1トークン毎時間）", cost: "キャンセル伝搬を怠ると「読まれない生成」に課金され続ける。", roleEn: "The client sending inference requests.", techEn: "Request batching, streaming, timeout handling.", bizEn: "Where latency is felt. TTFT here shapes perceived speed.", qaEn: "What is TTFT? (→ time to first token; dominated by prefill)", costEn: "Client-side batching improves throughput but adds latency." },
      gwy: { role: "認証・優先度付け・アドミッション制御の入口。", tech: "優先度キュー、負荷シェディング、タイムアウト。", biz: "過負荷時に「誰を待たせるか」はビジネス判断。SLA階層の実装点。", qa: "過負荷時に何を落とす？（→低優先度から。全員平等に遅くするのは最悪手）", cost: "SLA階層＝料金階層。技術と料金表を接続する場所。", roleEn: "Inference gateway fronting the engines.", techEn: "Routing, rate limiting, model selection.", bizEn: "A single control point for cost and model switching.", qaEn: "Why a gateway for inference? (→ centralize routing, limits, and cost tracking)", costEn: "One choke point makes serving cost governable." },
      sch: { role: "リクエストを動的に詰め直しGPUを遊ばせない頭脳。", tech: "連続バッチング。完了系列の空きに新規を即充填。", biz: "静的バッチ比で利用率が数倍。サービング経済性の核心を一言で説明できる要所。", qa: "なぜ連続バッチングが効く？（→系列長のばらつきで生じる空きを動的に埋める）", cost: "利用率が2倍なら1トークン原価は半分。ここが単価競争力の源泉。", roleEn: "Scheduler doing continuous batching.", techEn: "Continuous batching, request queuing, preemption.", bizEn: "The heart of serving economics. Fills GPU gaps to multiply utilization.", qaEn: "What is continuous batching? (→ fills completed slots with new requests)", costEn: "2x utilization ≈ half the unit cost; the core serving lever." },
      eng: { role: "実行エンジン。メモリ管理と並列化の作り込みが性能を決める。", tech: "vLLM/TensorRT-LLM級。PagedAttention、テンソル並列。", biz: "OSSエンジン選定は「無料」でなく運用人材コストとの交換、と語れること。", qa: "PagedAttentionは何を解決？（→KVキャッシュのメモリ断片化。OSのページングと同じ発想）", cost: "エンジン更改だけでスループット3〜5割改善の事例は珍しくない。", roleEn: "The inference engine running the forward pass.", techEn: "vLLM/TensorRT-LLM, kernel optimization, parallelism.", bizEn: "The compute core. Engine choice drives throughput and cost.", qaEn: "What makes serving fast? (→ batching, paged KV, optimized kernels)", costEn: "Engine efficiency directly sets your cost per token." },
      gpu: { role: "計算資源の本体。稼働率が採算の全て。", tech: "メモリ内訳＝重み＋KVキャッシュ＋アクティベーション。", biz: "「GPUが足りない」の大半は稼働率の問題。増設の前に利用率を見る癖を。", qa: "70Bモデル(FP16)に必要なメモリは？（→概算140GB＋KV。概算ドリル参照）", cost: "予約容量の実行部隊。遊休1時間はそのまま損失。", roleEn: "The GPU cluster doing the computation.", techEn: "Multi-GPU parallelism, interconnect, scheduling.", bizEn: "The cost center. Utilization is the number that matters.", qaEn: "How do you cut GPU cost? (→ raise utilization via batching; right-size models)", costEn: "Idle GPUs burn money; utilization is the key economic metric." },
      asc: { role: "需要変動に合わせた台数制御。", tech: "キュー深度ベース＋予測スケーリングの併用。", biz: "LLMの需要は営業時間に張り付く。予測可能な波はリザーブ、突発は従量で。", qa: "LLMのオートスケールが難しい理由は？（→起動が分単位、モデルロードが重い、状態あり）", cost: "スケールイン判断の遅れが最も高くつく。閾値は下り側を攻める。", roleEn: "Autoscaler adjusting capacity to demand.", techEn: "Predictive scaling, warm pools, cold-start handling.", bizEn: "LLM serving has heavy startup. Naive scale-to-zero breaks SLOs.", qaEn: "Why not scale to zero? (→ cold starts miss latency SLOs)", costEn: "Keep a warm baseline; absorb bursts with batching headroom." },
      spd: { role: "小型モデルが下書きし、大型モデルが一括検証する高速化。", tech: "ドラフトモデル選定、棄却率の監視。", biz: "「品質を落とさず1.5〜3倍速」という説明が経営に一番通る最適化。", qa: "なぜ品質が落ちない？（→大型モデルが検証し不一致は棄却。出力分布は同一）", cost: "レイテンシ短縮＝同一GPUでの処理能力増＝実質値下げ。", roleEn: "Speculative decoding for faster generation.", techEn: "Draft model, verification, acceptance rate.", bizEn: "Speed without quality loss — the optimization execs approve fastest.", qaEn: "What is speculative decoding? (→ small model drafts, large verifies)", costEn: "1.5–3x speed at same quality; needs a good draft model." },
      mon: { role: "TTFT p95・TPOT・利用率・回答単価の継続計測。", tech: "パーセンタイル監視、系列長別の分解。", biz: "「平均は良いがp95が悪い」を検知できるかが運用の格。役員報告は単価/1K tokで。", qa: "平均でなくp95を見る理由は？（→体験を壊すのは裾。長文リクエストが偏在）", cost: "単価の週次トレンドが最適化投資の効果測定そのもの。", roleEn: "Monitors latency, throughput, and errors.", techEn: "Metrics, tracing, SLO alerting.", bizEn: "You can't operate serving blind. Monitoring is table stakes.", qaEn: "What do you monitor in serving? (→ TTFT, throughput, error rate, cost)", costEn: "Monitoring cost is negligible vs an undetected outage." }
    }
