    details: {
      req: { role: "推論リクエスト。プロンプト長・共通接頭辞・同時実行数がKVキャッシュ負荷を決める。", tech: "入力トークン列、コンテキスト長、バッチ内の並行リクエスト。", biz: "「どんな入力か」がコストの入力変数。共通接頭辞が多いほど再利用余地が大きい。", qa: "KVキャッシュ負荷は何で決まる？（→文脈長×バッチ×層数×ヘッド次元）", cost: "長文脈×大バッチほどKVがGPUメモリを食い、台数を押し上げる。", roleEn: "The inference request. Prompt length, common prefix, and concurrency decide KV-cache load.", techEn: "Input token sequence, context length, concurrent requests in a batch.", bizEn: "'What kind of input' is the cost variable. More common prefix means more reuse headroom.", qaEn: "What decides KV-cache load? (→ context length × batch × layers × head dim)", costEn: "Long context × large batch makes KV eat GPU memory, pushing up GPU count." },
      prefix: { role: "システムプロンプトや長文書など共通接頭辞のKVを保存し、再計算を省く。", tech: "接頭辞ハッシュ、KV再利用、自動プレフィックスキャッシュ（vLLM/SGLang）。", biz: "エージェント・RAG・コード補助で絶大。共通接頭辞の比率がそのまま削減率になる。", qa: "プレフィックスキャッシュが効く条件は？（→同一接頭辞の反復。応答再利用のセマンティックキャッシュとは別層）", cost: "プレフィルコストと初動遅延（TTFT）を同時に削る。最大90%減の報告も。", roleEn: "Stores the KV of a common prefix (system prompt, long doc) to skip recomputation.", techEn: "Prefix hashing, KV reuse, automatic prefix caching (vLLM/SGLang).", bizEn: "Huge for agents, RAG, coding assistants. The prefix share becomes the reduction rate.", qaEn: "When does prefix cache help? (→ repeated identical prefixes; a different layer from response-level semantic cache)", costEn: "Cuts prefill cost and TTFT at once; up to 90% reduction reported." },
      gqa: { role: "注意ヘッドがKVペアを共有し、KVキャッシュのメモリと帯域を減らす。", tech: "Grouped-Query（グループ共有）/ Multi-Query（単一共有）。", biz: "Llama/Mistral等の定番。MLAより単純だが品質/メモリのトレードオフがある。", qa: "GQAとMQAの違いは？（→GQAはグループ単位、MQAは全ヘッドで単一KVを共有）", cost: "メモリ帯域を減らしデコード速度を上げる、確立された標準手法。", roleEn: "Attention heads share KV pairs, reducing KV-cache memory and bandwidth.", techEn: "Grouped-Query (group sharing) / Multi-Query (single shared KV).", bizEn: "A staple in Llama/Mistral. Simpler than MLA but with a quality/memory trade-off.", qaEn: "GQA vs MQA? (→ GQA shares KV per group, MQA shares a single KV across all heads)", costEn: "Reduces memory bandwidth and speeds decode; an established standard." },
      mla: { role: "Key/Valueを共有の低ランク潜在空間に圧縮してキャッシュし、ヘッドごとに復元。", tech: "低ランク潜在射影、潜在KVキャッシュ（DeepSeek-V2）。", biz: "KVを大幅削減し128K級長文脈を安価に。長文脈が本質のアーキで効く。", qa: "MLAの勘所は？（→圧縮潜在だけを保持し品質を保ちつつKVを激減）", cost: "KVキャッシュを桁で削り、長文脈サービングの単価を下げる。", roleEn: "Compresses Key/Value into a shared low-rank latent space for caching, reconstructing per head.", techEn: "Low-rank latent projection, latent KV cache (DeepSeek-V2).", bizEn: "Slashes KV to serve 128K-class context cheaply. Wins where long context is essential.", qaEn: "The crux of MLA? (→ keep only compressed latents, slashing KV while preserving quality)", costEn: "Cuts the KV cache by an order of magnitude, lowering long-context serving cost." },
      paged: { role: "KVキャッシュを固定サイズのページに分割し、OSの仮想メモリのように非連続配置。", tech: "ページテーブル、非連続ブロック割当、断片化排除（vLLM）。", biz: "KVの過剰予約と断片化を無くし、GPUあたりの同時実行数を上げる標準基盤。", qa: "PagedAttentionの効果は？（→断片化排除で2〜4倍のスループット）", cost: "同じGPUでより多くのリクエストを捌き、トークン単価を直接下げる。", roleEn: "Splits the KV cache into fixed-size pages placed non-contiguously, like OS virtual memory.", techEn: "Page table, non-contiguous block allocation, fragmentation removal (vLLM).", bizEn: "Eliminates KV over-reservation and fragmentation, raising concurrency per GPU. A standard base.", qaEn: "Effect of PagedAttention? (→ 2–4x throughput by removing fragmentation)", costEn: "Serves more requests on the same GPU, directly lowering token unit cost." },
      quant: { role: "KVキャッシュ自体を低精度（FP8/INT等）に量子化し、メモリと帯域をさらに削る。", tech: "KV量子化、per-channel/per-token スケール、精度と品質のトレードオフ。", biz: "MLA/GQAと直交して効く。長文脈のメモリをもう一段削れる。", qa: "KV量子化の注意点は？（→過度な低精度は長文脈で品質劣化。実測が必須）", cost: "KVメモリをさらに圧縮し、より長い文脈やより大きなバッチを可能に。", roleEn: "Quantizes the KV cache itself to low precision (FP8/INT), further cutting memory and bandwidth.", techEn: "KV quantization, per-channel/per-token scaling, precision/quality trade-off.", bizEn: "Works orthogonally to MLA/GQA. Shaves long-context memory one more notch.", qaEn: "Caveat of KV quantization? (→ too-low precision degrades long-context quality; measure)", costEn: "Compresses KV memory further, enabling longer context or larger batches." },
      serve: { role: "上記の最適化を束ねて実行するサービング基盤。連続バッチング・分離サービングと連携。", tech: "連続バッチング、チャンクドプレフィル、プレフィル/デコード分離、投機的デコード。", biz: "個々の最適化はエンジン上で合成される。全体で単価と遅延を最小化する。", qa: "サービング最適化の適用順は？（→連続バッチング→キャッシュ→量子化→大規模なら分離）", cost: "最適化の合成で、同一ハードのスループットを最大化する。", roleEn: "The serving platform that combines these optimizations, coordinating with continuous batching and disaggregation.", techEn: "Continuous batching, chunked prefill, prefill/decode disaggregation, speculative decoding.", bizEn: "Individual optimizations compose on the engine, minimizing cost and latency overall.", qaEn: "Order of applying serving optimizations? (→ continuous batching → caching → quantization → disaggregation at scale)", costEn: "Composing optimizations maximizes throughput on the same hardware." },
      cost: { role: "最終的なトークン単価と体感遅延（TTFT/TBT）。全ての最適化がここに集約される。", tech: "コスト/トークン、TTFT、トークン間遅延、GPU利用率。", biz: "「1回答いくら・どれだけ速いか」が事業のKPI。最適化の成果はここで測る。", qa: "何を最適化目標にする？（→SLOを満たす最小コスト。TTFTと単価は別々に最適化可能）", cost: "全ての技術選択がトークン単価と遅延に集約される。ここを数字で語る。", roleEn: "Final token unit cost and perceived latency (TTFT/TBT). All optimizations converge here.", techEn: "Cost/token, TTFT, inter-token latency, GPU utilization.", bizEn: "'Cost per answer and how fast' is the business KPI. Optimization results are measured here.", qaEn: "What is the optimization target? (→ minimum cost meeting the SLO; TTFT and unit cost can be optimized separately)", costEn: "Every technical choice converges into token unit cost and latency — speak in these numbers." }
    }
