// ===== 問題バンク（クイズ用・抜粋。全問は元データを保持）=====
// 注: 元の全BANK配列をそのまま保持
const BANK = [{"d": "D1", "q": "オンプレミス(自社データセンター)環境と比較して、SaaS(Software as a Service)モデルでは責任共有モデル上、顧客の責任範囲はどうなりますか?", "o": ["顧客の責任範囲は減少し、データやアクセス管理などに限定される", "顧客の責任範囲は変わらず、常にすべての責任を負う　　　　　　", "顧客の責任範囲はゼロになり、何も管理しない", "顧客の責任範囲はオンプレミスより増加する"], "a": 0, "e": "SaaSではMicrosoftがインフラやアプリのほとんどを管理し、顧客はデータ、デバイス、アカウント、アクセス管理などに責任が限定されます。", "qEn": "Compared with an on-premises (self-managed datacenter) environment, how does the customer's responsibility change under the shared responsibility model in a SaaS (Software as a Service) model?", "oEn": ["The customer's responsibility decreases and becomes limited to areas such as data and access management", "The customer's responsibility stays the same and the customer remains responsible for everything", "The customer's responsibility becomes zero and the customer manages nothing", "The customer's responsibility increases compared with on-premises"], "eEn": "In SaaS, Microsoft manages most of the infrastructure and application, so the customer's responsibility is limited to items such as data, devices, accounts, and access management.", "oe": ["SaaSではMicrosoftが大部分を管理するため、顧客の責任はデータやアクセス管理に限定される。", "SaaSでもMicrosoftが多くを管理するため、顧客が常にすべての責任を負うわけではない。", "顧客もデータやアカウント、アクセス管理には引き続き責任を負うため、責任がゼロにはならない。", "責任範囲はクラウド化が進むほど縮小するため、オンプレミスより増加することはない。"], "oeEn": ["In SaaS, Microsoft manages most of the stack, so the customer's responsibility is limited to items like data and access management.", "Since Microsoft manages much of a SaaS environment, the customer does not always bear full responsibility for everything.", "Customers still remain responsible for data, accounts, and access management, so their responsibility never reaches zero.", "Responsibility shrinks as you move toward SaaS, so it never increases compared with on-premises."], "ref": "参考: Microsoft Azure 責任共有モデル (Shared Responsibility Model)", "refEn": "Ref: Microsoft Azure Shared Responsibility Model"}, {"d": "D1", "q": "クラウドサービスの種類(IaaS/PaaS/SaaS)にかかわらず、常にMicrosoftが責任を持つ項目はどれですか?", "o": ["ユーザーアカウントとID", "物理的なホストとネットワークインフラ", "データの分類", "エンドポイント(デバイス)の保護　　"], "a": 1, "e": "物理的なデータセンターやホスト、ネットワークインフラの管理はクラウドの提供形態を問わず常にMicrosoftの責任です。", "qEn": "Regardless of the type of cloud service (IaaS/PaaS/SaaS), which item is always Microsoft's responsibility?", "oEn": ["User accounts and identities", "The physical hosts and network infrastructure", "Data classification", "Protecting endpoints (devices)"], "eEn": "Management of the physical datacenter, hosts, and network infrastructure is always Microsoft's responsibility regardless of the cloud service model.", "oe": ["ユーザーアカウントとIDの管理は、クラウド形態を問わず常に顧客側の責任である。", "物理データセンター・ホスト・ネットワークインフラの管理はクラウド提供形態によらず常にMicrosoftの責任。", "データの分類は顧客が行う責任であり、Microsoftが常に担うものではない。", "エンドポイント(デバイス)の保護は多くの場合顧客の責任範囲に含まれる。"], "oeEn": ["Managing user accounts and identities is always the customer's responsibility, regardless of the cloud model.", "Managing the physical datacenter, hosts, and network infrastructure is always Microsoft's responsibility in every cloud model.", "Classifying data is the customer's responsibility, not something Microsoft always handles.", "Protecting endpoints (devices) is typically part of the customer's responsibility."], "ref": "参考: Microsoft Azure 責任共有モデル (Shared Responsibility Model)", "refEn": "Ref: Microsoft Azure Shared Responsibility Model"}, {"d": "D1", "q": "責任共有モデルにおいて、クラウド利用形態(オンプレミス→IaaS→PaaS→SaaS)が進むにつれて一般的にどのような変化が起きますか?", "o": ["顧客の責任が一定のまま変わらない", "顧客の責任範囲が拡大し、Microsoftの責任範囲が縮小する", "Microsoftの責任範囲が拡大し、顧客の責任範囲が縮小する", "両者の責任が完全になくなる"], "a": 2, "e": "オンプレミスからIaaS、PaaS、SaaSへ移行するにつれて、Microsoftが管理する範囲が広がり、顧客の責任範囲は相対的に縮小します。", "qEn": "In the shared responsibility model, as you move along on-premises → IaaS → PaaS → SaaS, what change generally occurs?", "oEn": ["The customer's responsibility stays constant and does not change", "The customer's responsibility expands while Microsoft's responsibility shrinks", "Microsoft's responsibility expands while the customer's responsibility shrinks", "Both parties' responsibilities disappear completely"], "eEn": "Moving from on-premises to IaaS, PaaS, and SaaS, the scope Microsoft manages expands, and the customer's responsibility shrinks accordingly.", "oe": ["オンプレミスからSaaSに進むにつれ責任範囲は変化するため、一定のままではない。", "実際には逆で、クラウド化が進むほど顧客の責任は縮小し、Microsoftの責任が拡大する。", "IaaS→PaaS→SaaSと進むほどMicrosoftの管理範囲が広がり、顧客の責任は相対的に縮小する。", "クラウド利用でも顧客にはデータやアクセス管理などの責任が残るため、両者ともゼロにはならない。"], "oeEn": ["Responsibility changes as you move from on-premises to SaaS, so it does not stay constant.", "The opposite is true: as cloud adoption deepens, customer responsibility shrinks while Microsoft's responsibility expands.", "Moving through IaaS, PaaS, and SaaS, Microsoft's managed scope grows while the customer's responsibility shrinks accordingly.", "Customers retain responsibilities like data and access management even in the cloud, so neither side's responsibility reaches zero."], "ref": "参考: Microsoft Azure 責任共有モデル (Shared Responsibility Model)", "refEn": "Ref: Microsoft Azure Shared Responsibility Model"}, {"d": "D1", "q": "IaaS(Infrastructure as a Service)モデルにおいて、顧客が責任を持つ項目として正しいものはどれですか?", "o": ["物理データセンターの警備", "ネットワークコントローラーのパッチ適用", "物理ネットワークの配線", "オペレーティングシステムの管理"], "a": 3, "e": "IaaSでは顧客がOS、ミドルウェア、アプリ、データを管理する責任を持ちます。物理層やネットワークコントローラーはMicrosoftの責任です。", "qEn": "In the IaaS (Infrastructure as a Service) model, which item is the customer responsible for?", "oEn": ["Physical datacenter security", "Patching the network controller", "Physical network cabling", "Managing the operating system"], "eEn": "In IaaS, the customer is responsible for managing the OS, middleware, applications, and data. The physical layer and network controller remain Microsoft's responsibility.", "oe": ["物理データセンターの警備はIaaSでもMicrosoftの責任であり、顧客の責任ではない。", "ネットワークコントローラーのパッチ適用はMicrosoftが担当するインフラ層の責任。", "物理ネットワークの配線はMicrosoftが管理する物理インフラの一部。", "IaaSでは顧客がOS、ミドルウェア、アプリ、データの管理責任を負う。"], "oeEn": ["Physical datacenter security remains Microsoft's responsibility even in IaaS, not the customer's.", "Patching the network controller is part of the infrastructure layer that Microsoft manages.", "Physical network cabling is part of the physical infrastructure that Microsoft manages.", "In IaaS, the customer is responsible for managing the OS, middleware, applications, and data."], "ref": "参考: Microsoft Azure IaaS 責任共有モデル", "refEn": "Ref: Microsoft Azure IaaS Shared Responsibility Model"}, {"d": "D1", "q": "「多層防御(Defense in Depth)」の目的として最も適切なものはどれですか?", "o": ["複数の防御層を組み合わせ、1つの層が突破されても攻撃を遅延・阻止する", "単一の強力なセキュリティ製品にすべてを依存させる", "セキュリティ対策を一つの層に集約しコストを削減する　　　　　　　　　", "物理的なセキュリティのみを強化する"], "a": 0, "e": "多層防御は複数の防御層を組み合わせることで、いずれか一つの層が突破されても攻撃者の侵入を遅延・阻止することを目的とします。", "qEn": "What is the most appropriate purpose of \"Defense in Depth\"?", "oEn": ["Combining multiple layers of defense so that even if one layer is breached, the attack is delayed or stopped", "Relying on a single powerful security product for everything", "Consolidating security measures into a single layer to reduce cost", "Strengthening only physical security"], "eEn": "Defense in depth combines multiple layers of defense so that even if one layer is breached, the attacker's progress is delayed or stopped.", "oe": ["複数の防御層を組み合わせることで、一層が突破されても攻撃を遅延・阻止できる。", "単一製品への依存は、その製品が突破された場合に全体が無防備になるリスクがある。", "一つの層に集約するとその層が破られた際に防御全体が機能しなくなる。", "物理セキュリティのみでは、ネットワークやID層などへの攻撃を防げない。"], "oeEn": ["Combining multiple layers of defense means that even if one layer is breached, the attack is delayed or stopped.", "Relying on a single product creates risk: if that product is defeated, the whole system is left undefended.", "Consolidating into one layer means the entire defense fails once that single layer is breached.", "Physical security alone cannot stop attacks targeting the network or identity layers."], "ref": "参考: Microsoft Defense in Depth モデル", "refEn": "Ref: Microsoft Defense in Depth model"}, {"d": "D1", "q": "Microsoftが示す多層防御モデルにおいて、最も内側(データに最も近い)に位置する層はどれですか?", "o": ["物理層", "データ層", "ネットワーク層", "ID・アクセス層"], "a": 1, "e": "多層防御モデルはデータを中心に、アプリケーション、コンピューティング、ネットワーク、境界、ID・アクセス、物理層が同心円状に配置されます。", "qEn": "In Microsoft's defense-in-depth model, which layer is positioned innermost (closest to the data)?", "oEn": ["Physical layer", "Data layer", "Network layer", "Identity and access layer"], "eEn": "The defense-in-depth model is arranged concentrically around the data layer, surrounded by application, compute, network, perimeter, identity and access, and physical layers.", "oe": ["物理層は多層防御モデルの最も外側に位置する層。", "データ層はモデルの中心に位置し、最も内側で保護される対象。", "ネットワーク層はデータ層よりも外側に位置する。", "ID・アクセス層はデータ層より外側の層に位置する。"], "oeEn": ["The physical layer sits at the outermost position of the defense-in-depth model.", "The data layer sits at the center of the model, the innermost asset being protected.", "The network layer is positioned further outward than the data layer.", "The identity and access layer sits outward from the data layer."], "ref": "参考: Microsoft Defense in Depth モデル", "refEn": "Ref: Microsoft Defense in Depth model"}, {"d": "D1", "q": "多層防御モデルにおける「境界(Perimeter)」層の主な役割は何ですか?", "o": ["サーバーのOSにパッチを適用する", "ハッシュ関数でデータの整合性を検証する　　　　　　　　　　　　　　　", "分散型サービス拒否(DDoS)攻撃などからネットワーク境界を保護する", "ユーザーのパスワードポリシーを設定する"], "a": 2, "e": "境界層は、DDoS攻撃のフィルタリングやネットワーク境界での不正アクセス防止など、外部からの脅威から組織を保護する役割を担います。", "qEn": "What is the main role of the \"Perimeter\" layer in the defense-in-depth model?", "oEn": ["Patching the operating system on servers", "Verifying data integrity using a hash function", "Protecting the network perimeter from threats such as distributed denial-of-service (DDoS) attacks", "Setting user password policies"], "eEn": "The perimeter layer protects the organization from external threats, such as filtering DDoS attacks and preventing unauthorized access at the network boundary.", "oe": ["OSへのパッチ適用はコンピューティング層の役割であり、境界層の役割ではない。", "ハッシュ関数によるデータ整合性検証はデータ層に関わる対策。", "境界層はDDoS攻撃の遮断など、外部脅威からネットワーク境界を保護する役割を担う。", "パスワードポリシーの設定はID・アクセス層の役割。"], "oeEn": ["Patching the OS is a compute-layer task, not a perimeter-layer responsibility.", "Verifying data integrity with a hash function relates to the data layer, not the perimeter.", "The perimeter layer protects the network boundary from external threats such as DDoS attacks.", "Setting password policies belongs to the identity and access layer."], "ref": "参考: Microsoft Defense in Depth モデル", "refEn": "Ref: Microsoft Defense in Depth model"}, {"d": "D1", "q": "多層防御モデルにおいて、「ID とアクセス」層が担う主な役割は何ですか?", "o": ["物理サーバーの盗難防止", "ネットワークファイアウォールの設定　　　　　　　　　　　　　　", "データセンターの温度管理", "適切なユーザーのみが適切なリソースにアクセスできるよう制御する"], "a": 3, "e": "ID・アクセス層は、認証・認可の仕組みを通じて適切なユーザーのみが適切なリソースにアクセスできるよう制御します。", "qEn": "In the defense-in-depth model, what is the main role of the \"Identity and access\" layer?", "oEn": ["Preventing theft of physical servers", "Configuring network firewall rules", "Managing datacenter temperature", "Controlling access so only the right users can reach the right resources"], "eEn": "The identity and access layer controls access, through authentication and authorization, so that only the right users can reach the right resources.", "oe": ["物理サーバーの盗難防止は物理層の役割。", "ネットワークファイアウォールの設定はネットワーク層の役割。", "データセンターの温度管理は物理層の運用管理事項。", "ID・アクセス層は認証・認可により適切なユーザーのみが適切なリソースにアクセスできるよう制御する。"], "oeEn": ["Preventing theft of physical servers falls under the physical layer.", "Configuring network firewall rules is a network-layer responsibility.", "Managing datacenter temperature is an operational task within the physical layer.", "The identity and access layer uses authentication and authorization to ensure only the right users reach the right resources."], "ref": "参考: Microsoft Defense in Depth モデル", "refEn": "Ref: Microsoft Defense in Depth model"}, {"d": "D1", "q": "Zero Trustモデルの3つの指針(guiding principles)に含まれないものはどれですか?", "o": ["境界防御のみを信頼する(Trust the network perimeter)", "明示的に確認する(Verify explicitly)", "侵害を想定する(Assume breach)", "最小権限アクセスを使用する(Use least privilege access)"], "a": 0, "e": "Zero Trustの3つの指針は「明示的に確認する」「最小権限アクセスを使用する」「侵害を想定する」です。境界防御のみを信頼する考え方はZero Trustとは相反します。", "qEn": "Which of the following is NOT one of the three guiding principles of the Zero Trust model?", "oEn": ["Trust the network perimeter", "Verify explicitly", "Assume breach", "Use least privilege access"], "eEn": "The three guiding principles of Zero Trust are \"verify explicitly,\" \"use least privilege access,\" and \"assume breach.\" Trusting only the network perimeter contradicts the Zero Trust approach.", "oe": ["「境界防御のみを信頼する」という考え方はZero Trustの原則ではなく、旧来の境界防御モデルの発想。", "「明示的に確認する」はZero Trustの3原則の一つであるため、正解(除外対象)ではない。", "「侵害を想定する」はZero Trustの3原則の一つであるため、正解(除外対象)ではない。", "「最小権限アクセスを使用する」はZero Trustの3原則の一つであるため、正解(除外対象)ではない。"], "oeEn": ["\"Trust the network perimeter\" is not a Zero Trust principle; it reflects the older perimeter-defense mindset.", "\"Verify explicitly\" is one of the three Zero Trust guiding principles, so it is not the excluded item.", "\"Assume breach\" is one of the three Zero Trust guiding principles, so it is not the excluded item.", "\"Use least privilege access\" is one of the three Zero Trust guiding principles, so it is not the excluded item."], "ref": "参考: Microsoft Zero Trust ガイダンス (3つの指針)", "refEn": "Ref: Microsoft Zero Trust guiding principles"}, {"d": "D1", "q": "Zero Trustの原則「明示的に確認する(Verify explicitly)」が意味する内容として最も適切なものはどれですか?", "o": ["社内ネットワークからのアクセスは常に信頼する　　　　　　　　　", "利用可能なすべてのデータポイントに基づいて常に認証・認可を行う", "一度認証されたユーザーは以後確認を省略する", "VPN接続さえあれば追加の確認は不要とする"], "a": 1, "e": "「明示的に確認する」とは、ユーザーID、場所、デバイスの健全性などあらゆる利用可能なデータポイントに基づいて、常に認証・認可を行うという原則です。", "qEn": "What does the Zero Trust principle \"Verify explicitly\" most appropriately mean?", "oEn": ["Always trust access coming from the internal corporate network", "Always authenticate and authorize based on all available data points", "Skip further verification once a user has been authenticated once", "Additional verification is unnecessary as long as there is a VPN connection"], "eEn": "\"Verify explicitly\" means always authenticating and authorizing based on all available data points, such as user identity, location, and device health.", "oe": ["社内ネットワークだからと無条件に信頼するのはZero Trustの考え方に反する。", "「明示的に確認する」はID、場所、デバイスの健全性など利用可能な全データポイントに基づき常に認証・認可を行うこと。", "一度の認証で確認を省略することはZero Trustの継続的な検証の考え方に反する。", "VPN接続だけを根拠に追加確認を省略するのは境界防御の発想でありZero Trustに反する。"], "oeEn": ["Trusting access unconditionally just because it comes from the internal network contradicts Zero Trust.", "\"Verify explicitly\" means always authenticating and authorizing using all available data points, such as identity, location, and device health.", "Skipping further checks after one authentication contradicts Zero Trust's principle of continuous verification.", "Relying only on a VPN connection to skip further checks reflects perimeter-based thinking, which contradicts Zero Trust."], "ref": "参考: Microsoft Zero Trust ガイダンス (Verify explicitly)", "refEn": "Ref: Microsoft Zero Trust guidance (Verify explicitly)"}, {"d": "D1", "q": "Zero Trustの原則「侵害を想定する(Assume breach)」に基づく実践として適切なものはどれですか?", "o": ["侵害は発生しないと仮定してモニタリングを最小限にする　　　　　　", "一度の認証で全リソースへの永続アクセスを許可する", "通信を暗号化し、侵害範囲を制限するようにセグメント化・監視を行う", "内部ネットワークのトラフィックは検査しない"], "a": 2, "e": "「侵害を想定する」原則では、通信の暗号化、ネットワークのセグメント化、継続的な監視によって侵害の影響範囲を最小限に抑えることを重視します。", "qEn": "Which practice reflects the Zero Trust principle \"Assume breach\"?", "oEn": ["Assuming a breach will never happen and keeping monitoring to a minimum", "Granting permanent access to all resources after a single authentication", "Encrypting communications and using segmentation and monitoring to limit the blast radius of a breach", "Not inspecting traffic on the internal network"], "eEn": "The \"assume breach\" principle emphasizes minimizing the blast radius of a breach through encrypted communications, network segmentation, and continuous monitoring.", "oe": ["侵害は必ず発生しうると想定し、モニタリングを強化するのが正しい姿勢。", "永続的な全リソースアクセスを許可すると侵害時の被害範囲が拡大してしまう。", "通信の暗号化やセグメント化、監視により侵害時の影響範囲を最小化するのが「侵害を想定する」の実践。", "内部トラフィックを検査しないと侵害の拡大を早期に検知できない。"], "oeEn": ["The correct stance is to assume a breach can always happen and to strengthen monitoring accordingly.", "Granting permanent access to all resources would widen the blast radius if a breach occurs.", "Encrypting communications, segmenting networks, and monitoring continuously is how \"assume breach\" limits the impact of a breach.", "Failing to inspect internal traffic prevents early detection of a spreading breach."], "ref": "参考: Microsoft Zero Trust ガイダンス (Assume breach)", "refEn": "Ref: Microsoft Zero Trust guidance (Assume breach)"}, {"d": "D1", "q": "Microsoftが提唱するZero Trustの6つの防御領域(pillars)に含まれないものはどれですか?", "o": ["ID(Identities)", "デバイス(Devices)", "データ(Data)", "予算(Budget)"], "a": 3, "e": "Zero Trustの6つの防御領域はID、デバイス、アプリケーション、データ、インフラストラクチャ、ネットワークです。予算はこれに含まれません。", "qEn": "Which of the following is NOT one of the six Zero Trust defense pillars proposed by Microsoft?", "oEn": ["Identities", "Devices", "Data", "Budget"], "eEn": "The six Zero Trust pillars are identities, devices, applications, data, infrastructure, and network. Budget is not one of them.", "oe": ["IDはZero Trustの6つの防御領域の一つであり、除外対象ではない。", "デバイスはZero Trustの6つの防御領域の一つであり、除外対象ではない。", "データはZero Trustの6つの防御領域の一つであり、除外対象ではない。", "予算はZero Trustの6つの防御領域には含まれない項目。"], "oeEn": ["Identities is one of the six Zero Trust pillars, so it is not the excluded item.", "Devices is one of the six Zero Trust pillars, so it is not the excluded item.", "Data is one of the six Zero Trust pillars, so it is not the excluded item.", "Budget is not one of the six Zero Trust defense pillars."], "ref": "参考: Microsoft Zero Trust の6つの防御領域", "refEn": "Ref: Microsoft Zero Trust six defense pillars"}, {"d": "D1", "q": "Zero Trustの6つの防御領域のうち、「ネットワーク」領域で重視される対策はどれですか?", "o": ["ネットワークのセグメント化とリアルタイムの脅威検出", "パスワードレス認証の導入", "デバイスのコンプライアンス状態の確認　　　　　　　", "データの機密度分類"], "a": 0, "e": "ネットワーク領域では、ネットワークのセグメント化やマイクロセグメンテーション、リアルタイムの脅威検出・防御が重視されます。", "qEn": "Among the six Zero Trust pillars, which measure is emphasized in the \"Network\" pillar?", "oEn": ["Network segmentation and real-time threat detection", "Adopting passwordless authentication", "Checking device compliance status", "Classifying data sensitivity"], "eEn": "The network pillar emphasizes network segmentation, micro-segmentation, and real-time threat detection and prevention.", "oe": ["ネットワーク領域ではセグメント化やマイクロセグメンテーション、リアルタイム脅威検出が重視される。", "パスワードレス認証の導入はID領域の対策。", "デバイスのコンプライアンス確認はデバイス領域の対策。", "データの機密度分類はデータ領域の対策。"], "oeEn": ["The network pillar emphasizes segmentation, micro-segmentation, and real-time threat detection.", "Adopting passwordless authentication is a measure within the identities pillar.", "Checking device compliance status is a measure within the devices pillar.", "Classifying data sensitivity is a measure within the data pillar."], "ref": "参考: Microsoft Zero Trust ネットワーク領域", "refEn": "Ref: Microsoft Zero Trust Network pillar"}, {"d": "D1", "q": "Zero Trustの6つの防御領域における「アプリケーション」領域の目的として適切なものはどれですか?", "o": ["物理サーバーの電源管理を行う", "シャドーITを発見し、適切な権限とアクセス制御を適用する", "ハッシュ値によるファイル整合性の検証のみを行う　　　　　", "DNSサーバーの冗長化を行う"], "a": 1, "e": "アプリケーション領域では、組織内で使われるシャドーITを可視化・発見し、適切な権限やアクセス制御、監視を適用することが目的です。", "qEn": "What is the appropriate goal of the \"Applications\" pillar among the six Zero Trust pillars?", "oEn": ["Managing power supply for physical servers", "Discovering shadow IT and applying appropriate permissions and access controls", "Only verifying file integrity using hash values", "Adding redundancy to DNS servers"], "eEn": "The applications pillar aims to gain visibility into and discover shadow IT used within the organization, and apply appropriate permissions, access controls, and monitoring.", "oe": ["物理サーバーの電源管理はインフラストラクチャ領域や物理層の対策。", "アプリケーション領域ではシャドーITを発見し、適切な権限とアクセス制御を適用することが目的。", "ハッシュ値による整合性検証のみでは、アプリケーション領域の目的を満たさない。", "DNSサーバーの冗長化はインフラストラクチャ領域の対策。"], "oeEn": ["Managing power supply for physical servers relates to the infrastructure or physical layer, not applications.", "The applications pillar aims to discover shadow IT and apply appropriate permissions and access controls.", "Verifying integrity with hash values alone does not fulfill the applications pillar's goal.", "Adding DNS redundancy is an infrastructure-pillar measure, not an applications-pillar one."], "ref": "参考: Microsoft Zero Trust アプリケーション領域", "refEn": "Ref: Microsoft Zero Trust Applications pillar"}, {"d": "D1", "q": "対称暗号化(symmetric encryption)の特徴として正しいものはどれですか?", "o": ["暗号化と復号に異なる鍵を使用する", "鍵を一切使用せずデータを変換する", "暗号化と復号に同じ鍵を使用する", "元のデータに復元できない一方向の変換を行う"], "a": 2, "e": "対称暗号化は暗号化と復号に同一の鍵を使用する方式で、AESなどが代表例です。異なる鍵を使うのは非対称暗号化です。", "qEn": "What is a correct characteristic of symmetric encryption?", "oEn": ["It uses different keys for encryption and decryption", "It transforms data without using any key at all", "It uses the same key for both encryption and decryption", "It performs a one-way transformation that cannot be reversed to the original data"], "eEn": "Symmetric encryption uses the same key for both encryption and decryption; AES is a representative example. Using different keys describes asymmetric encryption.", "oe": ["異なる鍵を使うのは非対称暗号化の特徴であり、対称暗号化ではない。", "対称暗号化は鍵を使用してデータを変換する方式であり、鍵を使わないわけではない。", "対称暗号化は暗号化と復号に同一の鍵を使用する方式で、AESなどが代表例。", "復元不能な一方向変換はハッシュ関数の特徴であり、対称暗号化ではない。"], "oeEn": ["Using different keys describes asymmetric encryption, not symmetric encryption.", "Symmetric encryption does use a key to transform data; it does not omit key usage.", "Symmetric encryption uses the same key for both encryption and decryption, with AES as a representative example.", "An irreversible one-way transformation describes a hash function, not symmetric encryption."], "ref": "参考: NIST FIPS 197 (AES) / 対称鍵暗号", "refEn": "Ref: NIST FIPS 197 (AES) / symmetric-key encryption"}, {"d": "D1", "q": "非対称暗号化(asymmetric encryption)の説明として正しいものはどれですか?", "o": ["送信者と受信者が同一の秘密鍵を事前に共有する必要がある　　　　　　　　　　　", "ハッシュ値を生成し、元のデータには戻せない", "暗号化処理が対称暗号化より常に高速である", "公開鍵と秘密鍵のペアを使用し、一方で暗号化した内容はもう一方でのみ復号できる"], "a": 3, "e": "非対称暗号化は公開鍵と秘密鍵のペアを使用し、一方の鍵で暗号化したデータはもう一方の鍵でしか復号できない仕組みです。RSAが代表例です。", "qEn": "Which statement correctly describes asymmetric encryption?", "oEn": ["The sender and receiver must share the same private key in advance", "It generates a hash value and cannot be reversed to the original data", "Its encryption processing is always faster than symmetric encryption", "It uses a public/private key pair, where data encrypted with one key can only be decrypted with the other"], "eEn": "Asymmetric encryption uses a public/private key pair, where data encrypted with one key can only be decrypted with the other. RSA is a representative example."}, {"d": "D1", "q": "ハッシュ化(hashing)と暗号化(encryption)の最も重要な違いは何ですか?", "o": ["ハッシュ化は不可逆な一方向変換であり、暗号化はデータを復号して元に戻せる", "ハッシュ化は可逆(元のデータに戻せる)だが暗号化は不可逆である　　　　　", "両者はまったく同じ処理でありデータの機密性のためだけに使われる", "暗号化には鍵が不要だがハッシュ化には鍵が必須である"], "a": 0, "e": "ハッシュ化は元のデータに戻せない一方向の変換であるのに対し、暗号化は鍵を用いてデータを復号し元に戻すことができる点が最大の違いです。", "qEn": "What is the most important difference between hashing and encryption?", "oEn": ["Hashing is an irreversible one-way transformation, while encryption can be decrypted to recover the original data", "Hashing is reversible (can be restored to the original data) but encryption is irreversible", "Both are exactly the same process and are used solely for data confidentiality", "Encryption requires no key, but hashing always requires a key"], "eEn": "The key difference is that hashing is a one-way transformation that cannot be reversed to the original data, whereas encryption can be decrypted back to the original data using a key."}, {"d": "D1", "q": "ハッシュ関数が主に使用される用途として最も適切なものはどれですか?", "o": ["転送中のデータを第三者から読めないよう秘匿する", "データの改ざんを検出するための整合性検証", "大量データの圧縮によるストレージ削減", "ネットワーク帯域幅の最適化"], "a": 1, "e": "ハッシュ関数は主にデータが改ざんされていないかを検証する整合性チェックのために使用されます。データの秘匿には暗号化が使われます。", "qEn": "What is the most appropriate primary use of a hash function?", "oEn": ["Keeping data confidential from third parties while in transit", "Integrity verification to detect whether data has been tampered with", "Reducing storage through compression of large amounts of data", "Optimizing network bandwidth"], "eEn": "Hash functions are primarily used for integrity checks to verify that data has not been tampered with. Encryption, not hashing, is used to keep data confidential."}, {"d": "D1", "q": "「保存データの暗号化(encryption at rest)」が保護する対象として正しいものはどれですか?", "o": ["ネットワークを移動中のパケット", "メモリ上で一時的に処理中のデータのみ　　　　　　　　　　", "ディスクやデータベースなど記憶媒体に保存されているデータ", "ユーザーが入力するキーストロークのみ"], "a": 2, "e": "保存データの暗号化とは、ディスクやデータベースなどの記憶媒体に静止(保存)しているデータを暗号化して保護することを指します。", "qEn": "What does \"encryption at rest\" correctly protect?", "oEn": ["Packets that are moving across the network", "Only data being temporarily processed in memory", "Data stored on storage media such as disks and databases", "Only the keystrokes entered by a user"], "eEn": "Encryption at rest refers to encrypting and protecting data that is stationary (stored) on storage media such as disks and databases."}, {"d": "D1", "q": "「転送中のデータの暗号化(encryption in transit)」の例として最も適切なものはどれですか?", "o": ["ディスク全体を暗号化するBitLocker　　　　　　　　　　　　　　　　　　　　　　", "データベースの列レベル暗号化", "ハッシュ値によるパスワードの保存", "TLS(Transport Layer Security)を使用したWeb通信の暗号化"], "a": 3, "e": "転送中のデータの暗号化とは、ネットワークを移動しているデータを保護する仕組みで、TLSによるWeb通信の暗号化が代表例です。", "qEn": "Which is the most appropriate example of \"encryption in transit\"?", "oEn": ["BitLocker, which encrypts an entire disk", "Column-level encryption of a database", "Storing passwords as hash values", "Encrypting web communication using TLS (Transport Layer Security)"], "eEn": "Encryption in transit protects data while it is moving across a network; encrypting web communication with TLS is a representative example."}, {"d": "D1", "q": "GRC(ガバナンス、リスク、コンプライアンス)における「ガバナンス」が指す内容として最も適切なものはどれですか?", "o": ["組織の目標達成に向けて意思決定や監督の仕組みを整えるプロセス", "発生しうる脅威の可能性と影響を評価するプロセス", "法令や規制要件を満たしていることを証明するプロセス　　　　　", "攻撃者の侵入経路を特定するプロセス"], "a": 0, "e": "ガバナンスとは、組織の目標を達成するために意思決定、責任、監督の仕組みを整えるプロセスを指します。", "qEn": "In GRC (Governance, Risk, and Compliance), what does \"Governance\" most appropriately refer to?", "oEn": ["The process of establishing decision-making, accountability, and oversight to achieve organizational goals", "The process of assessing the likelihood and impact of potential threats", "The process of demonstrating that legal and regulatory requirements are met", "The process of identifying an attacker's intrusion path"], "eEn": "Governance refers to the process of establishing decision-making, accountability, and oversight mechanisms to help an organization achieve its goals."}, {"d": "D1", "q": "GRCにおける「リスク管理」の目的として最も適切なものはどれですか?", "o": ["規制当局への報告書を作成すること全般", "組織に影響を与えうるリスクを特定・評価し、対応策を講じること", "従業員の給与体系を管理すること", "ネットワーク機器のファームウェアを更新すること　　　　　　　"], "a": 1, "e": "リスク管理とは、組織に影響を与えうるリスクを特定・評価し、それに対する適切な対応策を講じるプロセスです。", "qEn": "What is the most appropriate purpose of \"risk management\" in GRC?", "oEn": ["Producing reports for regulators in general", "Identifying and assessing risks that could affect the organization and taking appropriate action", "Managing the employee compensation structure", "Updating firmware on network equipment"], "eEn": "Risk management is the process of identifying and assessing risks that could affect the organization and taking appropriate measures to address them."}, {"d": "D1", "q": "GRCにおける「コンプライアンス」が意味する内容として正しいものはどれですか?", "o": ["組織独自の内部ルールのみを指し、外部法令は含まない　　　", "セキュリティインシデントの技術的な調査プロセス", "法律、規制、業界標準など外部要件を組織が遵守していること", "ネットワークの物理的な冗長化構成"], "a": 2, "e": "コンプライアンスとは、法律、規制、業界標準といった外部要件を組織が遵守していることを指します。", "qEn": "What does \"Compliance\" correctly mean in GRC?", "oEn": ["It refers only to an organization's own internal rules and excludes external laws", "The technical investigation process for a security incident", "An organization adhering to external requirements such as laws, regulations, and industry standards", "Physical redundancy configuration of the network"], "eEn": "Compliance refers to an organization adhering to external requirements such as laws, regulations, and industry standards."}, {"d": "D1", "q": "Microsoft Purview コンプライアンス マネージャーが組織に提供する主な機能は何ですか?", "o": ["ネットワークのファイアウォール規則の自動生成　　　　　　　　　　　　　　　", "エンドポイントのウイルス駆除", "従業員の勤怠管理", "規制要件に対する組織の遵守状況を評価し、コンプライアンス スコアを提示する"], "a": 3, "e": "Compliance Managerは、規制やスタンダードに対する組織の遵守状況を評価し、改善アクションとともにコンプライアンス スコアを提示するツールです。", "qEn": "What is the main capability that Microsoft Purview Compliance Manager provides to an organization?", "oEn": ["Automatically generating network firewall rules", "Removing viruses from endpoints", "Managing employee attendance", "Assessing the organization's compliance against regulatory requirements and presenting a compliance score"], "eEn": "Compliance Manager assesses an organization's compliance against regulations and standards and presents a compliance score along with recommended improvement actions."}, {"d": "D1", "q": "提供形態(オンプレミス/IaaS/PaaS/SaaS)にかかわらず、常に顧客が責任を持つ項目はどれですか?", "o": ["情報とデータの分類・管理", "物理的なデータセンターの管理", "ネットワークコントローラー", "物理ネットワーク"], "a": 0, "e": "クラウドの提供形態にかかわらず、情報とデータの分類・管理、およびアカウントとIDの管理は常に顧客の責任です。", "qEn": "Regardless of the deployment model (on-premises/IaaS/PaaS/SaaS), which item is always the customer's responsibility?", "oEn": ["Classifying and managing information and data", "Managing the physical datacenter", "The network controller", "The physical network"], "eEn": "Regardless of the cloud deployment model, classifying and managing information and data, as well as managing accounts and identities, is always the customer's responsibility."}, {"d": "D1", "q": "多層防御モデルの「アプリケーション」層で行うべき対策として適切なものはどれですか?", "o": ["建物への入退室管理", "安全なコーディング手法の採用と脆弱性の除去", "電源バックアップの確保", "DNSキャッシュのクリア　　　　　　　　　"], "a": 1, "e": "アプリケーション層では、安全なコーディング手法(セキュアコーディング)の採用や脆弱性の管理・除去が重要な対策となります。", "qEn": "Which measure should be applied at the \"Application\" layer of the defense-in-depth model?", "oEn": ["Controlling entry and exit to a building", "Adopting secure coding practices and removing vulnerabilities", "Ensuring power backup", "Clearing the DNS cache"], "eEn": "At the application layer, adopting secure coding practices and managing and removing vulnerabilities are important measures."}, {"d": "D1", "q": "Zero Trustの原則「最小権限アクセスを使用する(Use least privilege access)」の実践例として最も適切なものはどれですか?", "o": ["すべてのユーザーに管理者権限を付与し利便性を高める　　　　　　　　　　　　　　　　", "一度付与した権限は永続的に維持し見直さない", "Just-In-Timeアクセスやリスクベースの適応型ポリシーでアクセスを制限する", "パスワードの複雑さ要件を撤廃する"], "a": 2, "e": "最小権限アクセスの原則では、Just-In-Timeアクセスやリスクベースの適応型ポリシーを用いて、必要最小限の権限のみを付与することが重視されます。", "qEn": "Which is the most appropriate example of practicing the Zero Trust principle \"Use least privilege access\"?", "oEn": ["Granting administrator privileges to all users for convenience", "Keeping granted privileges permanently without ever reviewing them", "Limiting access using Just-In-Time access and risk-based adaptive policies", "Removing password complexity requirements"], "eEn": "The least privilege access principle emphasizes granting only the minimum necessary privileges, using approaches such as Just-In-Time access and risk-based adaptive policies."}, {"d": "D1", "q": "対称暗号化アルゴリズムの代表例として正しいものはどれですか?", "o": ["RSA", "SHA-256　　　　　　　　　　　　　　　　　　　　　　　　　　", "ECDSA", "AES(Advanced Encryption Standard)"], "a": 3, "e": "AESは対称鍵暗号方式の代表例です。RSAとECDSAは非対称暗号、SHA-256はハッシュ関数です。", "qEn": "Which of the following is a representative example of a symmetric encryption algorithm?", "oEn": ["RSA", "SHA-256", "ECDSA", "AES (Advanced Encryption Standard)"], "eEn": "AES is a representative symmetric-key encryption algorithm. RSA and ECDSA are asymmetric encryption algorithms, and SHA-256 is a hash function."}, {"d": "D1", "q": "ハッシュ関数の特徴として正しいものはどれですか?", "o": ["入力データのサイズに関わらず固定長の出力(ハッシュ値)を生成する", "出力から元の入力データを常に復元できる　　　　　　　　　　　　　", "同じ入力から毎回異なる出力を生成する", "秘密鍵を用いて出力を復号できる"], "a": 0, "e": "ハッシュ関数は入力データのサイズに関わらず常に固定長の出力を生成し、同じ入力からは常に同じ出力が得られます。", "qEn": "Which is a correct characteristic of a hash function?", "oEn": ["It produces a fixed-length output (hash value) regardless of the size of the input data", "The original input data can always be recovered from the output", "It produces a different output each time for the same input", "The output can be decrypted using a private key"], "eEn": "A hash function always produces a fixed-length output regardless of the size of the input data, and the same input always yields the same output."}, {"d": "D1", "q": "組織が特定の規制(GDPRなど)に対する自社のコンプライアンス状況を継続的に監視し、改善アクションの推奨を受けられるMicrosoftのツールはどれですか?", "o": ["Microsoft Defender for Endpoint　　", "Microsoft Purview コンプライアンス マネージャー", "Azure Network Watcher", "Microsoft Sentinel"], "a": 1, "e": "Microsoft Purview コンプライアンス マネージャーは、特定の規制に対する組織のコンプライアンス状況を継続的に評価し、改善アクションを推奨します。", "qEn": "Which Microsoft tool lets an organization continuously monitor its compliance status against a specific regulation (such as GDPR) and receive recommended improvement actions?", "oEn": ["Microsoft Defender for Endpoint", "Microsoft Purview Compliance Manager", "Azure Network Watcher", "Microsoft Sentinel"], "eEn": "Microsoft Purview Compliance Manager continuously assesses an organization's compliance status against a specific regulation and recommends improvement actions."}, {"d": "D1", "q": "PaaS(Platform as a Service)モデルにおいて、顧客が引き続き責任を持つ項目として正しいものはどれですか?", "o": ["オペレーティングシステムのパッチ適用", "物理ネットワークの管理", "アプリケーションとデータ", "ランタイムの提供"], "a": 2, "e": "PaaSではMicrosoftがOSやランタイムを含むプラットフォームを管理し、顧客はアプリケーションとデータの管理に責任を持ちます。", "qEn": "In the PaaS (Platform as a Service) model, which item does the customer continue to be responsible for?", "oEn": ["Patching the operating system", "Managing the physical network", "Applications and data", "Providing the runtime"], "eEn": "In PaaS, Microsoft manages the platform, including the OS and runtime, while the customer remains responsible for managing applications and data."}, {"d": "D1", "q": "Zero Trustセキュリティモデルの基本的な考え方として最も適切なものはどれですか?", "o": ["社内ネットワーク上にあるものはすべて自動的に信頼する", "一度の認証で組織内のすべてのリソースへの永続的なアクセスを許可する", "ファイアウォールさえ設置すれば内部の脅威は考慮しなくてよい", "明示的な検証なしにはいかなる要求も信頼せず、常に検証する"], "a": 3, "e": "Zero Trustは「決して信頼せず、常に検証する(Never trust, always verify)」という考え方に基づき、あらゆるアクセス要求を明示的に検証します。", "qEn": "What is the most appropriate basic idea behind the Zero Trust security model?", "oEn": ["Automatically trust everything located on the internal corporate network", "Grant permanent access to all resources in the organization after a single authentication", "Installing a firewall alone means internal threats do not need to be considered", "Trust no request without explicit verification, and always verify it"], "eEn": "Zero Trust is based on the idea of \"never trust, always verify,\" explicitly verifying every access request."}, {"d": "D1", "q": "現代のセキュリティモデルにおいて、クラウドやリモートワークの普及に伴い、新たな主要なセキュリティ境界とされているものはどれか。", "o": ["ユーザーのID", "ネットワークファイアウォール", "データセンターの物理的な壁", "専用のVPN回線"], "a": 0, "e": "クラウド化やリモートワークの普及により、従来のネットワーク境界に代わってIDが新たな主要なセキュリティ境界とされている。", "qEn": "In the modern security model, driven by the shift to cloud computing and remote work, what is now considered the new primary security perimeter?", "oEn": ["User identity", "Network firewalls", "The physical walls of a data center", "A dedicated VPN circuit"], "eEn": "With the rise of cloud adoption and remote work, identity has replaced the traditional network perimeter as the new primary security boundary."}, {"d": "D1", "q": "「認証(authentication)」が果たす役割として最も適切なものはどれか。", "o": ["ユーザーがアクセスできるリソースを決定する", "ユーザーが主張する身元を検証する", "ユーザーのアカウントを削除する", "ユーザーの利用ログを保存する"], "a": 1, "e": "認証はユーザーが主張する身元(誰であるか)を検証するプロセスであり、リソースへのアクセス可否を決めるのは認可の役割である。", "qEn": "Which of the following best describes the role that authentication plays?", "oEn": ["Determining which resources a user can access", "Verifying the identity a user claims to have", "Deleting a user's account", "Storing a user's usage logs"], "eEn": "Authentication is the process of verifying who a user claims to be, while authorization is responsible for deciding what resources that user can access."}, {"d": "D1", "q": "「認可(authorization)」が果たす役割として最も適切なものはどれか。", "o": ["ユーザーが主張する身元を検証する　　　　　　　　　　　　　", "ユーザーのパスワードを暗号化する", "認証済みのユーザーがアクセスできる操作やリソースを決定する", "ネットワークの帯域幅を制御する"], "a": 2, "e": "認可は、認証によって身元が確認されたユーザーに対して、どのリソースや操作を許可するかを決定するプロセスである。", "qEn": "Which of the following best describes the role that authorization plays?", "oEn": ["Verifying the identity a user claims to have", "Encrypting a user's password", "Determining which operations or resources an authenticated user can access", "Controlling network bandwidth usage"], "eEn": "Authorization is the process of deciding what resources or operations an already-authenticated user is permitted to use."}, {"d": "D1", "q": "一般的なアクセス管理の流れにおいて、認証と認可はどのような順序で実行されるか。", "o": ["認可の後に認証が行われる", "認証と認可は無関係であり順序はない", "認可のみが実行され認証は行われない", "認証の後に認可が行われる"], "a": 3, "e": "通常、まずユーザーの身元を確認する認証が行われ、その後に何にアクセスできるかを決める認可が行われる。", "qEn": "In a typical access management flow, in what order are authentication and authorization performed?", "oEn": ["Authorization happens, then authentication", "Authentication and authorization are unrelated and have no order", "Only authorization is performed and authentication never occurs", "Authentication happens, then authorization"], "eEn": "Typically, authentication verifies a user's identity first, and authorization then determines what that user is allowed to access."}, {"d": "D1", "q": "ある従業員がノートPCにパスワードとワンタイムコードを入力してサインインした。このステップに該当するのはどれか。", "o": ["認証", "認可", "フェデレーション", "ディレクトリ同期"], "a": 0, "e": "パスワードやワンタイムコードの入力によって身元を証明する行為は認証に該当する。", "qEn": "An employee signs in to a laptop by entering a password and a one-time code. Which concept does this step correspond to?", "oEn": ["Authentication", "Authorization", "Federation", "Directory synchronization"], "eEn": "Proving one's identity by entering a password and a one-time code is an example of authentication."}, {"d": "D1", "q": "サインイン後、そのユーザーが特定の共有フォルダーへの読み取りアクセスを許可されているかどうかを判断するステップに該当するのはどれか。", "o": ["認証", "認可", "ディレクトリサービス", "フェデレーション"], "a": 1, "e": "サインイン後にユーザーが特定のリソースへアクセスできるかどうかを判断する処理は認可にあたる。", "qEn": "After sign-in, the step that determines whether a user is permitted read access to a specific shared folder corresponds to which concept?", "oEn": ["Authentication", "Authorization", "Directory service", "Federation"], "eEn": "Determining whether a signed-in user can access a specific resource is the role of authorization."}, {"d": "D1", "q": "ID プロバイダー(IdP)が提供する主な機能として最も適切なものはどれか。", "o": ["仮想マシンのホスティング", "ネットワークルーティングの制御　　　", "ユーザーIDの作成・管理と認証の実行", "ストレージ容量の割り当て"], "a": 2, "e": "IDプロバイダーはユーザーIDを作成・管理し、サインイン時の認証を行うサービスである。", "qEn": "Which of the following best describes the main function provided by an identity provider (IdP)?", "oEn": ["Hosting virtual machines", "Controlling network routing", "Creating and managing user identities and performing authentication", "Allocating storage capacity"], "eEn": "An identity provider creates and manages user identities and performs authentication during sign-in."}, {"d": "D1", "q": "Microsoft Entra ID(旧 Azure AD)について最も適切な説明はどれか。", "o": ["オンプレミス専用のファイルサーバー　　　　　　", "ネットワーク監視専用のツール", "仮想デスクトップ配信サービス", "クラウドベースのIDおよびアクセス管理サービス"], "a": 3, "e": "Microsoft Entra IDはMicrosoftが提供するクラウドベースのIDおよびアクセス管理サービスである。", "qEn": "Which of the following best describes Microsoft Entra ID (formerly Azure AD)?", "oEn": ["An on-premises-only file server", "A tool used only for network monitoring", "A virtual desktop delivery service", "A cloud-based identity and access management service"], "eEn": "Microsoft Entra ID is a cloud-based identity and access management service provided by Microsoft."}, {"d": "D1", "q": "シングルサインオン(SSO)を導入する主な利点として最も適切なものはどれか。", "o": ["ユーザーが一度のサインインで複数のアプリケーションを利用できるようになる", "各アプリケーションごとに異なるIDを作成させる　　　　　　　　　　　　　", "サーバーの物理的な設置場所を減らす", "ネットワーク遅延を完全に解消する"], "a": 0, "e": "SSOを利用すると、ユーザーは一度サインインするだけで許可された複数のアプリケーションやサービスにアクセスできるようになる。", "qEn": "What is the main benefit of implementing single sign-on (SSO)?", "oEn": ["Users can access multiple applications after signing in just once", "Users must create a different identity for every application", "It reduces the number of physical server locations", "It completely eliminates network latency"], "eEn": "With SSO, a user signs in only once and gains access to multiple authorized applications and services."}, {"d": "D1", "q": "SSOがセキュリティ上もたらす効果として最も適切なものはどれか。", "o": ["すべてのアプリケーションの脆弱性を自動的に修正する　　　　　　　　　", "ユーザーが管理するパスワードの数を減らし、使い回しのリスクを軽減する", "ファイアウォールのルールを自動生成する", "ネットワークの帯域幅を増やす"], "a": 1, "e": "SSOによりユーザーが記憶・管理するパスワードの数が減るため、パスワードの使い回しなどのリスクが軽減される。", "qEn": "What security benefit does SSO provide?", "oEn": ["It automatically fixes vulnerabilities in every application", "It reduces the number of passwords a user must manage, lowering the risk of password reuse", "It automatically generates firewall rules", "It increases available network bandwidth"], "eEn": "Because SSO reduces the number of passwords a user needs to remember and manage, it lowers risks such as password reuse."}, {"d": "D1", "q": "「ディレクトリサービス」の説明として最も適切なものはどれか。", "o": ["ネットワークトラフィックを暗号化する仕組み", "アプリケーションのソースコードを保管する仕組み　　　　　　　", "ユーザー・グループ・デバイスなどの情報を格納し管理する仕組み", "ハードウェアの温度を監視する仕組み"], "a": 2, "e": "ディレクトリサービスは、ユーザーやグループ、デバイスなどの情報を一元的に格納・管理する仕組みである。", "qEn": "Which of the following best describes a directory service?", "oEn": ["A mechanism for encrypting network traffic", "A mechanism for storing application source code", "A mechanism that stores and manages information about users, groups, and devices", "A mechanism for monitoring hardware temperature"], "eEn": "A directory service is a mechanism that centrally stores and manages information about users, groups, devices, and similar objects."}, {"d": "D1", "q": "Active Directory Domain Services(AD DS)の説明として最も適切なものはどれか。", "o": ["クラウド専用のIDガバナンスツール", "ネットワーク帯域幅を管理するサービス　　　　　　　", "電子メールの配信を行うサービス", "オンプレミス環境向けの伝統的なディレクトリサービス"], "a": 3, "e": "AD DSはオンプレミス環境で長年利用されてきた伝統的なディレクトリサービスであり、ドメインベースの認証を提供する。", "qEn": "Which of the following best describes Active Directory Domain Services (AD DS)?", "oEn": ["A cloud-only identity governance tool", "A service that manages network bandwidth", "A service that delivers email messages", "A traditional directory service designed for on-premises environments"], "eEn": "AD DS is a traditional directory service long used in on-premises environments, providing domain-based authentication."}, {"d": "D1", "q": "Active Directory Domain Services(AD DS)がディレクトリへの問い合わせに利用する主な標準プロトコルはどれか。", "o": ["LDAP", "SMTP", "FTP", "DNS"], "a": 0, "e": "AD DSはLDAP(Lightweight Directory Access Protocol)を用いてディレクトリ情報への問い合わせや更新を行う。", "qEn": "Which standard protocol does Active Directory Domain Services (AD DS) primarily use to query the directory?", "oEn": ["LDAP", "SMTP", "FTP", "DNS"], "eEn": "AD DS uses LDAP (Lightweight Directory Access Protocol) to query and update directory information."}, {"d": "D1", "q": "AD DS環境において、認証要求の処理やディレクトリ情報の保持を行うサーバーの役割はどれか。", "o": ["ロードバランサー　　　", "ドメインコントローラー", "プロキシサーバー", "メールサーバー"], "a": 1, "e": "ドメインコントローラーはAD DS環境において認証要求を処理し、ディレクトリ情報を保持するサーバーの役割を担う。", "qEn": "In an AD DS environment, which server role is responsible for processing authentication requests and holding directory information?", "oEn": ["Load balancer", "Domain controller", "Proxy server", "Mail server"], "eEn": "A domain controller is the server role in an AD DS environment that processes authentication requests and stores directory information."}, {"d": "D1", "q": "Microsoft Entra IDとActive Directory Domain Services(AD DS)の違いについて最も適切な説明はどれか。", "o": ["両者は全く同じ機能を持つ同一の製品である", "AD DSはクラウド専用でEntra IDはオンプレミス専用である　　　　　　　　　　　　", "Entra IDはクラウドベース、AD DSはオンプレミス向けのディレクトリサービスである", "Entra IDはハードウェア機器の名称である"], "a": 2, "e": "Microsoft Entra IDはクラウドベースのID管理サービスであり、AD DSはオンプレミス環境向けの伝統的なディレクトリサービスである。", "qEn": "Which of the following best describes the difference between Microsoft Entra ID and Active Directory Domain Services (AD DS)?", "oEn": ["They are the exact same product with identical functionality", "AD DS is cloud-only while Entra ID is on-premises-only", "Entra ID is cloud-based, while AD DS is a directory service designed for on-premises environments", "Entra ID is the name of a hardware appliance"], "eEn": "Microsoft Entra ID is a cloud-based identity management service, while AD DS is a traditional directory service designed for on-premises environments."}, {"d": "D1", "q": "オンプレミスのAD DSとMicrosoft Entra IDの両方を組み合わせて利用する構成は一般的に何と呼ばれるか。", "o": ["フェデレーテッドストレージ", "マルチテナント認可", "ゼロトラストネットワーク", "ハイブリッドID"], "a": 3, "e": "オンプレミスのAD DSとクラウドのMicrosoft Entra IDを組み合わせて利用する構成はハイブリッドIDと呼ばれる。", "qEn": "What is the configuration commonly called when an organization uses both on-premises AD DS and Microsoft Entra ID together?", "oEn": ["Federated storage", "Multi-tenant authorization", "Zero trust network", "Hybrid identity"], "eEn": "A configuration that combines on-premises AD DS with cloud-based Microsoft Entra ID is referred to as hybrid identity."}, {"d": "D1", "q": "オンプレミスのAD DSのユーザー情報をMicrosoft Entra IDと同期するために使用されるツールはどれか。", "o": ["Microsoft Entra Connect", "Microsoft Defender　　　　　", "Azure Monitor", "Microsoft Purview"], "a": 0, "e": "Microsoft Entra Connect(旧Azure AD Connect)は、オンプレミスのAD DSとMicrosoft Entra ID間でID情報を同期するためのツールである。", "qEn": "Which tool is used to synchronize on-premises AD DS user information with Microsoft Entra ID?", "oEn": ["Microsoft Entra Connect", "Microsoft Defender", "Azure Monitor", "Microsoft Purview"], "eEn": "Microsoft Entra Connect (formerly Azure AD Connect) is the tool used to synchronize identity information between on-premises AD DS and Microsoft Entra ID."}, {"d": "D1", "q": "「フェデレーション」の説明として最も適切なものはどれか。", "o": ["単一の組織内でのみ有効なパスワードポリシー", "複数の組織や複数のIDシステムの間で信頼関係を確立し、IDを連携させる仕組み", "ネットワーク機器のファームウェアを更新する仕組み　　　　　　　　　　　　　　", "ディスク容量を自動的に圧縮する仕組み"], "a": 1, "e": "フェデレーションとは、複数の組織やIDシステムの間で信頼関係を構築し、一方で認証された情報を他方でも利用できるようにする仕組みである。", "qEn": "Which of the following best describes federation?", "oEn": ["A password policy that applies only within a single organization", "A mechanism that establishes trust between multiple organizations or identity systems to link identities together", "A mechanism for updating network device firmware", "A mechanism for automatically compressing disk storage"], "eEn": "Federation is a mechanism that establishes a trust relationship between multiple organizations or identity systems so that authentication performed in one can be recognized by the other."}, {"d": "D1", "q": "2つの組織がフェデレーションを構成した場合に実現される内容として最も適切なものはどれか。", "o": ["両組織のネットワーク帯域が自動的に統合される", "一方の組織のすべてのデータが自動的に削除される　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　", "一方の組織でサインインしたユーザーが、信頼関係に基づきもう一方の組織のリソースにもアクセスできるようになる", "両組織のデータベースが物理的に統合される"], "a": 2, "e": "フェデレーションにより組織間で信頼関係が構築されると、一方でサインインしたユーザーがもう一方のリソースにアクセスできるようになる。", "qEn": "When two organizations set up federation, what is typically achieved?", "oEn": ["The network bandwidth of both organizations is automatically merged", "All data in one organization is automatically deleted", "A user who signs in with one organization can, based on the trust relationship, also access resources of the other organization", "The databases of both organizations are physically merged"], "eEn": "Once a trust relationship is established through federation, a user who signs in with one organization can access resources belonging to the other."}, {"d": "D1", "q": "フェデレーションでよく利用される標準的なプロトコルはどれか。", "o": ["FTP", "SMTP", "ICMP", "SAML"], "a": 3, "e": "SAML(Security Assertion Markup Language)は、フェデレーションにおいて認証情報を連携するための標準的なプロトコルの一つである。", "qEn": "Which standard protocol is commonly used in federation scenarios?", "oEn": ["FTP", "SMTP", "ICMP", "SAML"], "eEn": "SAML (Security Assertion Markup Language) is one of the standard protocols used to exchange authentication information in federation scenarios."}, {"d": "D1", "q": "クレームベースのID(claims-based identity)における「クレーム」が表すものとして最も適切なものはどれか。", "o": ["ユーザーに関する属性や情報を含む主張", "ネットワークのIPアドレス範囲　　　", "サーバーのCPU使用率", "ディスクの空き容量"], "a": 0, "e": "クレームとは、ユーザーの名前や役割などの属性に関する主張であり、IDプロバイダーによって発行され信頼される。", "qEn": "In claims-based identity, what does a claim represent?", "oEn": ["An assertion containing attributes or information about a user", "A range of network IP addresses", "A server's CPU utilization", "The amount of free disk space"], "eEn": "A claim is an assertion about a user's attributes, such as name or role, issued and trusted as coming from an identity provider."}, {"d": "D1", "q": "パートナー企業とフェデレーションを構成する利点として最も適切なものはどれか。", "o": ["パートナー企業とのネットワーク回線費用が無料になる　　　　　　　　　　", "パートナー企業のユーザーごとに新しいアカウントを作成する必要がなくなる", "パートナー企業のサーバー台数が自動的に減る", "パートナー企業のライセンス費用が発生しなくなる"], "a": 1, "e": "フェデレーションを構成すると、パートナー企業のユーザーは自組織の既存の資格情報でリソースにアクセスできるため、新たにアカウントを作成する必要がなくなる。", "qEn": "What is a key benefit of setting up federation with a partner organization?", "oEn": ["Network circuit costs with the partner organization become free", "There is no need to create a new account for each user from the partner organization", "The number of servers at the partner organization automatically decreases", "Licensing costs for the partner organization disappear"], "eEn": "With federation in place, users from a partner organization can access resources using their existing credentials, removing the need to create separate new accounts."}, {"d": "D1", "q": "「セキュリティプリンシパル」の説明として最も適切なものはどれか。", "o": ["ネットワークケーブルの配線図", "データベースのバックアップスケジュール　　　　　　　　　　　　　　　", "リソースへのアクセスを要求できるユーザーやサービスなどのエンティティ", "サーバーのラック配置図"], "a": 2, "e": "セキュリティプリンシパルとは、リソースへのアクセスを要求し、認証・認可の対象となるユーザーやグループ、サービスなどのエンティティを指す。", "qEn": "Which of the following best describes a security principal?", "oEn": ["A diagram of network cable wiring", "A database backup schedule", "An entity, such as a user or service, that can request access to a resource", "A server rack layout diagram"], "eEn": "A security principal is an entity — such as a user, group, or service — that can request access to a resource and is subject to authentication and authorization."}, {"d": "D1", "q": "次のうちセキュリティプリンシパルの種類に該当しないものはどれか。", "o": ["ユーザー", "グループ", "サービスプリンシパル　", "ファイアウォールルール"], "a": 3, "e": "ユーザー、グループ、サービスプリンシパル、マネージドIDなどはセキュリティプリンシパルの種類だが、ファイアウォールルールはこれに該当しない。", "qEn": "Which of the following is NOT a type of security principal?", "oEn": ["User", "Group", "Service principal", "Firewall rule"], "eEn": "Users, groups, service principals, and managed identities are all types of security principals, but a firewall rule is not."}, {"d": "D1", "q": "Azureの「マネージドID」が主に解決する課題として最も適切なものはどれか。", "o": ["アプリケーションコード内に資格情報を保存せずにAzureリソースへ認証できるようにする", "仮想マシンのCPUコア数を自動的に増やす　　　　　　　　　　　　　　　　　　　　　　　", "ネットワーク遅延を完全に解消する", "ストレージの暗号化キーを削除する"], "a": 0, "e": "マネージドIDを使用すると、開発者がコード内に資格情報を保存することなく、アプリケーションがAzureリソースに対して認証できるようになる。", "qEn": "What problem does an Azure managed identity primarily solve?", "oEn": ["It lets an application authenticate to Azure resources without storing credentials in application code", "It automatically increases a virtual machine's CPU core count", "It completely eliminates network latency", "It deletes storage encryption keys"], "eEn": "A managed identity allows an application to authenticate to Azure resources without developers having to store credentials in the application code."}, {"d": "D1", "q": "「サービスプリンシパル」の主な用途として最も適切なものはどれか。", "o": ["人間のユーザーの代わりにヘルプデスクへ問い合わせる　　　　　　　　　　　　　　　　　", "アプリケーションやサービスがAzureリソースにアクセスする際のIDとして利用される", "物理サーバーの温度を監視する", "ネットワークスイッチのポートを設定する"], "a": 1, "e": "サービスプリンシパルは、アプリケーションやサービスがAzureリソースへアクセスする際に使用されるIDである。", "qEn": "What is the main use of a service principal?", "oEn": ["It contacts the help desk on behalf of a human user", "It serves as the identity an application or service uses to access Azure resources", "It monitors the temperature of a physical server", "It configures ports on a network switch"], "eEn": "A service principal is the identity that an application or service uses when accessing Azure resources."}, {"d": "D1", "q": "ゼロトラストモデルの「明示的に検証する(verify explicitly)」原則とIDの関係として最も適切なものはどれか。", "o": ["一度認証されたユーザーは以降永続的に信頼され再検証しない　　　　　　　　　　　　　　　　　", "IDの検証はネットワーク内部からのアクセスでは省略できる", "利用可能なすべてのデータポイントに基づき、すべてのアクセス要求についてIDを含め検証を行う", "ゼロトラストではIDの検証は不要である"], "a": 2, "e": "ゼロトラストの「明示的に検証する」原則では、ユーザーの場所に関わらず、利用可能なすべてのデータポイントに基づいてすべてのアクセス要求を検証する必要がある。", "qEn": "Which of the following best describes the relationship between the Zero Trust principle of verifying explicitly and identity?", "oEn": ["A user who is authenticated once is trusted permanently afterward without re-verification", "Identity verification can be skipped for access originating from inside the network", "Every access request, including identity, is verified based on all available data points", "Zero Trust does not require identity verification at all"], "eEn": "The Zero Trust principle of verifying explicitly requires that every access request be verified using all available data points, regardless of where the request originates."}, {"d": "D1", "q": "多要素認証(MFA)が認証のセキュリティを強化する仕組みとして最も適切なものはどれか。", "o": ["パスワードの入力を完全に不要にする　　　　　　　　　　　　　　　　　　　　　　　　　　　　　", "ネットワーク帯域幅を増加させる", "ユーザーのサインイン回数を減らす", "パスワードのみに依存せず、複数の異なる種類の証拠を要求することで不正アクセスのリスクを下げる"], "a": 3, "e": "MFAは、パスワードに加えてワンタイムコードや生体情報など複数の異なる種類の証拠を要求することで、不正アクセスのリスクを低減する。", "qEn": "How does multi-factor authentication (MFA) strengthen authentication security?", "oEn": ["By making password entry completely unnecessary", "By increasing available network bandwidth", "By reducing how many times a user needs to sign in", "By requiring multiple different types of evidence instead of relying on a password alone, reducing the risk of unauthorized access"], "eEn": "MFA reduces the risk of unauthorized access by requiring multiple different types of evidence, such as a one-time code or biometric data, in addition to a password."}, {"d": "D1", "q": "認証の3要素として一般的に挙げられる組み合わせはどれか。", "o": ["知っているもの・持っているもの・自分自身であるもの", "パスワード・ユーザー名・メールアドレス　　　　　　", "IPアドレス・ポート番号・プロトコル", "部署名・役職・入社日"], "a": 0, "e": "認証の3要素とは、一般に「知っているもの(パスワードなど)」「持っているもの(デバイスなど)」「自分自身であるもの(生体情報など)」を指す。", "qEn": "Which combination is commonly cited as the three factors of authentication?", "oEn": ["Something you know, something you have, and something you are", "Password, username, and email address", "IP address, port number, and protocol", "Department name, job title, and hire date"], "eEn": "The three factors of authentication are generally something you know (like a password), something you have (like a device), and something you are (like biometric data)."}, {"d": "D1", "q": "Microsoft Entra IDの機能のうち、外部の取引先ユーザーが自組織のリソースへ自社の資格情報でアクセスできるようにする仕組みはどれか。", "o": ["マネージドID", "外部ID(B2Bコラボレーション)", "ディレクトリレプリケーション　　　", "ロードバランシング"], "a": 1, "e": "Microsoft Entra IDの外部ID(B2Bコラボレーション)機能を使うと、外部組織のユーザーが自社の資格情報のまま自組織のリソースにアクセスできるようになる。", "qEn": "Which Microsoft Entra ID feature allows users from an external partner organization to access an organization's resources using their own organization's credentials?", "oEn": ["Managed identity", "External Identities (B2B collaboration)", "Directory replication", "Load balancing"], "eEn": "The External Identities (B2B collaboration) feature of Microsoft Entra ID lets users from an external organization access resources while keeping their own organization's credentials."}, {"d": "D1", "q": "ユーザーがIDプロバイダーによって正常に認証された後、通常発行されるものはどれか。", "o": ["新しい物理デバイス", "新しいネットワークケーブル　", "アクセスに使用されるトークン", "新しいIPアドレス範囲"], "a": 2, "e": "認証が正常に完了すると、IDプロバイダーは通常、以降のリソースアクセスに使用されるトークンを発行する。", "qEn": "After a user is successfully authenticated by an identity provider, what is typically issued?", "oEn": ["A new physical device", "A new network cable", "A token used for subsequent access", "A new range of IP addresses"], "eEn": "Once authentication succeeds, the identity provider typically issues a token that is used for subsequent access to resources."}, {"d": "D1", "q": "個々のユーザーではなくグループに対して権限を割り当てる主な利点として最も適切なものはどれか。", "o": ["グループにはパスワードが不要になる", "グループは自動的にネットワーク帯域を拡張する　　　　　　　　　　　　　　　　　　　", "グループはディスク容量を無制限に使用できる", "メンバーが増減してもグループへの割り当てを変更するだけで管理でき、運用の手間が減る"], "a": 3, "e": "グループに対して権限を割り当てると、メンバーの追加・削除時に個別のユーザーごとの設定変更が不要になり、管理の手間が軽減される。", "qEn": "What is the main benefit of assigning permissions to a group instead of to individual users?", "oEn": ["Groups no longer require passwords", "Groups automatically expand network bandwidth", "Groups can use unlimited disk storage", "Adding or removing members only requires updating group assignment, reducing administrative overhead"], "eEn": "Assigning permissions to a group means that adding or removing members does not require changing settings for each individual user, reducing administrative effort."}, {"d": "D2", "q": "Microsoft Entra ID の主な役割として最も適切なものはどれですか。", "o": ["クラウドベースのIDおよびアクセス管理サービスを提供する", "オンプレミスのファイルサーバーの容量を管理する（このような説明が用いられることもある）", "ネットワーク機器のファームウェアを自動更新する", "物理データセンターの空調設備を制御する"], "a": 0, "e": "Microsoft Entra ID はクラウドベースのID・アクセス管理サービスであり、ユーザー認証やシングルサインオンなどを提供します。", "qEn": "What is the primary role of Microsoft Entra ID?", "oEn": ["It provides a cloud-based identity and access management service", "It manages the storage capacity of on-premises file servers (this description is sometimes used)", "It automatically updates the firmware of network devices", "It controls the air conditioning of physical data centers"], "eEn": "Microsoft Entra ID is a cloud-based identity and access management service that provides authentication and single sign-on capabilities."}, {"d": "D2", "q": "Microsoft Entra ID のテナントに関する説明として正しいものはどれですか。", "o": ["すべての顧客が共有する単一のグローバルなアカウントである　　　", "組織専用に作成される分離されたディレクトリのインスタンスである", "オンプレミスのみに存在する物理サーバーの名称である", "課金情報だけを一時的に保存する専用の領域である"], "a": 1, "e": "テナントは組織専用に作成される Entra ID のインスタンスで、ユーザーやアプリなどのディレクトリデータを保持します。", "qEn": "Which statement about a Microsoft Entra ID tenant is correct?", "oEn": ["It is a single global account shared by all customers", "It is a dedicated, isolated directory instance created for an organization", "It is the name of a physical server that exists only on-premises", "It is a dedicated area that temporarily stores only billing data"], "eEn": "A tenant is a dedicated instance of Entra ID created for an organization, holding directory data such as users and applications."}, {"d": "D2", "q": "Microsoft Entra ID と Active Directory Domain Services (AD DS) の違いとして正しいものはどれですか。", "o": ["AD DS はクラウド専用、Entra ID はオンプレミス専用のサービスである（一般にこう語られることもある）", "両者は完全に同一の機能を持つ、単に名称が違うだけの製品である", "Entra ID はクラウド向け、AD DS はオンプレミス向けのディレクトリサービスである", "Entra ID はネットワークスイッチの設定専用に使うツールである"], "a": 2, "e": "Entra ID はクラウドベースの ID 管理サービス、AD DS はオンプレミス環境向けのディレクトリサービスです。", "qEn": "Which statement correctly describes the difference between Microsoft Entra ID and Active Directory Domain Services (AD DS)?", "oEn": ["AD DS is cloud-only, while Entra ID is an on-premises-only service (this is sometimes phrased this way)", "They are fully identical products that merely differ in name", "Entra ID targets the cloud, while AD DS is a directory service for on-premises", "Entra ID is a tool used only for configuring network switches"], "eEn": "Entra ID is a cloud-based identity management service, whereas AD DS is a directory service designed for on-premises environments."}, {"d": "D2", "q": "Microsoft Entra 管理センターでできることとして適切なものはどれですか。", "o": ["サーバーのOSライセンスキーを新規に発行する（そのように理解されることもある）", "物理的なネットワークケーブルの配線を設計する", "オフィスビルの座席レイアウトを作成する", "ユーザーやグループ、アプリの登録などのIDリソースを管理する"], "a": 3, "e": "Microsoft Entra 管理センターは、ユーザーやグループ、アプリの登録などのIDリソースを一元的に管理するためのポータルです。", "qEn": "What can be done using the Microsoft Entra admin center?", "oEn": ["Issue a new OS license key for a server (this is sometimes understood this way)", "Design the physical cabling layout of a network", "Create a seating layout for an office building", "Manage identity resources such as users, groups, and app registrations"], "eEn": "The Microsoft Entra admin center is a portal for centrally managing identity resources such as users, groups, and app registrations."}, {"d": "D2", "q": "Microsoft Entra ID Free、P1、P2 のエディションに関する説明として正しいものはどれですか。", "o": ["上位エディションほど条件付きアクセスやID保護などの高度な機能が追加される", "すべてのエディションで利用できる機能はまったく同一である", "Free エディションだけが条件付きアクセスを完全にサポートする（このような説明が用いられることもある）", "P2 エディションはオンプレミス環境専用として提供される"], "a": 0, "e": "エディションが上がるほど条件付きアクセスやEntra ID Protectionなどの高度な機能が利用可能になります。", "qEn": "Which statement correctly describes the Microsoft Entra ID Free, P1, and P2 editions?", "oEn": ["Higher-tier editions add advanced features such as Conditional Access and Identity Protection", "All editions offer exactly the same set of features", "Only the Free edition fully supports Conditional Access (this description is sometimes used)", "The P2 edition is offered exclusively for on-premises environments"], "eEn": "Higher-tier editions unlock advanced capabilities such as Conditional Access (P1) and Identity Protection (P2)."}, {"d": "D2", "q": "Microsoft Entra ID Governance の目的として最も適切なものはどれですか。", "o": ["サーバーのハードウェア故障を自動で修理する", "アクセス権のライフサイクルを管理し、適切な人に適切なアクセスを与える", "電子メールの配信経路を暗号化なしで高速化する（一般にこう語られることもある）", "ネットワーク上のファイルを自動で圧縮する"], "a": 1, "e": "Entra ID Governance は、アクセス権のライフサイクル管理を通じて適切なユーザーに適切なアクセスを付与・維持することを目的とします。", "qEn": "What is the main purpose of Microsoft Entra ID Governance?", "oEn": ["To automatically repair hardware failures on a server", "To manage the access lifecycle so the right people get the right access", "To speed up email delivery paths without encryption (this is sometimes phrased this way)", "To automatically compress files stored on a network"], "eEn": "Entra ID Governance focuses on managing the lifecycle of access rights so that the right people have the right access at the right time."}, {"d": "D2", "q": "Microsoft Entra B2B コラボレーションの主な用途は何ですか。", "o": ["自組織のネットワーク帯域幅を制限し監視する（そのように理解されることもある）", "オンプレミスのプリンター機器を共有登録する", "外部の取引先ユーザーをゲストとして招待し自組織のリソースへアクセスさせる", "社内サーバーの電源を遠隔から操作する"], "a": 2, "e": "B2B コラボレーションは、外部パートナーのユーザーをゲストとして招待し、自組織のリソースに安全にアクセスさせる機能です。", "qEn": "What is the primary use of Microsoft Entra B2B collaboration?", "oEn": ["To limit and monitor your organization's own network bandwidth (this is sometimes understood this way)", "To register and share an on-premises printer device", "To invite external partner users as guests to access resources in your organization", "To remotely control the power of an internal server"], "eEn": "B2B collaboration lets you invite external partner users as guests so they can securely access resources in your organization."}, {"d": "D2", "q": "Microsoft Entra External ID（旧 Azure AD B2C）の主な目的として正しいものはどれですか。", "o": ["社内従業員専用のオンプレミスファイル共有を構築する（このような説明が用いられることもある）", "サーバーのCPU使用率をリアルタイムで監視する", "無線LANアクセスポイントの電波強度を測定する", "外部の顧客や消費者が自社アプリケーションにサインインできるようにする"], "a": 3, "e": "External ID（B2C）は、企業が提供するアプリに顧客や消費者などの外部ユーザーがサインインできるようにするための機能です。", "qEn": "What is the main purpose of Microsoft Entra External ID (formerly Azure AD B2C)?", "oEn": ["To build an on-premises file share exclusively for internal employees (this description is sometimes used)", "To monitor server CPU utilization in real time", "To measure the signal strength of wireless access points", "To let external customers and consumers sign in to a company's applications"], "eEn": "External ID (B2C) allows organizations to let external users, such as customers, sign in to the applications they build."}, {"d": "D2", "q": "Microsoft Entra Domain Services の役割として最も適切なものはどれですか。", "o": ["ドメイン参加やグループポリシーなどの機能をクラウド上で利用可能にする", "クラウド上のすべてのユーザーパスワードを一括削除する（一般にこう語られることもある）", "モバイルデバイスのバッテリー消費を最適化する", "PDFファイルを別の形式へ自動的に変換する"], "a": 0, "e": "Entra Domain Services は、ドメイン参加やグループポリシー、LDAPなど従来型のディレクトリ機能をクラウド上で提供します。", "qEn": "What is the main role of Microsoft Entra Domain Services?", "oEn": ["It makes capabilities such as domain join and Group Policy available in the cloud", "It bulk-deletes all user passwords stored in the cloud (this is sometimes phrased this way)", "It optimizes battery consumption on mobile devices", "It automatically converts PDF files into another format"], "eEn": "Entra Domain Services offers classic directory features such as domain join, Group Policy, and LDAP as a managed cloud service."}, {"d": "D2", "q": "Microsoft Entra ID Protection の主な機能として正しいものはどれですか。", "o": ["アプリケーションのソースコードを自動的に書き換える（そのように理解されることもある）", "サインインやユーザーのリスクを検出し条件付きアクセスと連携して対応する", "オフィスの室温や照明を自動的に調整する", "動画ファイルを圧縮して保存容量を節約する"], "a": 1, "e": "Entra ID Protection はサインインリスクやユーザーリスクを検出し、条件付きアクセスと連携して自動的に対応します。", "qEn": "What is the main function of Microsoft Entra ID Protection?", "oEn": ["It automatically rewrites application source code (this is sometimes understood this way)", "It detects sign-in and user risk and works with Conditional Access to respond", "It automatically adjusts office room temperature and lighting", "It compresses video files to save storage space"], "eEn": "Entra ID Protection detects sign-in risk and user risk, integrating with Conditional Access to automatically respond to threats."}, {"d": "D2", "q": "Microsoft Entra ID がシングルサインオン（SSO）を提供する目的として最も適切なものはどれですか。", "o": ["毎回異なるパスワードの入力をユーザーへ強制する", "アプリごとに専用のネットワークケーブルを敷設する（このような説明が用いられることもある）", "1回のサインインで複数のアプリケーションへアクセスできるようにする", "サインインのたびに新しいアカウントを自動作成する"], "a": 2, "e": "SSO を利用すると、ユーザーは1回のサインインで複数の連携アプリケーションにアクセスできるようになり、利便性とセキュリティが向上します。", "qEn": "What is the purpose of single sign-on (SSO) provided by Microsoft Entra ID?", "oEn": ["To force users to enter a different password every time", "To lay a dedicated network cable for each application (this description is sometimes used)", "To allow users to access multiple applications with a single sign-in", "To automatically create a new account every time someone signs in"], "eEn": "SSO lets users sign in once and gain access to multiple integrated applications, improving both convenience and security."}, {"d": "D2", "q": "アプリの登録（App registration）とエンタープライズアプリケーションの関係として正しいものはどれですか。", "o": ["両者は完全に同じものであり、片方が存在すれば十分である", "エンタープライズアプリケーションは常にオンプレミスのみで動作する（一般にこう語られることもある）", "アプリ登録はユーザーのパスワードを保存するためだけの機能である", "アプリ登録はアプリの定義であり、それをテナントで表すのがエンタープライズアプリケーションである"], "a": 3, "e": "アプリ登録でアプリケーションオブジェクトを定義し、テナントにインストールすると、そのアプリのサービスプリンシパルであるエンタープライズアプリケーションが作成されます。", "qEn": "What is the relationship between an app registration and an enterprise application?", "oEn": ["They are exactly the same thing, so having only one of them is enough", "An enterprise application always runs only on-premises (this is sometimes phrased this way)", "An app registration exists only to store user passwords", "An app registration defines the app, and an enterprise application represents it within a tenant"], "eEn": "Registering an app creates an application object; installing it in a tenant creates an enterprise application, which is that app's service principal."}, {"d": "D2", "q": "Microsoft Entra ID における「サービスプリンシパル」とは何ですか。", "o": ["アプリケーションがテナント内でリソースにアクセスするためのIDインスタンス", "人間のユーザーが対話的にサインインするためのアカウント（そのように理解されることもある）", "物理的なネットワークルーターの管理者アカウント", "オフィスの入退室管理に使用する社員証カード"], "a": 0, "e": "サービスプリンシパルは、アプリケーションがテナント内でリソースにアクセスするために使用するセキュリティIDのインスタンスです。", "qEn": "What is a \"service principal\" in Microsoft Entra ID?", "oEn": ["An identity instance an application uses to access resources in a tenant", "An account used by a human user to sign in interactively (this is sometimes understood this way)", "An administrator account for a physical network router", "An employee badge card used for office entry and exit control"], "eEn": "A service principal is a security identity instance that an application uses to access resources within a tenant."}, {"d": "D2", "q": "マネージドID（Managed Identity）の主な利点として正しいものはどれですか。", "o": ["すべてのユーザーへ同一のパスワードを割り当てる", "資格情報の管理をAzureが自動的に行い開発者が管理しなくてよい", "オンプレミスサーバーの物理的な設置場所を追跡する（このような説明が用いられることもある）", "アプリケーションのライセンス費用を無料にする"], "a": 1, "e": "マネージドIDでは、資格情報の管理をAzureが自動的に行うため、開発者がシークレットを管理する必要がありません。", "qEn": "What is the main benefit of a managed identity?", "oEn": ["It assigns the same password to every user", "Azure automatically manages the credentials so developers need not manage them", "It tracks the physical installation location of on-premises servers (this description is sometimes used)", "It makes application licensing costs free"], "eEn": "With a managed identity, Azure automatically manages the underlying credentials, removing the need for developers to manage secrets."}, {"d": "D2", "q": "システム割り当てマネージドIDとユーザー割り当てマネージドIDの違いとして正しいものはどれですか。", "o": ["ユーザー割り当てマネージドIDは常にオンプレミスでのみ動作する", "システム割り当てマネージドIDはパスワードを手動で設定する必要がある（一般にこう語られることもある）", "システム割り当ては特定リソースに紐づき、ユーザー割り当ては独立して複数リソースで共有できる", "両者に機能的な違いはまったく存在しない"], "a": 2, "e": "システム割り当てIDはリソースのライフサイクルに結び付けられ、ユーザー割り当てIDは独立したリソースとして作成され複数のAzureリソース間で共有可能です。", "qEn": "What is the difference between a system-assigned and a user-assigned managed identity?", "oEn": ["A user-assigned managed identity always runs only on-premises", "A system-assigned managed identity requires a manually configured password (this is sometimes phrased this way)", "System-assigned is tied to one resource; user-assigned is standalone and shared across resources", "There is no functional difference between the two whatsoever"], "eEn": "A system-assigned identity's lifecycle is tied to its resource, whereas a user-assigned identity is a standalone resource that can be shared across multiple Azure resources."}, {"d": "D2", "q": "Microsoft Entra ID におけるデバイスIDの目的として最も適切なものはどれですか。", "o": ["デバイスの製造番号をインターネット上へ公開する（そのように理解されることもある）", "デバイスの電池残量を自動的に充電し続ける", "デバイスの画面の解像度を遠隔から変更する", "デバイスを組織のディレクトリに登録し条件付きアクセスなどの対象にする"], "a": 3, "e": "デバイスIDにより、デバイスを組織のディレクトリに登録し、条件付きアクセスなどのポリシーの対象として管理できます。", "qEn": "What is the purpose of a device identity in Microsoft Entra ID?", "oEn": ["To publish the device's serial number on the internet (this is sometimes understood this way)", "To keep automatically charging the device's battery", "To remotely change the device's screen resolution", "To register a device in the directory so policies like Conditional Access can govern it"], "eEn": "A device identity registers the device in the organization's directory, allowing it to be governed by policies such as Conditional Access."}, {"d": "D2", "q": "Microsoft Entra 参加済み（joined）デバイスと Microsoft Entra 登録済み（registered）デバイスの違いとして正しいものはどれですか。", "o": ["参加済みは組織所有デバイス、登録済みは個人所有のBYODデバイスを指す", "登録済みデバイスは常に組織所有のサーバーだけを指す（このような説明が用いられることもある）", "参加済みデバイスはインターネットへ一切接続できない", "両者に違いはなく単に呼び方が異なるだけである"], "a": 0, "e": "Entra参加済みは組織所有デバイスがEntra IDでサインインする形態、Entra登録済みは個人所有デバイス（BYOD）がアプリアクセスのために登録される形態です。", "qEn": "What is the difference between a Microsoft Entra joined device and a Microsoft Entra registered device?", "oEn": ["Joined refers to organization-owned devices; registered refers to personal BYOD devices", "A registered device always refers only to an organization-owned server (this description is sometimes used)", "A joined device can never connect to the internet at all", "There is no difference; the terms are simply named differently"], "eEn": "Entra joined devices are organization-owned devices that sign in using Entra ID, while Entra registered devices are personal (BYOD) devices registered to access apps."}, {"d": "D2", "q": "ハイブリッド Microsoft Entra 参加済みデバイスとは何ですか。", "o": ["2つの異なるクラウドプロバイダーへ同時に接続されるデバイス（一般にこう語られることもある）", "オンプレミスのADに参加し同時にEntra IDにも登録されたデバイス", "電源をまったく使用せず動作するデバイス", "常に完全なオフライン状態で運用されるデバイス"], "a": 1, "e": "ハイブリッドEntra参加済みデバイスは、オンプレミスのAD DSに参加していると同時にMicrosoft Entra IDにも登録されているデバイスです。", "qEn": "What is a hybrid Microsoft Entra joined device?", "oEn": ["A device connected to two different cloud providers at the same time (this is sometimes phrased this way)", "A device joined to on-premises AD and simultaneously registered with Entra ID", "A device that operates without using any electrical power at all", "A device that is always operated in a fully offline state"], "eEn": "A hybrid Entra joined device is joined to on-premises AD DS while also being registered with Microsoft Entra ID."}, {"d": "D2", "q": "Microsoft Entra Agent ID の目的として最も適切なものはどれですか。", "o": ["従業員の勤怠時間を自動的に記録し集計する（そのように理解されることもある）", "会議室の予約システムを自動的に運用する", "AIエージェントに一意のIDを付与し他のIDと同様に管理・保護する", "印刷用紙の在庫を自動的に発注管理する"], "a": 2, "e": "Microsoft Entra Agent ID は、AIエージェントに一意のIDを付与し、ユーザーやサービスプリンシパルと同様にガバナンスやセキュリティ管理の対象にする機能です。", "qEn": "What is the purpose of Microsoft Entra Agent ID?", "oEn": ["To automatically record and total employee attendance hours (this is sometimes understood this way)", "To automatically operate a meeting room reservation system", "To give AI agents a unique identity governed and secured like other identities", "To automatically manage and order stock of printer paper"], "eEn": "Microsoft Entra Agent ID assigns a unique identity to AI agents so they can be governed and secured in the same way as users and service principals."}, {"d": "D2", "q": "ワークロードIDとは何を指しますか。", "o": ["人間のユーザーがサインインする際に使うIDのみを指す（このような説明が用いられることもある）", "物理的な倉庫の在庫を管理するための番号を指す", "会社のロゴが入った社員証のデザインを指す", "アプリやサービス、スクリプトなどソフトウェアが使用するIDを指す"], "a": 3, "e": "ワークロードIDとは、アプリやサービス、スクリプトなどソフトウェアワークロードが認証に使用するIDのことを指します。", "qEn": "What does a \"workload identity\" refer to?", "oEn": ["An identity used only by a human user signing in interactively (this description is sometimes used)", "A number used to track inventory in a physical warehouse", "The design of an employee badge that features the company logo", "An identity used by software such as an app, service, or script"], "eEn": "A workload identity is an identity used by non-human software workloads, such as applications, services, and scripts, for authentication."}, {"d": "D2", "q": "Microsoft Entra ID のゲストユーザー（外部ID）に関する説明として正しいものはどれですか。", "o": ["B2Bコラボレーションで招待された外部組織のユーザーを指す", "自社の正社員のみに付与される特別なアカウント種別である", "パスワードを一切使わずに作成される専用アカウントである", "テナントの管理者権限が自動的に付与されるアカウントである　"], "a": 0, "e": "ゲストユーザーは、B2Bコラボレーションを通じて外部組織のユーザーを招待し、自組織のリソースへのアクセスを許可する仕組みです。", "qEn": "Which statement about guest users (external identities) in Microsoft Entra ID is correct?", "oEn": ["They refer to external organization users invited via B2B collaboration", "It is a special account type granted only to full-time employees", "It is a dedicated account created without ever using a password", "It is an account that automatically receives tenant admin rights"], "eEn": "Guest users are external organization members invited through B2B collaboration to access resources in your tenant."}, {"d": "D2", "q": "Microsoft Entra ID における「グループ」の主な用途は何ですか。", "o": ["個々のユーザーのパスワードを個別に暗号化する（一般にこう語られることもある）", "複数のユーザーやデバイスをまとめてアクセス権を一括管理する", "サーバーのファームウェアを自動的に更新する", "ネットワークのIPアドレスを動的に割り当てる"], "a": 1, "e": "グループを使用すると、複数のユーザーやデバイスをまとめてアクセス権やライセンスなどを一括管理できます。", "qEn": "What is the main use of a \"group\" in Microsoft Entra ID?", "oEn": ["To individually encrypt the passwords of each user (this is sometimes phrased this way)", "To collectively manage the access rights of multiple users or devices", "To automatically update the firmware of a server", "To dynamically assign IP addresses on a network"], "eEn": "Groups allow administrators to manage multiple users or devices together, assigning access rights and licenses in bulk."}, {"d": "D2", "q": "アプリケーションオブジェクトとサービスプリンシパルの関係について正しい説明はどれですか。", "o": ["アプリケーションオブジェクトはユーザーだけが所有できる限定的な資産である（そのように理解されることもある）", "サービスプリンシパルはネットワーク機器の物理アドレスを表す", "アプリケーションオブジェクトが設計図で、その実行表現がサービスプリンシパルである", "両者はまったく同じ意味を持つ互換可能な用語である"], "a": 2, "e": "アプリケーションオブジェクトはアプリのグローバルな定義（設計図）であり、サービスプリンシパルはそのアプリをテナント内で使用するためのローカルな表現です。", "qEn": "Which statement correctly describes the relationship between an application object and a service principal?", "oEn": ["An application object is a limited asset that only a user can own (this is sometimes understood this way)", "A service principal represents the physical address of a network device", "The application object is the blueprint; the service principal is its local representation", "The two terms mean exactly the same thing and are interchangeable"], "eEn": "An application object is the global definition (blueprint) of an app, while a service principal is its local representation used within a specific tenant."}, {"d": "D2", "q": "Microsoft Entra ID における「外部ID（External ID）」全体が包含する機能として正しいものはどれですか。", "o": ["オンプレミスのプリンター共有機能のみを指す言葉である", "社内ネットワークの物理配線だけを表す用語である", "サーバーのバックアップ実行スケジュールを指す言葉である（このような説明が用いられることもある）", "B2Bコラボレーションと顧客向けアプリへのサインインの両方を含む"], "a": 3, "e": "External IDは、パートナーとのB2Bコラボレーションと、顧客向けアプリケーションへの外部ユーザーのサインインの両方をカバーする包括的な概念です。", "qEn": "What does the overall concept of \"External ID\" in Microsoft Entra ID encompass?", "oEn": ["It is a term that refers only to on-premises printer sharing", "It is a term that describes only the physical wiring of an office network", "It is a term referring to a server's backup execution schedule (this description is sometimes used)", "Both B2B collaboration and sign-in for customer-facing applications"], "eEn": "External ID is a broad concept covering both B2B collaboration with partners and external user sign-in to customer-facing applications."}, {"d": "D2", "q": "組織がAzureリソースでVM上のコード実行時にシークレットをコードに埋め込みたくない場合、推奨される方法はどれですか。", "o": ["マネージドIDを使用してAzureリソースへの認証を行う", "全ユーザー共有の固定パスワードをソースコードへ直接記述する", "APIキーを電子メールで社内の関係者へ共有する", "資格情報をテキストファイルとしてVMのデスクトップに保存する"], "a": 0, "e": "マネージドIDを使用すると、シークレットをコードに埋め込むことなく、Azureが自動的に管理する資格情報でリソースに安全に認証できます。", "qEn": "If an organization wants to avoid embedding secrets in code when a VM accesses Azure resources, which approach is recommended?", "oEn": ["Use a managed identity to authenticate to Azure resources", "Write a fixed password shared by all users directly in the source code", "Share the API key with internal staff via email", "Save the credentials as a text file on the VM's desktop"], "eEn": "A managed identity lets the VM authenticate securely to Azure resources using credentials that Azure manages automatically, without embedding secrets in code."}, {"d": "D2", "q": "Microsoft Entra ID において「テナント管理者」が管理できる対象として正しいものはどれですか。", "o": ["他社が所有する別テナントのユーザーパスワードである", "ユーザーやグループ、アプリ登録、ライセンスなどディレクトリ全体である", "インターネット全体を管理するDNSルートサーバーである（一般にこう語られることもある）", "取引先企業が保有するクレジットカードの情報である"], "a": 1, "e": "テナント管理者は、自組織のディレクトリに含まれるユーザー、グループ、アプリ登録、ライセンスなどのリソースを管理する権限を持ちます。", "qEn": "In Microsoft Entra ID, what can a tenant administrator manage?", "oEn": ["User passwords in a separate tenant owned by another company", "Directory-wide resources such as users, groups, app registrations, and licenses", "The DNS root servers that manage the entire internet (this is sometimes phrased this way)", "Credit card information held by a partner company"], "eEn": "A tenant administrator has the authority to manage resources within their own organization's directory, including users, groups, app registrations, and licenses."}, {"d": "D2", "q": "個人所有のスマートフォンで会社のメールアプリのみを利用する場合、通常どの識別方法が使われますか。", "o": ["Microsoft Entra 参加済みデバイスとして参加させる方法", "オンプレミスのドメインへ直接参加させる方法", "Microsoft Entra 登録済みデバイスとして登録する方法", "デバイスを完全に匿名の状態で利用させる方法"], "a": 2, "e": "個人所有デバイス（BYOD）でアプリにアクセスする場合は、通常Microsoft Entra登録済みデバイスとして登録します。", "qEn": "When a personally owned smartphone is used only to access the company email app, which identification method is typically used?", "oEn": ["The method of joining it as a Microsoft Entra joined device", "The method of joining it directly to an on-premises domain", "The method of registering it as a Microsoft Entra registered device", "The method of using the device in a fully anonymous state"], "eEn": "For personally owned (BYOD) devices accessing corporate apps, the device is typically registered as a Microsoft Entra registered device."}, {"d": "D2", "q": "「クラウドのみのID（Cloud-only identity）」の説明として正しいものはどれですか。", "o": ["必ずオンプレミスのAD DSと同期される必要がある（そのように理解されることもある）", "インターネットへ一切接続できないアカウントである", "パスワードを一切設定できない特殊なアカウントである", "オンプレミスと同期されずEntra ID内だけで作成・管理される"], "a": 3, "e": "クラウドのみのIDは、オンプレミスのディレクトリと同期されず、Microsoft Entra ID内で直接作成・管理されるアカウントです。", "qEn": "Which statement correctly describes a \"cloud-only identity\"?", "oEn": ["It must always be synchronized with on-premises AD DS (this is sometimes understood this way)", "It is an account that cannot connect to the internet at all", "It is a special account for which no password can ever be set", "It is created and managed only within Entra ID, without on-premises sync"], "eEn": "A cloud-only identity is an account created and managed directly within Microsoft Entra ID, with no synchronization from an on-premises directory."}, {"d": "D2", "q": "Microsoft Entra Connect の主な役割は何ですか。", "o": ["オンプレミスのADとMicrosoft Entra IDの間でIDを同期する", "すべてのオンプレミスサーバーを完全にクラウドへ移行する（このような説明が用いられることもある）", "ネットワークのファイアウォールルールを自動的に生成する", "電子メールの添付ファイルをウイルススキャンする"], "a": 0, "e": "Microsoft Entra Connect は、オンプレミスのAD DSとMicrosoft Entra IDの間でユーザーやグループなどのID情報を同期するためのツールです。", "qEn": "What is the main role of Microsoft Entra Connect?", "oEn": ["To synchronize identities between on-premises AD and Microsoft Entra ID", "To completely migrate all on-premises servers to the cloud (this description is sometimes used)", "To automatically generate network firewall rules", "To virus-scan email attachments"], "eEn": "Microsoft Entra Connect is a tool used to synchronize identity data, such as users and groups, between on-premises AD DS and Microsoft Entra ID."}, {"d": "D2", "q": "パスワードハッシュ同期（Password Hash Synchronization）の説明として正しいものはどれですか。", "o": ["パスワードを平文のままクラウドへ送信して保存し続ける", "オンプレミスADのパスワードハッシュをEntra IDへ同期し認証を完結させる", "パスワードの同期を一切行わず常に別々の値を維持する", "オンプレミスサーバーを毎回再起動してパスワードを変更する（一般にこう語られることもある）"], "a": 1, "e": "パスワードハッシュ同期は、オンプレミスADのパスワードハッシュをMicrosoft Entra IDに同期し、クラウド側だけで認証を完結できるようにする方式です。", "qEn": "Which statement correctly describes Password Hash Synchronization?", "oEn": ["It transmits and stores passwords in plain text in the cloud continuously", "It syncs on-premises AD password hashes to Entra ID to complete authentication", "It never synchronizes passwords and always keeps separate values", "It restarts the on-premises server every time to change the password (this is sometimes phrased this way)"], "eEn": "Password Hash Synchronization syncs password hashes from on-premises AD to Microsoft Entra ID, allowing authentication to be completed entirely in the cloud."}, {"d": "D2", "q": "パススルー認証（Pass-through Authentication, PTA）の特徴として正しいものはどれですか。", "o": ["パスワードをすべてクラウドのデータベースに永続保存する（そのように理解されることもある）", "オンプレミスのネットワークが切断中でも認証を継続できる", "認証要求をオンプレミスADへ転送しハッシュをクラウドに保存しない", "AD FSサーバーが不要な代わりに専用回線を必須とする"], "a": 2, "e": "パススルー認証は、サインイン要求をオンプレミスのAD DSに転送して検証し、パスワードハッシュをクラウドに保存しない方式です。", "qEn": "What is a characteristic of Pass-through Authentication (PTA)?", "oEn": ["It permanently stores all passwords in a cloud database (this is sometimes understood this way)", "It can keep authenticating even while on-premises network is disconnected", "It forwards requests to on-premises AD and stores no hash in the cloud", "It removes the need for AD FS but requires a dedicated line instead"], "eEn": "Pass-through Authentication forwards sign-in requests to on-premises AD DS for validation and does not store password hashes in the cloud."}, {"d": "D2", "q": "フェデレーション認証（AD FSを使用したシナリオ）を選択する主な理由として正しいものはどれですか。", "o": ["同期処理を一切不要にしたい場合に選ばれる方式である", "クラウドのみで完結する最も単純な構成にしたい場合である（このような説明が用いられることもある）", "インターネット接続を完全に遮断したい場合に選ばれる", "スマートカードなど高度な認証要件をオンプレミスで活用したい場合"], "a": 3, "e": "フェデレーションは、スマートカードなど既存の高度な認証要件をオンプレミスのインフラでそのまま利用したい場合に選択されます。", "qEn": "What is a primary reason to choose federated authentication (using AD FS)?", "oEn": ["It is chosen when synchronization is meant to be entirely unnecessary", "It is chosen for the simplest possible cloud-only configuration (this description is sometimes used)", "It is chosen when internet connectivity must be completely blocked", "When advanced on-premises requirements, like smart cards, must be kept"], "eEn": "Federation is chosen when organizations need to retain existing advanced on-premises authentication requirements, such as smart card authentication."}, {"d": "D2", "q": "シームレスシングルサインオン（Seamless SSO）の目的として正しいものはどれですか。", "o": ["社内ネットワーク内のユーザーがパスワードを再入力せずに済むようにする", "すべてのユーザーのパスワードを毎日自動的に変更する（一般にこう語られることもある）", "外部ネットワークからのアクセスを完全に禁止する", "クラウド上のすべてのアプリのライセンスを無料化する"], "a": 0, "e": "シームレスSSOは、社内ネットワークに接続しているユーザーが資格情報を再入力せずにクラウドリソースへサインインできるようにします。", "qEn": "What is the purpose of Seamless Single Sign-On (Seamless SSO)?", "oEn": ["To let users on the corporate network avoid re-entering their password", "To automatically change every user's password on a daily basis (this is sometimes phrased this way)", "To completely block access from external networks", "To make licenses for every cloud app free of charge"], "eEn": "Seamless SSO allows users connected to the corporate network to sign in to cloud resources without re-entering their credentials."}, {"d": "D2", "q": "Microsoft Entra Connect Health の主な機能は何ですか。", "o": ["ユーザーの給与情報を自動的に計算する機能である（そのように理解されることもある）", "オンプレミスのID基盤コンポーネントの正常性を監視しアラートする", "サーバーの物理的な温度を測定する機能である", "会議のスケジュールを自動的に調整する機能である"], "a": 1, "e": "Entra Connect Health は、オンプレミスのAD FSやEntra Connect Syncなどのコンポーネントの正常性を監視し、問題発生時にアラートを提供します。", "qEn": "What is the main function of Microsoft Entra Connect Health?", "oEn": ["A function that automatically calculates employee salary data (this is sometimes understood this way)", "To monitor on-premises identity component health and provide alerts", "A function that measures the physical temperature of a server", "A function that automatically adjusts meeting schedules"], "eEn": "Entra Connect Health monitors the health of components such as on-premises AD FS and Entra Connect Sync, alerting administrators to issues."}, {"d": "D2", "q": "Microsoft Entra Cloud Sync と Microsoft Entra Connect Sync の違いとして正しいものはどれですか。", "o": ["Cloud Syncはオンプレミスのディレクトリを一切必要としない　　", "Connect Syncは常にクラウドのみで完結して動作する", "Cloud Syncは軽量エージェント経由でクラウド側が同期処理を行う", "両者はまったく同じ製品であり相違点は存在しない"], "a": 2, "e": "Cloud Syncは軽量エージェント経由でクラウド側が同期ロジックを処理するのに対し、Connect Syncはオンプレミスサーバー上で同期ロジックを実行します。", "qEn": "What is the difference between Microsoft Entra Cloud Sync and Microsoft Entra Connect Sync?", "oEn": ["Cloud Sync requires no on-premises directory of any kind", "Connect Sync always operates entirely within the cloud alone", "Cloud Sync uses a lightweight agent while the cloud performs the sync work", "The two are exactly the same product with no differences at all"], "eEn": "Cloud Sync relies on a lightweight agent with sync logic processed in the cloud, whereas Connect Sync executes the sync logic on an on-premises server."}, {"d": "D2", "q": "ハイブリッドID戦略を採用する組織にとっての利点として正しいものはどれですか。", "o": ["オンプレミスのシステムを即座にすべて廃止できる点である　", "パスワードポリシーの設定がまったく不要になる点である", "組織にインターネット接続が不要になる点である", "オンプレミスとクラウド双方で一貫したID体験を提供できる"], "a": 3, "e": "ハイブリッドID戦略により、ユーザーはオンプレミスとクラウドの両方のリソースに対して一貫したサインイン体験を得られます。", "qEn": "What is a benefit of adopting a hybrid identity strategy for an organization?", "oEn": ["It is the ability to decommission all on-premises systems immediately", "It is that configuring any password policy becomes unnecessary", "It is that the organization no longer needs an internet connection", "It provides a consistent identity experience across on-premises and cloud"], "eEn": "A hybrid identity strategy gives users a consistent sign-in experience across both on-premises and cloud resources."}, {"d": "D2", "q": "Microsoft Entra Connect の同期処理で、オンプレミスのオブジェクトが変更された場合の一般的な動作はどれですか。", "o": ["変更内容が定期的な同期サイクルでEntra IDへ反映される", "変更内容は自動的にすぐ元の状態へ戻される", "変更内容は手動操作でしかクラウドへ反映できない", "変更内容はオンプレミス側だけに留まり同期されない（このような説明が用いられることもある）"], "a": 0, "e": "Entra Connectは定期的な同期サイクル（既定では約30分ごと）でオンプレミスの変更をMicrosoft Entra IDに反映します。", "qEn": "In Microsoft Entra Connect synchronization, what typically happens when an on-premises object is changed?", "oEn": ["The change is reflected in Entra ID during the periodic sync cycle", "The change is automatically reverted back right away", "The change can only ever be reflected in the cloud manually", "The change stays on-premises only and is never synchronized (this description is sometimes used)"], "eEn": "Entra Connect reflects on-premises changes into Microsoft Entra ID during its periodic synchronization cycle (about every 30 minutes by default)."}, {"d": "D2", "q": "パスワードハッシュ同期とパススルー認証を比較したとき、パスワードハッシュ同期特有の利点は何ですか。", "o": ["オンプレミスサーバーが常に稼働している必要がある点である（一般にこう語られることもある）", "オンプレミスADが一時停止していてもクラウド側で認証を継続できる", "認証要求のたびにオンプレミスへの通信が必須になる点である", "フェデレーションサーバーの設置が必須になる点である"], "a": 1, "e": "パスワードハッシュ同期はハッシュ値自体をクラウドに保持するため、オンプレミスADが一時的に停止していてもクラウド側で認証を継続できます。", "qEn": "Compared with Pass-through Authentication, what is a specific benefit of Password Hash Synchronization?", "oEn": ["It requires the on-premises server to always keep running (this is sometimes phrased this way)", "Authentication can continue in the cloud even if on-premises AD is down", "It requires on-premises communication for every authentication request", "It requires a federation server to always be deployed"], "eEn": "Because Password Hash Synchronization stores the hash values in the cloud, authentication can continue there even if on-premises AD is temporarily down."}, {"d": "D2", "q": "Windows Hello for Business の特徴として正しいものはどれですか。", "o": ["常にネットワークケーブル経由でしか認証を行えない", "ユーザー全員が同一の顔写真データを共有して利用する（そのように理解されることもある）", "デバイスに紐づく生体認証やPINを使いパスワードレスでサインインできる", "パスワード入力を必須とし他の認証手段を許可しない"], "a": 2, "e": "Windows Hello for Business は生体認証やPINなど、特定のデバイスに紐づいた資格情報を使用し、パスワードレスでサインインできる仕組みです。", "qEn": "Which statement correctly describes Windows Hello for Business?", "oEn": ["It can only ever authenticate through a wired network cable", "All users share and use the same facial recognition data (this is sometimes understood this way)", "It uses device-bound biometrics or a PIN for passwordless sign-in", "It mandates password entry and disallows any other method"], "eEn": "Windows Hello for Business uses credentials bound to a specific device, such as biometrics or a PIN, to enable passwordless sign-in."}, {"d": "D2", "q": "FIDO2セキュリティキーによる認証の特徴として正しいものはどれですか。", "o": ["パスワードをキー内に平文保存し常にネットワークへ送信する　", "インターネット接続がない状態でのみ利用できる方式である", "すべてのユーザーが同一のキーを共有して使用する必要がある", "物理キーと公開鍵暗号によりフィッシング耐性のある認証を行う"], "a": 3, "e": "FIDO2セキュリティキーは、公開鍵暗号方式を利用した物理デバイスによる認証方式で、フィッシングに強い認証を提供します。", "qEn": "Which statement correctly describes authentication using a FIDO2 security key?", "oEn": ["It stores the password in plain text on the key and always sends it", "It is a method that only works with no internet connection", "All users are required to share a single common key", "It uses a physical key and public-key crypto for phishing-resistant auth"], "eEn": "A FIDO2 security key is a physical device that uses public-key cryptography to provide strong, phishing-resistant authentication."}, {"d": "D2", "q": "証明書ベース認証（Certificate-based Authentication）の仕組みとして正しいものはどれですか。", "o": ["ユーザーが持つデジタル証明書を使いEntra IDへ直接サインインする", "毎回SMSで送られるコードのみを使い認証を行う仕組みである（このような説明が用いられることもある）", "認証にはパスワード入力のみが必要で証明書は使わない", "証明書は紙の書類として保管され電子的には使われない"], "a": 0, "e": "証明書ベース認証は、ユーザーが保有するデジタル証明書を使用してMicrosoft Entra IDへ直接サインインできる認証方式です。", "qEn": "How does certificate-based authentication work?", "oEn": ["Users sign in directly to Entra ID using a digital certificate they hold", "It is a mechanism that authenticates using only an SMS code each time (this description is sometimes used)", "Authentication requires only a password, and no certificate is used", "The certificate is kept as a paper document and never used electronically"], "eEn": "Certificate-based authentication allows users to sign in directly to Microsoft Entra ID using a digital certificate they hold."}, {"d": "D2", "q": "OATHハードウェアトークンを使用したMFAの仕組みとして正しいものはどれですか。", "o": ["トークンがユーザーのパスワードを記憶し代わりに入力する", "一定間隔で生成される使い捨てコードをサインイン時に入力させる", "トークンはインターネット経由で常時サーバーへ接続され続ける　", "トークンは一度使うと物理的に自動で破棄される仕組みである"], "a": 1, "e": "OATHハードウェアトークンは一定時間ごとにワンタイムパスコード（OTP）を生成し、ユーザーはそれをサインイン時に入力して認証します。", "qEn": "How does MFA using an OATH hardware token work?", "oEn": ["The token remembers and enters the user's password on their behalf", "A code generated at regular intervals is entered by the user at sign-in", "The token must maintain a constant live connection to a server", "The token is a device that physically destroys itself after one use"], "eEn": "An OATH hardware token generates a one-time passcode (OTP) at regular intervals, which the user enters during sign-in to authenticate."}, {"d": "D2", "q": "電話（SMSまたは音声通話）による認証方法の説明として正しいものはどれですか。", "o": ["電話番号を使いパスワードを完全に恒久的に置き換える仕組みである", "電話回線が使えない環境でのみ機能する認証方式である", "登録済み電話番号にコードを送りそれを入力させ本人確認する", "SMSや音声を使わず常にメールだけで確認を行う仕組みである"], "a": 2, "e": "電話による認証は、登録済みの電話番号にSMSでコードを送るか音声通話で伝え、それをユーザーが入力することで本人確認を行う方式です。", "qEn": "Which statement correctly describes phone-based authentication (SMS or voice call)?", "oEn": ["It is a mechanism that permanently replaces the user's password entirely", "It is a method that only functions where phone lines are unavailable", "It sends a code to a registered phone number for the user to verify", "It never uses SMS or voice and always relies on email instead"], "eEn": "Phone-based authentication verifies identity by sending a code via SMS or voice call to a registered phone number, which the user then enters."}, {"d": "D2", "q": "Microsoft Authenticator アプリを使ったサインインの利点として正しいものはどれですか。", "o": ["インストールが完了すると全パスワードが自動で削除される　", "利用すると他のすべての認証方法が永久に無効になる", "常にオフラインで動作し通知を一切送信しない仕組みである", "プッシュ通知の承認だけでパスワードレスにサインインできる"], "a": 3, "e": "Microsoft Authenticator アプリでは、プッシュ通知を承認するだけでパスワードレスサインインが可能になり、利便性とセキュリティが向上します。", "qEn": "What is a benefit of signing in using the Microsoft Authenticator app?", "oEn": ["Installing the app automatically deletes all existing passwords", "Using the app permanently disables every other authentication method", "It is a mechanism that always works offline and sends no notifications", "Users can sign in passwordlessly by approving a push notification"], "eEn": "The Microsoft Authenticator app enables passwordless sign-in by simply approving a push notification, improving both convenience and security."}, {"d": "D2", "q": "パスワードレス認証を採用する主な目的として正しいものはどれですか。", "o": ["フィッシングや使い回しのリスクを減らしつつ利便性を高める", "ユーザーのアクセス権をすべて完全に削除する目的である　　", "サインインのステップ数を意図的に増加させる目的である", "デバイスの登録機能をすべて無効化する目的である"], "a": 0, "e": "パスワードレス認証は、フィッシングや使い回しなどパスワードに起因するリスクを軽減しつつ、サインインの利便性を高めることを目的とします。", "qEn": "What is the main goal of adopting passwordless authentication?", "oEn": ["To reduce risks like phishing and reuse while improving convenience", "The goal of completely removing all access rights from users", "The goal of intentionally increasing the number of sign-in steps", "The goal of disabling every device registration capability"], "eEn": "Passwordless authentication aims to reduce risks associated with passwords, such as phishing and reuse, while making sign-in more convenient."}, {"d": "D2", "q": "一時アクセスパス（Temporary Access Pass, TAP）の用途として最も適切なものはどれですか。", "o": ["永久に有効な固定パスワードを新しく発行する目的で使う", "期間限定でパスワードなしにサインインし認証方法を登録させる", "デバイスのハードウェアを物理交換するための許可証である　　", "オフィスビルへの入館証として利用される仕組みである"], "a": 1, "e": "一時アクセスパスは、パスワードなしで期間限定でサインインでき、その間にパスワードレス認証方法の登録などを行うために使用されます。", "qEn": "What is the main use of a Temporary Access Pass (TAP)?", "oEn": ["It is used to issue a new password that remains valid permanently", "To sign in temporarily without a password to register other methods", "It is an authorization used to physically replace device hardware", "It is a mechanism used as a building entry pass for offices"], "eEn": "A Temporary Access Pass allows a time-limited sign-in without a password, commonly used to register passwordless authentication methods."}, {"d": "D2", "q": "従来のパスワード認証が抱える課題として一般的に指摘されるものはどれですか。", "o": ["他の認証方法よりも常に安全性が高いと評価される点である　　", "生体情報を必要とせず絶対に破られないとされる点である", "推測されやすくフィッシングや使い回しによる漏洩リスクが高い", "利用にあたって一切のユーザー入力を必要としない点である"], "a": 2, "e": "パスワードは推測やフィッシング、複数サービスでの使い回しなどにより漏洩するリスクが高いことが一般的な課題として挙げられます。", "qEn": "What is a commonly cited challenge with traditional password-based authentication?", "oEn": ["The point that it is always rated more secure than any other method", "The point that it needs no biometric data and can never be broken", "It is easily guessed and carries high risk via phishing or reuse", "The point that it requires no user input whatsoever to use"], "eEn": "Passwords are commonly criticized for being guessable and prone to compromise through phishing and reuse across multiple services."}, {"d": "D2", "q": "OATHソフトウェアトークン（認証アプリで生成するコード）の特徴として正しいものはどれですか。", "o": ["物理的なUSBデバイスとしてのみ提供される仕組みである", "生成されたコードは一度発行されると永久に有効であり続ける（一般にこう語られることもある）", "インターネットに常時接続していないとコードを生成できない", "スマートフォンのアプリ上で時間ベースのワンタイムコードを生成する"], "a": 3, "e": "OATHソフトウェアトークンは、スマートフォンなどにインストールした認証アプリ上で、一定時間ごとに変化するワンタイムコードを生成します。", "qEn": "What is a characteristic of an OATH software token (a code generated by an authenticator app)?", "oEn": ["It is a mechanism provided only as a physical USB device", "The generated code remains valid forever once it has been issued (this is sometimes phrased this way)", "It can never generate a code without a constant internet connection", "It generates a time-based one-time code within an app on a device"], "eEn": "An OATH software token generates a one-time code that changes at regular intervals, produced by an authenticator app installed on a device like a smartphone."}, {"d": "D2", "q": "Microsoft Entra ID がサポートする認証方法の組み合わせとして正しいものはどれですか。", "o": ["パスワードや電話、FIDO2、Windows Helloなど複数を組み合わせられる", "パスワードのみが唯一サポートされる認証方法である", "認証方法は一度設定すると二度と変更できない仕組みである（そのように理解されることもある）", "すべてのユーザーが必ず同一の認証方法を使う必要がある"], "a": 0, "e": "Microsoft Entra IDは、パスワード、電話、FIDO2、Windows Hello for Business、証明書ベース認証など複数の認証方法をサポートし、組み合わせて利用できます。", "qEn": "Which set of authentication methods does Microsoft Entra ID support?", "oEn": ["A combination such as password, phone, FIDO2, and Windows Hello", "Password is the only authentication method that is supported", "An authentication method, once configured, can never be changed (this is sometimes understood this way)", "Every single user must use exactly the same authentication method"], "eEn": "Microsoft Entra ID supports multiple authentication methods, including password, phone, FIDO2, Windows Hello for Business, and certificate-based authentication, which can be combined."}, {"d": "D2", "q": "証明書ベース認証を利用する際に必要となる主要な前提条件はどれですか。", "o": ["ユーザーのソーシャルメディアアカウントとの事前連携である　　　", "信頼された証明機関が発行したユーザー証明書と信頼チェーンの構成", "オフィスの座席レイアウトを示すデータである", "デバイスのバッテリー残量が常に満充電であることである"], "a": 1, "e": "証明書ベース認証を有効化するには、信頼された証明機関が発行したユーザー証明書と、その証明書チェーンの信頼設定が必要です。", "qEn": "What is a key prerequisite for using certificate-based authentication?", "oEn": ["Prior integration with the user's social media accounts", "A user certificate from a trusted CA plus a configured trust chain", "Data describing an office's seating layout arrangement", "The device battery must always remain at full charge"], "eEn": "Enabling certificate-based authentication requires a user certificate issued by a trusted CA and a properly configured certificate trust chain."}, {"d": "D2", "q": "Windows Hello for Business における生体認証情報の保存場所として正しいものはどれですか。", "o": ["常にMicrosoftのクラウドデータベースへ集中管理される仕組みである", "紙の書類として印刷され保管される仕組みである", "デバイスのTPMなどローカルなセキュリティチップに保存される", "電子メールの添付ファイルとして共有される仕組みである"], "a": 2, "e": "Windows Hello for Business の生体情報は、デバイス内のTPMなどのセキュリティチップにローカル保存され、クラウドには送信されません。", "qEn": "Where is biometric data stored in Windows Hello for Business?", "oEn": ["It is a mechanism always centrally managed in a Microsoft cloud database", "It is a mechanism printed and kept as a paper document", "It is stored locally on the device's security chip, such as a TPM", "It is a mechanism shared as an attachment through email"], "eEn": "In Windows Hello for Business, biometric data is stored locally in the device's security chip (e.g., TPM) and is never transmitted to the cloud."}, {"d": "D2", "q": "組織がフィッシング耐性の高い認証方法を選定する場合、最も適した選択肢はどれですか。", "o": ["SMSで送信されるワンタイムコードだけを使う方式である（このような説明が用いられることもある）", "共有される固定パスワードだけを使う方式である", "電話番号を用いる音声通話だけを使う方式である", "FIDO2キーやWindows Helloなど証明書ベースの認証方式"], "a": 3, "e": "FIDO2セキュリティキーやWindows Hello for Businessは公開鍵暗号を利用するため、フィッシングに強い認証方法として推奨されます。", "qEn": "When an organization wants a highly phishing-resistant authentication method, which option is most suitable?", "oEn": ["A method that uses only a one-time code sent via SMS (this description is sometimes used)", "A method that uses only a shared, static password", "A method that uses only a voice call to a phone number", "Certificate-based methods, such as FIDO2 keys or Windows Hello"], "eEn": "FIDO2 security keys and Windows Hello for Business rely on public-key cryptography, making them recommended, highly phishing-resistant authentication methods."}, {"d": "D2", "q": "多要素認証（MFA）の基本的な考え方として正しいものはどれですか。", "o": ["知識・所持・生体という異なる要素を2つ以上組み合わせて確認する", "同じパスワードを2回連続して入力させることで確認する（一般にこう語られることもある）", "ユーザー名だけを2回入力させることで確認を強化する", "すべての要素を単一のカテゴリからのみ選択して使う"], "a": 0, "e": "MFAは、知識情報（パスワード）、所持情報（デバイス）、生体情報など、異なるカテゴリの要素を2つ以上組み合わせて本人確認を強化する仕組みです。", "qEn": "What is the basic concept behind multifactor authentication (MFA)?", "oEn": ["Combining two or more different factors, like knowledge, possession, and biometrics", "Verifying identity by having the user enter the same password twice (this is sometimes phrased this way)", "Strengthening verification by having the user enter their username twice", "Selecting all the factors from a single category only"], "eEn": "MFA strengthens identity verification by combining two or more factors from different categories, such as something you know, something you have, and something you are."}, {"d": "D2", "q": "MFAにおける「所持要素（something you have）」の例として正しいものはどれですか。", "o": ["ユーザーが記憶しているパスワードそのものである　", "スマートフォンの認証アプリやハードウェアトークン", "ユーザーの指紋や顔などの生体データである", "ユーザーが所属する部署の名称である"], "a": 1, "e": "所持要素とは、スマートフォンの認証アプリやハードウェアトークンなど、ユーザーが物理的に所持しているものを指します。", "qEn": "Which of the following is an example of the \"something you have\" factor in MFA?", "oEn": ["The password itself that the user has memorized", "A smartphone authenticator app or a hardware token", "The user's own biometric data, such as a fingerprint or face", "The name of the department the user belongs to"], "eEn": "The \"something you have\" factor refers to a physical item the user possesses, such as a smartphone authenticator app or a hardware token."}, {"d": "D2", "q": "セキュリティの既定値（Security defaults）を有効にした場合の効果として正しいものはどれですか。", "o": ["すべてのユーザーのMFAを完全に無効化してしまう効果である", "ライセンスなしで無制限に複雑なポリシーを作成できる効果である　", "組織内の全ユーザーへMFA要求などの基本保護を無料で適用できる", "パスワードポリシーそのものを完全に撤廃してしまう効果である"], "a": 2, "e": "セキュリティの既定値は、追加のライセンス費用なしで、MFAの要求などの基本的なセキュリティ保護を組織全体に適用できる機能です。", "qEn": "What is the effect of enabling security defaults?", "oEn": ["It is an effect that completely disables MFA for every user", "It is an effect allowing unlimited complex policies without any license", "It applies baseline protections, like requiring MFA, at no extra cost", "It is an effect that completely removes any password policy"], "eEn": "Security defaults let organizations apply baseline protections, such as requiring MFA, across all users without needing an additional license."}, {"d": "D2", "q": "条件付きアクセスポリシーでMFAを要求する主な利点は何ですか。", "o": ["すべてのサインインへ常に同じ静的ルールしか設定できない", "MFAをまったく使わずにアクセス制御を実現できる点である", "ライセンスに関係なく無制限に高度な条件を設定できる点である　　", "未知の場所や新デバイスなどリスク状況に応じ動的にMFAを課せる"], "a": 3, "e": "条件付きアクセスを使うと、場所やデバイスの状態などの条件に応じて動的にMFAを要求するなど、柔軟なアクセス制御が可能になります。", "qEn": "What is the main benefit of requiring MFA through a Conditional Access policy?", "oEn": ["Only the same static rule can ever be applied to every sign-in", "It is the ability to control access without ever using MFA at all", "It is the ability to set unlimited advanced conditions regardless of license", "MFA can be enforced dynamically based on risk, like an unfamiliar device"], "eEn": "Conditional Access enables flexible access control by dynamically requiring MFA based on conditions such as location or device state."}, {"d": "D2", "q": "Microsoft Authenticator アプリの「番号一致（Number matching）」機能の目的として正しいものはどれですか。", "o": ["画面に表示された番号をアプリへ入力させ誤承認のリスクを下げる", "ユーザーの電話番号を自動的に変更してしまう機能である（そのように理解されることもある）", "パスワードの文字数を数えるための機能である", "アプリの通知音量を自動的に調整するための機能である"], "a": 0, "e": "番号一致機能は、サインイン画面に表示された番号をユーザーがアプリに入力することを要求し、意図しない承認（MFA疲労攻撃）のリスクを減らします。", "qEn": "What is the purpose of the \"number matching\" feature in the Microsoft Authenticator app?", "oEn": ["It has the user enter a displayed number to lower false-approval risk", "It is a feature that automatically changes the user's phone number (this is sometimes understood this way)", "It is a feature used to count the number of characters in a password", "It is a feature that automatically adjusts the app's notification volume"], "eEn": "Number matching requires the user to enter the number displayed on the sign-in screen into the app, reducing the risk of accidental approval from MFA fatigue attacks."}, {"d": "D2", "q": "MFAの登録をユーザーに求めることで得られる効果として最も適切なものはどれですか。", "o": ["ユーザーがパスワードを覚える必要が完全になくなる効果である", "パスワード漏洩時でも不正アクセスのリスクを大幅に低減できる", "サインインの手順自体がすべてのユーザーで不要になる効果である", "アカウントロックアウトの機能が使えなくなってしまう効果である"], "a": 1, "e": "MFAを登録・利用することで、たとえパスワードが漏洩しても追加の認証要素が必要となり、不正アクセスのリスクを大幅に低減できます。", "qEn": "What is the main benefit of requiring users to register for MFA?", "oEn": ["It is an effect that removes the need to remember a password entirely", "It greatly reduces unauthorized access risk even if the password leaks", "It is an effect that removes the sign-in process for every user", "It is an effect that disables the account lockout feature entirely"], "eEn": "Registering for and using MFA means that even if a password is compromised, an additional factor is required, greatly reducing the risk of unauthorized access."}, {"d": "D2", "q": "組織がMFAを導入する際に一般的に推奨される方針として正しいものはどれですか。", "o": ["MFAはコストが高いため常に無効化しておくべきという方針である", "一般ユーザーには適用せず外部ゲストにのみ強制するという方針である", "管理者アカウントなど重要度の高い対象から優先的にMFAを適用する", "MFAはネットワーク帯域にのみ影響しセキュリティとは無関係という方針である"], "a": 2, "e": "MFA導入では、管理者アカウントやリスクの高いアクセスなど、重要度の高い対象から優先的に適用することが一般的に推奨されます。", "qEn": "What is a commonly recommended approach when introducing MFA in an organization?", "oEn": ["A policy stating MFA should always be disabled due to its high cost", "A policy applying MFA only to external guests, never to regular users", "Prioritize high-value targets first, such as administrator accounts", "A policy claiming MFA only affects bandwidth and not security at all"], "eEn": "When introducing MFA, it is generally recommended to prioritize high-value targets first, such as administrator accounts and high-risk access scenarios."}, {"d": "D2", "q": "多要素認証において「生体要素（something you are）」に分類されるものはどれですか。", "o": ["ユーザーが記憶しているPINコードそのものである", "ハードウェアトークンが画面に表示する数字である", "ユーザーが所有するスマートカードそのものである", "指紋認証や顔認識などの身体的特徴を用いる要素"], "a": 3, "e": "生体要素は、指紋や顔認識など、ユーザー自身の身体的特徴を利用する認証要素です。", "qEn": "Which of the following is classified as the \"something you are\" factor in multifactor authentication?", "oEn": ["The PIN code itself that the user has memorized", "The number that a hardware token displays on its screen", "The smart card itself that is owned by the user", "A factor using physical traits, such as a fingerprint or face"], "eEn": "The \"something you are\" factor uses the user's own physical characteristics, such as a fingerprint or facial recognition."}, {"d": "D2", "q": "MFAを有効化した環境でユーザーが新しいデバイスから初めてサインインしようとした場合に起こり得る動作として正しいものはどれですか。", "o": ["追加の認証要素の入力を求められることがある動作である", "アカウントが自動的に完全削除されてしまう動作である", "パスワードの入力が一切不要になってしまう動作である", "サインインの試行がすべて無条件で拒否される動作である"], "a": 0, "e": "条件付きアクセスなどでMFAが構成されている場合、見慣れないデバイスからのサインインでは追加の認証要素の入力が求められることがあります。", "qEn": "In an MFA-enabled environment, what might happen when a user first tries to sign in from a new device?", "oEn": ["It is a behavior where an additional factor may be requested", "It is a behavior where the account is automatically deleted entirely", "It is a behavior where password entry becomes entirely unnecessary", "It is a behavior where every sign-in attempt is rejected unconditionally"], "eEn": "When MFA is configured, for example via Conditional Access, sign-in attempts from an unfamiliar device may prompt for an additional authentication factor."}, {"d": "D2", "q": "MFAが不正アクセス防止において重要とされる理由として最も適切なものはどれですか。", "o": ["MFAを設定するとパスワード管理が完全に不要になるからである", "パスワードを盗んでも追加要素がないとサインインを完了できない", "MFAはネットワーク速度を向上させる技術であるからである", "MFAを使うとロックアウトが二度と発生しなくなるからである"], "a": 1, "e": "MFAでは、攻撃者がパスワードを盗んでも追加の認証要素を満たせない限りサインインが完了できないため、不正アクセスの防止に非常に有効です。", "qEn": "Why is MFA considered important for preventing unauthorized access?", "oEn": ["Because configuring MFA removes the need to manage passwords entirely", "A stolen password alone still cannot complete sign-in without the factor", "Because MFA is a technology that improves overall network speed", "Because using MFA means account lockouts will never occur again"], "eEn": "MFA is highly effective at preventing unauthorized access because an attacker who steals a password still cannot sign in without satisfying the additional factor."}, {"d": "D2", "q": "セルフサービスパスワードリセット（SSPR）の目的として正しいものはどれですか。", "o": ["管理者がすべてのユーザーのパスワードを強制的に閲覧できる　　", "パスワードのリセット自体を完全に禁止してしまう機能である", "管理者へ問い合わせずユーザー自身でパスワードをリセットできる", "パスワードを永久に変更不可能な状態にしてしまう機能である"], "a": 2, "e": "SSPRは、ユーザーがヘルプデスクに連絡することなく、自分自身でパスワードをリセットできるようにする機能です。", "qEn": "What is the purpose of self-service password reset (SSPR)?", "oEn": ["It lets administrators forcibly view the password of every user", "It is a feature that completely prohibits any password reset", "It lets users reset their own password without contacting an admin", "It is a feature that makes passwords permanently unchangeable"], "eEn": "SSPR enables users to reset their own password without having to contact the help desk."}, {"d": "D2", "q": "SSPRを利用するためにユーザーが事前に行う必要がある作業はどれですか。", "o": ["オンプレミスサーバーへの物理アクセス権を取得することである", "自分のパスワードを他の同僚と共有しておくことである", "会社のネットワーク回線を新規に契約することである", "電話番号やメールなど本人確認に使う認証方法の登録である"], "a": 3, "e": "SSPRを利用するには、事前に電話番号やメールアドレスなど本人確認に使用する認証方法を登録しておく必要があります。", "qEn": "What must a user do beforehand in order to use SSPR?", "oEn": ["Obtain physical access rights to an on-premises server first", "Share their password with a colleague ahead of time", "Sign a new contract for the company's network line first", "Register verification methods, such as a phone number or email"], "eEn": "To use SSPR, users must first register authentication methods, such as a phone number or email address, that will be used to verify their identity."}, {"d": "D2", "q": "グローバル禁止パスワードリスト（Global banned password list）の役割として正しいものはどれですか。", "o": ["よく使われ推測されやすいパスワードの使用をブロックする", "すべてのユーザーへ同一のパスワードを強制的に割り当てる", "パスワードの有効期限を無期限に延長してしまう仕組みである", "ユーザーの電話番号を自動的に一般公開してしまう仕組みである"], "a": 0, "e": "グローバル禁止パスワードリストは、Microsoftが収集した一般的で推測されやすいパスワードの使用をブロックする仕組みです。", "qEn": "What is the role of the global banned password list?", "oEn": ["It blocks the use of common, easily guessed passwords", "It is a mechanism that assigns the same password to every user", "It is a mechanism that extends password expiration indefinitely", "It is a mechanism that automatically publishes users' phone numbers"], "eEn": "The global banned password list blocks the use of common, easily guessable passwords collected and maintained by Microsoft."}, {"d": "D2", "q": "カスタム禁止パスワードリスト（Custom banned password list）の用途として正しいものはどれですか。", "o": ["すべてのユーザーのアカウントを恒久的にロックしてしまう機能である", "会社名やブランド名を含むパスワードの使用を追加で禁止する", "パスワードの複雑性要件そのものを完全に撤廃する機能である", "外部ユーザーのみパスワード変更を強制する機能である"], "a": 1, "e": "カスタム禁止パスワードリストを使うと、組織固有の会社名やブランド名などを含むパスワードの使用を管理者が追加で禁止できます。", "qEn": "What is the purpose of the custom banned password list?", "oEn": ["It is a feature that permanently locks every user account", "It additionally blocks passwords that include the company or brand name", "It is a feature that completely eliminates password complexity rules", "It is a feature that forces only external users to change passwords"], "eEn": "The custom banned password list lets administrators additionally block passwords containing organization-specific terms, such as the company name or brand."}, {"d": "D2", "q": "スマートロックアウト（Smart lockout）の目的として正しいものはどれですか。", "o": ["すべてのサインイン試行を無条件で永久にブロックしてしまう", "パスワードの入力そのものを完全に不要にしてしまう仕組みである", "不正な試行を検出し正規ユーザーへの影響を抑えつつロックする", "ネットワークの帯域幅を制限してしまう仕組みである"], "a": 2, "e": "スマートロックアウトは、不正な試行者を一時的にロックアウトする一方で、正規のユーザーが影響を受けにくいよう区別して動作します。", "qEn": "What is the purpose of Smart Lockout?", "oEn": ["It is a mechanism that unconditionally blocks every sign-in forever", "It is a mechanism that removes the need for password entry entirely", "It locks out malicious attempts while limiting impact on legitimate users", "It is a mechanism that limits available network bandwidth"], "eEn": "Smart Lockout temporarily locks out malicious actors attempting sign-in while distinguishing them so legitimate users are minimally affected."}, {"d": "D2", "q": "Microsoft Entra パスワード保護をオンプレミスのActive Directory環境にも拡張する目的として正しいものはどれですか。", "o": ["オンプレミスのすべてのパスワードを削除してしまう目的である　　", "オンプレミスの認証機能そのものを完全に無効化する目的である", "クラウドとの同期処理をすべて停止させる目的である", "オンプレミスでもクラウドと同じ禁止パスワードポリシーを適用する"], "a": 3, "e": "パスワード保護をオンプレミスに拡張することで、オンプレミス環境でもクラウドと同じ禁止パスワードリストによる保護を適用できます。", "qEn": "What is the purpose of extending Microsoft Entra Password Protection to an on-premises Active Directory environment?", "oEn": ["It is a purpose that deletes every password stored on-premises", "It is a purpose that completely disables on-premises authentication", "It is a purpose that stops all synchronization with the cloud", "To apply the same banned password policy on-premises as in the cloud"], "eEn": "Extending Password Protection on-premises applies the same banned password list protections used in the cloud to the on-premises environment as well."}, {"d": "D2", "q": "SSPRとオンプレミスのパスワードライトバック（Writeback）機能を組み合わせる利点として正しいものはどれですか。", "o": ["クラウドでリセットしたパスワードをオンプレミスADにも反映させる", "オンプレミスのパスワードを完全に無効化してしまう機能である　　　", "クラウド側のパスワードのみを永久に凍結してしまう機能である", "ライトバックを使うとMFAが不要になるという性質である"], "a": 0, "e": "パスワードライトバックを有効にすると、クラウドでリセットしたパスワードが即座にオンプレミスのAD DSに反映され、両環境のパスワードが一致します。", "qEn": "What is the benefit of combining SSPR with the on-premises password writeback feature?", "oEn": ["A cloud password reset is written back and reflected in on-premises AD", "It is a feature that completely disables on-premises passwords", "It is a feature that permanently freezes only the cloud-side password", "It is a property where using writeback removes the need for MFA"], "eEn": "With password writeback enabled, a password reset in the cloud is immediately reflected in on-premises AD DS, keeping the password consistent across both environments."}, {"d": "D2", "q": "組織がパスワードの有効期限（パスワード有効期限ポリシー）を見直す際、現在のセキュリティガイダンスで推奨される方向性はどれですか。", "o": ["パスワードは毎日必ず強制的に変更させるべきという方向性である", "強力なパスワードとMFAを組み合わせリスクベースの対応を重視する", "パスワードの長さや複雑性の要件をすべて撤廃すべきという方向性である", "MFAを導入すればパスワード自体が完全に不要になるという考え方である"], "a": 1, "e": "現在のガイダンスでは、単純な定期的パスワード変更よりも、強力なパスワードとMFA、リスクベースの検出を組み合わせることが推奨されています。", "qEn": "When reviewing password expiration policy, what direction does current security guidance generally recommend?", "oEn": ["A direction insisting passwords must be force-changed every single day", "Combine strong passwords with MFA, favoring risk-based responses", "A direction insisting all length and complexity rules be eliminated", "A view claiming adopting MFA removes any need for passwords at all"], "eEn": "Current guidance favors combining strong passwords with MFA and risk-based detection over simply forcing periodic password changes."}, {"d": "D2", "q": "スマートロックアウトのしきい値に関する説明として正しいものはどれですか。", "o": ["しきい値に関係なく1回の失敗で永久にアカウントを削除してしまう", "しきい値は変更できず常に同一の固定値であり続けるものである", "失敗した試行回数や送信元情報などから攻撃者を識別しようとする", "しきい値はパスワードの文字数のみを基準に決まるものである"], "a": 2, "e": "スマートロックアウトは、失敗した試行の回数や送信元の情報などを分析し、正規ユーザーへの影響を抑えつつ攻撃者を識別しようとします。", "qEn": "Which statement correctly describes Smart Lockout's threshold behavior?", "oEn": ["Regardless of threshold, it permanently deletes the account after one failure", "The threshold cannot be changed and remains the same fixed value always", "It tries to identify attackers using failed attempt counts and origin data", "The threshold is decided solely based on the number of password characters"], "eEn": "Smart Lockout analyzes factors like the number and origin of failed attempts to distinguish attackers from legitimate users while minimizing impact on the latter."}, {"d": "D2", "q": "SSPRで複数の認証方法（電話、メール、セキュリティの質問など）の登録を要求する理由として正しいものはどれですか。", "o": ["登録数が多いほどパスワードの複雑性要件が免除されるからである", "ユーザーの個人情報をより多く収集し販売するためである", "認証方法が多いほどパスワードリセット自体が不要になるからである　", "1つの方法が使えない場合でも本人確認手段を確保しなりすましを防ぐ"], "a": 3, "e": "複数の認証方法を登録させることで、1つの手段が使えない場合でも本人確認を継続でき、なりすましによる不正なリセットのリスクを低減できます。", "qEn": "Why does SSPR require registering multiple authentication methods (e.g., phone, email, security questions)?", "oEn": ["Because registering more methods exempts users from complexity rules", "It is done to collect more personal information from users for resale", "Because having more methods removes the need for resets entirely", "To keep an identity-check path available if one method fails, preventing impersonation"], "eEn": "Requiring multiple registered authentication methods ensures identity verification remains possible even if one method is unavailable, reducing the risk of fraudulent resets via impersonation."}, {"d": "D2", "q": "Conditional Access のポリシーは、条件が満たされた場合に何を行うか最も適切に説明しているのはどれか。", "o": ["シグナルを評価してアクセスを許可・ブロック・追加要件のいずれかに決定すること", "サインインの場所やデバイス状態などの入力条件を収集すること　　　　　　　　　", "多要素認証などの強制アクションを実行すること", "ポリシーの対象ユーザーやアプリを定義すること"], "a": 0, "e": "Conditional Access はシグナルを評価し、アクセスを許可・ブロック、または追加の要件を課すかを判断する仕組みである。", "qEn": "Which best describes what a Conditional Access policy does when its conditions are met?", "oEn": ["Evaluating signals to decide whether to grant, block, or require additional controls for access", "Collecting input conditions such as sign-in location or device state", "Executing an enforcement action such as multi-factor authentication", "Defining the target users or apps the policy applies to"], "eEn": "Conditional Access evaluates signals and makes a decision to allow, block, or require additional controls before granting access."}, {"d": "D2", "q": "次のうち、Conditional Access ポリシーの評価対象となるシグナルの例として正しいものはどれか。", "o": ["ユーザーのメールボックス使用容量", "サインイン時のリスクレベル", "割り当てられているライセンスの単価", "テナントのタイムゾーン設定"], "a": 1, "e": "サインイン時のリスクレベルは Conditional Access が評価する代表的なシグナルの一つである。", "qEn": "Which of the following is a correct example of a signal evaluated by a Conditional Access policy?", "oEn": ["The user's mailbox storage usage", "The risk level at sign-in time", "The unit price of the assigned license", "The tenant's time zone setting"], "eEn": "Sign-in risk level is one of the typical signals evaluated by Conditional Access."}, {"d": "D2", "q": "Conditional Access で「アクセス制御」として構成できる項目はどれか。", "o": ["パスワードの有効期限を自動延長する", "ユーザーのメールボックスを自動削除する", "多要素認証を要求する", "ライセンスの自動更新を無効化する"], "a": 2, "e": "多要素認証の要求は Conditional Access の代表的なアクセス制御（コントロール）である。", "qEn": "Which item can be configured as an access control in Conditional Access?", "oEn": ["Automatically extending the password expiration date", "Automatically deleting the user's mailbox", "Requiring multi-factor authentication", "Disabling automatic license renewal"], "eEn": "Requiring multi-factor authentication is a typical Conditional Access control."}, {"d": "D2", "q": "Conditional Access ポリシーの適用対象として指定できるのはどれか。", "o": ["特定の物理サーバーのラック位置", "ネットワークスイッチのファームウェア　　　　　　　", "プリンタードライバーのバージョン", "特定のユーザーグループとクラウドアプリの組み合わせ"], "a": 3, "e": "Conditional Access はユーザー/グループとクラウドアプリの組み合わせに対して割り当てを行う。", "qEn": "What can be specified as the assignment target of a Conditional Access policy?", "oEn": ["The rack position of a specific physical server", "The firmware of a network switch", "The version of a printer driver", "A combination of specific user groups and cloud apps"], "eEn": "Conditional Access assignments target combinations of users/groups and cloud apps."}, {"d": "D2", "q": "Conditional Access で「準拠デバイスが必要」という制御を使用する主な目的は何か。", "o": ["Intune 等でコンプライアンス基準を満たしたデバイスのみアクセスを許可する", "すべてのデバイスに同じアプリを自動配布する　　　　　　　　　　　　　　　　　　", "デバイスのストレージ容量を自動的に拡張する", "デバイスの既定言語を統一的に設定する"], "a": 0, "e": "「準拠デバイスが必要」は、Intune などでコンプライアンスを満たしたデバイスのみアクセスを許可する制御である。", "qEn": "What is the main purpose of the 'Require device to be marked as compliant' control in Conditional Access?", "oEn": ["Allowing access only from devices that meet compliance standards, e.g. via Intune", "Automatically distributing the same app to all devices", "Automatically expanding a device's storage capacity", "Uniformly setting the default language on devices"], "eEn": "This control only permits access from devices that meet compliance requirements set through tools like Intune."}, {"d": "D2", "q": "Conditional Access ポリシーを評価する際、まず何が行われるか。", "o": ["サブスクリプションの契約更新処理　　　　", "第一要素認証（パスワードなど）の完了確認", "リソースグループの自動削除処理", "請求先住所の確認処理"], "a": 1, "e": "Conditional Access はまず第1要素認証が完了した後にポリシーが評価される。", "qEn": "What generally happens first when a Conditional Access policy is evaluated?", "oEn": ["Processing the subscription contract renewal", "Confirming completion of first-factor authentication (e.g. password)", "Automatically deleting a resource group", "Confirming the billing address"], "eEn": "Conditional Access policies are evaluated after first-factor authentication completes."}, {"d": "D2", "q": "Conditional Access の「名前付きの場所」機能の用途はどれか。", "o": ["ユーザーの自宅住所を登録して管理する", "データセンターの物理的な座標を記録する　　　　　　　", "特定のIPアドレス範囲を信頼できる場所として定義する", "会議室の予約状況を一覧管理する"], "a": 2, "e": "名前付きの場所は、特定のIPアドレス範囲を信頼できる/危険な場所として定義するために使用する。", "qEn": "What is the 'Named locations' feature in Conditional Access used for?", "oEn": ["Registering and managing a user's home address", "Recording the physical coordinates of a data center", "Defining specific IP address ranges as trusted locations", "Managing a list of meeting room reservations"], "eEn": "Named locations let administrators define IP address ranges as trusted or risky locations."}, {"d": "D2", "q": "Conditional Access ポリシーで複数の制御（コントロール）を組み合わせた場合の既定の動作はどれか。", "o": ["常に最初に構成した制御のみが適用される", "適用する制御が毎回ランダムに選ばれる", "制御を2つ以上設定すると自動的に無効化される　　　　　　　　", "「すべての制御を要求」と「いずれかの制御を要求」を選択できる"], "a": 3, "e": "複数コントロールを組み合わせる場合、すべて要求するか、いずれか一つを要求するかを選択できる。", "qEn": "What happens by default when multiple controls are combined in a Conditional Access policy?", "oEn": ["Only the first configured control is always applied", "The control to apply is chosen randomly each time", "Configuring two or more controls automatically disables them", "You can choose to require all controls or require one of the controls"], "eEn": "When combining multiple controls, administrators can require all of them or require just one."}, {"d": "D2", "q": "Conditional Access はどのライセンスで利用できるか（一般的な位置付け）。", "o": ["Microsoft Entra ID P1 以上のライセンス", "すべてのプランで無条件かつ無料で利用可能", "Exchange Online のライセンスのみで十分", "Windows Server の CAL ライセンスのみ　　"], "a": 0, "e": "Conditional Access は一般的に Microsoft Entra ID P1 以上のライセンスで利用可能である。", "qEn": "Which licensing tier generally provides access to Conditional Access?", "oEn": ["Microsoft Entra ID P1 or higher licensing", "Any plan, free and unconditional", "Exchange Online licensing alone is sufficient", "Windows Server CAL licensing alone"], "eEn": "Conditional Access is generally available with Microsoft Entra ID P1 or higher licensing."}, {"d": "D2", "q": "Conditional Access ポリシーの「レポート専用」モードの目的は何か。", "o": ["対象ユーザーへのアクセスを即座に遮断する", "ポリシーを適用せずに影響をシミュレートして確認する", "ユーザーのライセンス構成を自動的に変更する　　　　", "パスワードを強制的に失効させる"], "a": 1, "e": "レポート専用モードは、ポリシーを実際に適用せずに影響を評価するために使う。", "qEn": "What is the purpose of 'Report-only' mode for a Conditional Access policy?", "oEn": ["Immediately blocking access for the target users", "Simulating and reviewing the impact without actually enforcing the policy", "Automatically changing the user's license configuration", "Forcibly expiring the password"], "eEn": "Report-only mode lets administrators evaluate a policy's impact before actually enforcing it."}, {"d": "D2", "q": "Conditional Access で「アプリの強制制限（App Enforced Restrictions）」の役割は何か。", "o": ["アプリのライセンス価格を自動的に割り引く", "アプリのインストール先フォルダーを自動選択する　　　　　　　　　", "非準拠デバイスからのアクセス時にアプリ側で制限付き体験を提供する", "アプリのソースコードを自動的に暗号化する"], "a": 2, "e": "アプリの強制制限は、非準拠デバイスからのアクセス時にアプリ自体が制限付き体験を提供する機能である。", "qEn": "What role does 'App Enforced Restrictions' play in Conditional Access?", "oEn": ["Automatically discounting the app's license price", "Automatically choosing the app's install destination folder", "Providing a restricted experience within the app itself when accessed from a non-compliant device", "Automatically encrypting the app's source code"], "eEn": "App enforced restrictions let the app itself limit the user experience when access comes from a non-compliant device."}, {"d": "D2", "q": "Global Secure Access は Conditional Access とどのように連携するか。", "o": ["ネットワーク帯域幅を無条件に無制限へ拡張する　　　　　　　　　　　　　", "テナント全体の電力使用量を最適化する", "印刷ジョブの優先度を自動的に調整する", "ネットワークトラフィックをシグナルとして評価しアクセス制御を適用できる"], "a": 3, "e": "Global Secure Access はネットワークトラフィックをシグナルとして扱い、Conditional Access のアクセス制御を適用できる。", "qEn": "How does Global Secure Access integrate with Conditional Access?", "oEn": ["Unconditionally expanding network bandwidth without limit", "Optimizing the tenant's overall power consumption", "Automatically adjusting print job priority", "Evaluating network traffic as a signal so access controls can be applied"], "eEn": "Global Secure Access can feed network traffic signals into Conditional Access so its controls also apply there."}, {"d": "D2", "q": "Conditional Access ポリシーが「ユーザーごとの多要素認証（レガシーMFA）」と異なる主な点は何か。", "o": ["条件に基づいて動的できめ細かい制御を実現できる", "常にすべてのユーザーへ一律に同じ設定が適用される", "デバイスの種類を判定する機能を持たない", "特定のクラウドアプリを対象に指定できない"], "a": 0, "e": "Conditional Access はレガシーMFAと異なり、条件に基づいた動的できめ細かな制御を実現できる。", "qEn": "What is a key difference between Conditional Access and legacy per-user MFA?", "oEn": ["It provides dynamic, fine-grained control based on conditions", "The same setting is always applied uniformly to every user", "It has no ability to determine the device type", "It cannot be scoped to specific cloud apps"], "eEn": "Unlike legacy per-user MFA, Conditional Access allows dynamic and granular control based on evaluated conditions."}, {"d": "D2", "q": "Conditional Access で除外設定を行う一般的な理由はどれか。", "o": ["全ユーザーをポリシーの対象から除外するため　　　　　　　　　", "緊急アクセス用アカウントがロックアウトされないようにするため", "ポリシーの評価処理を高速化するため", "対象アプリの課金処理を停止するため"], "a": 1, "e": "緊急アクセス（ブレークグラス）アカウントを除外し、ロックアウトを防ぐのが一般的な理由である。", "qEn": "What is a common reason for configuring exclusions in Conditional Access?", "oEn": ["To exclude every user from the policy scope", "To prevent emergency access (break-glass) accounts from being locked out", "To speed up the policy evaluation process", "To stop billing processing for the target app"], "eEn": "Excluding break-glass emergency access accounts prevents administrators from being locked out."}, {"d": "D2", "q": "Microsoft Entra のロールベースアクセス制御(RBAC)における「ロールの割り当て」の説明として正しいものはどれか。", "o": ["ロールをスコープに関係なくテナント全体へ自動適用すること　　　", "ロールを削除すると監査ログが自動的に消去されること", "ユーザーやグループに特定のスコープでロールの権限を付与すること", "ロールがサブスクリプションの請求方法を決定すること"], "a": 2, "e": "ロールの割り当てとは、ユーザーやグループに特定のスコープでロールの権限を付与することである。", "qEn": "Which correctly describes a 'role assignment' in Microsoft Entra RBAC?", "oEn": ["Automatically applying a role tenant-wide regardless of scope", "Deleting a role automatically erases audit logs", "Granting a user or group the permissions of a role at a specific scope", "A role determines the subscription's billing method"], "eEn": "A role assignment grants a user or group the permissions of a role within a defined scope."}, {"d": "D2", "q": "「最小特権の原則」に基づいてMicrosoft Entraロールを付与する際の推奨事項はどれか。", "o": ["すべてのユーザーにグローバル管理者ロールを付与する", "ロールの割り当ては常に恒久的な方法でのみ行う", "役割を割り当てず全員をゲストユーザーとして扱う", "業務に必要な最小限の権限を持つロールのみを付与する"], "a": 3, "e": "最小特権の原則では、業務遂行に必要な最小限の権限のみを割り当てることが推奨される。", "qEn": "Following the principle of least privilege, what is recommended when assigning Microsoft Entra roles?", "oEn": ["Assign Global Administrator to every user", "Only ever assign roles in a permanent manner", "Assign no role and treat everyone as a guest user", "Assign only roles with the minimum permissions needed for the job"], "eEn": "Least privilege recommends assigning only the minimum permissions required for a person's job."}, {"d": "D2", "q": "Microsoft Entra の「グローバル管理者」ロールについて正しい説明はどれか。", "o": ["テナント内のほぼすべての管理機能にアクセスできる最上位のロール", "パスワードのリセットのみに限定されたロール", "特定の1つのアプリケーション利用のみを許可するロール　　　　　", "課金情報の閲覧のみが可能なロール"], "a": 0, "e": "グローバル管理者はテナント内のほぼすべての管理機能にアクセスできる最上位のロールである。", "qEn": "Which is a correct description of the 'Global Administrator' role in Microsoft Entra?", "oEn": ["The top-level role with access to nearly all administrative functions in the tenant", "A role limited only to resetting passwords", "A role that permits use of only one specific application", "A role that can only view billing information"], "eEn": "Global Administrator is the top-level role with access to nearly all management capabilities in the tenant."}, {"d": "D2", "q": "Microsoft Entra の組み込みロールと比較したカスタムロールの利点はどれか。", "o": ["常に無料かつ無制限に作成できる特別なロール", "組織固有の権限セットを細かく組み合わせて定義できる", "グローバル管理者より常に強い権限を持つロール", "Azure リソースの請求額を自動的に減らすロール"], "a": 1, "e": "カスタムロールを使うと、組織固有の要件に合わせて権限を細かく定義できる。", "qEn": "What is an advantage of custom roles compared to built-in roles in Microsoft Entra?", "oEn": ["A special role that can always be created for free without limit", "Allowing fine-grained combinations of an organization-specific permission set", "A role that always has stronger permissions than Global Administrator", "A role that automatically reduces Azure resource billing"], "eEn": "Custom roles let organizations precisely tailor permission sets to their specific needs."}, {"d": "D2", "q": "「ユーザー管理者」ロールが一般的に実行できる操作はどれか。", "o": ["サブスクリプション全体を削除する権限", "Azure仮想マシンを新規作成する権限", "一般ユーザーアカウントのパスワードリセットや属性管理", "グローバル管理者ロールを永久に剥奪する権限　　　　　"], "a": 2, "e": "ユーザー管理者は一般ユーザーアカウントの管理、パスワードリセットや属性変更などを行える。", "qEn": "Which operation can the 'User Administrator' role generally perform?", "oEn": ["The right to delete an entire subscription", "The right to create a new Azure virtual machine", "Resetting passwords and managing attributes of regular user accounts", "The right to permanently revoke the Global Administrator role"], "eEn": "User Administrator can manage regular user accounts, including password resets and attribute changes."}, {"d": "D2", "q": "Microsoft Entra ロールと Azure RBAC ロールの違いを最もよく表しているのはどれか。", "o": ["両者はまったく同じ機能を提供する仕組みである", "Azure RBAC はテナント全体のディレクトリ管理専用である　　　　　　　　　　　　　　　　", "Entra ロールはリソースグループの課金のみを制御する", "Entra ロールはディレクトリ管理、Azure RBAC はAzureリソース管理を対象とする"], "a": 3, "e": "Microsoft Entraロールはディレクトリ（ID）の管理、Azure RBACはAzureリソースへのアクセス管理を対象とする。", "qEn": "Which best describes the difference between Microsoft Entra roles and Azure RBAC roles?", "oEn": ["They provide exactly the same mechanism and functionality", "Azure RBAC is exclusively for managing the entire tenant directory", "Entra roles control only resource group billing", "Entra roles govern directory management while Azure RBAC governs Azure resource management"], "eEn": "Microsoft Entra roles manage the directory/identity, while Azure RBAC manages access to Azure resources."}, {"d": "D2", "q": "組み込みロールで対応できない要件がある場合の一般的な対処方法はどれか。", "o": ["カスタムロールを作成し必要な権限のみを組み合わせる", "全ユーザーにグローバル管理者ロールを付与する　　　", "ロール機能そのものを完全に無効化する", "該当するサブスクリプションを解約する"], "a": 0, "e": "組み込みロールで足りない場合は、必要な権限のみを組み合わせたカスタムロールを作成するのが一般的な対処法である。", "qEn": "What is a common approach when a requirement cannot be met by built-in roles?", "oEn": ["Create a custom role combining only the needed permissions", "Assign Global Administrator to every user", "Disable the role feature entirely", "Cancel the subscription in question"], "eEn": "Creating a custom role with exactly the required permissions is the standard approach in such cases."}, {"d": "D2", "q": "「セキュリティ管理者」ロールの主な責務はどれか。", "o": ["給与計算システムの運用管理", "セキュリティ関連機能やポリシーの構成・監視", "社内の印刷サーバーの運用管理　　　　　　　", "会議室予約システムの運用管理"], "a": 1, "e": "セキュリティ管理者はセキュリティ関連の機能やポリシーの構成・監視を主な責務とする。", "qEn": "What is the main responsibility of the 'Security Administrator' role?", "oEn": ["Operating and managing the payroll system", "Configuring and monitoring security-related features and policies", "Operating and managing the in-house print server", "Operating and managing the meeting room booking system"], "eEn": "Security Administrator is primarily responsible for configuring and monitoring security features and policies."}, {"d": "D2", "q": "Microsoft Entra でロールの割り当てを確認・監査する際に役立つ機能はどれか。", "o": ["サブスクリプションの請求書の内容", "ネットワーク帯域幅のモニタリング画面　", "監査ログとロール割り当てのレビュー機能", "印刷ジョブの実行履歴"], "a": 2, "e": "監査ログとロール割り当てのレビュー機能を使うことで、誰にどのロールが割り当てられているかを確認・監査できる。", "qEn": "Which feature is useful for checking and auditing role assignments in Microsoft Entra?", "oEn": ["The contents of subscription invoices", "A network bandwidth monitoring screen", "Audit logs together with role assignment review features", "The execution history of print jobs"], "eEn": "Audit logs together with role assignment review capabilities help verify who holds which role."}, {"d": "D2", "q": "職務分掌（Separation of Duties）の観点から推奨される運用はどれか。", "o": ["一人のユーザーにすべての管理ロールを集中させる運用　", "ロールの割り当て状況を一切記録しない運用", "重要な操作の承認プロセスを省略する運用", "重要な操作を複数の異なるロール保持者に分担させる運用"], "a": 3, "e": "職務分掌の観点からは、重要な操作を複数の担当者に分担させ、権限の集中を避けることが推奨される。", "qEn": "Which practice is recommended from a separation-of-duties perspective?", "oEn": ["Concentrating all administrative roles in a single user", "Keeping no record at all of role assignment status", "Skipping the approval process for critical operations", "Splitting critical operations across multiple different role holders"], "eEn": "Separation of duties recommends distributing critical operations across multiple people rather than concentrating power in one account."}, {"d": "D2", "q": "Microsoft Entra ID Governance の「entitlement management（権限管理）」の主な目的は何か。", "o": ["アクセスパッケージを通じてリソースへのアクセス要求・承認・有効期限管理を自動化する", "すべてのユーザーへ無条件で管理者権限を付与する　　　　　　　　　　　　　　　　　　", "テナント全体のネットワーク帯域幅を割り当てる", "顧客向けの請求書を自動的に生成する"], "a": 0, "e": "entitlement management はアクセスパッケージを通じて、リソースへのアクセス要求・承認・有効期限を自動化する。", "qEn": "What is the main purpose of 'entitlement management' in Microsoft Entra ID Governance?", "oEn": ["Automating access requests, approvals, and expiration for resources via access packages", "Unconditionally granting administrative rights to every user", "Allocating network bandwidth across the tenant", "Automatically generating invoices for customers"], "eEn": "Entitlement management automates access requests, approvals, and expiration of access to resources through access packages."}, {"d": "D2", "q": "「アクセスパッケージ」に含めることができるリソースの例はどれか。", "o": ["物理的な会議室の入退室用の鍵", "グループ、Teams、アプリケーション、SharePointサイトなど", "倉庫に保管された印刷用紙の在庫", "社員食堂で提供されるメニュー情報　　　　　　　　　　　　　　　　　　　"], "a": 1, "e": "アクセスパッケージには、グループやTeams、アプリケーション、SharePointサイトなどを含めることができる。", "qEn": "Which is an example of a resource that can be included in an 'access package'?", "oEn": ["A physical key for entering a meeting room", "Groups, Teams, applications, SharePoint sites, and the like", "Printer paper inventory stored in a warehouse", "Menu information served in the employee cafeteria"], "eEn": "Access packages can bundle groups, Teams, applications, and SharePoint sites, among other resources."}, {"d": "D2", "q": "entitlement management における「有効期限（expiration）」設定の目的はどれか。", "o": ["ユーザーのパスワードを強制的に変更させること　　　　　　　　　　　", "対象アプリのライセンス価格を引き下げること", "一定期間後にアクセス権を自動失効させ不要なアクセスの蓄積を防ぐこと", "ネットワークの通信遅延を減らすこと"], "a": 2, "e": "有効期限設定により、一定期間後にアクセス権を自動失効させ、不要なアクセスの蓄積を防止できる。", "qEn": "What is the purpose of the 'expiration' setting in entitlement management?", "oEn": ["Forcing a change of the user's password", "Lowering the license price of the target app", "Automatically expiring access after a set period to prevent unnecessary access from accumulating", "Reducing network communication latency"], "eEn": "Expiration settings automatically revoke access after a period, preventing stale access from piling up."}, {"d": "D2", "q": "「ライフサイクルワークフロー（Lifecycle Workflows）」機能が自動化する対象はどれか。", "o": ["サーバーのファームウェアを自動的に更新すること　　　　　　　", "年次の会計監査を自動的に実施すること", "建物の入退室記録を自動的に集計すること", "従業員の入社・異動・退職に伴うID関連タスクを自動化すること"], "a": 3, "e": "Lifecycle Workflows は入社・異動・退職に伴うID関連タスクを自動化する機能である。", "qEn": "What does the 'Lifecycle Workflows' feature automate?", "oEn": ["Automatically updating server firmware", "Automatically conducting an annual accounting audit", "Automatically tallying building entry and exit records", "Automating identity-related tasks tied to employee joining, moving, and leaving"], "eEn": "Lifecycle Workflows automates identity tasks associated with joiner, mover, and leaver events."}, {"d": "D2", "q": "外部ユーザー（B2B）に対してentitlement managementを使う利点はどれか。", "o": ["承認ワークフローを経て必要なリソースへのアクセスを付与し期限切れで自動削除できる", "外部ユーザーを無条件でグローバル管理者に昇格させる　　　　　　　　　　　　　　　", "外部ユーザーの請求情報を組織外に公開する", "外部ユーザーのネットワーク帯域を無制限に拡張する"], "a": 0, "e": "entitlement managementを使うと、外部ユーザーに承認プロセスを経てアクセスを付与し、期限切れで自動削除できる。", "qEn": "What is a benefit of using entitlement management for external (B2B) users?", "oEn": ["Granting needed resource access through an approval workflow and removing it automatically at expiration", "Unconditionally promoting external users to Global Administrator", "Publicly exposing external users' billing information outside the organization", "Expanding external users' network bandwidth without limit"], "eEn": "Entitlement management lets external users get access via an approval workflow, with automatic removal at expiration."}, {"d": "D2", "q": "アクセスパッケージの承認者として設定できるのはどれか。", "o": ["システムが自動生成した架空のユーザーのみ　　", "指定されたマネージャーや特定の承認者グループ", "常に外部の監査法人に限定される", "承認者を設定する仕組みは存在しない"], "a": 1, "e": "アクセスパッケージの承認者には、指定されたマネージャーや特定の承認者グループを設定できる。", "qEn": "Who can be configured as an approver for an access package?", "oEn": ["Only fictitious users automatically generated by the system", "A designated manager or a specific group of approvers", "Always limited to an external audit firm", "There is no mechanism to configure an approver"], "eEn": "Access package approvers can be a specific manager or a designated group of approvers."}, {"d": "D2", "q": "entitlement management における「カタログ（Catalog）」の役割はどれか。", "o": ["ネットワーク機器の在庫を管理する仕組み　　　　　　　", "請求書のテンプレートを集約した仕組み", "アクセスパッケージに含めるリソースをまとめたコンテナ", "会議室予約の履歴を保存する仕組み"], "a": 2, "e": "カタログは、アクセスパッケージに含めるリソースをまとめて管理するコンテナである。", "qEn": "What is the role of a 'Catalog' in entitlement management?", "oEn": ["A mechanism for managing network equipment inventory", "A mechanism aggregating invoice templates", "A container that groups resources to be included in access packages", "A mechanism that stores meeting room reservation history"], "eEn": "A catalog is a container that groups together the resources used to build access packages."}, {"d": "D2", "q": "Lifecycle Workflows で「退職時タスク」の例として適切なものはどれか。", "o": ["新しいノートPCを発注する処理　　　　", "給与の増額を処理する作業", "入社時研修の予約を行う作業", "アカウントの無効化やグループからの削除"], "a": 3, "e": "退職時タスクの例として、アカウントの無効化やグループからの削除が挙げられる。", "qEn": "Which is an appropriate example of a 'leaver task' in Lifecycle Workflows?", "oEn": ["Processing an order for a new laptop", "Processing a salary increase", "Booking new-hire onboarding training", "Disabling the account and removing it from groups"], "eEn": "Disabling the account and removing group memberships are typical leaver tasks."}, {"d": "D2", "q": "entitlement management のアクセス要求ポリシーで「誰が要求できるか」を制限する対象例はどれか。", "o": ["特定のディレクトリ内のユーザーや特定組織の外部ユーザー", "サーバーのIPアドレス範囲のみに限定される　　　　　　", "消費される電力使用量のみに限定される", "印刷される用紙の枚数のみに限定される"], "a": 0, "e": "要求ポリシーでは、特定のディレクトリ内のユーザーや特定組織の外部ユーザーなどに要求可能者を限定できる。", "qEn": "In an entitlement management request policy, which is an example of restricting 'who can request'?", "oEn": ["Users within a specific directory or external users from a specific organization", "Limited only to a server's IP address range", "Limited only to the amount of power consumed", "Limited only to the number of pages printed"], "eEn": "Request policies can restrict requesters to specific directories or external users from a designated organization."}, {"d": "D2", "q": "Microsoft Entra ID Governance が組織にもたらす主な価値はどれか。", "o": ["テナント全体のネットワーク遅延を削減する価値　　　　　　　　　　", "アクセスのライフサイクル全体を通じたガバナンスと監査可能性の向上", "施設全体の電気料金を削減する価値", "オフィスの印刷コストを削減する価値"], "a": 1, "e": "ID Governance は、アクセスのライフサイクル全体でガバナンスと監査可能性を高める価値を提供する。", "qEn": "What is the main value that Microsoft Entra ID Governance brings to an organization?", "oEn": ["Reducing network latency tenant-wide", "Improving governance and auditability across the entire access lifecycle", "Reducing electricity costs across a facility", "Reducing an office's printing costs"], "eEn": "ID Governance provides governance and auditability throughout the full lifecycle of access."}, {"d": "D2", "q": "アクセスパッケージへのアクセス要求時に「利用規約への同意」を要求できる機能はどれか。", "o": ["パスワードの複雑さを強制するポリシー", "デバイスのコンプライアンス状態を確認するポリシー　　　　　", "利用規約（Terms of Use）への同意を要求する機能", "通信経路を制限するネットワークポリシー"], "a": 2, "e": "利用規約（Terms of Use）機能を使うと、アクセス要求時に規約への同意を求めることができる。", "qEn": "Which feature can require agreement to terms when requesting an access package?", "oEn": ["A policy enforcing password complexity", "A policy checking a device's compliance state", "A feature requiring acceptance of Terms of Use", "A network policy restricting the communication path"], "eEn": "The Terms of Use feature can require users to accept terms as part of the access request."}, {"d": "D2", "q": "entitlement management における定期的な「アクセスレビュー」との連携の目的はどれか。", "o": ["アクセスパッケージの価格設定を変更すること　　　　　　　　　　　　　　　　", "サーバーの再起動スケジュールを管理すること", "テナントのネットワーク帯域を拡張すること", "割り当てられたアクセスが引き続き必要かを定期的に確認し不要なら削除すること"], "a": 3, "e": "アクセスレビューとの連携により、割り当てられたアクセスが引き続き必要かを定期的に確認し不要分を削除できる。", "qEn": "What is the purpose of integrating periodic 'access reviews' with entitlement management?", "oEn": ["Changing the pricing of the access package", "Managing the server reboot schedule", "Expanding the tenant's network bandwidth", "Periodically verifying whether assigned access is still needed and removing it if not"], "eEn": "Integrating access reviews lets organizations periodically confirm whether assigned access is still needed and remove it otherwise."}, {"d": "D2", "q": "Microsoft Entra の「アクセスレビュー」機能の主な目的は何か。", "o": ["グループ・アプリ・ロールへのアクセス権を定期的に見直し不要なアクセスを削除する", "すべてのユーザーのパスワードを毎月一括変更する　　　　　　　　　　　　　　　　", "サーバーのバックアップ処理を自動化する", "請求書の支払い処理を自動化する"], "a": 0, "e": "アクセスレビューは、グループ・アプリ・ロールへのアクセス権を定期的に見直し不要なアクセスを削除する機能である。", "qEn": "What is the main purpose of the 'Access reviews' feature in Microsoft Entra?", "oEn": ["Periodically reviewing access to groups, apps, and roles and removing unnecessary access", "Batch-changing every user's password every month", "Automating server backup processing", "Automating invoice payment processing"], "eEn": "Access reviews periodically reassess access to groups, apps, and roles, removing what is no longer needed."}, {"d": "D2", "q": "アクセスレビューのレビュー担当者として指定できるのはどれか。", "o": ["システムが生成したランダムな外部ユーザーのみ　　　　　　　　", "グループ所有者、マネージャー、または指定されたレビュー担当者", "常に組織内の全社員が対象になる", "レビュー担当者を個別に指定する仕組みはない"], "a": 1, "e": "アクセスレビューでは、グループ所有者やマネージャー、または指定したレビュー担当者を割り当てることができる。", "qEn": "Who can be designated as a reviewer for an access review?", "oEn": ["Only random external users generated by the system", "The group owner, manager, or a designated reviewer", "Always the entire company, without exception", "There is no mechanism to individually designate a reviewer"], "eEn": "Access reviews can be assigned to group owners, managers, or specifically designated reviewers."}, {"d": "D2", "q": "アクセスレビューで「自己レビュー（self-review）」を有効にした場合の動作はどれか。", "o": ["レビュー処理そのものが完全にスキップされる　　　", "管理者のみが一方的にレビューを実施する", "ユーザー自身が自分のアクセス継続の要否を確認する", "外部監査人が必ず代わりにレビューを行う"], "a": 2, "e": "自己レビューを有効にすると、ユーザー自身が自分のアクセス継続の要否を確認する。", "qEn": "What happens when 'self-review' is enabled for an access review?", "oEn": ["The review process is completely skipped", "Only the administrator performs the review unilaterally", "The users themselves confirm whether their own access should continue", "An external auditor always performs the review instead"], "eEn": "With self-review enabled, users confirm for themselves whether their access should continue."}, {"d": "D2", "q": "アクセスレビューで承認されなかった（拒否された）場合の一般的な結果はどれか。", "o": ["対象のアクセス権が自動的に昇格される", "レビュー結果に関わらず状態は変化しない", "対象ユーザーが管理者ロールへ昇格する", "対象のアクセス権が削除される"], "a": 3, "e": "アクセスレビューで拒否された場合、対象のアクセス権は一般的に削除される。", "qEn": "What is the typical outcome when an access review request is denied?", "oEn": ["The target access right is automatically escalated", "The state does not change regardless of the review outcome", "The target user is promoted to an administrator role", "The target access right is removed"], "eEn": "When an access review denies continued access, that access is typically removed."}, {"d": "D2", "q": "アクセスレビューを自動化する目的として最も適切なものはどれか。", "o": ["定期的な棚卸しを手動作業なしで継続的に実施しコンプライアンスを維持する", "レビュー作業そのものを完全に不要にする　　　　　　　　　　　　　　　　", "組織全体のユーザー数を増加させる", "テナントのネットワーク速度を向上させる"], "a": 0, "e": "自動化されたアクセスレビューは、手動作業なしで定期的な棚卸しを継続的に実施しコンプライアンスを維持する。", "qEn": "What is the most appropriate purpose of automating access reviews?", "oEn": ["Continuously performing periodic recertification without manual effort while maintaining compliance", "Making the review process itself entirely unnecessary", "Increasing the number of users across the organization", "Improving the tenant's network speed"], "eEn": "Automated access reviews continuously perform periodic recertification without manual work, helping maintain compliance."}, {"d": "D2", "q": "「ゲストユーザーのアクセスレビュー」が特に重要とされる理由はどれか。", "o": ["ゲストユーザーは課金対象にならないため", "外部ユーザーのアクセスは放置されると不要な権限が残りやすいため", "ゲストユーザーは常に自動的にロールを失うため", "ゲストユーザーはネットワーク帯域を優先されるため　　　　　　　"], "a": 1, "e": "外部ゲストユーザーのアクセスは放置されると不要な権限として残りやすいため、レビューが特に重要である。", "qEn": "Why is reviewing guest user access considered especially important?", "oEn": ["Because guest users are not subject to billing", "Because access for external users tends to linger unnecessarily if left unchecked", "Because guest users always automatically lose their roles", "Because guest users are given network bandwidth priority"], "eEn": "External guest access, if left unreviewed, tends to accumulate as unnecessary residual permissions."}, {"d": "D2", "q": "アクセスレビューの結果、レビュー担当者が何も回答しなかった場合に設定できる既定動作の例はどれか。", "o": ["レビュー機能そのものを無効化する設定", "対象サブスクリプションの課金を停止する設定　　　　　　　　　", "アクセスを自動承認または自動削除するルールを事前定義する設定", "対象のサブスクリプションを削除する設定"], "a": 2, "e": "レビュー担当者が未回答の場合の既定動作として、自動承認や自動削除のルールを事前定義できる。", "qEn": "Which is an example of a default action that can be configured for when a reviewer does not respond?", "oEn": ["A setting that disables the review feature entirely", "A setting that stops billing for the target subscription", "A setting that predefines a rule to auto-approve or auto-remove access", "A setting that deletes the target subscription"], "eEn": "Administrators can predefine whether non-response results in automatic approval or automatic removal."}, {"d": "D2", "q": "Microsoft Entra アクセスレビューを構成できる代表的な対象はどれか。", "o": ["物理サーバーに設置された温度センサー　　　　　　　　　　　　　　　　　　　　　　", "契約している電気料金プランの内容", "会議室の予約状況と稼働率", "Microsoft 365グループ、セキュリティグループ、アプリロールの割り当て"], "a": 3, "e": "アクセスレビューは、Microsoft 365グループ、セキュリティグループ、アプリロールの割り当てなどを対象に構成できる。", "qEn": "Which is a typical target that can be configured for Microsoft Entra access reviews?", "oEn": ["A temperature sensor installed on a physical server", "The contents of a contracted electricity billing plan", "Meeting room reservation status and utilization", "Microsoft 365 groups, security groups, and app role assignments"], "eEn": "Access reviews can target Microsoft 365 groups, security groups, and application role assignments, among others."}, {"d": "D2", "q": "アクセスレビューの結果レポートが提供する主な価値はどれか。", "o": ["誰が何をレビューしどんな決定を下したかの監査証跡を残す", "テナント全体のネットワーク帯域使用量を示す　　　　　　", "施設全体の電力消費量の推移を示す", "オフィスの印刷コストの内訳を示す"], "a": 0, "e": "アクセスレビューの結果レポートは、誰が何をレビューしどんな決定を下したかの監査証跡を提供する。", "qEn": "What is the main value provided by an access review's results report?", "oEn": ["It leaves an audit trail of who reviewed what and what decisions were made", "It shows tenant-wide network bandwidth usage", "It shows the facility's overall power consumption trend", "It shows a breakdown of the office's print costs"], "eEn": "The results report provides an audit trail documenting reviewers' actions and decisions."}, {"d": "D2", "q": "アクセスレビューとPIMの関係として正しい説明はどれか。", "o": ["両者はまったく無関係で連携する仕組みがない", "PIMで付与された特権ロールの割り当てもアクセスレビューの対象にできる", "アクセスレビューがPIMの機能をすべて置き換える　　　　　　　　　　　", "PIMがアクセスレビュー機能を無効化してしまう"], "a": 1, "e": "PIMで付与された特権ロールの割り当てもアクセスレビューの対象として構成できる。", "qEn": "Which correctly describes the relationship between access reviews and PIM?", "oEn": ["The two are completely unrelated with no integration mechanism", "Privileged role assignments granted through PIM can also be targeted by access reviews", "Access reviews replace all of PIM's functionality", "PIM disables the access reviews feature"], "eEn": "Privileged role assignments made through PIM can be included as targets of access reviews."}, {"d": "D2", "q": "Privileged Identity Management (PIM) の主な機能はどれか。", "o": ["ネットワーク帯域幅を自動的に割り当てる機能　　　　", "サーバーのファームウェアを自動更新する機能", "特権ロールへのオンデマンド・期間限定のアクセス付与", "印刷ジョブの優先順位を自動的に調整する機能"], "a": 2, "e": "PIMは特権ロールに対してオンデマンドかつ期間限定のアクセスを付与する機能を提供する。", "qEn": "What is the main function of Privileged Identity Management (PIM)?", "oEn": ["A function that automatically allocates network bandwidth", "A function that automatically updates server firmware", "On-demand, time-limited access to privileged roles", "A function that automatically adjusts print job priority"], "eEn": "PIM provides on-demand, time-bound access to privileged roles."}, {"d": "D2", "q": "PIM における「Just-In-Time（JIT）アクセス」の説明として正しいものはどれか。", "o": ["ロールを常時アクティブな状態に維持する仕組み", "ロールの割り当てそのものを完全に禁止する仕組み　　　", "全ユーザーへ恒久的な管理者権限を付与する仕組み", "必要なときだけ一時的に特権ロールを有効化できる仕組み"], "a": 3, "e": "Just-In-Timeアクセスとは、必要なときだけ一時的に特権ロールを有効化できる仕組みである。", "qEn": "Which correctly describes 'Just-In-Time (JIT) access' in PIM?", "oEn": ["A mechanism that keeps the role active at all times", "A mechanism that completely prohibits role assignments", "A mechanism that grants permanent administrative rights to all users", "A mechanism that lets a privileged role be activated temporarily only when needed"], "eEn": "Just-In-Time access activates a privileged role only for the duration it is actually needed."}, {"d": "D2", "q": "PIM で「アクティブ化（Activation）」時に要求できる追加条件はどれか。", "o": ["多要素認証や承認者の承認、理由の入力", "新しいライセンスの購入を必ず要求すること", "対象サブスクリプションの解約を要求すること", "印刷権限の付与を要求すること"], "a": 0, "e": "PIMのアクティブ化時には、多要素認証、承認者の承認、理由の入力などの条件を要求できる。", "qEn": "Which additional condition can be required at the time of 'activation' in PIM?", "oEn": ["Multi-factor authentication, approver approval, and entering a justification", "Always requiring the purchase of a new license", "Requiring cancellation of the target subscription", "Requiring the granting of print permissions"], "eEn": "PIM activation can require MFA, approver sign-off, and a justification reason among other conditions."}, {"d": "D2", "q": "PIM の「適格（Eligible）」なロール割り当てとは何を意味するか。", "o": ["ロールの権限が常時有効化されている状態", "必要なときにアクティブ化することで初めて権限が有効になる状態", "ロールの割り当てが完全に削除された状態", "対象サブスクリプションの課金が停止された状態　　　　　　　　"], "a": 1, "e": "適格な割り当てとは、必要なときにアクティブ化して初めて権限が有効になる状態を指す。", "qEn": "What does an 'Eligible' role assignment mean in PIM?", "oEn": ["A state where the role's permission is always active", "A state where permissions only become active once activated when needed", "A state where the role assignment has been completely deleted", "A state where billing for the target subscription has stopped"], "eEn": "An eligible assignment means the permission only becomes active after the user activates it when needed."}, {"d": "D2", "q": "PIM でロールのアクティブ化に時間制限を設定する目的はどれか。", "o": ["組織内のユーザー数を増加させるため", "テナントのネットワーク速度を向上させるため", "特権アクセスの露出時間を最小化するため", "サブスクリプションの請求額を増加させるため"], "a": 2, "e": "時間制限を設定することで、特権が有効になっている時間を最小化しリスクを減らせる。", "qEn": "What is the purpose of setting a time limit on role activation in PIM?", "oEn": ["To increase the number of users in the organization", "To improve the tenant's network speed", "To minimize the exposure window of privileged access", "To increase the subscription's billing amount"], "eEn": "Time limits reduce risk by minimizing how long privileged access remains active."}, {"d": "D2", "q": "PIM の監査履歴機能が提供する情報はどれか。", "o": ["施設全体の電力消費量の推移", "オフィスにおける印刷枚数の統計", "テナントのネットワーク遅延のグラフ　　　　　　　　", "誰がいつどのロールをアクティブ化・承認したかの記録"], "a": 3, "e": "PIMの監査履歴は、誰がいつどのロールをアクティブ化・承認したかを記録する。", "qEn": "What information does the PIM audit history feature provide?", "oEn": ["The facility's overall power consumption trend", "Statistics on the number of printed pages in the office", "A graph of the tenant's network latency", "A record of who activated or approved which role and when"], "eEn": "PIM's audit history records who activated or approved each role and when it occurred."}, {"d": "D2", "q": "PIM で「承認者（Approver）」を必須にする設定の効果はどれか。", "o": ["ロールのアクティブ化前に指定された承認者の許可が必要になる", "すべてのアクティブ化要求が自動的に拒否されるようになる　　", "承認プロセスそのものが完全に省略されるようになる", "承認者を指定する必要がなくなる"], "a": 0, "e": "承認者を必須にすると、ロールのアクティブ化前に指定された承認者からの許可が必要になる。", "qEn": "What is the effect of requiring an 'Approver' in PIM?", "oEn": ["A designated approver's permission is required before the role can be activated", "All activation requests are automatically denied", "The approval process itself becomes entirely skipped", "There is no longer a need to designate an approver"], "eEn": "Requiring an approver means activation requests must be approved by a designated person before taking effect."}, {"d": "D2", "q": "PIM の対象となるロールの例として適切なものはどれか。", "o": ["追加権限を持たない一般ユーザーの既定ロール", "グローバル管理者やユーザー管理者などの特権ロール", "ゲストユーザーに割り当てられる既定プロファイル　", "無料ライセンスユーザーの既定設定"], "a": 1, "e": "PIMは、グローバル管理者やユーザー管理者などの特権ロールを管理対象とする。", "qEn": "Which is an appropriate example of a role targeted by PIM?", "oEn": ["The default role of a regular user with no extra permissions", "Privileged roles such as Global Administrator or User Administrator", "The default profile assigned to a guest user", "The default settings for a free-license user"], "eEn": "PIM manages privileged roles such as Global Administrator and User Administrator."}, {"d": "D2", "q": "PIM で定期的にアクセスレビューを実施する理由はどれか。", "o": ["対象ロールの価格設定を変更するため", "テナントのネットワーク帯域を拡張するため　　　　　　　　　　　　　　　", "特権ロールの割り当てが依然として必要かを確認し余分な権限を削減するため", "オフィスの印刷コストを削減するため"], "a": 2, "e": "PIMで定期的にアクセスレビューを行うのは、特権ロールの割り当てが引き続き必要かを確認し余分な権限を削減するためである。", "qEn": "Why are periodic access reviews conducted for PIM role assignments?", "oEn": ["To change the pricing of the target role", "To expand the tenant's network bandwidth", "To verify privileged role assignments are still needed and remove excess permissions", "To reduce the office's printing costs"], "eEn": "Periodic reviews confirm whether privileged role assignments are still necessary and help remove excess access."}, {"d": "D2", "q": "PIM の通知機能が管理者に知らせる内容の例はどれか。", "o": ["当日の天気予報に関する情報", "通貨の為替レート変動に関する情報　", "道路の交通渋滞に関する情報", "特権ロールがアクティブ化されたこと"], "a": 3, "e": "PIMの通知機能は、特権ロールがアクティブ化された際に管理者へ通知する。", "qEn": "Which is an example of what PIM's notification feature informs administrators about?", "oEn": ["Information about the day's weather forecast", "Information about currency exchange rate fluctuations", "Information about road traffic congestion", "That a privileged role has been activated"], "eEn": "PIM notifications alert administrators when a privileged role is activated."}, {"d": "D2", "q": "PIM とConditional Access を組み合わせて使う利点はどれか。", "o": ["ロールのアクティブ化時にもMFAやデバイス準拠などの条件を追加で強制できる", "PIMの機能そのものを完全に無効化できる", "Conditional Access の評価処理を停止できる　　　　　　　", "ライセンス費用が自動的に無料になる"], "a": 0, "e": "PIMとConditional Accessを組み合わせると、ロールのアクティブ化時にもMFAやデバイス準拠を追加で強制できる。", "qEn": "What is the benefit of combining PIM with Conditional Access?", "oEn": ["Additional conditions such as MFA or device compliance can be enforced even during role activation", "PIM's functionality can be entirely disabled", "Conditional Access evaluation processing can be stopped", "License costs automatically become free"], "eEn": "Combining PIM with Conditional Access lets organizations enforce MFA and device compliance even at role activation time."}, {"d": "D2", "q": "PIM for Groups（グループの特権管理）の説明として正しいものはどれか。", "o": ["グループ機能そのものを無効化する仕組み", "グループメンバーシップやオーナー権限も期間限定でアクティブ化できるようにする", "グループの新規作成を完全に禁止する仕組み　　　　　　　　　　　　　　　　　　", "グループの名前を自動的に生成する仕組み"], "a": 1, "e": "PIM for Groupsは、グループのメンバーシップやオーナー権限も期間限定でアクティブ化できるようにする機能である。", "qEn": "Which correctly describes PIM for Groups?", "oEn": ["A mechanism that disables the group feature itself", "Allowing group membership and owner rights to also be activated on a time-bound basis", "A mechanism that completely prohibits creating new groups", "A mechanism that automatically generates group names"], "eEn": "PIM for Groups extends time-bound, just-in-time activation to group membership and ownership rights."}, {"d": "D2", "q": "PIM を使わずに特権ロールを恒久的に割り当て続けることの主なリスクはどれか。", "o": ["ライセンス費用が結果的に減少すること", "テナントのネットワーク遅延が減少すること　　　　　　　　　　", "不要になった特権アクセスが放置され攻撃対象領域が拡大すること", "オフィスの印刷速度が向上すること"], "a": 2, "e": "PIMを使わず恒久的に特権ロールを割り当て続けると、不要なアクセスが放置され攻撃対象領域が拡大するリスクがある。", "qEn": "What is the main risk of keeping privileged roles permanently assigned without using PIM?", "oEn": ["License costs ending up reduced", "The tenant's network latency being reduced", "Unneeded privileged access lingering, expanding the attack surface", "The office's print speed improving"], "eEn": "Without PIM, standing privileged access tends to persist unnecessarily, increasing the organization's attack surface."}, {"d": "D2", "q": "PIM のロール設定で「最大アクティブ化期間」を短く設定する目的はどれか。", "o": ["ユーザー体験をあえて悪化させるため", "対象サブスクリプションの課金を増加させるため", "サーバーへの負荷をあえて増加させるため", "特権が有効な時間を制限しリスクを低減するため"], "a": 3, "e": "最大アクティブ化期間を短く設定することで、特権が有効な時間を制限しリスクを低減できる。", "qEn": "What is the purpose of setting a short 'maximum activation duration' for a role in PIM?", "oEn": ["To deliberately worsen the user experience", "To increase billing for the target subscription", "To deliberately increase load on the server", "To limit how long the privilege stays active and reduce risk"], "eEn": "A short maximum activation duration limits how long the privilege is active, reducing exposure risk."}, {"d": "D2", "q": "Microsoft Entra ID Protection の主な役割はどれか。", "o": ["ユーザーやサインインのリスクを検出し自動的なリスクベースのポリシーを適用する", "テナント全体のサーバーバックアップを実施する　　　　　　　　　　　　　　　　", "組織内のネットワーク帯域を割り当てる", "顧客向けの請求書を発行する"], "a": 0, "e": "ID Protectionは、ユーザーやサインインのリスクを検出し、リスクベースのポリシーを自動適用する機能である。", "qEn": "What is the main role of Microsoft Entra ID Protection?", "oEn": ["Detecting user and sign-in risk and automatically applying risk-based policies", "Performing server backups across the tenant", "Allocating network bandwidth within the organization", "Issuing invoices to customers"], "eEn": "ID Protection detects risk on users and sign-ins and automatically applies risk-based policies."}, {"d": "D2", "q": "ID Protection における「サインインリスク」の例はどれか。", "o": ["割り当てられているライセンスの種類　　　　　　　　　　　　　　　", "匿名IPアドレスからのサインインや通常と異なる場所からのアクセス", "使用しているデバイスの購入日", "所属している部署名の変更履歴"], "a": 1, "e": "匿名IPアドレスからのサインインや異常な場所からのアクセスは、サインインリスクの代表例である。", "qEn": "Which is an example of 'sign-in risk' in ID Protection?", "oEn": ["The type of license assigned", "Sign-in from an anonymous IP address or access from an atypical location", "The purchase date of the device being used", "The history of changes to the department name"], "eEn": "Sign-ins from anonymous IPs or atypical locations are typical examples of sign-in risk."}, {"d": "D2", "q": "ID Protection における「ユーザーリスク」の例はどれか。", "o": ["サブスクリプションの契約更新日　　", "使用しているデバイスの筐体の色", "漏えいした資格情報が検出されたこと", "会議室の予約状況の変化"], "a": 2, "e": "漏えいした資格情報の検出は、ユーザーリスクの代表的な検出項目である。", "qEn": "Which is an example of 'user risk' in ID Protection?", "oEn": ["The subscription's contract renewal date", "The color of the device casing being used", "Detection of leaked credentials", "A change in meeting room reservation status"], "eEn": "Detection of leaked credentials is a typical example of a user risk detection."}, {"d": "D2", "q": "ID Protection のリスクポリシーでとれるアクションの例はどれか。", "o": ["対象サーバーを再起動する処理", "施設全体の電力使用量を削減する処理　　　　　　　　　　　", "印刷ジョブを一時的に停止する処理", "パスワードの変更を要求する、またはアクセスをブロックする"], "a": 3, "e": "リスクポリシーでは、パスワード変更の要求やアクセスのブロックといった対応をとることができる。", "qEn": "Which is an example of an action available from an ID Protection risk policy?", "oEn": ["Restarting the target server", "Reducing power usage across the facility", "Temporarily stopping print jobs", "Requiring a password change or blocking access"], "eEn": "Risk policies can require a password change or block access outright as remediation actions."}, {"d": "D2", "q": "ID Protection の「リスク検出（risk detection）」はどのように評価されるか。", "o": ["Microsoftの脅威インテリジェンスと機械学習を用いてリアルタイムまたはオフラインで評価される", "ユーザーが毎回手動で入力する情報に基づいて決まる　　　　　　　　　　　　　　　　　　　　　　　　　", "完全にランダムな値として割り当てられる", "テナントの課金額に基づいて自動的に決定される"], "a": 0, "e": "リスク検出は、Microsoftの脅威インテリジェンスと機械学習を用いてリアルタイムまたはオフラインで評価される。", "qEn": "How are 'risk detections' in ID Protection evaluated?", "oEn": ["Using Microsoft threat intelligence and machine learning, evaluated in real time or offline", "Determined based on information the user manually enters each time", "Assigned as a completely random value", "Automatically determined based on the tenant's billing amount"], "eEn": "Risk detections are evaluated using Microsoft's threat intelligence and machine learning, either in real time or offline."}, {"d": "D2", "q": "「リスキーサインインポリシー」で高リスクと判定された場合の一般的な対応例はどれか。", "o": ["対象ユーザーのライセンスを自動的にアップグレードする", "多要素認証を要求するか、サインインをブロックする", "対象サブスクリプションを解約する", "テナントのネットワーク帯域を拡張する"], "a": 1, "e": "高リスクと判定されたサインインには、多要素認証の要求やサインインのブロックといった対応が一般的である。", "qEn": "What is a typical response when the sign-in risk policy classifies a sign-in as high risk?", "oEn": ["Automatically upgrading the target user's license", "Requiring multi-factor authentication or blocking the sign-in", "Canceling the target subscription", "Expanding the tenant's network bandwidth"], "eEn": "High-risk sign-ins are typically handled by requiring MFA or blocking the sign-in outright."}, {"d": "D2", "q": "ID Protection のダッシュボードで確認できる情報はどれか。", "o": ["契約している電気料金プランの推移　　　　　　　　", "オフィスの印刷コストの内訳", "リスク検出されたユーザーやサインインの一覧と詳細", "会議室の稼働率の統計情報"], "a": 2, "e": "ID Protectionのダッシュボードでは、リスク検出されたユーザーやサインインの一覧と詳細を確認できる。", "qEn": "What information can be viewed in the ID Protection dashboard?", "oEn": ["The trend of a contracted electricity billing plan", "A breakdown of the office's print costs", "A list and details of users and sign-ins flagged with risk", "Statistical information on meeting room utilization"], "eEn": "The ID Protection dashboard shows a list and details of risk-flagged users and sign-ins."}, {"d": "D2", "q": "ID Protection と Conditional Access の統合による利点はどれか。", "o": ["リスク評価の機能そのものが無効化される　　　　　　　　　　　　　　　　　　　　　　　　　　", "パスワードポリシーが完全に不要になる", "ライセンス費用がすべてゼロになる", "リスクレベルをシグナルとしてConditional Accessポリシーの条件に利用できる"], "a": 3, "e": "ID ProtectionとConditional Accessを統合すると、リスクレベルをシグナルとしてポリシーの条件に使用できる。", "qEn": "What is the benefit of integrating ID Protection with Conditional Access?", "oEn": ["The risk evaluation function itself becomes disabled", "Password policy becomes entirely unnecessary", "All license costs become zero", "Risk level can be used as a signal in Conditional Access policy conditions"], "eEn": "Integration lets the detected risk level feed into Conditional Access as a condition signal."}, {"d": "D2", "q": "ID Protection の「リスキーユーザー」に対して管理者が取れる対応例はどれか。", "o": ["アカウントを無効化する、またはパスワードのリセットを強制する", "ライセンスを自動的に追加購入する処理　　　　　　　　　　　　", "部署異動の手続きを自動的に処理する", "対象ユーザーの給与を変更する処理"], "a": 0, "e": "リスキーユーザーに対しては、アカウントの無効化やパスワードリセットの強制といった対応が可能である。", "qEn": "Which is an example of an action an administrator can take against a 'risky user' in ID Protection?", "oEn": ["Disabling the account or forcing a password reset", "Automatically purchasing additional licenses", "Automatically processing a department transfer", "Changing the target user's salary"], "eEn": "Administrators can disable the account or force a password reset for risky users."}, {"d": "D2", "q": "ID Protection が検出するリスク検出の情報源に含まれるものはどれか。", "o": ["社員の勤怠管理システムに記録された情報　　　　　　　　　　　　　　　　　　", "漏えいした認証情報のデータベースやMicrosoftの脅威インテリジェンス", "会議室の予約システムに記録された情報", "経費精算システムに記録された情報"], "a": 1, "e": "ID Protectionのリスク検出は、漏えいした認証情報のデータベースやMicrosoftの脅威インテリジェンスを情報源とする。", "qEn": "Which is included among the sources of information behind ID Protection's risk detections?", "oEn": ["Information recorded in the employee attendance management system", "Databases of leaked credentials and Microsoft threat intelligence", "Information recorded in the meeting room booking system", "Information recorded in the expense reimbursement system"], "eEn": "Risk detections draw on sources such as leaked credential databases and Microsoft's threat intelligence."}, {"d": "D2", "q": "組織がID Protectionのリスクポリシーを自動化せずレポートのみに使う場合の一般的な理由はどれか。", "o": ["ライセンスの制約により自動化が常に不可能なため　　　　", "リスク検出そのものが完全に不要と判断されたため", "影響を事前に評価してから段階的に自動適用を進めたいため", "パスワードポリシーが不要になったため"], "a": 2, "e": "影響を事前に評価し段階的に自動適用へ移行したい場合、まずレポート専用として運用することが一般的である。", "qEn": "What is a common reason an organization uses ID Protection risk policies in report-only mode instead of enforcing automatically?", "oEn": ["Because license restrictions always make automation impossible", "Because risk detection itself was judged to be entirely unnecessary", "Because they want to assess impact first before gradually rolling out automatic enforcement", "Because password policy has become unnecessary"], "eEn": "Running in report-only mode first lets organizations assess impact before gradually moving to automatic enforcement."}, {"d": "D2", "q": "Microsoft Entra ID Protection が実現するセキュリティ上の価値として最も適切なものはどれか。", "o": ["オフィスの印刷コストを削減する価値", "施設全体の電力消費を最適化する価値", "テナントのネットワーク遅延を削減する価値　　　　　　　　　　　　　　", "侵害の兆候を早期に検出しリスクに応じた自動対応でアカウント侵害を防ぐ"], "a": 3, "e": "ID Protectionは侵害の兆候を早期に検出し、リスクに応じた自動対応によりアカウント侵害を防止する価値を提供する。", "qEn": "Which best describes the security value delivered by Microsoft Entra ID Protection?", "oEn": ["The value of reducing an office's print costs", "The value of optimizing power consumption across a facility", "The value of reducing the tenant's network latency", "Detecting signs of compromise early and preventing account takeover through risk-based automated response"], "eEn": "ID Protection's value is early detection of compromise indicators paired with automated, risk-based responses that prevent account takeover."}, {"d": "D3", "q": "Azure DDoS Protection の目的として最も適切なものはどれですか。", "o": ["大量のトラフィック攻撃からリソースの可用性を保護する", "仮想マシンのディスクを自動的に暗号化する", "ユーザーのサインインを多要素認証で保護する", "リソースの構成ドリフトを検出して自動修正する　　　　"], "a": 0, "e": "Azure DDoS Protection は、分散型サービス拒否 (DDoS) 攻撃からリソースの可用性を保護するサービスです。", "qEn": "What is the primary purpose of Azure DDoS Protection?", "oEn": ["To protect resource availability from large-scale traffic attacks", "To automatically encrypt virtual machine disks", "To secure user sign-in with multifactor authentication", "To detect and automatically fix resource configuration drift"], "eEn": "Azure DDoS Protection safeguards the availability of resources against distributed denial-of-service (DDoS) attacks."}, {"d": "D3", "q": "Azure DDoS Protection の「Network Protection」プランに含まれる機能はどれですか。", "o": ["仮想マシンへのリモートデスクトップ接続の中継", "仮想ネットワーク全体を対象とした常時トラフィック監視と自動緩和", "Web アプリケーションへの SQL インジェクション攻撃のブロック", "シークレットやキーの安全な保管"], "a": 1, "e": "DDoS Network Protection は仮想ネットワーク内のパブリック IP リソースを対象に、常時監視と攻撃検知時の自動緩和を提供します。", "qEn": "Which capability is included in the Azure DDoS Protection Network Protection plan?", "oEn": ["Relaying remote desktop connections to virtual machines", "Always-on traffic monitoring and automatic mitigation across a virtual network", "Blocking SQL injection attacks against web applications", "Secure storage of secrets and keys"], "eEn": "DDoS Network Protection continuously monitors public IP resources in a virtual network and automatically mitigates detected attacks."}, {"d": "D3", "q": "Azure DDoS Protection の Basic プランについて正しい説明はどれですか。", "o": ["追加料金を支払うことで手厚い保護レポートが提供される　　　　　　　　　　　", "仮想ネットワークごとに個別の設定が必要である", "Azure プラットフォームの全顧客に対して自動的に既定で有効になっている", "オンプレミス環境のサーバーを直接保護する"], "a": 2, "e": "DDoS Basic は Azure のインフラストラクチャに組み込まれており、追加コストなしですべての顧客に自動的に適用されます。", "qEn": "Which statement about the Azure DDoS Protection Basic tier is correct?", "oEn": ["Detailed protection reports are available for an extra fee", "It must be configured separately for every virtual network", "It is automatically enabled by default for every Azure customer", "It directly protects servers running on-premises"], "eEn": "DDoS Basic is built into the Azure platform and is automatically applied to all customers at no extra cost."}, {"d": "D3", "q": "DDoS 攻撃の一般的な特徴として適切な説明はどれですか。", "o": ["特定のユーザー アカウントの権限を段階的に昇格させる　　　　　　　　", "ディスク上のデータを暗号化して身代金を要求する", "内部ネットワークに侵入して機密ファイルを持ち出す", "大量のトラフィックでリソースを飽和させ、正規利用者のアクセスを妨げる"], "a": 3, "e": "DDoS 攻撃は大量の要求やトラフィックでサービスを過負荷にし、可用性を損なうことを目的とします。", "qEn": "Which of the following describes a typical characteristic of a DDoS attack?", "oEn": ["Gradually escalating the privileges of a specific user account", "Encrypting data on disk and demanding a ransom", "Infiltrating an internal network to exfiltrate confidential files", "Overwhelming a resource with excessive traffic to deny access to legitimate users"], "eEn": "DDoS attacks aim to overload a service with a flood of requests or traffic, degrading its availability."}, {"d": "D3", "q": "Azure DDoS Protection の Network Protection プランを利用するために前提となるものはどれですか。", "o": ["仮想ネットワークに関連付けられたパブリック IP アドレス", "Azure Active Directory Premium P2 ライセンス", "オンプレミスの VPN ゲートウェイ", "Microsoft Defender for Endpoint のエージェント"], "a": 0, "e": "DDoS Network Protection は仮想ネットワーク内のパブリック IP リソースに適用されるため、対象リソースにパブリック IP が関連付けられている必要があります。", "qEn": "What is a prerequisite for using the Azure DDoS Network Protection plan?", "oEn": ["A public IP address associated with the virtual network", "A Microsoft Entra ID Premium P2 license", "An on-premises VPN gateway", "A Microsoft Defender for Endpoint agent"], "eEn": "DDoS Network Protection applies to public IP resources within a virtual network, so the protected resource must have a public IP associated with it."}, {"d": "D3", "q": "Azure DDoS Protection が主に防御対象とする攻撃の層はどれですか。", "o": ["アプリケーション層のみに限定される　　　　　　　　　", "ネットワーク層およびトランスポート層を中心とした攻撃", "物理層のケーブル切断のみ", "データベースの内部クエリのみ"], "a": 1, "e": "DDoS Network Protection は主にネットワーク層 (レイヤー3/4) の攻撃からの保護に重点を置いています。アプリケーション層の保護は WAF と組み合わせます。", "qEn": "Which layer of attack does Azure DDoS Protection primarily defend against?", "oEn": ["Only the application layer", "Attacks centered on the network and transport layers", "Only physical-layer cable disconnections", "Only internal database queries"], "eEn": "DDoS Network Protection focuses mainly on protecting against network and transport layer (layer 3/4) attacks; application-layer protection is combined with a WAF."}, {"d": "D3", "q": "Azure Firewall の主な役割として最も適切なものはどれですか。", "o": ["仮想マシンへの安全なリモート管理接続を提供するサービス", "シークレットや証明書を一元的に安全に管理するサービス", "トラフィックを検査し規則に基づいて許可・拒否を制御するマネージド型ファイアウォール", "ストレージアカウントのアクセスキーを自動でローテーションするサービス　　　　　　　"], "a": 2, "e": "Azure Firewall はクラウドネイティブなネットワークセキュリティサービスで、仮想ネットワークの受信・送信トラフィックを制御します。", "qEn": "What is the primary role of Azure Firewall?", "oEn": ["A service that provides secure remote management connections to virtual machines", "A service that centrally and securely manages secrets and certificates", "A managed firewall that inspects traffic and controls allow/deny based on rules", "A service that automatically rotates storage account access keys"], "eEn": "Azure Firewall is a cloud-native network security service that controls inbound and outbound traffic for a virtual network."}, {"d": "D3", "q": "Azure Firewall の高可用性に関する特徴として正しいものはどれですか。", "o": ["高可用性を実現するには外部ロードバランサーを別途構築する必要がある　　　", "単一インスタンスでのみ動作し、冗長化はサポートされない", "可用性を確保するには手動でフェールオーバーを実行する必要がある", "サービスとして組み込みの高可用性を備え、追加の負荷分散構成を必要としない"], "a": 3, "e": "Azure Firewall はフルマネージドサービスとして組み込みの高可用性を提供し、利用者側での冗長構成は不要です。", "qEn": "Which statement correctly describes the high availability of Azure Firewall?", "oEn": ["An external load balancer must be built separately to achieve high availability", "It runs only as a single instance and does not support redundancy", "Failover must be performed manually to ensure availability", "It has built-in high availability as a service and requires no additional load-balancing configuration"], "eEn": "Azure Firewall is a fully managed service with built-in high availability, so customers do not need to configure redundancy themselves."}, {"d": "D3", "q": "Azure Firewall がサポートするフィルタリング方式として正しい組み合わせはどれですか。", "o": ["アプリケーションルールと、ネットワークルールの両方", "ユーザーのパスワード強度チェックのみ　　　　　　　", "ディスク暗号化キーの管理のみ", "仮想マシンのパッチ適用状況の確認のみ"], "a": 0, "e": "Azure Firewall は完全修飾ドメイン名 (FQDN) に基づくアプリケーションルールと、IP・ポート・プロトコルに基づくネットワークルールの両方をサポートします。", "qEn": "Which combination of filtering methods does Azure Firewall support?", "oEn": ["Both application rules and network rules", "Only user password strength checks", "Only management of disk encryption keys", "Only checking the patch status of virtual machines"], "eEn": "Azure Firewall supports application rules based on fully qualified domain names (FQDNs) as well as network rules based on IP address, port, and protocol."}, {"d": "D3", "q": "組織が複数のサブスクリプションにまたがるネットワークセキュリティポリシーを一元管理したい場合に利用できる Azure Firewall の機能はどれですか。", "o": ["Azure Bastion のセッション記録", "Azure Firewall Manager によるポリシーの集中管理", "Key Vault のアクセスポリシー", "Microsoft Entra の条件付きアクセス　　　　　　　　　　"], "a": 1, "e": "Azure Firewall Manager を使用すると、複数の Azure Firewall インスタンスに対してファイアウォールポリシーとセキュリティルールを一元管理できます。", "qEn": "Which Azure Firewall capability lets an organization centrally manage network security policy across multiple subscriptions?", "oEn": ["Azure Bastion session recording", "Centralized policy management through Azure Firewall Manager", "Key Vault access policies", "Microsoft Entra Conditional Access"], "eEn": "Azure Firewall Manager allows centralized management of firewall policies and security rules across multiple Azure Firewall instances."}, {"d": "D3", "q": "Azure Firewall と Network Security Group (NSG) の役割の違いに関する説明として適切なものはどれですか。", "o": ["NSG は仮想ネットワーク全体をドメイン名ベースで制御する唯一の手段である", "Azure Firewall はサブネット単位でのみ動作し集中管理はできない仕組みである", "Azure Firewall は高度な集中管理ルールを提供し、NSG は基本的なサブネット単位のフィルタリングを行う", "NSG は暗号化キーを保管し、Azure Firewall はユーザー認証を担当する仕組みである　　　　　　　　　　"], "a": 2, "e": "Azure Firewall は集中管理された高度なポリシーを提供し、NSG はサブネットやネットワークインターフェイス単位でのステートフルなフィルタリングを行います。", "qEn": "Which statement correctly describes the difference in roles between Azure Firewall and a Network Security Group (NSG)?", "oEn": ["An NSG is the only way to control traffic across an entire virtual network by domain name", "Azure Firewall works only at the subnet level and cannot be centrally managed at all", "Azure Firewall provides advanced centrally managed rules, while an NSG performs basic subnet-level filtering", "An NSG stores encryption keys, while Azure Firewall is responsible for user authentication"], "eEn": "Azure Firewall provides centrally managed, advanced policies, while an NSG performs stateful filtering at the subnet or network interface level."}, {"d": "D3", "q": "Azure Firewall の脅威インテリジェンスベースのフィルタリング機能の説明として正しいものはどれですか。", "o": ["ユーザーの生体認証情報を検証する", "ディスクの静止データを暗号化する", "仮想マシンのソフトウェア更新プログラムを自動適用する　　　　　　　　　　　　", "既知の悪意あるIPアドレスやドメインとの通信を自動的に警告またはブロックする"], "a": 3, "e": "Azure Firewall の脅威インテリジェンス機能は、Microsoft の脅威インテリジェンス フィードに基づいて既知の悪意ある送信元・宛先との通信を検知し、警告またはブロックします。", "qEn": "Which statement correctly describes Azure Firewall's threat intelligence-based filtering feature?", "oEn": ["It verifies a user's biometric credentials", "It encrypts data at rest on disks", "It automatically applies software updates to virtual machines", "It automatically alerts on or blocks traffic to and from known malicious IP addresses and domains"], "eEn": "Azure Firewall's threat intelligence feature detects traffic to or from known malicious sources based on Microsoft threat intelligence feeds and can alert or block it."}, {"d": "D3", "q": "Azure Web Application Firewall (WAF) の主な目的はどれですか。", "o": ["SQLインジェクションなどWebレイヤーの攻撃からアプリケーションを保護する", "仮想マシンへのリモートデスクトップ接続を安全に仲介する　　　　　　　　　　　", "仮想ネットワーク間のピアリング接続を構成する", "ストレージアカウントの冗長化レベルを設定変更する"], "a": 0, "e": "WAF は OWASP のトップ脆弱性など、一般的な Web 攻撃からアプリケーションを保護するために設計されています。", "qEn": "What is the primary purpose of Azure Web Application Firewall (WAF)?", "oEn": ["To protect applications from web-layer attacks such as SQL injection", "To securely broker remote desktop connections to virtual machines", "To configure a peering connection between virtual networks", "To change the redundancy level setting of a storage account"], "eEn": "A WAF is designed to protect applications from common web attacks, such as those in the OWASP top vulnerabilities."}, {"d": "D3", "q": "Azure WAF を展開できるサービスの組み合わせとして正しいものはどれですか。", "o": ["Azure Bastion と Azure Firewall のみ", "Azure Application Gateway と Azure Front Door", "Azure Key Vault と Microsoft Entra ID　　　　　　　　", "Azure Backup と Azure Site Recovery"], "a": 1, "e": "Azure WAF は Azure Application Gateway や Azure Front Door、Azure CDN と統合して展開できます。", "qEn": "Which combination of services can Azure WAF be deployed with?", "oEn": ["Only Azure Bastion and Azure Firewall", "Azure Application Gateway and Azure Front Door", "Azure Key Vault and Microsoft Entra ID", "Azure Backup and Azure Site Recovery"], "eEn": "Azure WAF can be deployed integrated with Azure Application Gateway, Azure Front Door, and Azure CDN."}, {"d": "D3", "q": "WAF の「検出モード」と「防止モード」の違いに関する説明として適切なものはどれですか。", "o": ["検出モードは攻撃を自動的にブロックし、防止モードはログのみを記録する", "両モードとも常にトラフィックをブロックし、違いはログの保存先のみである　　　　", "検出モードは一致したリクエストを記録するのみで、防止モードは実際にブロックする", "防止モードは仮想マシンの起動を停止させるモードである"], "a": 2, "e": "検出モードは一致したトラフィックをログに記録するだけですが、防止モードは実際にリクエストをブロックします。", "qEn": "Which statement correctly describes the difference between WAF's detection mode and prevention mode?", "oEn": ["Detection mode automatically blocks attacks while prevention mode only logs them", "Both modes always block traffic, and the only difference is where logs are stored", "Detection mode only logs matching requests, while prevention mode actually blocks them", "Prevention mode is a mode that stops virtual machines from starting"], "eEn": "Detection mode only logs matching traffic, whereas prevention mode actually blocks the request."}, {"d": "D3", "q": "Azure WAF が利用するルールセットの例として正しいものはどれですか。", "o": ["NIST 800-53 のコントロール一覧", "ISO/IEC 27001 の附属書A", "CIS Benchmark のスコアリング基準", "OWASP コアルールセット (CRS)"], "a": 3, "e": "Azure WAF は OWASP コアルールセットに基づく既定のマネージドルールセットを提供し、一般的な Web 脆弱性への対策を行います。", "qEn": "Which of the following is an example of a rule set used by Azure WAF?", "oEn": ["The NIST 800-53 list of controls", "ISO/IEC 27001 Annex A", "CIS Benchmark scoring criteria", "The OWASP Core Rule Set (CRS)"], "eEn": "Azure WAF provides a default managed rule set based on the OWASP Core Rule Set to address common web vulnerabilities."}, {"d": "D3", "q": "Azure WAF を使用する主なメリットとして適切なものはどれですか。", "o": ["個々のアプリケーションを変更せずに一元的に Web レベルの脅威対策を適用できる", "仮想ネットワークのルーティングテーブルを自動生成する　　　　　　　　　　　　　　", "オンプレミスのデータベースを直接暗号化する", "ユーザーのパスワードポリシーを設定する"], "a": 0, "e": "WAF を利用することで、アプリケーションコードを変更せずに一元的な保護ルールを適用できます。", "qEn": "What is a key benefit of using Azure WAF?", "oEn": ["It applies centralized web-level threat protection without modifying individual applications", "It automatically generates virtual network routing tables", "It directly encrypts on-premises databases", "It sets user password policies"], "eEn": "Using a WAF lets you apply centralized protection rules without changing application code."}, {"d": "D3", "q": "WAF がカスタムルールをサポートする目的として適切なものはどれですか。", "o": ["サーバーの物理的な設置場所を変更管理するため　　　　　　　　　　　　　　", "特定のIPやリクエストパターンに組織固有の許可・拒否ルールを追加するため", "仮想マシンのディスクサイズを事後変更するため", "バックアップデータの保持期間を設定するため"], "a": 1, "e": "カスタムルールを使用すると、既定のマネージドルールに加えて、組織固有の条件に基づくトラフィック制御を追加できます。", "qEn": "Why does WAF support custom rules?", "oEn": ["To manage changes to a server's physical location", "To add organization-specific allow/deny rules for particular IPs or request patterns", "To change a virtual machine's disk size after deployment", "To set the retention period for backup data"], "eEn": "Custom rules let you add traffic control based on organization-specific conditions in addition to the default managed rules."}, {"d": "D3", "q": "Azure 仮想ネットワークをサブネットに分割する主な目的として適切なものはどれですか。", "o": ["すべてのリソースを単一の管理者アカウントに統合するため　　　　　　　　　　　　　　　", "課金を単一のサブスクリプションにまとめるため", "リソースをグループ化し、トラフィックフローとアクセス制御を細かく管理しやすくするため", "ストレージの冗長化レベルを自動的に引き上げるため"], "a": 2, "e": "サブネットに分割することで、ワークロードごとに異なるセキュリティ境界やルーティングポリシーを適用しやすくなります。", "qEn": "What is the main purpose of dividing an Azure virtual network into subnets?", "oEn": ["To consolidate all resources under a single administrator account", "To combine billing into a single subscription", "To group resources so that traffic flow and access control can be managed more granularly", "To automatically raise the storage redundancy level"], "eEn": "Dividing a virtual network into subnets makes it easier to apply different security boundaries and routing policies per workload."}, {"d": "D3", "q": "仮想ネットワークピアリングに関する説明として正しいものはどれですか。", "o": ["異なるリージョンの仮想ネットワーク同士は接続できない仕組みである", "ピアリングされたネットワーク間の通信は必ずパブリックインターネットを経由する　　", "ピアリングを構成すると自動的にすべてのポートが公開される設定である", "2つの仮想ネットワークをプライベート接続しAzureバックボーン経由で通信させる"], "a": 3, "e": "仮想ネットワークピアリングにより、2つの VNet をシームレスかつプライベートに接続でき、トラフィックは Microsoft のバックボーンネットワークを通ります。", "qEn": "Which statement correctly describes virtual network peering?", "oEn": ["Virtual networks in different regions can never be connected to each other", "Traffic between peered networks always travels over the public internet", "Configuring peering automatically exposes all ports to the internet", "It privately connects two virtual networks so traffic flows over the Azure backbone"], "eEn": "Virtual network peering seamlessly and privately connects two VNets, with traffic traveling over Microsoft's backbone network."}, {"d": "D3", "q": "多層防御の考え方に基づいてネットワークをセグメント化する利点はどれですか。", "o": ["侵害が発生した場合の影響範囲を限定し、横方向の移動を抑制できる", "すべてのリソースへのアクセスを単一の管理者に集中できる　　　　", "バックアップの頻度を減らすことができる", "ライセンスコストを自動的に削減できる"], "a": 0, "e": "ネットワークセグメンテーションは、侵害の影響を特定の区画に封じ込め、攻撃者の横方向移動を制限するのに役立ちます。", "qEn": "What is a benefit of segmenting a network based on defense-in-depth principles?", "oEn": ["It limits the impact of a breach and restricts lateral movement", "It centralizes access to all resources under a single administrator", "It reduces how often backups need to be taken", "It automatically reduces licensing costs"], "eEn": "Network segmentation helps contain the impact of a breach to a specific segment and restricts an attacker's lateral movement."}, {"d": "D3", "q": "ハブアンドスポーク型のネットワークトポロジの特徴として適切な説明はどれですか。", "o": ["すべてのスポーク仮想ネットワークが直接インターネットにのみ接続される構成である　　　", "中央のハブ仮想ネットワークが共有サービスを提供し、スポークがそれに接続する構成である", "単一のサブネットのみで構成されるシンプルな構成である", "ハブとスポークの間で暗号化キーの共有ができない構成である"], "a": 1, "e": "ハブアンドスポーク型では、ハブに共有サービス（ファイアウォールなど）を配置し、各スポークがハブを経由して通信します。", "qEn": "Which statement correctly describes the hub-and-spoke network topology?", "oEn": ["A design where every spoke virtual network connects only directly to the internet", "A design where a central hub virtual network provides shared services and spokes connect to it", "A simple design consisting of only a single subnet", "A design where encryption keys cannot be shared between the hub and spokes"], "eEn": "In a hub-and-spoke topology, shared services (such as a firewall) sit in the hub, and each spoke communicates through the hub."}, {"d": "D3", "q": "サービスエンドポイントの目的として適切な説明はどれですか。", "o": ["仮想マシンへのリモートデスクトップ接続を安全に提供する　　　　　　　　　　", "シークレットとキーを一元的に安全に管理する", "特定のAzureサービスへの通信を最適化しインターネット経由なしで接続する", "ユーザーのサインインに多要素認証を強制する"], "a": 2, "e": "サービスエンドポイントを使用すると、仮想ネットワークから対象の Azure サービスへ直接かつ最適化された経路で通信できます。", "qEn": "What is the purpose of a service endpoint?", "oEn": ["To securely provide remote desktop connections to virtual machines", "To centrally and securely manage secrets and keys", "To optimize traffic to a specific Azure service without traversing the internet", "To enforce multifactor authentication for user sign-in"], "eEn": "Service endpoints allow traffic from a virtual network to reach target Azure services over a direct, optimized route."}, {"d": "D3", "q": "Network Security Group (NSG) の役割として最も適切なものはどれですか。", "o": ["シークレットやキーをアプリ全体で一元的に安全に保管する", "仮想マシンへの安全なリモート接続を常時仲介し続ける", "Webアプリケーションへの攻撃をシグネチャベースで検出しブロックする　　　　　　", "サブネットやNICの受信・送信トラフィックを許可・拒否ルールでフィルタリングする"], "a": 3, "e": "NSG はサブネットまたはネットワークインターフェイスに関連付けて、送受信トラフィックをルールに基づいてフィルタリングします。", "qEn": "What is the primary role of a Network Security Group (NSG)?", "oEn": ["Securely storing secrets and keys centrally across an application", "Continuously brokering secure remote connections to virtual machines", "Detecting and blocking attacks against web applications using signatures", "Filtering inbound/outbound traffic for a subnet or NIC using allow/deny rules"], "eEn": "An NSG is associated with a subnet or network interface and filters inbound/outbound traffic based on rules."}, {"d": "D3", "q": "NSG のルール評価に関する説明として正しいものはどれですか。", "o": ["優先度番号が小さいルールから順に評価され、一致した時点で処理が確定する", "すべてのルールが常に同時に適用され、最も緩いルールが優先される　　　　", "ルールの優先度は名前のアルファベット順で決まる", "送信ルールは常に受信ルールより後に評価される"], "a": 0, "e": "NSG のルールは優先度番号（小さいほど高優先）に基づいて評価され、条件に一致した最初のルールが適用されます。", "qEn": "Which statement correctly describes how NSG rules are evaluated?", "oEn": ["Rules are evaluated in order of priority number (lower first), and processing stops once a rule matches", "All rules are always applied simultaneously, and the most permissive rule takes precedence", "Rule priority is determined by alphabetical order of the rule name", "Outbound rules are always evaluated after inbound rules"], "eEn": "NSG rules are evaluated by priority number (lower numbers have higher priority), and the first matching rule is applied."}, {"d": "D3", "q": "NSG の既定のルールに関する説明として適切なものはどれですか。", "o": ["既定では仮想ネットワーク内のすべての通信がブロックされている", "既定で同一仮想ネットワーク内の通信を許可するルールが組み込まれている", "既定のルールはユーザーが必ず手動で作成する必要がある", "既定のルールにはインターネットからの受信を許可するものが含まれる　　"], "a": 1, "e": "NSG には既定のルールとして、仮想ネットワーク内通信の許可やロードバランサーからの通信許可などが組み込まれています。インターネットからの受信は既定で拒否されます。", "qEn": "Which statement correctly describes the default rules of an NSG?", "oEn": ["By default, all communication within the virtual network is blocked", "A built-in default rule allows communication within the same virtual network", "Default rules must always be created manually by the user", "The default rules include one that allows inbound traffic from the internet"], "eEn": "NSGs include built-in default rules such as allowing traffic within the virtual network and from the load balancer; inbound traffic from the internet is denied by default."}, {"d": "D3", "q": "NSG をネットワークインターフェイスとサブネットの両方に関連付けた場合の動作として正しいものはどれですか。", "o": ["サブネットレベルのNSGのみが評価され、NIC レベルは無視される　　　　", "NIC レベルのNSGのみが評価され、サブネットレベルは無視される", "受信トラフィックはサブネットNSGとNICのNSGの両方を満たす必要がある", "両方のNSGが競合する場合は常に許可が優先される"], "a": 2, "e": "両方のレベルにNSGを設定した場合、受信トラフィックは両方のルールセットを満たす必要があり、いずれかで拒否されればブロックされます。", "qEn": "What happens when an NSG is associated with both a network interface and a subnet?", "oEn": ["Only the subnet-level NSG is evaluated and the NIC level is ignored", "Only the NIC-level NSG is evaluated and the subnet level is ignored", "Inbound traffic must satisfy both the subnet NSG and the NIC NSG", "If the two NSGs conflict, allow always takes precedence"], "eEn": "When NSGs are set at both levels, inbound traffic must satisfy both rule sets; traffic is blocked if either one denies it."}, {"d": "D3", "q": "NSG で利用できるフィルタリングの条件として適切な組み合わせはどれですか。", "o": ["ユーザーのパスワード強度とサインイン地域", "ディスクの暗号化方式とキーの有効期限", "Web リクエストのHTTPヘッダーとCookie内容", "送信元/宛先IPアドレス、ポート、プロトコル"], "a": 3, "e": "NSG は送信元・宛先のIPアドレス、ポート番号、プロトコルなどに基づいてトラフィックをフィルタリングします。", "qEn": "Which combination of conditions can be used for filtering in an NSG?", "oEn": ["User password strength and sign-in region", "Disk encryption method and key expiration date", "HTTP headers and cookie contents of a web request", "Source/destination IP address, port, and protocol"], "eEn": "An NSG filters traffic based on criteria such as source and destination IP address, port number, and protocol."}, {"d": "D3", "q": "Azure でネットワークトラフィックの診断ログを取得し、どのNSGルールがトラフィックを許可/拒否したかを確認するための機能はどれですか。", "o": ["NSGフローログ", "Azure Key Vault の監査ログ", "Microsoft Entra サインインログ", "Azure Backup のジョブ履歴"], "a": 0, "e": "NSGフローログを使用すると、IPトラフィックがNSGルールによってどのように評価されたかの情報を記録・分析できます。", "qEn": "Which feature lets you capture diagnostic logs of network traffic and see which NSG rule allowed or denied it?", "oEn": ["NSG flow logs", "Azure Key Vault audit logs", "Microsoft Entra sign-in logs", "Azure Backup job history"], "eEn": "NSG flow logs let you record and analyze information about how IP traffic was evaluated by NSG rules."}, {"d": "D3", "q": "Azure Bastion の主な目的として適切なものはどれですか。", "o": ["仮想マシンのディスクを自動的に暗号化する", "パブリックIPを公開せずブラウザー経由で安全なRDP/SSH接続を提供する", "Webアプリケーションへの攻撃を自動的にブロックする", "複数のサブスクリプションのセキュリティポリシーを一元管理する　　　　　　　"], "a": 1, "e": "Azure Bastion は仮想マシンにパブリックIPを割り当てることなく、Azure Portal からブラウザー経由で安全にRDP/SSH接続できるPaaSサービスです。", "qEn": "What is the primary purpose of Azure Bastion?", "oEn": ["Automatically encrypting virtual machine disks", "Providing secure RDP/SSH connections via a browser without exposing a public IP", "Automatically blocking attacks against web applications", "Centrally managing security policies across multiple subscriptions"], "eEn": "Azure Bastion is a PaaS service that lets you securely connect via RDP/SSH through a browser from the Azure portal, without assigning a public IP to the VM."}, {"d": "D3", "q": "Azure Bastion を利用する利点として適切なものはどれですか。", "o": ["仮想マシンのバックアップを自動的にスケジュールする　　　　　　　　　　　　", "WAFのルールセットを自動更新する", "仮想マシンにパブリックIPを持たせる必要がなくなり、攻撃対象領域を減らせる", "DDoS攻撃のトラフィックを吸収する"], "a": 2, "e": "Bastion を使用すると仮想マシンにパブリックIPを割り当てる必要がなくなり、インターネットからの直接攻撃のリスクを低減できます。", "qEn": "What is a benefit of using Azure Bastion?", "oEn": ["It automatically schedules virtual machine backups", "It automatically updates WAF rule sets", "It removes the need to give virtual machines a public IP, reducing the attack surface", "It absorbs DDoS attack traffic"], "eEn": "Using Bastion removes the need to assign a public IP to virtual machines, reducing the risk of direct attacks from the internet."}, {"d": "D3", "q": "Azure Bastion のデプロイに関する説明として正しいものはどれですか。", "o": ["各仮想マシンごとに個別のBastionインスタンスをデプロイする必要がある　　　　　　　　　　　　", "オンプレミス環境にのみデプロイ可能である", "Bastionは仮想マシン内にエージェントとしてインストールする", "仮想ネットワーク内に専用のサブネット（AzureBastionSubnet）を用意してデプロイする"], "a": 3, "e": "Azure Bastion は仮想ネットワーク内の専用サブネット (AzureBastionSubnet) にデプロイし、同じ仮想ネットワーク内の複数のVMへの接続に利用できます。", "qEn": "Which statement correctly describes deploying Azure Bastion?", "oEn": ["A separate Bastion instance must be deployed for every individual virtual machine", "It can only be deployed in an on-premises environment", "Bastion is installed as an agent inside the virtual machine", "It is deployed into a dedicated subnet (AzureBastionSubnet) within the virtual network"], "eEn": "Azure Bastion is deployed into a dedicated subnet (AzureBastionSubnet) in the virtual network and can be used to connect to multiple VMs within that same virtual network."}, {"d": "D3", "q": "Azure Bastion を使用した接続とローカルのRDP/SSHクライアントを直接使用する接続の違いとして適切な説明はどれですか。", "o": ["Bastion接続はHTML5クライアントを使い、VMのパブリックIPやポート開放が不要になる", "Bastion経由の接続は必ず追加のVPNデバイス設置が必要になる仕組みである　　　　　　　　", "Bastion経由の接続はディスク暗号化キーを自動的に生成する仕組みである", "Bastion経由の接続はWebアプリケーションのみに限定される仕組みである"], "a": 0, "e": "Azure Bastion は HTML5 ベースのWebクライアントを提供し、VMのパブリックIP公開やRDP/SSHポートの直接開放を不要にします。", "qEn": "Which statement correctly describes the difference between connecting via Azure Bastion and using a local RDP/SSH client directly?", "oEn": ["A Bastion connection uses a browser HTML5 client, removing the need for a public IP or open ports on the VM", "A Bastion connection always requires deploying an additional VPN device to work at all", "A Bastion connection automatically generates new disk encryption keys each time", "A Bastion connection is limited only to connecting to web applications"], "eEn": "Azure Bastion provides an HTML5-based web client, removing the need to expose a public IP on the VM or directly open RDP/SSH ports."}, {"d": "D3", "q": "Azure Bastion がサポートする接続方法として適切なものはどれですか。", "o": ["FTP経由のファイル転送のみ　　　　　", "RDPとSSHの両方によるVMへの接続", "SMTPによるメール中継のみ", "DNS問い合わせの中継のみ"], "a": 1, "e": "Azure Bastion は Windows VM への RDP 接続と Linux VM への SSH 接続の両方をサポートします。", "qEn": "Which connection method does Azure Bastion support?", "oEn": ["Only file transfer via FTP", "Connecting to VMs using both RDP and SSH", "Only relaying email via SMTP", "Only relaying DNS queries"], "eEn": "Azure Bastion supports both RDP connections to Windows VMs and SSH connections to Linux VMs."}, {"d": "D3", "q": "Azure Key Vault の主な用途として適切なものはどれですか。", "o": ["仮想マシンの負荷分散を行う", "ネットワークトラフィックをフィルタリングする　　　　", "シークレット、キー、証明書を一元的かつ安全に管理する", "DDoS攻撃を検知して緩和する"], "a": 2, "e": "Azure Key Vault はアプリケーションシークレット、暗号化キー、証明書を安全に一元管理するためのサービスです。", "qEn": "What is the primary use case for Azure Key Vault?", "oEn": ["Load balancing virtual machines", "Filtering network traffic", "Centrally and securely managing secrets, keys, and certificates", "Detecting and mitigating DDoS attacks"], "eEn": "Azure Key Vault is a service for securely and centrally managing application secrets, encryption keys, and certificates."}, {"d": "D3", "q": "Key Vault にシークレットを保存する利点として適切なものはどれですか。", "o": ["アプリケーションのソースコードを自動的に難読化して保護できる　　　　　　　　", "仮想ネットワークのルーティングを自動的に最適化できる", "ストレージの冗長化レベルが自動的に引き上げられる", "コードや構成ファイルにシークレットを直接ハードコーディングする必要がなくなる"], "a": 3, "e": "Key Vault を利用することで、接続文字列やパスワードなどの機密情報をコードに直接埋め込む必要がなくなり、安全性が向上します。", "qEn": "What is a benefit of storing secrets in Key Vault?", "oEn": ["It automatically obfuscates and protects application source code", "It automatically optimizes virtual network routing paths", "It automatically raises the storage account's redundancy level", "It removes the need to hard-code secrets directly in code or configuration files"], "eEn": "Using Key Vault removes the need to embed sensitive information such as connection strings and passwords directly in code, improving security."}, {"d": "D3", "q": "Azure Key Vault へのアクセス制御に利用できる仕組みとして正しいものはどれですか。", "o": ["アクセスポリシーまたはAzure ロールベースアクセス制御 (RBAC)", "NSGのフローログのみ", "WAFのカスタムルールのみ", "DDoS Protectionのしきい値設定のみ　　　　　　　　　　　　"], "a": 0, "e": "Key Vault はアクセスポリシーモデルまたはAzure RBACのいずれかを使用して、キー・シークレット・証明書へのアクセスを制御できます。", "qEn": "Which mechanism can be used to control access to Azure Key Vault?", "oEn": ["An access policy or Azure role-based access control (RBAC)", "Only NSG flow logs", "Only WAF custom rules", "Only DDoS Protection threshold settings"], "eEn": "Key Vault can control access to keys, secrets, and certificates using either the access policy model or Azure RBAC."}, {"d": "D3", "q": "Key Vault が保存するキーや証明書の管理に関する説明として適切なものはどれですか。", "o": ["すべてのキーは平文でログに出力される仕様である", "HSMに裏付けられたキーの保護をサポートする", "証明書の自動更新は一切サポートされない", "シークレットのバージョン管理はサポートされない"], "a": 1, "e": "Key Vault はプレミアム SKU で HSM に保護されたキーをサポートし、証明書のライフサイクル管理やシークレットのバージョン管理も可能です。", "qEn": "Which statement correctly describes how Key Vault manages stored keys and certificates?", "oEn": ["All keys are always output to logs in plain text", "It supports key protection backed by a hardware security module (HSM)", "Automatic certificate renewal is not supported at all", "Secret versioning is not supported by the service"], "eEn": "Key Vault supports HSM-backed key protection with the Premium SKU, and also supports certificate lifecycle management and secret versioning."}, {"d": "D3", "q": "組織がアプリケーションからKey Vault内のシークレットへ安全にアクセスさせたい場合に推奨される認証方法はどれですか。", "o": ["共有のグローバル管理者アカウントを使い回す", "シークレットをアプリケーションの設定ファイルに直接コピーする　　　　　　　　", "マネージド ID を使用してアプリケーションからAzureリソースへ認証する", "FTPアカウントの共通パスワードを使用する"], "a": 2, "e": "マネージドIDを使用すると、資格情報を管理することなくAzureリソースからKey Vaultなどへ安全に認証できます。", "qEn": "Which authentication method is recommended for letting an application securely access secrets in Key Vault?", "oEn": ["Reusing a shared Global Administrator account", "Copying the secret directly into the application's configuration file", "Using a managed identity to authenticate the application to Azure resources", "Using a shared FTP account password"], "eEn": "Using a managed identity lets an Azure resource authenticate securely to services like Key Vault without managing credentials."}, {"d": "D3", "q": "Key Vault の監査に関して適切な説明はどれですか。", "o": ["監査ログの取得には必ずサードパーティ製品が必須である", "Key Vaultは操作ログを一切保持しない仕様である　", "監査ログはシークレットの内容を平文で記録する仕様である", "誰がいつどの操作を行ったかをログに記録し監視に利用できる"], "a": 3, "e": "Key Vault はアクセス・操作のログを記録でき、Azure Monitor などと連携して監視や異常検知に利用できます。", "qEn": "Which statement correctly describes auditing in Key Vault?", "oEn": ["A third-party product is always required to capture audit logs", "Key Vault does not retain any operation logs at all", "Audit logs record the plaintext content of secrets", "It logs who performed which operation and when, useful for monitoring"], "eEn": "Key Vault can log access and operations, and this can be used with services like Azure Monitor for monitoring and anomaly detection."}, {"d": "D3", "q": "Key Vault で誤って削除されたシークレットやキーを復旧するための機能はどれですか。", "o": ["論理的な削除 (ソフトデリート) と保持期間による復旧", "自動バックアップを取らないため復旧は不可能である　　　", "シークレットは削除操作自体をサポートしない", "削除は必ず即座に完全削除され復旧手段はない"], "a": 0, "e": "Key Vault のソフトデリート機能により、削除されたオブジェクトは指定した保持期間内であれば復旧できます。", "qEn": "Which feature allows recovery of an accidentally deleted secret or key in Key Vault?", "oEn": ["Soft delete along with recovery during a retention period", "Recovery is impossible because automatic backups are not taken", "Secrets do not support a delete operation at all", "Deletion is always immediate and permanent, with no recovery option"], "eEn": "Key Vault's soft-delete feature lets you recover deleted objects within a specified retention period."}, {"d": "D3", "q": "Microsoft Defender for Cloud の主な役割として適切な説明はどれですか。", "o": ["ユーザーのパスワードを定期的に自動変更する仕組みである", "クラウド環境のセキュリティ体制を評価し脅威保護を提供する統合プラットフォーム", "仮想ネットワークのルーティングテーブルを自動構成する仕組みである　　　　　　", "バックアップの保持ポリシーを自動的に設定する仕組みである"], "a": 1, "e": "Defender for Cloud はCSPM（クラウドセキュリティ体制管理）とCWP（クラウドワークロード保護）の機能を組み合わせた統合セキュリティ管理プラットフォームです。", "qEn": "Which statement correctly describes the primary role of Microsoft Defender for Cloud?", "oEn": ["A mechanism that automatically changes user passwords on a schedule", "An integrated platform that assesses cloud security posture and provides threat protection", "A mechanism that automatically configures virtual network routing tables", "A mechanism that automatically sets backup retention policies"], "eEn": "Defender for Cloud is an integrated security management platform that combines CSPM (cloud security posture management) and CWP (cloud workload protection) capabilities."}, {"d": "D3", "q": "Microsoft Defender for Cloud の無料プランに含まれる機能として適切なものはどれですか。", "o": ["高度な脅威検知とジャストインタイムVMアクセス　　　　　　", "コンテナイメージの脆弱性スキャン", "セキュリティポリシーの評価とセキュアスコアの基本的な可視化", "サーバーレスワークロードのランタイム保護"], "a": 2, "e": "無料プランでは、セキュリティポリシーに基づく継続的な評価とセキュアスコアの基本的な可視化が提供されます。高度な脅威検知は有料プランの機能です。", "qEn": "Which capability is included in the free plan of Microsoft Defender for Cloud?", "oEn": ["Advanced threat detection and just-in-time VM access", "Vulnerability scanning of container images", "Security policy assessment and basic secure score visibility", "Runtime protection for serverless workloads"], "eEn": "The free plan provides continuous assessment based on security policies and basic visibility into the secure score; advanced threat detection is a paid-plan feature."}, {"d": "D3", "q": "Defender for Cloud のセキュアスコアの目的として適切な説明はどれですか。", "o": ["仮想マシンの稼働時間を数値化して課金計算に利用する　　　　　　", "ユーザーごとのログイン回数を自動的にスコア化する", "ネットワーク帯域幅の使用率を継続的に測定する", "現在のセキュリティ体制を数値化し改善状況を追跡できるようにする"], "a": 3, "e": "セキュアスコアは組織のセキュリティ体制を数値で表し、推奨事項を実施することでスコアが向上し、体制改善を追跡できます。", "qEn": "What is the purpose of Defender for Cloud's secure score?", "oEn": ["To quantify virtual machine uptime for billing calculations", "To automatically score how many times each user has signed in", "To continuously measure network bandwidth utilization", "To quantify current security posture so improvement can be tracked"], "eEn": "The secure score represents an organization's security posture as a number, which improves as recommendations are implemented, allowing posture improvement to be tracked."}, {"d": "D3", "q": "Defender for Cloud が提供する推奨事項の主な目的はどれですか。", "o": ["検出された構成上の弱点を修正するための具体的なアクションを提示する", "仮想マシンのライセンス費用を自動的に削減する　　　　　　　　　　　", "ネットワーク帯域幅を自動的に拡張する", "ユーザーのパスワードを自動生成する"], "a": 0, "e": "推奨事項は、セキュリティ体制上の弱点を特定し、それを修正するための具体的な手順を提示します。", "qEn": "What is the main purpose of the recommendations provided by Defender for Cloud?", "oEn": ["To present concrete actions for fixing detected configuration weaknesses", "To automatically reduce virtual machine licensing costs", "To automatically expand network bandwidth", "To automatically generate user passwords"], "eEn": "Recommendations identify weaknesses in the security posture and present concrete steps to remediate them."}, {"d": "D3", "q": "Defender for Cloud のクラウドワークロード保護 (CWP) に含まれる機能として適切なものはどれですか。", "o": ["サブスクリプションの請求管理を自動化する機能", "サーバーやコンテナーなど特定ワークロードへの高度な脅威検出", "ユーザーのライセンス割り当てを一元管理する機能　　　　　　", "ドメイン名の登録情報を一元管理する機能"], "a": 1, "e": "クラウドワークロード保護 (CWP) は、サーバーやコンテナー、ストレージ、データベースなど特定のワークロードの種類に応じた高度な脅威検出を提供します。", "qEn": "Which capability is included in Defender for Cloud's cloud workload protection (CWP)?", "oEn": ["A feature that automates subscription billing management", "Advanced threat detection for specific workloads such as servers and containers", "A feature that centrally manages user license assignments", "A feature that centrally manages domain name registration data"], "eEn": "Cloud workload protection (CWP) provides advanced threat detection tailored to specific workload types such as servers, containers, storage, and databases."}, {"d": "D3", "q": "Defender for Cloud のジャストインタイム (JIT) VM アクセスの目的として適切なものはどれですか。", "o": ["仮想マシンのディスクを自動的に暗号化する", "WebアプリケーションへのSQLインジェクションを防ぐ　　　　　　", "管理ポートへのアクセスを必要な時間だけ許可し、攻撃対象領域を減らす", "バックアップの取得頻度を自動調整する"], "a": 2, "e": "JIT VM アクセスは、管理ポート（RDP/SSHなど）へのアクセスを必要なときだけ一時的に許可することで、攻撃対象領域を最小化します。", "qEn": "What is the purpose of Defender for Cloud's just-in-time (JIT) VM access?", "oEn": ["To automatically encrypt virtual machine disks", "To prevent SQL injection against web applications", "To allow access to management ports only for the time it is needed, reducing the attack surface", "To automatically adjust how often backups are taken"], "eEn": "JIT VM access minimizes the attack surface by temporarily allowing access to management ports (such as RDP/SSH) only when needed."}, {"d": "D3", "q": "Defender for Cloud がマルチクラウド環境（AWSやGCP）に対して提供できる機能として適切なものはどれですか。", "o": ["AWSやGCPのリソースは監視対象に一切含まれない", "他クラウドのリソースは料金計算のみを自動で行う", "他クラウドの仮想マシンのライセンス管理のみを継続的に行う　　　　　　　　　", "AWSやGCPのアカウントを接続しセキュリティ推奨事項と脅威検出を適用する"], "a": 3, "e": "Defender for Cloud はマルチクラウド対応であり、AWSやGCPのアカウントを接続してそれらの環境にもセキュリティ体制管理と脅威検出を拡張できます。", "qEn": "Which capability can Defender for Cloud provide for multicloud environments such as AWS and GCP?", "oEn": ["AWS and GCP resources are never included in monitoring at all", "It only automatically performs cost calculations for other clouds", "It only continuously manages virtual machine licensing in other clouds", "It connects AWS and GCP accounts and applies security recommendations and threat detection"], "eEn": "Defender for Cloud is multicloud-capable and can connect AWS and GCP accounts to extend security posture management and threat detection to those environments."}, {"d": "D3", "q": "Defender for Cloud のコンプライアンス管理機能に関する説明として適切なものはどれですか。", "o": ["業界標準への準拠状況を評価しダッシュボードで可視化する", "すべての規制要件を自動的に満たすよう構成を強制変更する", "コンプライアンス評価は年に一度のみ実行される仕様である", "コンプライアンス機能は仮想マシンにのみ適用される仕様である"], "a": 0, "e": "Defender for Cloud の規制コンプライアンスダッシュボードは、選択した標準に対する現在の準拠状況を評価し、可視化します。", "qEn": "Which statement correctly describes the compliance management capability of Defender for Cloud?", "oEn": ["It assesses compliance against industry standards and visualizes it in a dashboard", "It automatically forces configuration changes to meet every regulatory requirement", "Compliance assessment runs only once per year no matter what", "Compliance capabilities apply only to virtual machines and nothing else"], "eEn": "The Defender for Cloud regulatory compliance dashboard assesses and visualizes current compliance status against selected standards."}, {"d": "D3", "q": "Cloud Security Posture Management (CSPM) の目的として最も適切なものはどれですか。", "o": ["仮想マシンのディスク暗号化を自動的に代行する", "クラウド環境の構成を継続的に評価しリスクを可視化・改善する", "ネットワークトラフィックを物理的に遮断し続ける　　　　　　", "ユーザーのパスワードを定期的に自動変更する"], "a": 1, "e": "CSPM はクラウドリソースの構成を継続的に評価し、誤構成やリスクを検出して改善を促す仕組みです。", "qEn": "What is the primary purpose of Cloud Security Posture Management (CSPM)?", "oEn": ["Automatically performing virtual machine disk encryption on your behalf", "Continuously assessing cloud configuration to surface and improve security risks", "Physically blocking network traffic on an ongoing basis", "Regularly and automatically changing user passwords"], "eEn": "CSPM continuously assesses the configuration of cloud resources, detecting misconfigurations and risks and driving improvement."}, {"d": "D3", "q": "Defender for Cloud における CSPM 機能の基本（無料）階層で提供される内容として適切なものはどれですか。", "o": ["サーバーレスコンピューティングのランタイム保護　　　　　", "コンテナーレジストリの脆弱性スキャン", "セキュリティポリシーに基づく継続的な評価とセキュアスコア", "高度なマルウェア検出エンジン"], "a": 2, "e": "基本のCSPM機能は無料で提供され、セキュリティポリシーの評価とセキュアスコアの表示が含まれます。より高度な機能はDefender CSPMプランで有効化します。", "qEn": "Which content is provided in the free foundational tier of CSPM in Defender for Cloud?", "oEn": ["Runtime protection for serverless computing", "Vulnerability scanning of container registries", "Continuous assessment based on security policies and a secure score", "An advanced malware detection engine"], "eEn": "The foundational CSPM capability is free and includes security policy assessment and secure score display; more advanced features are enabled through the Defender CSPM plan."}, {"d": "D3", "q": "CSPM がリソースの誤構成を検出した際に取る典型的なアクションはどれですか。", "o": ["自動的に該当リソースを削除する", "ユーザーのアカウントを即座にロックする　　　　　　　　　　　", "課金プランを自動的に変更する", "推奨事項として提示し、修復手順や自動修復オプションを提案する"], "a": 3, "e": "CSPM は誤構成を検出すると推奨事項として提示し、必要に応じて自動修復のオプションを提供します。", "qEn": "What is a typical action CSPM takes when it detects a resource misconfiguration?", "oEn": ["It automatically deletes the affected resource", "It immediately locks the user's account", "It automatically changes the billing plan", "It surfaces it as a recommendation and suggests remediation steps or an auto-remediation option"], "eEn": "When CSPM detects a misconfiguration, it surfaces it as a recommendation and, where applicable, offers an auto-remediation option."}, {"d": "D3", "q": "Defender CSPM (拡張機能) が提供する追加機能として適切なものはどれですか。", "o": ["攻撃パスの可視化やエージェントレスの脆弱性スキャンなどの高度な分析", "仮想マシンのバックアップスケジュール管理　　　　　　　　　　　　　", "ドメイン名のDNS解決", "ユーザーのライセンス割り当て"], "a": 0, "e": "Defender CSPM プランでは攻撃パス分析、エージェントレススキャン、セキュリティガバナンスなどの高度な機能が追加されます。", "qEn": "Which additional capability does the Defender CSPM (enhanced) plan provide?", "oEn": ["Advanced analysis such as attack path visualization and agentless vulnerability scanning", "Managing virtual machine backup schedules", "DNS resolution of domain names", "Assigning user licenses"], "eEn": "The Defender CSPM plan adds advanced capabilities such as attack path analysis, agentless scanning, and security governance."}, {"d": "D3", "q": "CSPMにおける「攻撃パス分析」の目的として適切な説明はどれですか。", "o": ["ネットワーク帯域幅の使用状況を継続的にグラフ化する　　　　　　　　", "攻撃者が悪用しうる侵害経路を可視化し優先対応すべきリスクを特定する", "ユーザーのログイン時刻を自動的に記録する", "バックアップの実行状況を定期的に確認する"], "a": 1, "e": "攻撃パス分析は、脆弱性や誤構成が連鎖して悪用される可能性のある経路を可視化し、対応の優先順位付けに役立てます。", "qEn": "What is the purpose of \"attack path analysis\" in CSPM?", "oEn": ["Continuously graphing network bandwidth usage", "Visualizing exploitable breach paths to identify risks that need priority attention", "Automatically recording user sign-in times", "Periodically checking whether backups have run"], "eEn": "Attack path analysis visualizes chains of vulnerabilities and misconfigurations that could be exploited, helping prioritize remediation efforts."}, {"d": "D3", "q": "CSPMの継続的な評価が組織にもたらす利点として適切なものはどれですか。", "o": ["一度評価すれば以後は再評価が一切不要になる　　　　　　　　　　　　", "評価結果は監査担当者のみが常に閲覧できる", "環境変化に応じリスクをほぼリアルタイムに把握し劣化を早期発見できる", "評価はネットワーク帯域幅にのみ常に影響する"], "a": 2, "e": "クラウド環境は常に変化するため、継続的な評価によって新たなリスクや構成ドリフトを早期に発見できます。", "qEn": "What benefit does continuous CSPM assessment bring to an organization?", "oEn": ["Once assessed, no re-assessment is ever needed again", "Assessment results can only ever be viewed by auditors", "It gives near real-time risk awareness, enabling early detection of posture decline", "Assessment only ever affects network bandwidth"], "eEn": "Because cloud environments constantly change, continuous assessment allows early detection of new risks and configuration drift."}, {"d": "D3", "q": "Defender for Cloud のセキュリティポリシーの役割として適切な説明はどれですか。", "o": ["ユーザーのライセンス数を自動的に計算する", "仮想マシンの起動スケジュールを自動設定する　　　　　　　　　", "ネットワーク帯域幅の割り当てを自動で行う", "組織が満たすべきセキュリティ標準を定義し評価の基準を提供する"], "a": 3, "e": "セキュリティポリシーは、評価の基準となるルールセットを定義し、それに基づいて推奨事項やセキュアスコアが算出されます。", "qEn": "What is the role of a security policy in Defender for Cloud?", "oEn": ["Automatically calculating the number of user licenses", "Automatically setting the startup schedule of virtual machines", "Automatically allocating network bandwidth", "Defining security standards an organization must meet as an assessment baseline"], "eEn": "A security policy defines the rule set used as the baseline for assessment, from which recommendations and the secure score are calculated."}, {"d": "D3", "q": "セキュアスコアの数値が向上する典型的な要因として適切なものはどれですか。", "o": ["提示された推奨事項を実施し、未対応の弱点を修正すること", "サブスクリプションの数を増やすこと　　　　　　　　　　", "仮想マシンの台数を減らすこと", "ネットワーク帯域幅を増強すること"], "a": 0, "e": "推奨事項を実施して構成上の弱点を修正することで、対応するコントロールのスコアが加算され、全体のセキュアスコアが向上します。", "qEn": "What typically causes the secure score value to improve?", "oEn": ["Implementing the presented recommendations and fixing outstanding weaknesses", "Increasing the number of subscriptions", "Reducing the number of virtual machines", "Increasing network bandwidth"], "eEn": "Implementing recommendations to fix configuration weaknesses adds points to the corresponding control, raising the overall secure score."}, {"d": "D3", "q": "業界標準（規制コンプライアンス）をDefender for Cloudに追加する目的として適切なものはどれですか。", "o": ["仮想マシンのライセンス費用を自動的に削減するため　　", "組織が対象とする規制や標準への準拠状況を評価するため", "ネットワーク帯域幅を自動的に拡張し続けるため", "バックアップの保持期間を自動的に延長するため"], "a": 1, "e": "規制コンプライアンス機能を使用すると、選択した標準に対する現在の準拠状況を評価し、ギャップを可視化できます。", "qEn": "What is the purpose of adding an industry standard (regulatory compliance) to Defender for Cloud?", "oEn": ["To automatically reduce virtual machine licensing costs", "To assess compliance with a regulation or standard the organization is subject to", "To continuously and automatically expand network bandwidth", "To automatically extend the backup retention period"], "eEn": "The regulatory compliance feature lets you assess current compliance status against a selected standard and visualize the gaps."}, {"d": "D3", "q": "Defender for Cloud の推奨事項に付与される重大度（深刻度）レベルの目的として適切な説明はどれですか。", "o": ["課金額を算出するための指標として使用する　　　　　　　　　　", "ネットワーク帯域幅の割り当て量を決定する", "対応すべき優先順位を判断しやすくするためにリスクの高さを示す", "バックアップの取得頻度を自動的に決定する"], "a": 2, "e": "重大度レベルは推奨事項が示すリスクの高さを表し、組織が対応の優先順位を決める際の指標になります。", "qEn": "What is the purpose of the severity level assigned to a Defender for Cloud recommendation?", "oEn": ["To serve as a metric for calculating billing amounts", "To determine the amount of network bandwidth allocated", "To indicate how high the risk is, making it easier to judge remediation priority", "To automatically determine how often backups are taken"], "eEn": "The severity level indicates how high the risk represented by a recommendation is, giving the organization a way to prioritize remediation."}, {"d": "D3", "q": "セキュリティ標準（イニシアチブ）とセキュリティポリシーの関係として適切な説明はどれですか。", "o": ["ポリシーは標準よりも常に上位の概念である仕組みである　　　　　　　　　", "標準はポリシーの実行結果のログのみを指す仕組みである", "両者は同一のものであり全く区別されない概念である", "標準は関連する複数のポリシーをグループ化したものであり評価の基準となる"], "a": 3, "e": "セキュリティ標準（イニシアチブ）は複数の関連ポリシーをまとめたもので、Defender for Cloud はこれに基づいてリソースを評価します。", "qEn": "Which statement correctly describes the relationship between a security standard (initiative) and a security policy?", "oEn": ["A policy is always considered a higher-level concept than a standard", "A standard refers only to the log of a policy's execution results", "The two are entirely identical concepts with no distinction", "A standard groups together multiple related policies and serves as the assessment baseline"], "eEn": "A security standard (initiative) bundles multiple related policies together, and Defender for Cloud assesses resources based on it."}, {"d": "D3", "q": "組織がDefender for Cloudでカスタムの推奨事項を追加したい場合に利用できる仕組みはどれですか。", "o": ["カスタムのAzure Policyを作成し、セキュリティ標準に追加する", "NSGのフローログを手動で編集する", "WAFのマネージドルールセットを書き換える", "Key Vaultのアクセスポリシーを変更する　　　　　　　　　　　　"], "a": 0, "e": "組織固有の要件に対応するため、カスタムのAzure Policyを作成し、それをDefender for Cloudのセキュリティ標準に組み込むことでカスタム推奨事項として評価できます。", "qEn": "Which mechanism can an organization use to add a custom recommendation in Defender for Cloud?", "oEn": ["Creating a custom Azure Policy and adding it to the security standard", "Manually editing NSG flow logs", "Rewriting the WAF's managed rule set", "Changing a Key Vault access policy"], "eEn": "To address organization-specific requirements, you can create a custom Azure Policy and add it to a Defender for Cloud security standard so it is evaluated as a custom recommendation."}, {"d": "D3", "q": "クラウドワークロード保護 (CWP) が提供する強化されたセキュリティ機能の例として適切なものはどれですか。", "o": ["課金レポートの自動生成と配信機能", "サーバーの脆弱性評価やコンテナーの脅威検出などの保護", "ドメイン名の自動更新と登録管理機能", "ユーザーのライセンス自動割り当て機能　　　　　　　　"], "a": 1, "e": "CWPはサーバー、コンテナー、Kubernetes、ストレージ、データベースなど、ワークロードの種類ごとに特化した脅威検出と保護を提供します。", "qEn": "Which of the following is an example of enhanced security capability provided by cloud workload protection (CWP)?", "oEn": ["Automatic generation and delivery of billing reports", "Protections like vulnerability assessment for servers and threat detection for containers", "Automatic renewal and registration management of domain names", "Automatic assignment of user licenses"], "eEn": "CWP provides threat detection and protection specialized for each workload type, including servers, containers, Kubernetes, storage, and databases."}, {"d": "D3", "q": "Defender for Servers が提供する機能として適切なものはどれですか。", "o": ["Webアプリケーションへの攻撃をシグネチャベースでブロックする　　　　　　　　", "仮想ネットワークのピアリングを自動構成する", "サーバーの脆弱性評価やジャストインタイムVMアクセスなどのプラン固有の保護機能", "シークレットとキーの一元的な保管"], "a": 2, "e": "Defender for Servers はサーバー向けに脆弱性評価、JIT VMアクセス、適応型アプリケーション制御などの保護機能を提供します。", "qEn": "Which capability does Defender for Servers provide?", "oEn": ["Signature-based blocking of attacks against web applications", "Automatically configuring virtual network peering", "Plan-specific protections for servers such as vulnerability assessment and just-in-time VM access", "Centralized storage of secrets and keys"], "eEn": "Defender for Servers provides protections for servers such as vulnerability assessment, JIT VM access, and adaptive application controls."}, {"d": "D3", "q": "Defender for Containers が提供する保護として適切なものはどれですか。", "o": ["仮想マシンのディスク暗号化キーの生成　　　　　　　　", "DNSレコードの自動更新", "ネットワーク全体のDDoS緩和", "コンテナーイメージの脆弱性スキャンと実行時の脅威検出"], "a": 3, "e": "Defender for Containers はコンテナーイメージのスキャンや、実行中のコンテナー環境に対する脅威検出などの保護を提供します。", "qEn": "Which protection does Defender for Containers provide?", "oEn": ["Generating virtual machine disk encryption keys", "Automatically updating DNS records", "Network-wide DDoS mitigation", "Vulnerability scanning of container images and runtime threat detection"], "eEn": "Defender for Containers provides protections such as scanning container images and detecting threats against running container environments."}, {"d": "D3", "q": "拡張されたセキュリティ機能（CWPプラン）を有効化する主な利点として適切な説明はどれですか。", "o": ["ワークロード固有の高度な脅威検出が有効になり無料階層より深い保護を得られる", "課金体系が完全に無料へ切り替わる仕組みになる", "すべての推奨事項が自動的に無効化される設定になる　　　　　　　　　　　　　", "ネットワーク帯域幅の上限が完全に撤廃される"], "a": 0, "e": "CWPプランを有効化すると、サーバーやコンテナーなど各ワークロードに特化した高度な脅威検出機能が利用可能になり、無料階層を超えた保護が提供されます。", "qEn": "What is a key benefit of enabling enhanced security features (a CWP plan)?", "oEn": ["Advanced threat detection specialized for each workload is enabled, giving deeper protection than the free tier", "The billing model switches to being completely free", "All recommendations become automatically disabled", "The network bandwidth cap is completely removed"], "eEn": "Enabling a CWP plan makes advanced threat detection features specialized for each workload, such as servers and containers, available, providing protection beyond the free tier."}, {"d": "D3", "q": "Microsoft Sentinelはどのような種類のサービスとして分類されますか。", "o": ["仮想マシンの監視専用ツール", "メール配信専用のゲートウェイ製品", "クラウドネイティブなSIEMおよびSOARソリューション", "セキュリティ運用の現場では、オンプレミス専用のファイアウォール製品"], "a": 2, "e": "Microsoft Sentinelはクラウドネイティブなセキュリティ情報イベント管理（SIEM）とセキュリティオーケストレーション自動応答（SOAR）を統合したソリューションです。", "qEn": "How is Microsoft Sentinel best classified as a service?", "oEn": ["A tool solely for monitoring virtual machines", "A gateway product solely for mail delivery", "A cloud-native SIEM and SOAR solution", "In real-world security operations, An on-premises-only firewall product"], "eEn": "Microsoft Sentinel is a cloud-native solution combining Security Information and Event Management (SIEM) with Security Orchestration, Automation, and Response (SOAR)."}, {"d": "D3", "q": "Microsoft SentinelにおいてSOARの役割として最も適切な説明はどれですか。", "o": ["データを暗号化してストレージに保存する", "状況や設定によっては、仮想ネットワークのルーティングを設計する", "ネットワーク帯域幅を測定し課金する", "アラートへの対応を自動化し脅威への応答を効率化する"], "a": 3, "e": "SOAR（Security Orchestration, Automation, and Response）は、プレイブックなどを用いてインシデント対応の自動化と効率化を実現します。", "qEn": "Which description best fits the role of SOAR within Microsoft Sentinel?", "oEn": ["Encrypting data and storing it in storage", "Depending on the situation and configuration, Designing routing for virtual networks", "Measuring network bandwidth for billing purposes", "Automating responses to alerts to streamline threat response"], "eEn": "SOAR (Security Orchestration, Automation, and Response) uses tools like playbooks to automate and streamline incident response."}, {"d": "D3", "q": "Microsoft Sentinelがログデータを収集し保存するために利用する基盤サービスはどれですか。", "o": ["Log Analyticsワークスペース", "Azure Blob Storageの静的サイト機能", "Microsoft Teamsのチャネル", "Azure DevOpsのリポジトリ"], "a": 0, "e": "Microsoft SentinelはAzure Monitor Log Analyticsワークスペースを基盤として、収集したログデータを保存・分析します。", "qEn": "Which underlying service does Microsoft Sentinel use to collect and store log data?", "oEn": ["A Log Analytics workspace", "The static website feature of Azure Blob Storage", "A Microsoft Teams channel", "An Azure DevOps repository"], "eEn": "Microsoft Sentinel is built on an Azure Monitor Log Analytics workspace, which stores and enables analysis of collected log data."}, {"d": "D3", "q": "Microsoft Sentinelでログデータを検索・分析する際に使用されるクエリ言語はどれですか。", "o": ["YAMLテンプレート構文", "KQL（Kusto Query Language）", "PowerShell DSC構文", "多くの環境では、SQL Serverのストアドプロシージャ言語"], "a": 1, "e": "Microsoft SentinelはKQL（Kusto Query Language）を使用してログデータの検索、分析、可視化を行います。", "qEn": "Which query language is used to search and analyze log data in Microsoft Sentinel?", "oEn": ["YAML template syntax", "KQL (Kusto Query Language)", "PowerShell DSC syntax", "In many environments, SQL Server stored procedure language"], "eEn": "Microsoft Sentinel uses KQL (Kusto Query Language) to search, analyze, and visualize log data."}, {"d": "D3", "q": "Microsoft Sentinelの「データコネクタ」の主な目的は何ですか。", "o": ["課金レポートをExcelに変換すること", "ユーザーのパスワードを一括変更すること", "さまざまなソースからログやイベントデータを取り込むこと", "セキュリティ運用の現場では、仮想マシンのサイズを自動的に変更すること"], "a": 2, "e": "データコネクタは、Microsoft製品や他社製品、オンプレミス環境など多様なソースからログとイベントをMicrosoft Sentinelに取り込む機能です。", "qEn": "What is the main purpose of data connectors in Microsoft Sentinel?", "oEn": ["Converting billing reports into Excel", "Bulk-changing user passwords", "Ingesting log and event data from various sources", "In real-world security operations, Automatically resizing virtual machines"], "eEn": "Data connectors allow Microsoft Sentinel to ingest logs and events from diverse sources, including Microsoft products, third-party products, and on-premises environments."}, {"d": "D3", "q": "Microsoft Sentinelにおける「ブック（ワークブック）」の役割として正しいものはどれですか。", "o": ["脅威インテリジェンスのフィードを暗号化する", "エンドポイントのファイアウォールルールを変更する　　", "収集したデータを視覚的なダッシュボードとして表示する", "ユーザーのライセンス割り当てを管理する"], "a": 2, "e": "ワークブックは、Microsoft Sentinelに取り込まれたデータをグラフや表などで視覚化し、傾向やインサイトを把握するための機能です。", "qEn": "What is the correct role of workbooks in Microsoft Sentinel?", "oEn": ["Encrypting threat intelligence feeds", "Changing firewall rules on endpoints", "Displaying collected data visually as dashboards", "Managing user license assignments"], "eEn": "Workbooks visualize data ingested into Microsoft Sentinel using charts and tables, helping identify trends and insights."}, {"d": "D3", "q": "Microsoft Sentinelの分析ルール（Analytics rules）の主な目的は何ですか。", "o": ["ユーザーのプロファイル写真を更新すること　　　　　　　", "収集したデータからアラートやインシデントを生成すること", "ネットワークの帯域幅を予約すること", "仮想マシンのバックアップを実行すること"], "a": 1, "e": "分析ルールは、取り込まれたログデータに対して条件を評価し、該当するとアラートやインシデントを自動生成します。", "qEn": "What is the main purpose of analytics rules in Microsoft Sentinel?", "oEn": ["Updating user profile photos", "Generating alerts and incidents from collected data", "Reserving network bandwidth", "Running virtual machine backups"], "eEn": "Analytics rules evaluate conditions against ingested log data and automatically generate alerts and incidents when conditions are met."}, {"d": "D3", "q": "Microsoft SentinelのFusion分析ルールの特徴として正しいものはどれですか。", "o": ["ユーザーの多要素認証を強制する", "すべてのログを暗号化してアーカイブする", "ネットワークトラフィックを物理的に遮断する　　　　　　　　　　　　　", "機械学習を用いて複数の低忠実度アラートを相関させ高度な攻撃を検出する"], "a": 3, "e": "Fusionは機械学習アルゴリズムを利用し、複数の異なるシグナルを相関させることで、単独では見逃されがちな多段階攻撃を検出します。", "qEn": "What is a key characteristic of Fusion analytics rules in Microsoft Sentinel?", "oEn": ["Enforcing multifactor authentication for users", "Encrypting and archiving all logs", "Physically blocking network traffic", "Using machine learning to correlate multiple low-fidelity alerts to detect advanced attacks"], "eEn": "Fusion uses machine learning algorithms to correlate multiple distinct signals, detecting multi-stage attacks that might otherwise go unnoticed."}, {"d": "D3", "q": "Microsoft Sentinelの「インシデント」とは何を表しますか。", "o": ["多くの環境では、ネットワークセキュリティグループのルール", "課金対象のリソースグループ", "ユーザーのライセンス種別", "関連するアラートをグループ化した調査単位"], "a": 3, "e": "インシデントは、関連性のある複数のアラートを1つにまとめたもので、アナリストが調査・対応を行う単位となります。", "qEn": "What does an \"incident\" represent in Microsoft Sentinel?", "oEn": ["In many environments, A rule within a network security group", "A billable resource group", "A user license type", "A grouping of related alerts as an investigation unit"], "eEn": "An incident groups multiple related alerts together, serving as the unit that analysts investigate and respond to."}, {"d": "D3", "q": "Microsoft Sentinelにおける自動化ルールとプレイブックの関係として正しい説明はどれですか。", "o": ["自動化ルールがトリガー条件を定義し、プレイブックが実際のアクションを実行する", "プレイブックはKQLクエリの構文を検証するためだけに使われる　　　　　　　　", "自動化ルールはネットワーク機器のファームウェアを更新する", "プレイブックがすべてのユーザーアカウントを削除する権限を持つ"], "a": 0, "e": "自動化ルールはインシデントやアラートに対する対応の条件とトリガーを定義し、Azure Logic Appsで構築されたプレイブックが具体的な対応アクションを実行します。", "qEn": "Which statement correctly describes the relationship between automation rules and playbooks in Microsoft Sentinel?", "oEn": ["Automation rules define trigger conditions while playbooks execute the actual actions", "Playbooks are used only to validate KQL query syntax", "Automation rules update firmware on network devices", "Playbooks have permission to delete all user accounts"], "eEn": "Automation rules define the conditions and triggers for responding to incidents or alerts, while playbooks built with Azure Logic Apps carry out the actual response actions."}, {"d": "D3", "q": "Microsoft Sentinelのプレイブックはどのサービスを基盤として構築されますか。", "o": ["Azure DevOps Pipelines", "Azure Logic Apps", "Azure Cognitive Search", "Azure Kubernetes Service"], "a": 1, "e": "Microsoft Sentinelのプレイブックは、Azure Logic Appsを使用して構築され、脅威対応の自動化ワークフローを実現します。", "qEn": "Which service forms the foundation for Microsoft Sentinel playbooks?", "oEn": ["Azure DevOps Pipelines", "Azure Logic Apps", "Azure Cognitive Search", "Azure Kubernetes Service"], "eEn": "Microsoft Sentinel playbooks are built using Azure Logic Apps, enabling automated workflows for threat response."}, {"d": "D3", "q": "Microsoft Sentinelの「脅威ハンティング」機能の目的は何ですか。", "o": ["課金アラートを自動生成すること", "自動アラートでは検出されない潜在的な脅威を積極的に調査すること", "状況や設定によっては、すべてのユーザーパスワードを定期的にリセットすること", "仮想ネットワークのピアリングを設定すること"], "a": 1, "e": "脅威ハンティングは、アナリストが仮説に基づきクエリを実行し、既存の自動検出では見つからない潜在的な脅威を能動的に探す機能です。", "qEn": "What is the purpose of the threat hunting feature in Microsoft Sentinel?", "oEn": ["Automatically generating billing alerts", "Proactively investigating potential threats not caught by automated alerts", "Depending on the situation and configuration, Periodically resetting all user passwords", "Configuring virtual network peering"], "eEn": "Threat hunting lets analysts run hypothesis-driven queries to proactively search for potential threats that existing automated detections might miss."}, {"d": "D3", "q": "Microsoft Sentinelにおける「ブックマーク」機能の用途は何ですか。", "o": ["仮想マシンのスナップショットを作成すること　　　　　　　　　　", "ネットワークトラフィックをブロックすること", "ハンティング中に重要なクエリ結果を保存し後の調査に活用すること", "課金プランを変更すること"], "a": 2, "e": "ブックマークは、脅威ハンティング中に見つけた重要なイベントやクエリ結果を保存し、後で参照したりインシデントに関連付けたりするための機能です。", "qEn": "What is the purpose of the bookmark feature in Microsoft Sentinel?", "oEn": ["Creating snapshots of virtual machines", "Blocking network traffic", "Saving important query results during hunting for later investigation", "Changing the billing plan"], "eEn": "Bookmarks let analysts save important events or query results found during threat hunting for later reference or linking to incidents."}, {"d": "D3", "q": "Microsoft SentinelのUEBA（ユーザーおよびエンティティ行動分析）が主に検出しようとするものはどれですか。", "o": ["データベースのバックアップ失敗", "仮想マシンのCPU使用率の高さ", "通常のパターンから逸脱した異常なユーザーやエンティティの行動", "実務上のベストプラクティスとしては、ネットワークケーブルの物理的な断線"], "a": 2, "e": "UEBAは、ユーザーやデバイスなどのエンティティの通常の行動パターンを学習し、そこから逸脱した異常な挙動を検出することでリスクの高い活動を特定します。", "qEn": "What does UEBA (User and Entity Behavior Analytics) in Microsoft Sentinel primarily aim to detect?", "oEn": ["Database backup failures", "High CPU usage on virtual machines", "Anomalous user or entity behavior deviating from normal patterns", "As a matter of practical best practice, Physical disconnection of network cables"], "eEn": "UEBA learns normal behavior patterns for entities like users and devices, then detects deviations from those patterns to identify high-risk activity."}, {"d": "D3", "q": "Microsoft Sentinelの「コンテンツハブ」で提供されるものはどれですか。", "o": ["データコネクタ、分析ルール、ワークブックなどをまとめたソリューションパッケージ", "セキュリティ運用の現場では、組織のカスタムドメインに関するDNSレコードの設定情報", "仮想マシンのデプロイに使用するイメージテンプレート集", "各リソースグループごとの課金明細をまとめた詳細レポート"], "a": 0, "e": "コンテンツハブは、特定のベンダーや製品向けのデータコネクタ、分析ルール、ワークブック、プレイブックなどをまとめたソリューションを提供する場所です。", "qEn": "What does the Content Hub in Microsoft Sentinel provide?", "oEn": ["Solution packages bundling data connectors, analytics rules, and workbooks", "In real-world security operations, Configuration information for DNS records of the organization's custom domains", "A collection of image templates used to deploy virtual machines", "A detailed billing statement summarized for each resource group"], "eEn": "The Content Hub offers bundled solutions—data connectors, analytics rules, workbooks, and playbooks—tailored for specific vendors or products."}, {"d": "D3", "q": "Microsoft Sentinelでノートブック（Jupyter Notebooks）を利用する主な目的は何ですか。", "o": ["ユーザーのライセンス割り当てを変更すること", "高度なデータ分析や機械学習を用いた調査を行うこと", "課金アラートの通知先を設定すること", "ネットワークのファイアウォールルールを一括削除すること"], "a": 1, "e": "ノートブックは、Pythonなどを用いた高度なデータ分析、機械学習、可視化を活用してより深い調査を行うために使用されます。", "qEn": "What is the main purpose of using notebooks (Jupyter Notebooks) in Microsoft Sentinel?", "oEn": ["Changing user license assignments", "Performing advanced data analysis and machine-learning-based investigations", "Configuring notification recipients for billing alerts", "Bulk-deleting network firewall rules"], "eEn": "Notebooks allow analysts to use tools such as Python for advanced data analysis, machine learning, and visualization to conduct deeper investigations."}, {"d": "D3", "q": "Microsoft Sentinelが脅威インテリジェンスのフィードを取り込むために利用できるプロトコルはどれですか。", "o": ["SMTP（メール送信のための標準プロトコル）", "多くの環境では、RDP（リモートデスクトップ接続のためのプロトコル）", "FTP（ファイル転送のための標準プロトコル）", "TAXII（脅威インテリジェンス共有のための標準プロトコル）"], "a": 3, "e": "Microsoft SentinelはTAXIIプロトコルに対応した脅威インテリジェンスプラットフォームと連携し、外部の脅威指標を取り込むことができます。", "qEn": "Which protocol can Microsoft Sentinel use to ingest threat intelligence feeds?", "oEn": ["SMTP, a standard protocol for sending email", "In many environments, RDP, a protocol for remote desktop connections", "FTP, a standard protocol for file transfer", "TAXII, a standard protocol for sharing threat intelligence"], "eEn": "Microsoft Sentinel integrates with threat intelligence platforms that support the TAXII protocol to import external threat indicators."}, {"d": "D3", "q": "組織がMicrosoft Sentinelを他社製ファイアウォールと連携させたい場合、一般的に利用するログ転送方式はどれですか。", "o": ["Windowsイベントログの手動コピー　　　", "Excelファイルの電子メール送信", "Syslogまたは共通イベント形式（CEF）", "QRコードによるログ共有"], "a": 2, "e": "多くの他社製セキュリティ製品は、SyslogやCEF（Common Event Format）を使用してログをMicrosoft Sentinelに転送します。", "qEn": "When an organization wants to integrate a third-party firewall with Microsoft Sentinel, which log-forwarding method is commonly used?", "oEn": ["Manually copying Windows event logs", "Emailing Excel files", "Syslog or Common Event Format (CEF)", "Sharing logs via QR code"], "eEn": "Many third-party security products forward logs to Microsoft Sentinel using Syslog or CEF (Common Event Format)."}, {"d": "D3", "q": "Microsoft Sentinelでインシデントの重大度（Severity）を分類する際に一般的に使われないレベルはどれですか。", "o": ["低（Low）", "恒久的（Permanent）", "多くの環境では、中（Medium）", "高（High）"], "a": 1, "e": "Microsoft Sentinelのインシデント重大度は通常、高、中、低、情報（Informational）に分類され、「恒久的」という分類は存在しません。", "qEn": "Which severity level is NOT typically used to classify incidents in Microsoft Sentinel?", "oEn": ["Low", "Permanent", "In many environments, Medium", "High"], "eEn": "Incident severity in Microsoft Sentinel is typically classified as High, Medium, Low, or Informational; there is no \"Permanent\" classification."}, {"d": "D3", "q": "Microsoft Sentinelでインシデントの調査時に利用できる「調査グラフ（Investigation graph）」の目的はどれですか。", "o": ["状況や設定によっては、課金情報をグラフ化して表示すること", "エンティティ間の関係性を視覚的に表示し攻撃の全体像を把握しやすくすること", "従業員の勤怠状況を棒グラフで表示すること", "実務上のベストプラクティスとしては、ネットワーク帯域幅の使用率を円グラフで表示すること"], "a": 1, "e": "調査グラフは、インシデントに関連するエンティティ（ユーザー、ホスト、IPアドレスなど）間の関係性を視覚的にマッピングし、攻撃の全体像の把握を支援します。", "qEn": "What is the purpose of the Investigation graph used when investigating an incident in Microsoft Sentinel?", "oEn": ["Depending on the situation and configuration, Graphing billing information", "Visually mapping relationships between entities to make the full scope of an attack easier to understand", "Displaying employee attendance as a bar chart", "As a matter of practical best practice, Displaying network bandwidth usage as a pie chart"], "eEn": "The Investigation graph visually maps relationships between entities associated with an incident (such as users, hosts, and IP addresses), helping analysts understand the full scope of an attack."}, {"d": "D3", "q": "Microsoft Defender XDRの主な目的として最も適切な説明はどれですか。", "o": ["組織で使用するドメインのDNSレコードを自動的に生成し管理すること", "複数のMicrosoft Defender製品からのシグナルを相関させ、統合的な検出と対応を提供すること", "ネットワーク帯域幅の利用状況を分析し課金プランを最適化すること", "仮想マシンのバックアップスケジュールを一元的に管理し自動実行すること　　　　　　　　　　　　　　　　　　"], "a": 1, "e": "Microsoft Defender XDRは、エンドポイント、メール、ID、アプリなど複数のドメインからのシグナルを相関させ、統合されたインシデントビューと自動化された対応を提供します。", "qEn": "What is the primary purpose of Microsoft Defender XDR?", "oEn": ["Automatically generating and managing DNS records for domains used by the organization", "Correlating signals across multiple Microsoft Defender products for unified detection and response", "Analyzing network bandwidth usage to optimize the billing plan", "Centrally managing and automatically running virtual machine backup schedules"], "eEn": "Microsoft Defender XDR correlates signals across domains such as endpoints, email, identity, and apps, providing a unified incident view and automated response."}, {"d": "D3", "q": "Microsoft Defenderポータル（旧Microsoft 365 Defenderポータル）の役割として正しいものはどれですか。", "o": ["複数のDefender製品のセキュリティ情報を一元的に確認・管理できる統合ポータル", "セキュリティ運用の現場では、仮想マシンのコストとリソース使用量を管理するための専用ポータル", "社内の会議室の予約状況を一元的に管理するための予約ポータル", "従業員の給与情報や勤怠状況を一元的に管理するための人事ポータル"], "a": 0, "e": "Microsoft Defenderポータルは、Defender for Endpoint、Defender for Office 365、Defender for Identity、Defender for Cloud Appsなどの情報を統合的に表示・管理するポータルです。", "qEn": "What is the role of the Microsoft Defender portal (formerly Microsoft 365 Defender portal)?", "oEn": ["A unified portal to view and manage security information across multiple Defender products", "In real-world security operations, A dedicated portal for managing virtual machine costs and resource usage", "A reservation portal for centrally managing meeting room booking status", "An HR portal for centrally managing employee payroll and attendance information"], "eEn": "The Microsoft Defender portal centrally displays and manages information from products such as Defender for Endpoint, Defender for Office 365, Defender for Identity, and Defender for Cloud Apps."}, {"d": "D3", "q": "Microsoft Defender XDRが提供する「自動調査と対応（AIR）」の目的は何ですか。", "o": ["従業員の勤怠を自動集計すること", "アラートに対する調査と修復アクションを自動的に実行し対応時間を短縮すること", "仮想マシンのライセンスを自動更新すること　　　　　　　　　　　　　　　　　", "会議のスケジュールを自動調整すること"], "a": 1, "e": "自動調査と対応（AIR）は、検出されたアラートを自動的に調査し、必要に応じて修復アクションを実行することで、セキュリティチームの対応時間を短縮します。", "qEn": "What is the purpose of Automated Investigation and Response (AIR) in Microsoft Defender XDR?", "oEn": ["Automatically tallying employee attendance", "Automatically investigating alerts and executing remediation actions to reduce response time", "Automatically renewing virtual machine licenses", "Automatically adjusting meeting schedules"], "eEn": "Automated Investigation and Response (AIR) automatically investigates detected alerts and, where appropriate, executes remediation actions, reducing the time security teams spend on response."}, {"d": "D3", "q": "Microsoft Defender XDRの「攻撃の中断（Automatic attack disruption）」機能の目的は何ですか。", "o": ["ネットワーク機器のファームウェアを自動更新すること　　　　　　　　　　　　　　　", "ユーザーのライセンス割り当てを自動変更すること", "進行中の攻撃を検出した際に侵害されたアセットを自動的に封じ込め被害拡大を防ぐこと", "会議室の予約を自動キャンセルすること"], "a": 2, "e": "攻撃の中断機能は、進行中の高信頼度の攻撃を検出すると、侵害されたユーザーやデバイスを自動的に封じ込め、攻撃の拡大を最小限に抑えます。", "qEn": "What is the purpose of Automatic Attack Disruption in Microsoft Defender XDR?", "oEn": ["Automatically updating firmware on network devices", "Automatically changing user license assignments", "Automatically containing compromised assets upon detecting an in-progress attack to limit its spread", "Automatically canceling meeting room reservations"], "eEn": "Attack disruption automatically contains compromised users or devices when a high-confidence, in-progress attack is detected, minimizing the extent of the attack."}, {"d": "D3", "q": "Microsoft Defender XDRの高度なハンティング（Advanced hunting）機能で使用されるクエリ言語はどれですか。", "o": ["T-SQL", "GraphQL　　　　　　　　　　　　　　　　　　", "Regexのみ", "KQL（Kusto Query Language）"], "a": 3, "e": "高度なハンティングは、Advanced huntingスキーマに対してKQL（Kusto Query Language）を使用し、脅威を能動的に検索するための機能です。", "qEn": "Which query language is used for the Advanced hunting feature in Microsoft Defender XDR?", "oEn": ["T-SQL", "GraphQL", "Regex only", "KQL (Kusto Query Language)"], "eEn": "Advanced hunting uses KQL (Kusto Query Language) against the advanced hunting schema to proactively search for threats."}, {"d": "D3", "q": "Microsoft Defender XDRの脅威分析（Threat analytics）の目的として正しいものはどれですか。", "o": ["状況や設定によっては、会議室の利用状況を分析すること", "実際の運用環境や組織のポリシーによっては、ネットワークの帯域幅使用量を課金すること", "多くの環境では、従業員の勤務時間を追跡すること", "新興の脅威やキャンペーンに関する専門家レポートと組織への影響評価を提供すること"], "a": 3, "e": "脅威分析は、Microsoftのセキュリティ研究者による新しい脅威やキャンペーンに関するレポートと、それが自組織にどう影響するかの評価を提供します。", "qEn": "What is the purpose of Threat analytics in Microsoft Defender XDR?", "oEn": ["Depending on the situation and configuration, Analyzing meeting room utilization", "Depending on the actual operating environment or organizational policy, Billing for network bandwidth usage", "In many environments, Tracking employee working hours", "Providing expert reports on emerging threats and campaigns along with an assessment of organizational impact"], "eEn": "Threat analytics provides reports from Microsoft security researchers on emerging threats and campaigns, along with an assessment of how they may affect the organization."}, {"d": "D3", "q": "Microsoft Defender XDRが統合的な保護を提供する対象領域として通常含まれないものはどれですか。", "o": ["クラウドアプリケーション", "多くの環境では、メールおよびコラボレーションツール", "物理的なオフィスビルの入退室管理システム", "エンドポイント（デバイス）"], "a": 2, "e": "Microsoft Defender XDRはエンドポイント、メール、ID、クラウドアプリなどデジタル資産を対象とし、物理的な入退室管理システムは対象領域ではありません。", "qEn": "Which of the following is NOT typically part of the domains protected by Microsoft Defender XDR?", "oEn": ["Cloud applications", "In many environments, Email and collaboration tools", "A physical office building's access control system", "Endpoints (devices)"], "eEn": "Microsoft Defender XDR covers digital assets such as endpoints, email, identities, and cloud apps; physical building access control systems are not within its scope."}, {"d": "D3", "q": "Microsoft Defender for Cloud AppsがMicrosoft Defender XDRと統合された際に提供される機能領域はどれですか。", "o": ["セキュリティ運用の現場では、ネットワークケーブルの物理配線管理", "クラウドアプリの利用状況の可視化とシャドーITの検出", "会議室の予約システム", "仮想マシンのディスク暗号化"], "a": 1, "e": "Defender for Cloud Appsは、クラウドアプリケーションの利用状況を可視化し、シャドーITの検出やデータ保護ポリシーの適用を行う機能をDefender XDRに提供します。", "qEn": "What functional area does Microsoft Defender for Cloud Apps provide when integrated with Microsoft Defender XDR?", "oEn": ["In real-world security operations, Physical cabling management for network cables", "Visibility into cloud app usage and detection of shadow IT", "A meeting room reservation system", "Disk encryption for virtual machines"], "eEn": "Defender for Cloud Apps provides visibility into cloud application usage, detecting shadow IT and enforcing data protection policies, as part of Defender XDR."}, {"d": "D3", "q": "Microsoft Defender for Identityが検出しようとする典型的な脅威はどれですか。", "o": ["本社ビルの会議室に設置されたエアコンの経年劣化による故障", "経理部門における従業員の給与計算の入力ミスや誤り", "実務上のベストプラクティスとしては、データセンター内のネットワークケーブルの物理的な劣化や損傷", "オンプレミスActive Directoryを標的とした侵害されたIDや不審な活動"], "a": 3, "e": "Defender for Identityは、オンプレミスのActive Directoryシグナルを分析し、侵害されたIDや内部関係者による不正行為などの脅威を検出します。", "qEn": "What typical threat does Microsoft Defender for Identity aim to detect?", "oEn": ["Age-related failure of air conditioning units installed in head-office meeting rooms", "Data-entry mistakes or errors in employee payroll calculations made by the accounting department", "As a matter of practical best practice, Physical degradation or damage to network cables inside a data center", "Compromised identities or suspicious activity targeting on-premises Active Directory"], "eEn": "Defender for Identity analyzes on-premises Active Directory signals to detect threats such as compromised identities and malicious insider actions."}, {"d": "D3", "q": "Microsoft Defender XDRにおける統合インシデントキューの利点として正しいものはどれですか。", "o": ["複数のセキュリティ製品からのインシデントを1か所で優先順位付けして確認できること", "インシデントの重大度を手動で毎回入力する必要があること", "セキュリティ運用の現場では、各製品ごとに個別のポータルへログインする手間が増えること", "セキュリティ運用の現場では、課金情報のみを一元管理すること"], "a": 0, "e": "統合インシデントキューにより、セキュリティチームは複数のDefender製品からのインシデントを1つの画面で優先順位付けして効率的に確認・対応できます。", "qEn": "What is the benefit of the unified incident queue in Microsoft Defender XDR?", "oEn": ["Viewing and prioritizing incidents from multiple security products in one place", "Requiring manual entry of incident severity every time", "In real-world security operations, Increasing the effort of logging into separate portals for each product", "In real-world security operations, Centrally managing only billing information"], "eEn": "The unified incident queue lets security teams efficiently view, prioritize, and respond to incidents from multiple Defender products on a single screen."}, {"d": "D3", "q": "Microsoft Defender XDRの「統合設定」ページでMicrosoft Sentinelとの連携を有効にすると得られる利点はどれですか。", "o": ["多くの環境では、社内の会議室予約システムとリアルタイムで連携できること", "実際の運用環境や組織のポリシーによっては、人事部門が利用する給与計算システムとデータ連携ができること　　　", "セキュリティ運用の現場では、勤怠管理システムと連携し出退勤データを取り込めること", "Defender XDRのインシデントデータをMicrosoft Sentinelに双方向で同期できること"], "a": 3, "e": "Microsoft Defender XDRとMicrosoft Sentinelの連携を有効にすると、インシデントデータを双方向で同期し、両方のツールで一貫した調査・対応が可能になります。", "qEn": "What benefit is gained by enabling integration with Microsoft Sentinel from the Microsoft Defender XDR settings page?", "oEn": ["In many environments, Integrating in real time with an internal meeting room reservation system", "Depending on the actual operating environment or organizational policy, Exchanging data with the payroll system used by the HR department", "In real-world security operations, Integrating with an attendance management system to import clock-in/out data", "Bidirectional synchronization of Defender XDR incident data with Microsoft Sentinel"], "eEn": "Enabling integration between Microsoft Defender XDR and Microsoft Sentinel synchronizes incident data bidirectionally, allowing consistent investigation and response across both tools."}, {"d": "D3", "q": "Microsoft Defender XDRにおける「統合設定」でロールベースアクセス制御（RBAC）を構成する目的はどれですか。", "o": ["従業員の給与等級を設定すること", "ユーザーの役割に応じてポータル内で表示・操作できる範囲を制御すること", "会議室の利用権限を設定すること", "ネットワーク帯域幅を割り当てること　　　　　　　　　　　　　　　　　"], "a": 1, "e": "RBACを構成することで、セキュリティチームのメンバーがその役割に応じて必要な情報や機能にのみアクセスできるよう制御できます。", "qEn": "What is the purpose of configuring role-based access control (RBAC) in the unified settings of Microsoft Defender XDR?", "oEn": ["Setting employee salary grades", "Controlling what a user can view and operate within the portal based on their role", "Setting meeting room usage permissions", "Allocating network bandwidth"], "eEn": "Configuring RBAC ensures that members of a security team can access only the information and functionality relevant to their role."}, {"d": "D3", "q": "Microsoft Defender XDRのポータルでテナント全体のセキュリティ体制を数値で示す指標はどれですか。", "o": ["会議室稼働率", "多くの環境では、ネットワーク帯域幅利用率", "従業員満足度スコア", "Microsoftセキュアスコア"], "a": 3, "e": "Microsoftセキュアスコアは、組織全体のセキュリティ構成状態を数値化し、改善の優先順位を示す指標としてMicrosoft Defenderポータルで確認できます。", "qEn": "Which metric numerically represents the overall security posture of a tenant in the Microsoft Defender portal?", "oEn": ["Meeting room utilization rate", "In many environments, Network bandwidth utilization rate", "Employee satisfaction score", "Microsoft Secure Score"], "eEn": "Microsoft Secure Score quantifies an organization's overall security configuration posture and can be viewed in the Microsoft Defender portal as an indicator of improvement priorities."}, {"d": "D3", "q": "Microsoft Defender for Office 365の主な保護対象はどれですか。", "o": ["電子メールやコラボレーションツールを介した脅威", "オンプレミスのファイルサーバー", "多くの環境では、ネットワークスイッチのファームウェア", "仮想マシンのディスク暗号化"], "a": 0, "e": "Microsoft Defender for Office 365は、電子メール、Microsoft Teams、SharePoint、OneDriveなどのコラボレーションツールを介したフィッシングやマルウェアなどの脅威から保護します。", "qEn": "What is the primary protection target of Microsoft Defender for Office 365?", "oEn": ["Threats delivered via email and collaboration tools", "On-premises file servers", "In many environments, Firmware on network switches", "Disk encryption on virtual machines"], "eEn": "Microsoft Defender for Office 365 protects against threats such as phishing and malware delivered through email and collaboration tools like Microsoft Teams, SharePoint, and OneDrive."}, {"d": "D3", "q": "Microsoft Defender for Office 365の「セーフリンク（Safe Links）」機能の目的はどれですか。", "o": ["メールやドキュメント内のURLをクリック時にスキャンし悪意あるサイトへのアクセスを防ぐこと", "送信するすべてのメールを自動的に暗号化しアーカイブに保存すること　　　　　　　　　　　　　", "ユーザーのメールボックスの容量を自動的に拡張し続けること", "全ユーザーのパスワードを定期的かつ強制的に変更させること"], "a": 0, "e": "セーフリンクは、メールやOfficeドキュメント内のURLをユーザーがクリックした時点でリアルタイムにスキャンし、悪意あるサイトへのアクセスをブロックします。", "qEn": "What is the purpose of the Safe Links feature in Microsoft Defender for Office 365?", "oEn": ["Scanning URLs in emails and documents at click-time to prevent access to malicious sites", "Automatically encrypting and archiving all outgoing email", "Continuously and automatically expanding a user's mailbox storage capacity", "Periodically forcing all users to change their passwords"], "eEn": "Safe Links performs real-time scanning of URLs in emails and Office documents at the moment a user clicks, blocking access to malicious sites."}, {"d": "D3", "q": "Microsoft Defender for Office 365の「セーフアタッチメント（Safe Attachments）」機能の仕組みとして正しいものはどれですか。", "o": ["添付ファイルを送信者に自動返送する", "添付ファイルのサイズを自動的に圧縮する　　　　　　　　　　　　　　　", "添付ファイルのファイル名を暗号化する", "添付ファイルを隔離環境（サンドボックス）で実行し不審な挙動を検査する"], "a": 3, "e": "セーフアタッチメントは、添付ファイルを安全な検出環境（サンドボックス）で開いて動作を分析し、悪意あるコンテンツを検出してからユーザーに配信します。", "qEn": "How does the Safe Attachments feature in Microsoft Defender for Office 365 work?", "oEn": ["It automatically returns attachments to the sender", "It automatically compresses attachment file sizes", "It encrypts attachment file names", "It runs attachments in an isolated sandbox environment to inspect suspicious behavior"], "eEn": "Safe Attachments opens attachments in a secure detonation environment (sandbox) to analyze their behavior for malicious content before delivering them to the user."}, {"d": "D3", "q": "Microsoft Defender for Office 365の脅威エクスプローラー（Threat Explorer）の主な用途は何ですか。", "o": ["仮想マシンのコストを分析すること", "組織内で検出された脅威をリアルタイムで調査・分析すること", "従業員の有給休暇残日数を確認すること", "多くの環境では、ネットワークのルーティングテーブルを編集すること"], "a": 1, "e": "脅威エクスプローラーは、組織に対するメールベースの攻撃をほぼリアルタイムで確認し、脅威の傾向を調査するためのツールです。", "qEn": "What is the main use of Threat Explorer in Microsoft Defender for Office 365?", "oEn": ["Analyzing virtual machine costs", "Investigating and analyzing threats detected within the organization in near real time", "Checking employees' remaining paid leave balance", "In many environments, Editing network routing tables"], "eEn": "Threat Explorer allows near real-time viewing of email-based attacks against the organization, helping investigate threat trends."}, {"d": "D3", "q": "Microsoft Defender for Office 365における「攻撃シミュレーショントレーニング」の目的として正しいものはどれですか。", "o": ["状況や設定によっては、実際のマルウェアを従業員の端末に配布して耐性を試すこと", "従業員のメールボックス容量を自動拡張すること", "フィッシングなどの模擬攻撃を実施し従業員のセキュリティ意識を高めること", "従業員の給与を自動計算すること"], "a": 2, "e": "攻撃シミュレーショントレーニングは、実際には無害な模擬フィッシング攻撃を送信し、従業員の対応を評価してセキュリティ意識向上のためのトレーニングを提供します。", "qEn": "What is the purpose of Attack Simulation Training in Microsoft Defender for Office 365?", "oEn": ["Depending on the situation and configuration, Distributing real malware to employee devices to test resilience", "Automatically expanding employees' mailbox storage capacity", "Running simulated attacks like phishing to raise employees' security awareness", "Automatically calculating employee salaries"], "eEn": "Attack Simulation Training sends realistic but harmless simulated phishing attacks, evaluating employee responses and providing training to raise security awareness."}, {"d": "D3", "q": "Microsoft Defender for Office 365 Plan 1に含まれる機能として一般的なものはどれですか。", "o": ["高度なハンティングとカスタム検出ルール　　　　　　　　　", "セーフリンクとセーフアタッチメントによるリアルタイム保護", "攻撃シミュレーショントレーニング", "脅威追跡ツールと自動調査対応"], "a": 1, "e": "Plan 1は主にセーフリンク、セーフアタッチメント、リアルタイム検出などの予防的な保護機能を提供し、Plan 2ではより高度な調査・対応機能が追加されます。", "qEn": "Which feature is commonly included in Microsoft Defender for Office 365 Plan 1?", "oEn": ["Advanced hunting and custom detection rules", "Real-time protection through Safe Links and Safe Attachments", "Attack Simulation Training", "Threat trackers and automated investigation and response"], "eEn": "Plan 1 primarily provides preventive protection features such as Safe Links, Safe Attachments, and real-time detection, while Plan 2 adds more advanced investigation and response capabilities."}, {"d": "D3", "q": "Microsoft Defender for Office 365 Plan 2に含まれる機能として一般的なものはどれですか。", "o": ["Officeアプリのライセンス管理のみ", "メールボックスの容量拡張のみ", "多くの環境では、セーフリンクの基本的なURLスキャンのみ", "自動調査と対応、および脅威エクスプローラー"], "a": 3, "e": "Plan 2には自動調査と対応（AIR）、脅威エクスプローラー、攻撃シミュレーショントレーニングなど、より高度な調査・対応機能が含まれます。", "qEn": "Which feature is commonly included in Microsoft Defender for Office 365 Plan 2?", "oEn": ["Only Office app license management", "Only mailbox storage expansion", "In many environments, Only basic URL scanning via Safe Links", "Automated investigation and response, and Threat Explorer"], "eEn": "Plan 2 includes more advanced investigation and response capabilities such as Automated Investigation and Response (AIR), Threat Explorer, and Attack Simulation Training."}, {"d": "D3", "q": "Microsoft Defender for Office 365の反フィッシングポリシーが検出しようとする典型的な脅威はどれですか。", "o": ["なりすましメールやドメインスプーフィングによる詐欺攻撃", "データベースのインデックス断片化", "セキュリティ運用の現場では、ネットワークケーブルの物理的な損傷", "ハードウェアのファン故障"], "a": 0, "e": "反フィッシングポリシーは、送信者のなりすましやドメインスプーフィングを検出し、フィッシング詐欺からユーザーを保護します。", "qEn": "What typical threat does the anti-phishing policy in Microsoft Defender for Office 365 aim to detect?", "oEn": ["Impersonation and domain-spoofing fraud attacks", "Database index fragmentation", "In real-world security operations, Physical damage to network cables", "Hardware fan failures"], "eEn": "Anti-phishing policies detect sender impersonation and domain spoofing, protecting users from phishing fraud."}, {"d": "D3", "q": "Microsoft Defender for Office 365が保護対象とするコラボレーションツールに一般的に含まれないものはどれですか。", "o": ["OneDrive for Business", "Microsoft Teams", "サードパーティ製の会計ソフトウェア", "SharePoint Online"], "a": 2, "e": "Microsoft Defender for Office 365は、Teams、SharePoint、OneDriveなどMicrosoft 365のコラボレーションツールを保護対象としますが、サードパーティの会計ソフトウェアは対象外です。", "qEn": "Which of the following is generally NOT among the collaboration tools protected by Microsoft Defender for Office 365?", "oEn": ["OneDrive for Business", "Microsoft Teams", "Third-party accounting software", "SharePoint Online"], "eEn": "Microsoft Defender for Office 365 protects Microsoft 365 collaboration tools such as Teams, SharePoint, and OneDrive, but does not cover third-party accounting software."}, {"d": "D3", "q": "Microsoft Defender for Office 365における「キャンペーンビュー（Campaign Views）」の目的はどれですか。", "o": ["従業員の勤怠記録を集計すること", "セキュリティ運用の現場では、ネットワーク帯域幅の使用量を可視化すること", "組織を標的とした一連のフィッシング攻撃の全体像を把握すること", "仮想マシンのコストを分析すること"], "a": 2, "e": "キャンペーンビューは、組織を狙った一連の関連するフィッシング攻撃をまとめて可視化し、攻撃の全体像や規模を把握するのに役立ちます。", "qEn": "What is the purpose of Campaign Views in Microsoft Defender for Office 365?", "oEn": ["Tallying employee attendance records", "In real-world security operations, Visualizing network bandwidth usage", "Understanding the full picture of a coordinated series of phishing attacks targeting the organization", "Analyzing virtual machine costs"], "eEn": "Campaign Views aggregate and visualize a series of related phishing attacks targeting the organization, helping analysts understand the scope and scale of the attack."}, {"d": "D3", "q": "Microsoft Defender for Office 365における「隔離（Quarantine）」機能の目的として正しいものはどれですか。", "o": ["メールボックスの容量を自動拡張すること", "送信メールを自動的に暗号化すること", "悪意があると判定されたメールを安全な場所に保管しユーザーへの配信を防ぐこと", "ユーザーのライセンスを自動割り当てすること　　　　　　　　　　　　　　　　"], "a": 2, "e": "隔離機能は、フィッシングやマルウェアが疑われるメールをユーザーの受信トレイに届く前に安全な場所に保管し、管理者やユーザーが確認・処理できるようにします。", "qEn": "What is the purpose of the Quarantine feature in Microsoft Defender for Office 365?", "oEn": ["Automatically expanding mailbox storage capacity", "Automatically encrypting outgoing email", "Storing emails judged malicious in a safe location to prevent delivery to users", "Automatically assigning user licenses"], "eEn": "Quarantine holds emails suspected of phishing or malware in a safe location before they reach a user's inbox, allowing administrators or users to review and act on them."}, {"d": "D3", "q": "Microsoft Defender for Office 365の「ゼロアワー自動消去（ZAP）」機能の目的はどれですか。", "o": ["メールの送信予約を自動設定すること", "配信後に悪意があると判明したメールを事後的に隔離すること", "状況や設定によっては、メールボックスの容量を毎時自動拡張すること", "ユーザーの署名を自動的に統一すること"], "a": 1, "e": "ZAP（Zero-hour Auto Purge）は、配信済みのメールが後から悪意あるものと判明した場合に、そのメールを受信トレイから自動的に隔離する機能です。", "qEn": "What is the purpose of the Zero-hour Auto Purge (ZAP) feature in Microsoft Defender for Office 365?", "oEn": ["Automatically scheduling email send times", "Retroactively quarantining emails later determined to be malicious after delivery", "Depending on the situation and configuration, Automatically expanding mailbox storage every hour", "Automatically unifying user signatures"], "eEn": "ZAP (Zero-hour Auto Purge) automatically quarantines an already-delivered email from a user's inbox if it is later determined to be malicious."}, {"d": "D3", "q": "Microsoft Defender for Office 365における「テナントの許可/ブロックリスト」の用途はどれですか。", "o": ["会議室の利用権限を設定すること", "従業員の勤務シフトを管理すること", "実際の運用環境や組織のポリシーによっては、ネットワーク帯域幅を割り当てること", "特定のURL、ファイル、送信者を明示的に許可またはブロックする設定を行うこと"], "a": 3, "e": "テナントの許可/ブロックリストは、管理者が特定のURL、ファイル、送信者アドレスを明示的に許可またはブロックするために使用する設定です。", "qEn": "What is the purpose of the Tenant Allow/Block List in Microsoft Defender for Office 365?", "oEn": ["Setting meeting room usage permissions", "Managing employee work shifts", "Depending on the actual operating environment or organizational policy, Allocating network bandwidth", "Configuring explicit allow or block settings for specific URLs, files, or senders"], "eEn": "The Tenant Allow/Block List is a configuration administrators use to explicitly allow or block specific URLs, files, or sender addresses."}, {"d": "D3", "q": "Microsoft Defender for Office 365において、メール内の添付ファイルが安全と判断されるまでユーザーへの配信を遅延させる仕組みはどれですか。", "o": ["Safe Attachmentsの動的配信（Dynamic Delivery）", "指定した日時にメールを自動送信する予約送信機能", "受信メールを自動的にアーカイブフォルダーへ移動する機能　　　　　　　　　　　　", "予定表アプリと自動的に同期を行うカレンダー同期機能"], "a": 0, "e": "動的配信は、添付ファイルの安全性検証が完了するまでメール本文だけを先に配信し、ファイルはスキャン完了後に利用可能にする機能です。", "qEn": "Which mechanism in Microsoft Defender for Office 365 delays delivering an email attachment to a user until it is deemed safe?", "oEn": ["Safe Attachments' Dynamic Delivery", "A scheduled-send feature that automatically sends email at a specified date and time", "A feature that automatically moves received email into an archive folder", "A calendar sync feature that automatically synchronizes with a scheduling app"], "eEn": "Dynamic Delivery delivers the email body first while the attachment's safety verification is still in progress, making the file available only after scanning completes."}, {"d": "D3", "q": "Microsoft Defender for Office 365における「なりすまし保護（Impersonation protection）」の目的はどれですか。", "o": ["ユーザーの署名を統一すること", "メールボックスの容量を自動拡張すること　　　　　　　　　　", "メールの送信者名を自動的に変更すること", "経営幹部や取引先を装った詐欺メールを検出しブロックすること"], "a": 3, "e": "なりすまし保護は、経営幹部や取引先などの実際の送信者を装った詐欺的なメールを検出し、ビジネスメール詐欺（BEC）などの被害を防ぎます。", "qEn": "What is the purpose of Impersonation protection in Microsoft Defender for Office 365?", "oEn": ["Unifying user signatures", "Automatically expanding mailbox storage capacity", "Automatically changing an email's sender name", "Detecting and blocking fraudulent emails impersonating executives or business partners"], "eEn": "Impersonation protection detects fraudulent emails that impersonate actual senders, such as executives or business partners, helping prevent business email compromise (BEC) and similar fraud."}, {"d": "D3", "q": "Microsoft Defender for Office 365でメール認証技術（SPF、DKIM、DMARC）の主な役割はどれですか。", "o": ["送信ドメインのなりすましを防ぎメールの正当性を検証すること", "メールの送信速度を高速化すること", "実務上のベストプラクティスとしては、メールの表示フォントを統一すること", "メールボックスの容量を拡張すること"], "a": 0, "e": "SPF、DKIM、DMARCは、送信元ドメインが正当であることを検証する認証技術であり、なりすましメールやフィッシングを防ぐ基盤となります。", "qEn": "What is the primary role of email authentication technologies (SPF, DKIM, DMARC) in Microsoft Defender for Office 365?", "oEn": ["Preventing sending-domain spoofing and verifying email legitimacy", "Speeding up email delivery", "As a matter of practical best practice, Unifying email display fonts", "Expanding mailbox storage capacity"], "eEn": "SPF, DKIM, and DMARC are authentication technologies that verify the legitimacy of a sending domain, forming the foundation for preventing spoofed and phishing emails."}, {"d": "D3", "q": "Microsoft Defender for Endpointが主に対象とする保護領域はどれですか。", "o": ["組織内のエンドポイント（デバイス）に対する脅威", "電子メールの送受信内容", "会議室予約システムの脆弱性", "セキュリティ運用の現場では、給与計算システムのデータ整合性"], "a": 0, "e": "Microsoft Defender for Endpointは、Windows、macOS、Linux、モバイルデバイスなどのエンドポイントを保護し、高度な脅威に対する予防・検出・対応を提供します。", "qEn": "What is the primary protection domain of Microsoft Defender for Endpoint?", "oEn": ["Threats against endpoints (devices) within the organization", "The content of sent and received emails", "Vulnerabilities in a meeting room reservation system", "In real-world security operations, Data integrity in a payroll system"], "eEn": "Microsoft Defender for Endpoint protects endpoints such as Windows, macOS, Linux, and mobile devices, providing prevention, detection, and response against advanced threats."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「脅威と脆弱性の管理（Threat and Vulnerability Management）」の主な目的はどれですか。", "o": ["会議室の予約状況を分析すること", "デバイスの脆弱性を発見し優先順位付けして修復を支援すること", "従業員の勤怠を自動集計すること", "ネットワーク帯域幅の課金を管理すること　　　　　　　　　　"], "a": 1, "e": "脅威と脆弱性の管理は、デバイス上のソフトウェアの脆弱性や設定の不備をリアルタイムで発見し、リスクベースで優先順位付けして修復を支援する機能です。", "qEn": "What is the main purpose of Threat and Vulnerability Management in Microsoft Defender for Endpoint?", "oEn": ["Analyzing meeting room reservation status", "Discovering device vulnerabilities, prioritizing them, and aiding remediation", "Automatically tallying employee attendance", "Managing billing for network bandwidth"], "eEn": "Threat and Vulnerability Management discovers software vulnerabilities and misconfigurations on devices in real time, prioritizing them on a risk basis to help remediation."}, {"d": "D3", "q": "Microsoft Defender for Endpointにおける「攻撃対象領域の減少（Attack Surface Reduction）」ルールの目的はどれですか。", "o": ["従業員のライセンス費用を削減すること", "ネットワークケーブルの配線を最適化すること　　　　　　　　　　　　　　　", "マルウェアが悪用しやすい動作や設定をブロックし攻撃の侵入経路を減らすこと", "デバイスのストレージ容量を自動拡張すること"], "a": 2, "e": "攻撃対象領域の減少ルールは、マクロやスクリプトの悪用などマルウェアがよく利用する挙動をブロックし、攻撃者が侵入に使える経路を減らします。", "qEn": "What is the purpose of Attack Surface Reduction rules in Microsoft Defender for Endpoint?", "oEn": ["Reducing employee license costs", "Optimizing network cable wiring", "Blocking behaviors and configurations often exploited by malware to reduce attack entry points", "Automatically expanding device storage capacity"], "eEn": "Attack Surface Reduction rules block behaviors commonly abused by malware, such as malicious macros or scripts, reducing the pathways attackers can use to gain entry."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「次世代の保護（Next-generation protection）」に含まれる代表的な機能はどれですか。", "o": ["Microsoft Defender ウイルス対策によるリアルタイムのマルウェア検出", "実務上のベストプラクティスとしては、ネットワーク帯域幅の利用状況に関する課金レポートを作成すること", "多くの環境では、社内の会議室予約システムを一元的に管理すること", "セキュリティ運用の現場では、従業員の給与を毎月自動的に計算し支払うこと"], "a": 0, "e": "次世代の保護には、クラウド提供の保護や機械学習を活用したMicrosoft Defenderウイルス対策によるリアルタイムのマルウェア検出とブロックが含まれます。", "qEn": "What is a representative feature included in Next-generation protection in Microsoft Defender for Endpoint?", "oEn": ["Real-time malware detection via Microsoft Defender Antivirus", "As a matter of practical best practice, Producing billing reports on network bandwidth usage", "In many environments, Centrally managing an internal meeting room reservation system", "In real-world security operations, Automatically calculating and paying employee salaries every month"], "eEn": "Next-generation protection includes real-time malware detection and blocking through Microsoft Defender Antivirus, leveraging cloud-delivered protection and machine learning."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「エンドポイント検出と対応（EDR）」機能の主な役割はどれですか。", "o": ["多くの環境では、デバイスのディスプレイ解像度を自動調整すること", "従業員の休暇申請を承認すること", "デバイス上の不審な活動を検出し調査・対応を可能にすること", "デバイスのバッテリー消費を最適化すること"], "a": 2, "e": "EDR機能は、デバイス上で発生する不審な挙動やイベントを継続的に監視・記録し、セキュリティチームが脅威を検出・調査・対応できるようにします。", "qEn": "What is the main role of Endpoint Detection and Response (EDR) in Microsoft Defender for Endpoint?", "oEn": ["In many environments, Automatically adjusting a device's display resolution", "Approving employee leave requests", "Detecting suspicious activity on devices and enabling investigation and response", "Optimizing device battery consumption"], "eEn": "EDR continuously monitors and records suspicious behavior and events occurring on devices, enabling security teams to detect, investigate, and respond to threats."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「ライブレスポンス（Live response）」機能でできることはどれですか。", "o": ["デバイスのディスプレイの色設定を変更すること", "多くの組織のセキュリティ運用の現場では、デバイスの物理的な電源を遠隔操作でオンにすること", "デバイスの製造元保証情報を更新すること", "デバイスにリモート接続しコマンド実行やファイル収集などの調査アクションを行うこと"], "a": 3, "e": "ライブレスポンスは、セキュリティ担当者が侵害されたデバイスにリモートで接続し、コマンドの実行やファイルの収集などリアルタイムの調査・修復アクションを行える機能です。", "qEn": "What can be done with the Live response feature in Microsoft Defender for Endpoint?", "oEn": ["Changing a device's display color settings", "In the security operations of many organizations, Remotely powering on a device's physical power switch", "Updating a device's manufacturer warranty information", "Remotely connecting to a device to run commands or collect files for investigation"], "eEn": "Live response lets security personnel remotely connect to a compromised device to run commands, collect files, and perform other real-time investigation and remediation actions."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「デバイスに対するMicrosoftセキュアスコア」の目的はどれですか。", "o": ["デバイスの製造年月日を記録すること　　　　　　　　　　　　　　　　", "デバイスの保証期間を延長すること", "組織のデバイスのセキュリティ構成状態を評価し改善提案を提示すること", "デバイスの購入コストを計算すること"], "a": 2, "e": "デバイスに対するセキュアスコアは、組織のデバイス全体のセキュリティ構成の状態を評価し、リスクを軽減するための改善提案を提供します。", "qEn": "What is the purpose of Microsoft Secure Score for Devices in Microsoft Defender for Endpoint?", "oEn": ["Recording a device's manufacturing date", "Extending a device's warranty period", "Assessing the security configuration state of an organization's devices and suggesting improvements", "Calculating device purchase costs"], "eEn": "Secure Score for Devices evaluates the security configuration state across an organization's devices and offers recommendations to reduce risk."}, {"d": "D3", "q": "Microsoft Defender for Endpointにおけるデバイスの「オンボーディング」とは何を意味しますか。", "o": ["デバイスをMicrosoft Defender for Endpointによる監視・保護対象として登録すること", "使用済みのデバイスを廃棄処分の対象として正式に登録する手続き", "セキュリティ運用の現場では、デバイスメーカーが提供する保証期間を更新するための手続き", "実際の運用環境や組織のポリシーによっては、新入社員に対して社内システムの利用アカウントを新規に発行する手続き　"], "a": 0, "e": "オンボーディングは、デバイスにセンサーを構成し、Microsoft Defender for Endpointによる監視・保護の対象として組み込むプロセスを指します。", "qEn": "What does device \"onboarding\" mean in Microsoft Defender for Endpoint?", "oEn": ["Registering a device to be monitored and protected by Microsoft Defender for Endpoint", "The procedure for formally registering a used device for disposal", "In real-world security operations, The procedure for renewing the warranty period provided by the device manufacturer", "Depending on the actual operating environment or organizational policy, The procedure for issuing a new internal system account to a new employee"], "eEn": "Onboarding refers to configuring the sensor on a device and bringing it under monitoring and protection by Microsoft Defender for Endpoint."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「デバイスインベントリ」機能で確認できる情報はどれですか。", "o": ["仮想マシンの月額課金額　　　　　　　　　　　　　　　　", "会議室の予約状況", "従業員の給与明細", "組織内のオンボード済みデバイスの一覧とそのリスクレベル"], "a": 3, "e": "デバイスインベントリは、組織内でオンボードされたデバイスの一覧、リスクレベル、脆弱性情報などを確認できる機能です。", "qEn": "What information can be viewed in the Device Inventory feature of Microsoft Defender for Endpoint?", "oEn": ["Monthly billing amounts for virtual machines", "Meeting room reservation status", "Employee pay stubs", "A list of onboarded devices in the organization along with their risk levels"], "eEn": "Device Inventory shows a list of devices onboarded within the organization, including their risk levels and vulnerability information."}, {"d": "D3", "q": "Microsoft Defender for Endpointにおける「デバイスの分離（Isolate device）」アクションの目的はどれですか。", "o": ["侵害された疑いのあるデバイスをネットワークから切り離し被害拡大を防ぐこと", "デバイスの保証を無効化すること", "実務上のベストプラクティスとしては、デバイスの物理的な電源を完全にオフにすること", "デバイスのライセンスを削除すること"], "a": 0, "e": "デバイスの分離アクションは、侵害が疑われるデバイスをネットワークから隔離し、他のリソースへの攻撃の拡散を防ぎながら管理者による接続は維持します。", "qEn": "What is the purpose of the \"Isolate device\" action in Microsoft Defender for Endpoint?", "oEn": ["Disconnecting a device suspected of compromise from the network to prevent further spread", "Invalidating a device's warranty", "As a matter of practical best practice, Completely turning off a device's physical power", "Removing a device's license"], "eEn": "The Isolate device action disconnects a device suspected of compromise from the network to prevent the spread of an attack to other resources, while still allowing administrator connectivity."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「カスタム検出ルール」を作成する際に一般的に使用されるクエリ言語はどれですか。", "o": ["HTMLとCSS", "実務上のベストプラクティスとしては、バッチファイルのコマンド構文", "XMLスキーマ言語のみ", "KQL（Kusto Query Language）"], "a": 3, "e": "カスタム検出ルールは、高度なハンティングと同様にKQL（Kusto Query Language）を使用して条件を定義し、該当する場合にアラートを生成します。", "qEn": "Which query language is typically used when creating a custom detection rule in Microsoft Defender for Endpoint?", "oEn": ["HTML and CSS", "As a matter of practical best practice, Batch file command syntax", "XML schema language only", "KQL (Kusto Query Language)"], "eEn": "Custom detection rules, like advanced hunting, use KQL (Kusto Query Language) to define conditions and generate alerts when they are met."}, {"d": "D3", "q": "Microsoft Defender for Endpointの脅威と脆弱性の管理における「セキュリティに関する推奨事項」の目的はどれですか。", "o": ["組織のリスクを低減するための具体的な修復アクションを優先順位付けして提示すること", "会議室の空き状況を従業員に自動的に推奨すること", "仮想マシンのコスト削減案のみを毎月提示すること", "多くの組織のセキュリティ運用の現場では、従業員の勤怠評価を毎月まとめて自動的に実施すること"], "a": 0, "e": "セキュリティに関する推奨事項は、検出された脆弱性や設定不備に基づき、リスク軽減のために優先的に対応すべき修復アクションを提示します。", "qEn": "What is the purpose of Security recommendations in Microsoft Defender for Endpoint's threat and vulnerability management?", "oEn": ["Presenting prioritized, concrete remediation actions to reduce organizational risk", "Automatically recommending meeting room availability to employees", "Presenting only virtual-machine cost-reduction ideas every month", "In the security operations of many organizations, Automatically compiling and conducting employee attendance evaluations every month"], "eEn": "Security recommendations, based on detected vulnerabilities and misconfigurations, present prioritized remediation actions that should be addressed to reduce risk."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「脅威エキスパート（Microsoft Threat Experts）」サービスの目的はどれですか。", "o": ["実際の運用環境や組織のポリシーによっては、従業員の勤怠を専門家が代行入力すること", "専門アナリストによる的を絞った攻撃通知や専門家への問い合わせ支援を提供すること", "会議室予約を専門スタッフが代行すること", "給与計算を専門家が代行すること"], "a": 1, "e": "Microsoft Threat Expertsは、Microsoftのセキュリティ専門家による標的型攻撃の通知や、組織のセキュリティチームが専門家に直接問い合わせできるサービスを提供します。", "qEn": "What is the purpose of the Microsoft Threat Experts service in Microsoft Defender for Endpoint?", "oEn": ["Depending on the actual operating environment or organizational policy, Having experts enter employee attendance on their behalf", "Providing targeted attack notifications and expert consultation support from specialized analysts", "Having specialized staff handle meeting room reservations on the organization's behalf", "Having experts handle payroll calculations on the organization's behalf"], "eEn": "Microsoft Threat Experts provides targeted attack notifications from Microsoft security experts and lets an organization's security team consult directly with experts."}, {"d": "D3", "q": "Microsoft Defender for Endpointにおける「ファイルの隔離（Quarantine file）」アクションの目的はどれですか。", "o": ["実務上のベストプラクティスとしては、ファイルを自動的にクラウドへバックアップすること", "ファイルの所有者情報を書き換えること", "悪意があると判定されたファイルを実行不可能な状態でデバイスから隔離すること", "ファイルの拡張子を自動変更すること"], "a": 2, "e": "ファイルの隔離は、悪意があると判定されたファイルを実行できない状態で隔離場所に移動させ、被害の拡大を防ぐ対応アクションです。", "qEn": "What is the purpose of the \"Quarantine file\" action in Microsoft Defender for Endpoint?", "oEn": ["As a matter of practical best practice, Automatically backing up files to the cloud", "Rewriting a file's owner information", "Isolating a file judged malicious from the device in a non-executable state", "Automatically changing a file's extension"], "eEn": "Quarantining a file moves a file judged malicious to an isolated location in a non-executable state, preventing further damage."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「デバイスグループ」を作成する主な目的はどれですか。", "o": ["組織構造に基づきデバイスを分類しロールベースアクセス制御（RBAC）を適用しやすくすること", "購入したすべてのデバイスの保証期間を一律に延長する手続き", "実務上のベストプラクティスとしては、組織内の全デバイスの電源オン・オフのスケジュールを一括設定すること", "オフィス内にあるデバイスの物理的な設置場所を移動すること"], "a": 0, "e": "デバイスグループは、部門や役割に応じてデバイスを分類し、それぞれのグループに異なるロールベースアクセス制御（RBAC）や自動化レベルを適用するために使用されます。", "qEn": "What is the main purpose of creating device groups in Microsoft Defender for Endpoint?", "oEn": ["Categorizing devices based on organizational structure to more easily apply role-based access control (RBAC)", "The procedure for uniformly extending the warranty period of all purchased devices", "As a matter of practical best practice, Bulk-configuring the power on/off schedule for all devices in the organization", "Moving the physical installation location of devices within the office"], "eEn": "Device groups categorize devices by department or role, enabling different levels of role-based access control (RBAC) and automation to be applied to each group."}, {"d": "D3", "q": "Microsoft Defender for Endpointの「自動化レベル」設定が制御するものはどれですか。", "o": ["自動調査と修復がどの程度自動的にアクションを実行するかの範囲", "多くの組織のセキュリティ運用の現場では、デバイスのディスプレイ輝度", "デバイスの保証期間", "デバイスの通信速度"], "a": 0, "e": "自動化レベルの設定により、自動調査と修復機能が修復アクションを完全に自動で実行するか、承認を必要とするかなどの範囲を制御できます。", "qEn": "What does the \"automation level\" setting control in Microsoft Defender for Endpoint?", "oEn": ["The extent to which automated investigation and remediation executes actions automatically", "In the security operations of many organizations, A device's display brightness", "A device's warranty period", "A device's communication speed"], "eEn": "The automation level setting controls the extent to which automated investigation and remediation executes remediation actions fully automatically versus requiring approval."}, {"d": "D3", "q": "Microsoft Defender for Cloud Appsは主にどのカテゴリのソリューションに分類されるか。", "o": ["CASB(クラウドアクセスセキュリティブローカー)", "SIEMのログ集約プラットフォーム", "EDRのエンドポイント検知製品", "境界防御型のネットワークファイアウォール　　　　　"], "a": 0, "e": "Defender for Cloud AppsはCASB(Cloud Access Security Broker)であり、クラウドアプリの可視化、データ保護、脅威検出を提供する。", "qEn": "Which category does Microsoft Defender for Cloud Apps primarily belong to?", "oEn": ["A CASB (Cloud Access Security Broker)", "A SIEM log-aggregation platform", "An EDR endpoint-detection product", "A perimeter-based network firewall"], "eEn": "Defender for Cloud Apps is a CASB (Cloud Access Security Broker) that provides visibility, data protection, and threat detection for cloud apps."}, {"d": "D3", "q": "Defender for Cloud AppsのクラウドDiscovery(検出)機能は何を実現するか。", "o": ["組織全体のメール通信を自動的に暗号化する", "ログを解析しシャドーITのクラウドアプリ利用状況を可視化する", "登録済みデバイスへセキュリティパッチを配布する　　　　　　　", "社内ネットワークの帯域幅利用を制御する"], "a": 1, "e": "Cloud Discoveryはネットワークやプロキシのログを解析し、組織内で利用されているクラウドアプリ(シャドーITを含む)を可視化する。", "qEn": "What does Cloud Discovery in Defender for Cloud Apps accomplish?", "oEn": ["Automatically encrypting all organizational email traffic", "Analyzing logs to reveal shadow IT cloud app usage", "Deploying security patches to registered devices", "Controlling bandwidth usage on the internal network"], "eEn": "Cloud Discovery analyzes network or proxy logs to surface the cloud apps in use across the organization, including shadow IT."}, {"d": "D3", "q": "Defender for Cloud AppsのConditional Access App Controlは主に何と連携して機能するか。", "o": ["Microsoft Defender for Endpoint単体の検知エンジン", "オンプレミスに設置されたファイアウォール機器", "Microsoft Entra IDの条件付きアクセス機能", "組織内で運用されているDNSサーバー"], "a": 2, "e": "Conditional Access App ControlはMicrosoft Entra IDの条件付きアクセスと連携し、リアルタイムのセッション制御を実現する。", "qEn": "What does Conditional Access App Control in Defender for Cloud Apps primarily work with?", "oEn": ["The standalone detection engine of Defender for Endpoint", "An on-premises firewall appliance", "Microsoft Entra ID Conditional Access", "A DNS server operated within the organization"], "eEn": "Conditional Access App Control integrates with Microsoft Entra ID Conditional Access to enable real-time session controls."}, {"d": "D3", "q": "Defender for Cloud Appsのセッションポリシーで実現できることは何か。", "o": ["社内デバイスのファームウェアを一括更新する　　　　　　　　　　　　　　", "データセンター内サーバーの温度を監視する", "メールサーバーのストレージ容量を拡張する", "ファイルのダウンロード時にコンテンツを検査しリアルタイムでブロックする"], "a": 3, "e": "セッションポリシーはリアルタイムのセッション監視・制御を行い、機密データのダウンロード時に検査やブロックを実行できる。", "qEn": "What can session policies in Defender for Cloud Apps achieve?", "oEn": ["Bulk-updating firmware across internal devices", "Monitoring the temperature of data center servers", "Expanding storage capacity on the mail server", "Inspecting content and blocking downloads in real time"], "eEn": "Session policies provide real-time monitoring and control, inspecting or blocking downloads of sensitive content as they happen."}, {"d": "D3", "q": "Defender for Cloud AppsのOAuthアプリガバナンス機能の目的は何か。", "o": ["サードパーティアプリの権限やアクセス範囲を評価し不審なアプリを検出する", "拠点間を結ぶVPN接続を新規に確立する", "社内ハードウェア資産の在庫台帳を管理する", "業務データベースの定期バックアップを取得する　　　　　　　　　　　　　"], "a": 0, "e": "OAuthアプリガバナンスは、テナントに接続されたサードパーティアプリの権限を評価し、リスクの高いアプリを特定・対処する。", "qEn": "What is the purpose of OAuth app governance in Defender for Cloud Apps?", "oEn": ["Assessing third-party app permissions and scope to detect risky apps", "Establishing a new VPN connection between office sites", "Managing an inventory ledger of internal hardware assets", "Performing scheduled backups of business databases"], "eEn": "OAuth app governance evaluates the permissions of third-party apps connected to the tenant and helps identify and remediate risky apps."}, {"d": "D3", "q": "Defender for Cloud AppsのApp risk assessment(アプリリスク評価)で評価される観点は何か。", "o": ["社内会議室の予約状況や利用率の傾向　　　　　　　　　", "セキュリティ、コンプライアンス、法的リスクなどの観点", "従業員ごとの勤怠時間や休暇取得状況", "部門ごとの月間印刷枚数の推移"], "a": 1, "e": "App risk assessmentはクラウドアプリをセキュリティ、コンプライアンス、法的リスクなど複数の観点でスコアリングする。", "qEn": "What aspects does Defender for Cloud Apps' app risk assessment evaluate?", "oEn": ["Meeting room reservation trends and utilization rates", "Security, compliance, and legal risk factors", "Employee-by-employee attendance hours and leave usage", "Monthly print volume trends by department"], "eEn": "App risk assessment scores cloud apps across multiple dimensions such as security, compliance, and legal risk."}, {"d": "D3", "q": "Defender for Cloud Appsのアクティビティポリシーの主な用途は何か。", "o": ["部門間でのネットワーク帯域幅の割り当て変更", "データセンターサーバーの電源スケジュール管理　　　　　　　　　　　　", "ユーザーの異常な操作(大量ダウンロードなど)を検出してアラートを出す", "有効期限が近いライセンスの自動更新処理"], "a": 2, "e": "アクティビティポリシーはユーザーの操作ログを監視し、大量ダウンロードなど異常な振る舞いを検出してアラートを生成する。", "qEn": "What is the main use of activity policies in Defender for Cloud Apps?", "oEn": ["Reallocating network bandwidth between departments", "Managing the power schedule of data center servers", "Detecting anomalous user actions such as mass downloads and alerting", "Automatically renewing licenses nearing expiration"], "eEn": "Activity policies monitor user activity logs and generate alerts when anomalous behavior, such as mass downloads, is detected."}, {"d": "D3", "q": "Defender for Cloud Appsのファイルポリシーで実施できる制御はどれか。", "o": ["各端末のOSアップデートスケジュールの設定変更　　　　　　　　", "社内ネットワークのルーティング経路の変更", "部門ごとの印刷ジョブの割り当て管理", "共有設定に基づいて機密ファイルを検出し保護アクションを適用する"], "a": 3, "e": "ファイルポリシーは共有範囲や機密ラベルなどの条件に基づいてファイルを検出し、暗号化や共有解除などの保護アクションを適用できる。", "qEn": "Which control can be implemented with file policies in Defender for Cloud Apps?", "oEn": ["Changing the OS update schedule configuration on each device", "Changing internal network routing paths", "Managing print job allocation by department", "Detecting sensitive files by sharing settings and applying protective actions"], "eEn": "File policies detect files based on conditions like sharing scope or sensitivity labels, and can apply protective actions such as encryption or removing sharing."}, {"d": "D3", "q": "Defender for Cloud Appsの異常検出ポリシーの例として正しいものはどれか。", "o": ["短時間に離れた地域からログインする「不可能な移動」の検出", "サーバーのCPU使用率が高止まりする状態の監視", "ストレージのディスク空き容量が逼迫する状況の監視　　　　", "プリンターの印刷キューに滞留するジョブの監視"], "a": 0, "e": "異常検出ポリシーには、短時間に地理的に離れた場所からログインが行われる「不可能な移動」の検出などが含まれる。", "qEn": "Which is an example of an anomaly detection policy in Defender for Cloud Apps?", "oEn": ["Detecting impossible travel, where logins occur from distant regions in a short time", "Monitoring servers whose CPU utilization stays persistently high", "Monitoring storage where free disk capacity is running low", "Monitoring print jobs backed up in a printer's queue"], "eEn": "Anomaly detection policies include detecting impossible travel, where logins occur from geographically distant locations within a short time."}, {"d": "D3", "q": "Defender for Cloud Appsにおけるサンクションアプリとアンサンクションアプリの違いは何か。", "o": ["アプリの月額利用料金や課金モデルの違い", "組織が承認して利用を許可しているか否かの分類", "アプリの開発に使われたプログラミング言語の違い", "アプリのライセンス契約が有効な期間の長さの違い"], "a": 1, "e": "サンクションアプリは組織が承認して利用を許可しているアプリを指し、アンサンクションアプリは承認されていないアプリを指す分類である。", "qEn": "What distinguishes sanctioned apps from unsanctioned apps in Defender for Cloud Apps?", "oEn": ["A difference in monthly pricing or billing model", "Classification based on whether the organization has approved usage", "A difference in the programming language used to build the app", "A difference in the duration of the app's license agreement"], "eEn": "Sanctioned apps are those the organization has approved for use, while unsanctioned apps have not been approved; this is the basis of the classification."}, {"d": "D3", "q": "Defender for Cloud AppsのAPI connectorsを使用する目的は何か。", "o": ["オフィス内の物理プリンターと直接連携する", "社内ネットワークスイッチの設定を変更する", "サンクションされたクラウドアプリに直接接続してデータを可視化・制御する", "従業員のローカルドライブを丸ごと暗号化する　　　　　　　　　　　　　　"], "a": 2, "e": "API connectorsはサンクションされたクラウドアプリのAPIに直接接続し、保存データの可視化やガバナンスコントロールの適用を可能にする。", "qEn": "What is the purpose of API connectors in Defender for Cloud Apps?", "oEn": ["Directly integrating with physical printers in the office", "Changing the configuration of internal network switches", "Connecting directly to sanctioned cloud apps to gain visibility and control over data", "Encrypting an employee's entire local drive"], "eEn": "API connectors connect directly to a sanctioned cloud app's API, enabling visibility into stored data and applying governance controls."}, {"d": "D3", "q": "Defender for Cloud Appsが監視できる対象として正しいものはどれか。", "o": ["オフィスへの物理的な入退室の記録　　　　　　　　　　", "社用車の走行距離や燃費のデータ", "会議室の室温や湿度の環境データ", "クラウドサービス間でのデータ移動やユーザーの操作行動"], "a": 3, "e": "Defender for Cloud Appsは複数のクラウドサービス間でのデータ移動やユーザーの操作行動を監視し、リスクを可視化する。", "qEn": "Which of the following can Defender for Cloud Apps monitor?", "oEn": ["Physical entry and exit records at the office", "Company vehicle mileage and fuel-efficiency data", "Meeting room temperature and humidity readings", "Data movement and user behavior across cloud services"], "eEn": "Defender for Cloud Apps monitors data movement and user behavior across multiple cloud services, providing visibility into risk."}, {"d": "D3", "q": "Microsoft Defender for Identityが監視する主なデータソースは何か。", "o": ["オンプレミスのActive Directoryドメインコントローラー", "契約中のクラウドストレージの使用容量", "モバイルデバイスのバッテリー残量の推移　　　　　　　　　　　　　　　", "会社支給プリンターの利用状況ログ"], "a": 0, "e": "Defender for Identityはオンプレミスのドメインコントローラー(およびAD FSなど)から信号を収集し、アイデンティティに対する脅威を検出する。", "qEn": "What is the primary data source that Microsoft Defender for Identity monitors?", "oEn": ["On-premises Active Directory domain controllers", "The used capacity of a contracted cloud storage service", "The battery-level trend of mobile devices", "Usage logs from company-issued printers"], "eEn": "Defender for Identity collects signals from on-premises domain controllers (and AD FS, etc.) to detect identity-based threats."}, {"d": "D3", "q": "Defender for Identityのセンサーが配置される場所として正しいのはどれか。", "o": ["クラウド上に設置されたゲートウェイのみ", "ドメインコントローラーやAD FSサーバー", "従業員が利用するモバイル端末", "ネットワークスイッチのファームウェア内部　"], "a": 1, "e": "Defender for Identityのセンサーはドメインコントローラーやフェデレーションサーバー(AD FS)などに直接インストールされトラフィックを監視する。", "qEn": "Where are Defender for Identity sensors deployed?", "oEn": ["Only on gateways set up in the cloud", "On domain controllers or AD FS servers", "On mobile devices used by employees", "Inside network switch firmware"], "eEn": "Defender for Identity sensors are installed directly on domain controllers or federation servers (AD FS) to monitor traffic."}, {"d": "D3", "q": "Defender for Identityが検出する攻撃フェーズに含まれるものはどれか。", "o": ["購入済みソフトウェアライセンスの期限切れ通知　　　　　　　　", "定期バックアップジョブの失敗イベント", "攻撃対象の環境を探る偵察活動(Reconnaissance)", "メールサーバーのストレージ容量不足の警告"], "a": 2, "e": "Defender for Identityは偵察、侵害された認証情報、横方向移動、ドメイン支配といった攻撃キルチェーンの各フェーズを検出する。", "qEn": "Which attack phase does Defender for Identity detect?", "oEn": ["Notification of an expiring purchased software license", "A failure event in a scheduled backup job", "Reconnaissance activity probing the target environment", "A warning about mail server storage capacity shortage"], "eEn": "Defender for Identity detects phases of the attack kill chain such as reconnaissance, compromised credentials, lateral movement, and domain dominance."}, {"d": "D3", "q": "Defender for IdentityのLateral Movement Paths(横方向移動パス)機能の目的は何か。", "o": ["部門間のネットワーク帯域幅利用を最適化する", "不要なクラウドリソースを削減しコストを下げる　　　　　　　　　　　　　　　　", "ユーザーへのライセンス割り当てを自動で行う", "侵害された可能性のあるアカウントが機密アカウントに到達しうる経路を可視化する"], "a": 3, "e": "Lateral Movement Pathsは、攻撃者が侵害したアカウントを起点に機密アカウントへ到達しうる経路を可視化し、事前対策を支援する。", "qEn": "What is the purpose of Lateral Movement Paths in Defender for Identity?", "oEn": ["Optimizing network bandwidth usage between departments", "Reducing unnecessary cloud resources to lower costs", "Automatically assigning licenses to users", "Visualizing paths a compromised account could take to reach sensitive accounts"], "eEn": "Lateral Movement Paths visualize the routes an attacker could use from a compromised account to reach sensitive accounts, supporting proactive defense."}, {"d": "D3", "q": "Defender for Identityが検出するドメイン支配(Domain Dominance)の兆候として正しいものはどれか。", "o": ["DCShadowやゴールデンチケット攻撃などの手法の使用", "定期的に実施される通常のパスワード変更", "スケジュール通りに行われるソフトウェア更新　　　　　　　", "標準的な権限に基づくファイル共有アクセス"], "a": 0, "e": "ドメイン支配フェーズでは、DCShadowやゴールデンチケット攻撃のような、永続的な支配権を確立する手法が検出対象となる。", "qEn": "Which is a sign of Domain Dominance detected by Defender for Identity?", "oEn": ["Use of techniques like DCShadow or Golden Ticket attacks", "A routine password change performed on a regular schedule", "Scheduled software updates being applied as planned", "Standard file share access based on normal permissions"], "eEn": "In the domain dominance phase, techniques such as DCShadow or Golden Ticket attacks, which establish persistent control, are detection targets."}, {"d": "D3", "q": "Defender for Identityのアラートはどこに統合されて表示されるか。", "o": ["Defender for Identity専用の独立したコンソールのみ", "Microsoft Defenderポータル(統合SOC体験)", "オンプレミスのイベントビューアーのみ", "組織が別途契約するサードパーティのSIEMのみ"], "a": 1, "e": "Defender for IdentityのアラートはMicrosoft Defenderポータルに統合され、他のDefender製品のアラートと合わせて調査できる。", "qEn": "Where are Defender for Identity alerts integrated and displayed?", "oEn": ["Only in a separate, dedicated Defender for Identity console", "In the Microsoft Defender portal (unified SOC experience)", "Only in the on-premises Event Viewer", "Only in a third-party SIEM the organization contracts separately"], "eEn": "Defender for Identity alerts are integrated into the Microsoft Defender portal, allowing investigation alongside alerts from other Defender products."}, {"d": "D3", "q": "Defender for Identityが検出できる不審なアクティビティの例として正しいものはどれか。", "o": ["スケジュール通りに実行される定期的なOSアップデート", "正規の認証情報を使った正常なログオン試行", "総当たり攻撃(ブルートフォース)によるログイン試行", "権限内で行われる標準的なファイルの読み取り"], "a": 2, "e": "Defender for Identityは総当たり攻撃によるログイン試行など、認証情報を狙った不審な活動を検出する。", "qEn": "Which is an example of suspicious activity detected by Defender for Identity?", "oEn": ["Regular OS updates applied on schedule", "A normal logon attempt using legitimate credentials", "Brute-force login attempts", "A standard file read performed within normal permissions"], "eEn": "Defender for Identity detects suspicious activity targeting credentials, such as brute-force login attempts."}, {"d": "D3", "q": "Defender for Identityの正常性(Health)機能の役割は何か。", "o": ["各拠点間のネットワーク帯域幅を測定する", "製品導入にかかるライセンスコストを計算する　　　　　　", "従業員の製品満足度アンケートを実施する", "センサーの構成上の問題やセキュリティ推奨事項を通知する"], "a": 3, "e": "正常性機能はセンサーの構成状態を監視し、問題や推奨されるセキュリティ設定変更を管理者に通知する。", "qEn": "What is the role of the Health feature in Defender for Identity?", "oEn": ["Measuring network bandwidth between office locations", "Calculating the license cost of a product deployment", "Conducting an employee product-satisfaction survey", "Notifying administrators of sensor configuration issues and security recommendations"], "eEn": "The Health feature monitors sensor configuration status and notifies administrators of issues or recommended security setting changes."}, {"d": "D3", "q": "Defender for Identityが利用する技術的アプローチとして正しいものはどれか。", "o": ["機械学習による行動分析とシグネチャベースの検出の組み合わせ", "すべてのログを人手でレビューする手作業のみの運用　　　　　", "オフィス各所に設置した物理的な監視カメラ", "紙に記録して保管する従来型の監査記録"], "a": 0, "e": "Defender for Identityは機械学習による行動分析とシグネチャベースの検出手法を組み合わせて脅威を識別する。", "qEn": "Which technical approach does Defender for Identity use?", "oEn": ["A combination of machine-learning behavioral analytics and signature-based detection", "Manual review of all logs by staff, with no automation", "Physical security cameras installed throughout the office", "Traditional paper-based audit records kept in storage"], "eEn": "Defender for Identity combines machine-learning behavioral analytics with signature-based detection to identify threats."}, {"d": "D3", "q": "Defender for Identityで検出可能な「Pass-the-Ticket」攻撃とは何か。", "o": ["正規に承認されたソフトウェアライセンスの移行手続き　　　　　　　　　　　　　　", "盗まれたKerberosチケットを再利用して他のリソースへ不正アクセスする手法", "定期的に案内される標準のパスワードリセット手順", "業務データを転送する際の通常のファイル転送手順"], "a": 1, "e": "Pass-the-Ticket攻撃は、盗み出したKerberosチケットを再利用して正規ユーザーになりすまし別のリソースへアクセスする手法である。", "qEn": "What is the \"Pass-the-Ticket\" attack that Defender for Identity can detect?", "oEn": ["A formally approved software license migration procedure", "A technique that reuses a stolen Kerberos ticket to gain unauthorized access to other resources", "The standard password reset procedure announced periodically", "The normal file transfer procedure used to move business data"], "eEn": "A Pass-the-Ticket attack reuses a stolen Kerberos ticket to impersonate a legitimate user and access other resources."}, {"d": "D3", "q": "Defender for Identityの導入に必要な前提条件の1つとして正しいものはどれか。", "o": ["全クライアント端末へのアンチウイルス製品の導入　　　　　　　　　", "全社規模で締結するVPNサービス契約", "オンプレミスのActive Directoryフォレストとの統合", "自社専用の物理データセンターの保有"], "a": 2, "e": "Defender for IdentityはオンプレミスのActive Directoryフォレストと統合して動作するため、ADドメインの存在が前提条件となる。", "qEn": "Which is a prerequisite for deploying Defender for Identity?", "oEn": ["Installing an antivirus product on every client device", "A company-wide VPN service contract", "Integration with an on-premises Active Directory forest", "Owning a dedicated physical data center"], "eEn": "Defender for Identity operates by integrating with an on-premises Active Directory forest, so an AD domain is a prerequisite."}, {"d": "D3", "q": "Defender for Identityが提供する「機密アカウント」の概念として正しいものはどれか。", "o": ["組織内で最も多くファイルを共有しているアカウント　　　　　　", "比較的最近作成された新しいアカウント", "権限が限定的なゲストアカウント全般", "侵害された場合に重大な影響を及ぼす可能性がある特権アカウント"], "a": 3, "e": "機密アカウントとは、ドメイン管理者などのように侵害された際に組織へ重大な影響を及ぼす可能性のある特権アカウントを指す。", "qEn": "What is the concept of a \"sensitive account\" in Defender for Identity?", "oEn": ["The account within the organization that shares the most files", "An account that was created relatively recently", "Guest accounts in general, which have limited permissions", "A privileged account that could cause significant impact if compromised"], "eEn": "A sensitive account refers to a privileged account, such as a domain admin, that could cause significant organizational impact if compromised."}, {"d": "D3", "q": "Microsoft Defender脆弱性管理の主な目的は何か。", "o": ["資産の脆弱性や誤設定を発見し優先順位付けして修復を支援する", "部門をまたぐ給与計算の処理を自動化する　　　　　　　　　　", "社内会議の日程調整を効率化する", "組織全体のメール配信ルートを最適化する"], "a": 0, "e": "Defender脆弱性管理は組織内の資産に存在する脆弱性や誤設定を継続的に発見し、リスクに基づいて優先順位付けを行い修復を支援する。", "qEn": "What is the main purpose of Microsoft Defender Vulnerability Management?", "oEn": ["Discovering vulnerabilities and misconfigurations in assets and prioritizing remediation", "Automating cross-department payroll processing", "Streamlining internal meeting scheduling", "Optimizing the organization's overall email delivery routes"], "eEn": "Defender Vulnerability Management continuously discovers vulnerabilities and misconfigurations in organizational assets, prioritizes them by risk, and supports remediation."}, {"d": "D3", "q": "Defender脆弱性管理が提供するリスクベースの優先順位付けの根拠として正しいものはどれか。", "o": ["資産名のアルファベット順に基づく単純な並べ替え　　　", "悪用可能性やビジネスへの影響度などのコンテキスト情報", "製品を導入した日時のみに基づく判断", "デバイス名の文字数の長さのみに基づく判断"], "a": 1, "e": "リスクベースの優先順位付けは、脆弱性の悪用可能性や資産のビジネス上の重要度などのコンテキスト情報を考慮して行われる。", "qEn": "What is the basis for risk-based prioritization in Defender Vulnerability Management?", "oEn": ["A simple sort based on the alphabetical order of asset names", "Contextual information such as exploitability and business impact", "A judgment based only on the product's deployment date", "A judgment based only on the length of the device name"], "eEn": "Risk-based prioritization considers contextual information such as the likelihood of exploitation and the business importance of the asset."}, {"d": "D3", "q": "Defender脆弱性管理のセキュリティベースライン評価機能の役割は何か。", "o": ["契約中のクラウドストレージの料金を削減する　　　　　　　　　　　　　", "会議室予約システムの利用状況を管理する", "デバイスが業界標準の構成ベンチマークに準拠しているか継続的に評価する", "部門ごとの印刷コストを集計して管理する"], "a": 2, "e": "セキュリティベースライン評価は、CISベンチマークなどの業界標準の構成ベンチマークに対するデバイスの準拠状況を継続的に評価する。", "qEn": "What is the role of the security baselines assessment feature in Defender Vulnerability Management?", "oEn": ["Reducing the cost of a contracted cloud storage service", "Managing usage of a meeting room reservation system", "Continuously assessing device compliance against industry configuration benchmarks", "Tallying and managing printing costs by department"], "eEn": "Security baselines assessment continuously evaluates device compliance against industry-standard configuration benchmarks such as CIS benchmarks."}, {"d": "D3", "q": "Defender脆弱性管理が評価できるブラウザ拡張機能の観点として正しいものはどれか。", "o": ["ストアでのインストール数のランキング順位のみ　", "拡張機能を開発した企業の所在国籍", "拡張機能アイコンのデザインや色使い", "拡張機能に付与されている権限とそれに伴うリスク"], "a": 3, "e": "ブラウザ拡張機能の評価では、拡張機能がどのような権限を持ちどのようなリスクをもたらすかを可視化する。", "qEn": "Which aspect of browser extensions can Defender Vulnerability Management assess?", "oEn": ["Only the store ranking based on installation counts", "The country where the extension's developer is based", "The design or color scheme of the extension's icon", "The permissions granted to the extension and the associated risk"], "eEn": "Browser extension assessment reveals what permissions an extension holds and the risk those permissions pose."}, {"d": "D3", "q": "Defender脆弱性管理のデジタル証明書評価機能の目的は何か。", "o": ["期限切れや脆弱な証明書を可視化しリスクを低減する", "証明書に表示されるデザインテンプレートを変更する", "組織全体のメール署名フォントを統一する", "VPN接続の通信速度を向上させる"], "a": 0, "e": "デジタル証明書評価は、期限切れや脆弱なアルゴリズムを使用する証明書を可視化し、関連するセキュリティリスクの低減を支援する。", "qEn": "What is the purpose of digital certificate assessment in Defender Vulnerability Management?", "oEn": ["Surfacing expired or weak certificates to reduce risk", "Changing the design template displayed on a certificate", "Standardizing the email signature font across the organization", "Improving the communication speed of a VPN connection"], "eEn": "Digital certificate assessment surfaces expired certificates or those using weak algorithms, helping reduce the associated security risk."}, {"d": "D3", "q": "Defender脆弱性管理が提供する資産インベントリで確認できる情報として正しいものはどれか。", "o": ["従業員一人ひとりの勤怠履歴の詳細　　", "デバイス、ソフトウェア、脆弱性の一覧", "社内会議室の予約状況の一覧", "経費精算申請の承認履歴の記録"], "a": 1, "e": "資産インベントリでは組織内のデバイス、インストール済みソフトウェア、検出された脆弱性の一覧を一元的に確認できる。", "qEn": "What information can be viewed in the asset inventory provided by Defender Vulnerability Management?", "oEn": ["Detailed attendance history for each individual employee", "A list of devices, software, and vulnerabilities", "A list of internal meeting room reservation statuses", "Records of expense reimbursement approval history"], "eEn": "The asset inventory provides a centralized list of devices, installed software, and detected vulnerabilities across the organization."}, {"d": "D3", "q": "Defender脆弱性管理のネットワーク共有分析機能が検出するものは何か。", "o": ["社内ネットワークの物理的な配線図", "オフィス各所のWi-Fi電波強度の測定値", "誤って設定された安全でないネットワーク共有", "ネットワークスイッチのファームウェアバージョン"], "a": 2, "e": "ネットワーク共有分析は、誤って設定され安全でないネットワーク共有を検出し、データ漏えいリスクの低減を支援する。", "qEn": "What does the network share analysis feature in Defender Vulnerability Management detect?", "oEn": ["Physical wiring diagrams of the internal network", "Measured Wi-Fi signal strength throughout the office", "Misconfigured, insecure network shares", "The firmware version running on network switches"], "eEn": "Network share analysis detects misconfigured, insecure network shares, helping reduce the risk of data leakage."}, {"d": "D3", "q": "Defender脆弱性管理が対応するプラットフォームの範囲として正しいものはどれか。", "o": ["特定の単一OSベンダーが提供する製品のみ　　　　　　　　　　　　　　　", "パブリッククラウドで稼働するサービスのみ", "スマートフォン上のモバイルアプリのみ", "Windows、macOS、Linuxなど複数のOSにまたがるデバイス"], "a": 3, "e": "Defender脆弱性管理はWindows、macOS、Linux、iOS、Androidなど複数のプラットフォームにまたがるデバイスに対応する。", "qEn": "What is the range of platforms supported by Defender Vulnerability Management?", "oEn": ["Only products from one specific single OS vendor", "Only services running in the public cloud", "Only mobile apps running on smartphones", "Devices spanning multiple OSes such as Windows, macOS, and Linux"], "eEn": "Defender Vulnerability Management supports devices across multiple platforms, including Windows, macOS, Linux, iOS, and Android."}, {"d": "D3", "q": "Defender脆弱性管理の脅威分析との連携メリットは何か。", "o": ["実際に悪用されている脆弱性を優先的に修復対象として特定できる", "社内メールの配信速度が全体的に向上する", "部門ごとの印刷コストが自動的に削減される　　　　　　　　　　", "定例会議の進行効率が向上する"], "a": 0, "e": "脅威分析との連携により、実際の攻撃キャンペーンで悪用されている脆弱性を特定し、優先的に修復対象とすることができる。", "qEn": "What is the benefit of integrating Defender Vulnerability Management with threat analytics?", "oEn": ["Identifying vulnerabilities actively exploited in the wild as remediation priorities", "Overall improvement in internal email delivery speed", "Automatic reduction in printing costs by department", "Improved efficiency in running regular meetings"], "eEn": "Integration with threat analytics helps identify vulnerabilities actively exploited in real attack campaigns and prioritize them for remediation."}, {"d": "D3", "q": "Defender脆弱性管理のソフトウェアインベントリで把握できるものは何か。", "o": ["従業員個人の給与に関する明細情報　　　　　　　　　　　　　", "組織内にインストールされているソフトウェアとそのバージョン", "社内会議室の直近の予約履歴", "経費申請の承認フローに関する記録"], "a": 1, "e": "ソフトウェアインベントリは組織内にインストールされているソフトウェアとそのバージョン情報を一覧化する。", "qEn": "What can be identified through the software inventory in Defender Vulnerability Management?", "oEn": ["Individual employees' salary statement details", "Software installed across the organization and its version", "Recent reservation history for internal meeting rooms", "Records related to the expense request approval workflow"], "eEn": "The software inventory lists software installed across the organization along with its version information."}, {"d": "D3", "q": "Defender脆弱性管理が提供する修復要求の追跡機能の目的は何か。", "o": ["各部門の給与計算処理を自動化する", "会議参加者のスケジュールを自動調整する　　　　", "IT担当者への修復タスクの割り当てと進捗の追跡", "組織全体のメール配信を最適化する"], "a": 2, "e": "修復要求の追跡機能は、脆弱性への対応タスクをIT担当者に割り当て、その修復状況の進捗を追跡できるようにする。", "qEn": "What is the purpose of the remediation request tracking feature in Defender Vulnerability Management?", "oEn": ["Automating payroll processing for each department", "Automatically coordinating the schedules of meeting participants", "Assigning remediation tasks to IT staff and tracking progress", "Optimizing email delivery across the organization"], "eEn": "Remediation request tracking assigns vulnerability remediation tasks to IT staff and allows progress to be tracked."}, {"d": "D3", "q": "Defender脆弱性管理はどのライセンス形態で利用可能か。", "o": ["常にすべての機能が無償で提供される", "オンプレミス環境でのみ提供される仕組み　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　", "他社ベンダーの製品としてのみ提供される", "Defender for Endpointに含まれる機能やスタンドアロンのアドオンとして提供される"], "a": 3, "e": "Defender脆弱性管理はDefender for Endpointの一部機能として、あるいはスタンドアロンのアドオンとして提供される。", "qEn": "In what licensing forms is Defender Vulnerability Management available?", "oEn": ["Always free with all features included", "A mechanism offered only in on-premises environments", "Only offered as a product from a different vendor", "As a capability within Defender for Endpoint or as a standalone add-on"], "eEn": "Defender Vulnerability Management is available as part of Defender for Endpoint or as a standalone add-on license."}, {"d": "D3", "q": "Microsoft Defender Threat Intelligence(Defender TI)の主な目的は何か。", "o": ["脅威インテリジェンスを収集・強化し脅威の調査や属性特定を支援する", "部門をまたぐ給与計算システムを統合する　　　　　　　　　　　　　", "社内会議室の予約プロセスを効率化する", "組織全体の印刷コストを削減する"], "a": 0, "e": "Defender TIは脅威インテリジェンスデータを収集・エンリッチし、脅威の調査や攻撃者の属性特定(アトリビューション)を支援する。", "qEn": "What is the main purpose of Microsoft Defender Threat Intelligence (Defender TI)?", "oEn": ["Aggregating and enriching threat intelligence to support threat investigation and attribution", "Integrating a cross-department payroll system", "Streamlining the internal meeting room booking process", "Reducing printing costs across the organization"], "eEn": "Defender TI aggregates and enriches threat intelligence data to support threat investigation and attacker attribution."}, {"d": "D3", "q": "Defender TIが提供するIOC(Indicator of Compromise)の例として正しいものはどれか。", "o": ["従業員一人ひとりの勤怠データの記録　　　　　　　　", "悪意のあるIPアドレスやドメイン、ファイルハッシュ", "会議室ごとの予約状況の一覧", "経費精算の申請書に記載された金額"], "a": 1, "e": "IOC(侵害指標)には、悪意のあるIPアドレス、ドメイン、ファイルハッシュなど攻撃活動を示す痕跡情報が含まれる。", "qEn": "Which is an example of an IOC (Indicator of Compromise) provided by Defender TI?", "oEn": ["Attendance data records for each individual employee", "Malicious IP addresses, domains, and file hashes", "A list of reservation status for each meeting room", "Amounts listed on expense reimbursement forms"], "eEn": "IOCs (Indicators of Compromise) include artifacts of attack activity such as malicious IP addresses, domains, and file hashes."}, {"d": "D3", "q": "Defender TIのプロファイル機能が提供する情報の対象として正しいものはどれか。", "o": ["社内の組織図や部署間の指揮系統", "定例会議の議題や開催スケジュール　　　", "脅威アクター、脆弱性、ツールセットなど", "従業員の給与体系や等級テーブル"], "a": 2, "e": "Defender TIのプロファイル機能は、脅威アクターや脆弱性、攻撃ツールセットなどに関する詳細な情報をまとめて提供する。", "qEn": "What subjects does the profiles feature in Defender TI provide information on?", "oEn": ["The internal organizational chart and reporting lines between departments", "The agenda and schedule of regular meetings", "Threat actors, vulnerabilities, and tool sets", "Employee salary structures and grade tables"], "eEn": "The profiles feature in Defender TI provides detailed, consolidated information on subjects such as threat actors, vulnerabilities, and attack tool sets."}, {"d": "D3", "q": "Defender TIが収集するパッシブDNSデータの用途は何か。", "o": ["社内プリンターの印刷ジョブを管理する", "会議室ごとの空き状況をリアルタイムで確認する　　　　　　　　　　　　　", "従業員の給与計算処理を自動化する", "ドメインとIPアドレスの履歴的な関連付けを分析し攻撃インフラを特定する"], "a": 3, "e": "パッシブDNSデータは、ドメインとIPアドレスの過去の関連付けを分析することで、攻撃者が使用するインフラの特定に役立つ。", "qEn": "What is the use of passive DNS data collected by Defender TI?", "oEn": ["Managing print jobs sent to internal printers", "Checking meeting room availability in real time", "Automating employee payroll processing", "Analyzing historical domain-to-IP address associations to identify attack infrastructure"], "eEn": "Passive DNS data helps identify attacker infrastructure by analyzing historical associations between domains and IP addresses."}, {"d": "D3", "q": "Defender TIのWHOIS情報分析機能の目的は何か。", "o": ["ドメイン登録者情報の履歴を調査し攻撃インフラの関連性を特定する", "会議室予約システムの操作画面を改善する　　　　　　　　　　　　", "従業員の給与計算処理を自動化する", "組織全体の印刷コストを削減する"], "a": 0, "e": "WHOIS情報分析は、ドメイン登録者情報の履歴を調査することで、複数の攻撃インフラ間の関連性を特定するのに役立つ。", "qEn": "What is the purpose of WHOIS information analysis in Defender TI?", "oEn": ["Investigating domain registrant history to identify links between attack infrastructures", "Improving the user interface of a meeting room booking system", "Automating employee payroll processing", "Reducing printing costs across the organization"], "eEn": "WHOIS information analysis investigates historical domain registrant data, helping identify links between multiple pieces of attack infrastructure."}, {"d": "D3", "q": "Defender TIが提供する記事(Articles)機能の役割は何か。", "o": ["社内定例会議の議事録を自動的に生成する　　　　　　　　　　　　　　　　　　　　　　", "新たな脅威や攻撃キャンペーンに関する分析情報をセキュリティ専門家がまとめて提供する", "従業員の月次給与明細を発行する", "プリンターごとの印刷履歴を記録する"], "a": 1, "e": "記事機能は、Microsoftのセキュリティ専門家が新たな脅威や攻撃キャンペーンについて分析した情報をまとめて提供するものである。", "qEn": "What is the role of the Articles feature in Defender TI?", "oEn": ["Automatically generating minutes for internal regular meetings", "Providing analysis on new threats and attack campaigns compiled by security experts", "Issuing employees' monthly payslips", "Recording print history for each printer"], "eEn": "The Articles feature provides analysis on new threats and attack campaigns, compiled by Microsoft's security experts."}, {"d": "D3", "q": "Defender TIを利用する主なユーザー層として正しいものはどれか。", "o": ["人事部門で採用業務を担当する担当者　　　　　　　　　", "経理部門で決算業務を担当する担当者", "セキュリティアナリストや脅威インテリジェンスの専門家", "オフィスの施設管理を担当する担当者"], "a": 2, "e": "Defender TIは主にセキュリティアナリストや脅威インテリジェンスの専門家が脅威の調査や対応判断に利用する。", "qEn": "Who is the primary user base for Defender TI?", "oEn": ["HR staff who handle recruitment duties", "Accounting staff who handle closing-period duties", "Security analysts and threat intelligence professionals", "Staff responsible for managing office facilities"], "eEn": "Defender TI is primarily used by security analysts and threat intelligence professionals for threat investigation and response decisions."}, {"d": "D3", "q": "Defender TIのインフラチェイニング(infrastructure chaining)機能の目的は何か。", "o": ["会議室の予約手続きを自動化する", "部門をまたぐ給与計算処理を効率化する", "プリンターの印刷ジョブの割り当てを管理する　　　　　　　　　　", "関連する攻撃インフラ同士のつながりを辿り攻撃者の全容を把握する"], "a": 3, "e": "インフラチェイニングは、ドメインやIPなどの攻撃インフラ間の関連性を辿ることで、攻撃者の全体像を把握する助けとなる。", "qEn": "What is the purpose of infrastructure chaining in Defender TI?", "oEn": ["Automating the meeting room reservation procedure", "Streamlining cross-department payroll processing", "Managing the allocation of print jobs on printers", "Tracing connections between related attack infrastructure to understand the full scope of an attacker"], "eEn": "Infrastructure chaining traces relationships between attack infrastructure elements such as domains and IPs, helping analysts understand the full scope of an attacker."}, {"d": "D3", "q": "Defender TIが提供する脆弱性情報プロファイルに含まれる内容として正しいものはどれか。", "o": ["CVEの詳細や悪用状況、関連する脅威アクターの情報", "従業員一人ひとりの勤怠に関する記録　　　　　　　　", "会議室ごとの利用予定の一覧", "経費精算の承認履歴に関する記録"], "a": 0, "e": "脆弱性プロファイルには、CVEの詳細情報、実際の悪用状況、関連する脅威アクターに関する情報が含まれる。", "qEn": "What is included in a vulnerability profile provided by Defender TI?", "oEn": ["CVE details, exploitation status, and related threat actor information", "Attendance-related records for each individual employee", "A list of usage schedules for each meeting room", "Records related to expense reimbursement approval history"], "eEn": "A vulnerability profile includes CVE details, real-world exploitation status, and information on related threat actors."}, {"d": "D3", "q": "Defender TIとMicrosoft Sentinelを連携させる利点は何か。", "o": ["会議室予約システムとの機能統合が実現する", "脅威インテリジェンスをSentinelの分析ルールやハンティングクエリに活用できる", "給与計算システムとの機能統合が実現する", "プリンター管理システムとの機能統合が実現する　　　　　　　　　　　　　　　　　　　"], "a": 1, "e": "Defender TIとSentinelを連携させることで、脅威インテリジェンスをSentinelの分析ルールやハンティングクエリに取り込んで活用できる。", "qEn": "What is the benefit of integrating Defender TI with Microsoft Sentinel?", "oEn": ["Achieving functional integration with a meeting room booking system", "Threat intelligence can be leveraged in Sentinel's analytics rules and hunting queries", "Achieving functional integration with a payroll system", "Achieving functional integration with a printer management system"], "eEn": "Integrating Defender TI with Sentinel allows threat intelligence to be incorporated into Sentinel's analytics rules and hunting queries."}, {"d": "D3", "q": "Defender TIが提供するリーク認証情報(leaked credentials)の検出機能の目的は何か。", "o": ["会議室予約プロセスの効率化を図る　　　　", "印刷にかかるコストの削減を図る", "侵害されたアカウント情報の早期発見と対応", "給与計算処理の自動化を図る"], "a": 2, "e": "リーク認証情報の検出機能は、漏えいしたアカウント情報を早期に発見し、対応につなげることを目的としている。", "qEn": "What is the purpose of the leaked credentials detection feature in Defender TI?", "oEn": ["Streamlining the meeting room reservation process", "Reducing costs associated with printing", "Early detection of and response to compromised account information", "Automating payroll processing"], "eEn": "The leaked credentials detection feature aims to detect exposed account information early so it can be acted upon."}, {"d": "D3", "q": "Defender TIのポータルで検索できる対象として正しいものはどれか。", "o": ["従業員個々の休暇申請の承認状況", "各会議室のリアルタイムな空き時間", "経費精算に関する承認プロセスの状況　　　　　　　　　　　　　", "ドメイン、IPアドレス、ホスト名などのインターネット資産情報"], "a": 3, "e": "Defender TIのポータルでは、ドメイン、IPアドレス、ホスト名などのインターネット資産情報を検索・調査できる。", "qEn": "What can be searched in the Defender TI portal?", "oEn": ["The approval status of each individual employee's leave request", "Real-time availability of each meeting room", "The status of the approval process for expense reimbursements", "Internet asset information such as domains, IP addresses, and hostnames"], "eEn": "The Defender TI portal allows searching and investigating internet asset information such as domains, IP addresses, and hostnames."}, {"d": "D3", "q": "Microsoft Defenderポータルが提供する統合SOC体験の目的は何か。", "o": ["複数のセキュリティ製品からの情報を単一のポータルに統合し可視性と対応を効率化する", "複数拠点の会議室予約管理を一つのシステムに統一する　　　　　　　　　　　　　　　", "部門をまたぐ給与計算システムを一元的に統合する", "全社の印刷管理業務を一つの窓口に集約する"], "a": 0, "e": "統合SOC体験は複数のMicrosoftセキュリティ製品からの情報を単一のポータルに集約し、可視性の向上と対応の効率化を実現する。", "qEn": "What is the purpose of the unified SOC experience provided by the Microsoft Defender portal?", "oEn": ["Consolidating information from multiple security products into a single portal for greater visibility and efficient response", "Unifying meeting room booking management across multiple sites into one system", "Centrally integrating a cross-department payroll system", "Consolidating company-wide print management into a single point of contact"], "eEn": "The unified SOC experience consolidates information from multiple Microsoft security products into a single portal, improving visibility and response efficiency."}, {"d": "D3", "q": "Microsoft Defenderポータルにおける「インシデント」とは何か。", "o": ["単発で発生した給与計算処理のエラー　　　　　　　　　　　　　　", "関連するアラートをまとめて1つの攻撃ストーリーとして表す集合体", "会議室の予約が重複してしまった状態", "印刷ジョブの実行中に発生したエラー"], "a": 1, "e": "インシデントは、関連する複数のアラートをまとめ、1つの攻撃ストーリーとして相関付けて表す集合体である。", "qEn": "What is an \"incident\" in the Microsoft Defender portal?", "oEn": ["A one-off error that occurred in payroll processing", "A collection of related alerts correlated into a single attack story", "A situation where a meeting room booking overlaps with another", "An error that occurred while a print job was running"], "eEn": "An incident is a collection of related alerts correlated together to represent a single attack story."}, {"d": "D3", "q": "Microsoft Defenderポータルの高度な検索(Advanced Hunting)で使用されるクエリ言語はどれか。", "o": ["リレーショナルデータベース向けのSQL言語", "汎用スクリプト言語であるPython", "KQL(Kusto Query Language)", "Webブラウザ向けのJavaScript言語　　　"], "a": 2, "e": "Advanced HuntingではKQL(Kusto Query Language)を使用して、生データに対する柔軟なクエリを実行できる。", "qEn": "Which query language is used in Advanced Hunting in the Microsoft Defender portal?", "oEn": ["SQL, a language for relational databases", "Python, a general-purpose scripting language", "KQL (Kusto Query Language)", "JavaScript, a language for web browsers"], "eEn": "Advanced Hunting uses KQL (Kusto Query Language) to run flexible queries against raw data."}, {"d": "D3", "q": "Microsoft Defenderポータルの自動調査と対応(AIR)機能の目的は何か。", "o": ["会議室の予約手続きを自動化する　　　　　　　　　　　　　　　　", "給与計算の処理を自動化する", "印刷ジョブの実行を自動化する", "アラートを自動的に調査し可能な場合は自動的に修復措置を実行する"], "a": 3, "e": "自動調査と対応(AIR)は、アラートを自動的に調査し、必要に応じて自動的に修復アクションを実行する機能である。", "qEn": "What is the purpose of Automated Investigation and Response (AIR) in the Microsoft Defender portal?", "oEn": ["Automating the meeting room reservation procedure", "Automating payroll processing", "Automating the execution of print jobs", "Automatically investigating alerts and taking automatic remediation action when possible"], "eEn": "Automated Investigation and Response (AIR) automatically investigates alerts and, when possible, automatically takes remediation action."}, {"d": "D3", "q": "Microsoft Defenderポータルの脅威分析(Threat Analytics)機能が提供するものは何か。", "o": ["現在進行中の脅威キャンペーンに関する専門家によるレポートと組織への影響評価", "会議室ごとの利用統計データ", "部門ごとの給与計算処理の履歴", "部門ごとの印刷コストの分析結果　　　　　　　　　　　　　　　　　　　　　　"], "a": 0, "e": "脅威分析は、進行中の脅威キャンペーンに関する専門家によるレポートと、自組織への影響評価を提供する。", "qEn": "What does the Threat Analytics feature in the Microsoft Defender portal provide?", "oEn": ["Expert reports on ongoing threat campaigns and their organizational impact assessment", "Usage statistics data for each meeting room", "Payroll processing history broken down by department", "Analysis of printing cost results broken down by department"], "eEn": "Threat Analytics provides expert reports on ongoing threat campaigns along with an assessment of their impact on the organization."}, {"d": "D3", "q": "Microsoft Defenderポータルは主にどのURLからアクセスするか。", "o": ["Azureリソース管理向けのportal.azure.com", "統合セキュリティ運用向けのsecurity.microsoft.com", "Microsoft 365管理向けのadmin.microsoft.com", "Office製品利用向けのportal.office.com"], "a": 1, "e": "Microsoft Defenderポータルはsecurity.microsoft.comからアクセスする統合セキュリティ運用ポータルである。", "qEn": "Which URL is primarily used to access the Microsoft Defender portal?", "oEn": ["portal.azure.com, used for Azure resource management", "security.microsoft.com, used for unified security operations", "admin.microsoft.com, used for Microsoft 365 administration", "portal.office.com, used for accessing Office products"], "eEn": "The Microsoft Defender portal is the unified security operations portal accessed via security.microsoft.com."}, {"d": "D3", "q": "Microsoft Defenderポータルと統合されているMicrosoft Sentinelの役割は何か。", "o": ["複数拠点の会議室予約を一元管理する", "部門をまたぐ給与計算処理を実施する", "クラウドネイティブのSIEM/SOAR機能によるログ分析と自動化", "全社の印刷ジョブの割り当てを管理する　　　　　　　　　　　　　　"], "a": 2, "e": "Microsoft SentinelはMicrosoft Defenderポータルに統合され、クラウドネイティブのSIEM/SOAR機能によるログ分析と対応の自動化を提供する。", "qEn": "What is the role of Microsoft Sentinel integrated with the Microsoft Defender portal?", "oEn": ["Centrally managing meeting room bookings across multiple sites", "Carrying out cross-department payroll processing", "Providing log analysis and automation via cloud-native SIEM/SOAR capabilities", "Managing the allocation of print jobs company-wide"], "eEn": "Microsoft Sentinel, integrated into the Microsoft Defender portal, provides log analysis and response automation through cloud-native SIEM/SOAR capabilities."}, {"d": "D3", "q": "Microsoft Defenderポータルにおける攻撃シミュレーショントレーニングの目的は何か。", "o": ["会議室予約システムの動作テストを行う　　　　　　　　　　　　　　　", "給与計算システムの動作テストを行う", "印刷システムの動作テストを行う", "フィッシングなどの模擬攻撃を通じて従業員のセキュリティ意識を高める"], "a": 3, "e": "攻撃シミュレーショントレーニングは、フィッシングなどの模擬攻撃を実施し、従業員のセキュリティ意識向上と訓練を行う機能である。", "qEn": "What is the purpose of attack simulation training in the Microsoft Defender portal?", "oEn": ["Testing the operation of a meeting room booking system", "Testing the operation of a payroll system", "Testing the operation of a printing system", "Raising employee security awareness through simulated attacks such as phishing"], "eEn": "Attack simulation training conducts simulated attacks, such as phishing, to raise employee security awareness and provide training."}, {"d": "D3", "q": "Microsoft Defenderポータルのインシデントキューで確認できる情報は何か。", "o": ["重要度や影響範囲別に整理されたセキュリティインシデントの一覧", "各会議室の予約状況をまとめた一覧　　　　　　　　　　　　　　", "従業員に発行された給与明細の一覧", "プリンターごとの印刷履歴の一覧"], "a": 0, "e": "インシデントキューは、重要度や影響範囲などで整理されたセキュリティインシデントの一覧を提供し、優先順位付けを支援する。", "qEn": "What information can be viewed in the incident queue of the Microsoft Defender portal?", "oEn": ["A list of security incidents organized by severity and scope of impact", "A consolidated list of each meeting room's reservation status", "A list of payslips issued to employees", "A list of print history for each printer"], "eEn": "The incident queue provides a list of security incidents organized by severity and impact scope, supporting prioritization."}, {"d": "D3", "q": "Microsoft Defenderポータルが統合するデータソースの例として正しいものはどれか。", "o": ["会議室予約システムのデータのみ　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　", "Defender for Endpoint、Defender for Identity、Defender for Cloud Appsなど複数のDefender製品", "給与計算システムのデータのみ", "印刷管理システムのデータのみ"], "a": 1, "e": "Microsoft DefenderポータルはDefender for Endpoint、Defender for Identity、Defender for Cloud Appsなど複数のDefender製品からの信号を統合する。", "qEn": "Which is an example of a data source integrated into the Microsoft Defender portal?", "oEn": ["Only data from a meeting room booking system", "Multiple Defender products such as Defender for Endpoint, Defender for Identity, and Defender for Cloud Apps", "Only data from a payroll system", "Only data from a print management system"], "eEn": "The Microsoft Defender portal integrates signals from multiple Defender products, including Defender for Endpoint, Defender for Identity, and Defender for Cloud Apps."}, {"d": "D3", "q": "Microsoft Defenderポータルのハンティングクエリを保存して定期実行することで得られる利点は何か。", "o": ["会議室予約の手続きを自動化できる　　　　　　　　　　　　　　　　", "給与計算の処理を自動化できる", "特定の脅威兆候を継続的に監視し新たな検出を自動的にアラートできる", "印刷ジョブの実行を自動化できる"], "a": 2, "e": "保存したハンティングクエリを定期実行することで、特定の脅威兆候を継続的に監視し、新たな検出結果を自動的にアラートとして通知できる。", "qEn": "What is the benefit of saving and scheduling hunting queries in the Microsoft Defender portal?", "oEn": ["Automating the meeting room reservation procedure", "Automating payroll processing", "Continuously monitoring specific threat indicators and automatically alerting on new detections", "Automating the execution of print jobs"], "eEn": "Running saved hunting queries on a schedule continuously monitors specific threat indicators and automatically alerts on new detection results."}, {"d": "D3", "q": "Microsoft Defenderポータルにおけるロールベースアクセス制御(RBAC)の目的は何か。", "o": ["会議室の予約に関する権限を管理する", "従業員の給与情報へのアクセス権限を管理する　　　　　　　　　　　", "印刷に関する権限を部門ごとに管理する", "ユーザーの役割に応じてポータル内で閲覧・操作できる範囲を制限する"], "a": 3, "e": "ロールベースアクセス制御(RBAC)は、ユーザーの役割に応じてポータル内で閲覧・操作できる範囲を制限し、最小権限の原則を実現する。", "qEn": "What is the purpose of role-based access control (RBAC) in the Microsoft Defender portal?", "oEn": ["Managing permissions related to meeting room bookings", "Managing access permissions to employees' payroll information", "Managing printing permissions by department", "Restricting what users can view and do in the portal based on their role"], "eEn": "Role-based access control (RBAC) restricts what users can view and do within the portal based on their assigned role, implementing the principle of least privilege."}, {"d": "D4", "q": "Microsoft Service Trust Portal の主な目的として最も適切なものはどれですか。", "o": ["組織のスコアを算出して改善タスクを割り当てる", "テナント内のデータへ機密ラベルを自動的に付与する　　　　　　　　", "監査レポートや準拠資料など、コンプライアンス関連の文書を提供する", "ユーザーのサインイン活動をリアルタイムで監視する"], "a": 2, "e": "Service Trust Portal は、Microsoft の各種クラウドサービスに関する監査レポートやトラスト文書を提供するポータルです。改善タスクの管理は Compliance Manager が担います。", "qEn": "What is the primary purpose of the Microsoft Service Trust Portal?", "oEn": ["To calculate an organization's score and assign improvement tasks", "To automatically apply sensitivity labels to tenant data", "To provide audit reports and compliance-related documents about Microsoft cloud services", "To monitor user sign-in activity in real time"], "eEn": "Service Trust Portal offers audit reports and trust documents about Microsoft's cloud services. Managing improvement actions is the role of Compliance Manager."}, {"d": "D4", "q": "Service Trust Portal で提供されている文書の分類として含まれないものはどれですか。", "o": ["監査レポート（Audit reports）", "地域別コンプライアンス（Regional compliance）", "業界別コンプライアンス（Industry compliance）", "従業員の給与明細"], "a": 3, "e": "Service Trust Portal には監査レポート、データ保護、地域別・業界別コンプライアンス、トラスト文書、リソースといった分類がありますが、従業員給与明細のような人事情報は含まれません。", "qEn": "Which of the following is NOT a category of documents provided on the Service Trust Portal?", "oEn": ["Audit reports", "Regional compliance", "Industry compliance", "Employee payroll statements"], "eEn": "The Service Trust Portal organizes content into categories such as audit reports, data protection, regional and industry compliance, trust documents, and resources — not employee payroll data."}, {"d": "D4", "q": "Service Trust Portal 上のすべてのコンテンツを閲覧するために必要なこととして正しいものはどれですか。", "o": ["Azure サブスクリプションの購入が必須である", "一部の詳細な文書を閲覧するには Microsoft アカウントまたは組織アカウントでのサインインが必要になる", "Compliance Manager のライセンスを別途購入する必要がある　　　　　　　　　　　　　　　　　", "Microsoft 365 E5 ライセンスがなければ一切アクセスできない"], "a": 1, "e": "概要レベルの情報は誰でも閲覧できますが、詳細な監査レポートなど一部の資料を閲覧するにはサインインが必要です。", "qEn": "What is required to view the full range of content on the Service Trust Portal?", "oEn": ["Purchasing an Azure subscription is mandatory", "Signing in with a Microsoft account or organizational account is required to view certain detailed documents", "A separate Compliance Manager license must be purchased", "Access is impossible without a Microsoft 365 E5 license"], "eEn": "General overview information is publicly available, but signing in is required to access certain detailed audit reports and resources."}, {"d": "D4", "q": "Service Trust Portal の「トラスト文書」セクションに含まれる内容として最も適切なものはどれですか。", "o": ["組織内で作成した機密ラベルの一覧", "DLP ポリシーの違反件数を示すレポート　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　", "各ユーザーのライセンス割り当て状況", "Microsoft のセキュリティ、プライバシー、コンプライアンスへの取り組みを説明するホワイトペーパーなど"], "a": 3, "e": "トラスト文書には、Microsoft のセキュリティ・プライバシー・コンプライアンスに関する取り組みを解説する資料が含まれます。組織固有の設定情報は含まれません。", "qEn": "What kind of content is included in the Trust Documents section of the Service Trust Portal?", "oEn": ["A list of sensitivity labels created within the organization", "A report on the number of DLP policy violations", "Each user's license assignment status", "Whitepapers describing Microsoft's approach to security, privacy, and compliance"], "eEn": "Trust documents include whitepapers explaining Microsoft's approach to security, privacy, and compliance; they do not contain organization-specific configuration data."}, {"d": "D4", "q": "Microsoft のデータ保護に関する契約条項をまとめた文書で、Service Trust Portal から入手できるものはどれですか。", "o": ["データ保護補遺（Data Protection Addendum）", "サービスレベルアグリーメント違反通知　　　　　　　　　　　　　　　", "ユーザーライセンス契約書", "サポートチケットの履歴"], "a": 0, "e": "データ保護補遺（DPA）は、Microsoft のオンラインサービスにおけるデータ保護に関する契約条件をまとめた文書であり、Service Trust Portal から参照できます。", "qEn": "Which document summarizing Microsoft's contractual data protection terms can be obtained from the Service Trust Portal?", "oEn": ["The Data Protection Addendum", "Service level agreement breach notices", "The user license agreement", "A history of support tickets"], "eEn": "The Data Protection Addendum (DPA) outlines the contractual data protection terms for Microsoft's online services and can be found on the Service Trust Portal."}, {"d": "D4", "q": "組織のコンプライアンス状況を数値化した「コンプライアンス スコア」を確認したい場合、Service Trust Portal ではなくどのツールを使用するべきですか。", "o": ["Compliance Manager", "Azure Monitor", "Microsoft Defender ポータル", "Exchange 管理センター"], "a": 0, "e": "コンプライアンススコアの算出と改善アクションの管理は Compliance Manager の機能であり、Service Trust Portal では提供されません。", "qEn": "Which tool, rather than the Service Trust Portal, should be used to check an organization's numeric compliance score?", "oEn": ["Compliance Manager", "Azure Monitor", "the Microsoft Defender portal", "the Exchange admin center"], "eEn": "Calculating a compliance score and tracking improvement actions is a function of Compliance Manager, not the Service Trust Portal."}, {"d": "D4", "q": "Service Trust Portal の「地域別コンプライアンス」セクションで確認できる内容の例として適切なものはどれですか。", "o": ["従業員の勤怠管理データ", "個々のメールボックスの容量　　　　　　　　　", "GDPR など特定の地域の規制に関連する情報", "社内チャットの会話ログ"], "a": 2, "e": "地域別コンプライアンスのセクションでは、GDPR のような特定の地域・国の規制に対する Microsoft の取り組みに関する情報が提供されます。", "qEn": "What is an example of content found in the Regional Compliance section of the Service Trust Portal?", "oEn": ["Employee attendance tracking data", "Individual mailbox storage capacity", "Information related to region-specific regulations such as GDPR", "Internal chat conversation logs"], "eEn": "The Regional Compliance section provides information about Microsoft's efforts regarding regulations specific to a particular region or country, such as GDPR."}, {"d": "D4", "q": "Service Trust Portal と Microsoft Purview コンプライアンス機能の関係について正しい説明はどれですか。", "o": ["Service Trust Portal は組織のすべてのラベルポリシーを直接編集できる", "Service Trust Portal は Microsoft 側の対応状況を示す文書を提供し、組織固有の設定管理は Purview 側で行う", "Service Trust Portal を使えば DLP ポリシーを作成できる", "Service Trust Portal は Purview のログイン情報を管理する認証基盤である　　　　　　　　　　　　　　　　　　　　　　"], "a": 1, "e": "Service Trust Portal は Microsoft 自身のコンプライアンス対応状況を示す文書を提供する場であり、組織固有のポリシー設定や管理は Microsoft Purview で行います。", "qEn": "Which statement correctly describes the relationship between the Service Trust Portal and Microsoft Purview compliance capabilities?", "oEn": ["The Service Trust Portal can directly edit all of an organization's label policies", "The Service Trust Portal provides documents about Microsoft's own compliance posture, while organization-specific configuration is managed in Purview", "DLP policies can be created using the Service Trust Portal", "The Service Trust Portal is the authentication backbone that manages Purview sign-in credentials"], "eEn": "The Service Trust Portal offers documentation about Microsoft's own compliance efforts, while organization-specific policy configuration and management take place in Microsoft Purview."}, {"d": "D4", "q": "Service Trust Portal の「リソース」セクションで提供される情報として適切なものはどれですか。", "o": ["テナントの全ユーザー一覧", "各国の税務申告フォーム", "社内で作成されたカスタムラベルの詳細設定　　　　　　　　　　　　", "FAQ やナビゲーションガイドなど、ポータルの利用を補助する資料"], "a": 3, "e": "リソースセクションには、ポータルの使い方に関する FAQ やガイドなど、利用者を補助するための資料が含まれます。", "qEn": "What kind of information is provided in the Resources section of the Service Trust Portal?", "oEn": ["A list of all users in the tenant", "Tax filing forms for each country", "Detailed settings of custom labels created internally", "Materials such as FAQs and navigation guides that help users use the portal"], "eEn": "The Resources section includes materials such as FAQs and guides that help users navigate and use the portal effectively."}, {"d": "D4", "q": "Service Trust Portal に関する記述として正しいものはどれですか。", "o": ["Service Trust Portal は Azure サブスクリプション保有者のみが利用できる　　　　　", "Service Trust Portal はオンプレミス環境専用のポータルである", "Service Trust Portal は無料トライアル期間中のみ利用できる", "監査報告書などの一部の資料は、Azure サブスクリプションを持たないユーザーでもサインインすれば閲覧できる"], "a": 3, "e": "Service Trust Portal は Microsoft アカウントまたは組織アカウントでサインインすれば、Azure サブスクリプションがなくても多くの資料を閲覧できます。", "qEn": "Which statement about the Service Trust Portal is correct?", "oEn": ["The Service Trust Portal is available only to Azure subscription holders", "The Service Trust Portal is a portal exclusively for on-premises environments", "The Service Trust Portal is available only during a free trial period", "Certain materials, such as audit reports, can be viewed by users without an Azure subscription as long as they sign in"], "eEn": "Signing in with a Microsoft account or organizational account gives access to much of the Service Trust Portal's content, even without an Azure subscription."}, {"d": "D4", "q": "Microsoft のプライバシー原則のうち「コントロール」が意味する内容として最も適切なものはどれですか。", "o": ["Microsoft がすべてのデータの所有権を持つこと　　　　　", "顧客が自分のデータを管理し、収集・使用方法について選択できること", "第三者が自由に顧客データへアクセスできること", "データの保存場所を顧客が選べないこと"], "a": 1, "e": "「コントロール」の原則は、顧客が自身のデータに対する所有権を持ち、その収集・使用方法をコントロールできることを意味します。", "qEn": "What does the Microsoft privacy principle of \"Control\" most accurately mean?", "oEn": ["Microsoft owns all customer data outright", "Customers own their data and can control how it is collected and used", "Third parties can freely access customer data", "Customers cannot choose where their data is stored"], "eEn": "The Control principle means that customers own their data and have control over how it is collected and used."}, {"d": "D4", "q": "Microsoft のプライバシー原則における「透明性」が指す内容はどれですか。", "o": ["顧客データを第三者へ非公開で販売すること", "データの収集目的と利用方法を明確に開示すること", "収集したデータの内容を顧客に一切知らせないこと", "契約書を意図的に難解にすること"], "a": 1, "e": "「透明性」の原則は、どのようなデータをどのような目的で収集・利用するかを明確かつわかりやすく開示することを意味します。", "qEn": "What does the Microsoft privacy principle of \"Transparency\" refer to?", "oEn": ["Selling customer data to third parties without disclosure", "Clearly disclosing the purpose and manner of data collection and use", "Never informing customers about what data has been collected", "Deliberately making contracts difficult to understand"], "eEn": "The Transparency principle means clearly and understandably disclosing what data is collected and how it is used."}, {"d": "D4", "q": "Microsoft のプライバシー原則のうち、広告目的でメールやドキュメントの内容を分析しないという方針を表すものはどれですか。", "o": ["強力な法的保護", "コンテンツに基づく広告を行わないこと（No content-based targeting）", "セキュリティ", "お客様にとっての利点　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　"], "a": 1, "e": "Microsoft は、電子メールやドキュメントなどの内容を広告目的でスキャン・分析しないという原則を掲げています。", "qEn": "Which Microsoft privacy principle states that email and document content is not analyzed for advertising purposes?", "oEn": ["Strong legal protections", "No content-based targeting", "Security", "Benefits to you"], "eEn": "Microsoft commits to not scanning or analyzing content such as email and documents for advertising purposes."}, {"d": "D4", "q": "Microsoft のプライバシー原則の一つである「強力な法的保護」が意味する内容として正しいものはどれですか。", "o": ["顧客データのプライバシーを、法律で定められた要件以上の契約上の約束によって保護すること", "政府機関がいつでも自由にデータへアクセスできるようにすること　　　　　　　　　　　　　", "各国の法律をすべて無視して独自ルールを適用すること", "契約内容を顧客に開示しないこと"], "a": 0, "e": "「強力な法的保護」は、法的な最低要件にとどまらず、契約上の約束としてプライバシー保護を強化する原則です。", "qEn": "What does the Microsoft privacy principle of \"Strong legal protections\" mean?", "oEn": ["Protecting customer data privacy through contractual commitments that go beyond legal minimums", "Allowing government agencies unrestricted access to data at any time", "Ignoring all national laws and applying Microsoft's own independent rules", "Refusing to disclose contract terms to customers"], "eEn": "Strong legal protections means reinforcing privacy protection through contractual commitments that go beyond the minimum legal requirements."}, {"d": "D4", "q": "Microsoft のプライバシー原則における「セキュリティ」の考え方として最も適切なものはどれですか。", "o": ["パスワードを設定させないことで利便性を優先すること　　　　　　　　　", "暗号化などの強力な保護対策により顧客データを不正アクセスから守ること", "セキュリティ対策を顧客自身のみの責任とすること", "データを暗号化せず平文のまま保存すること"], "a": 1, "e": "「セキュリティ」の原則は、暗号化などの強固な保護手段によって顧客データを不正アクセスや侵害から守ることを指します。", "qEn": "What is the correct interpretation of the Microsoft privacy principle of \"Security\"?", "oEn": ["Prioritizing convenience by not requiring passwords at all", "Protecting customer data from unauthorized access through strong safeguards such as encryption", "Treating security as solely the customer's own responsibility", "Storing data as plain text without any encryption"], "eEn": "The Security principle refers to protecting customer data from unauthorized access and breaches through strong safeguards such as encryption."}, {"d": "D4", "q": "Microsoft のプライバシー原則における「お客様にとっての利点」とは何を意味しますか。", "o": ["収集したデータを完全に匿名化せずそのまま公開すること　　　　　　　　　　　　　　", "顧客からデータ利用の同意を取らずに済ませること", "収集したデータを顧客自身の利益のために活用し、顧客にとって役立つ形で還元すること", "収集したデータをすべて削除して一切利用しないこと"], "a": 2, "e": "「お客様にとっての利点」の原則は、収集したデータを顧客自身に価値をもたらす形で活用することを意味します。", "qEn": "What does the Microsoft privacy principle of \"Benefits to you\" mean?", "oEn": ["Publishing collected data as-is without anonymization", "Skipping customer consent for data usage", "Using collected data in ways that bring value back to the customer", "Deleting all collected data and never using it"], "eEn": "The Benefits to you principle means that data collected is used in ways that provide value back to the customer."}, {"d": "D4", "q": "Microsoft のプライバシー原則のうち、顧客が自身のデータの所有者であることを最も強く示す原則はどれですか。", "o": ["透明性", "セキュリティ", "強力な法的保護", "コントロール"], "a": 3, "e": "コントロールの原則は、顧客が自分自身のデータの所有者であり、その使用方法を管理できることを明確に示しています。", "qEn": "Which Microsoft privacy principle most directly emphasizes that customers own their own data?", "oEn": ["Transparency", "Security", "Strong legal protections", "Control"], "eEn": "The Control principle explicitly states that customers own their own data and can manage how it is used."}, {"d": "D4", "q": "Microsoft が公表しているプライバシーに関する基本方針の説明として正しいものはどれですか。", "o": ["単一の原則のみで構成され、それ以外の考慮事項は存在しない　　　　　", "コントロール、透明性、セキュリティなど複数の原則から構成されている", "国ごとに全く異なる独自の原則を個別に定めている", "顧客の同意なくデータを自由に販売できるとしている"], "a": 1, "e": "Microsoft のプライバシーに関する基本方針は、コントロール、透明性、セキュリティ、強力な法的保護、コンテンツに基づく広告をしないこと、お客様にとっての利点など複数の原則で構成されています。", "qEn": "Which statement correctly describes Microsoft's published privacy principles?", "oEn": ["They consist of a single principle with no other considerations", "They consist of multiple principles, including control, transparency, and security", "They define entirely separate, country-specific principles with no common basis", "They state that customer data can be freely sold without consent"], "eEn": "Microsoft's privacy principles include multiple pillars such as control, transparency, security, strong legal protections, no content-based targeting, and benefits to you."}, {"d": "D4", "q": "Microsoft Purview ポータルの説明として最も適切なものはどれですか。", "o": ["オンプレミスのファイルサーバーを管理するための専用ツールである　　　　", "Azure の課金明細のみを表示するポータルである", "コンプライアンスとデータガバナンスの機能を1つに統合したポータルである", "エンドユーザー向けの Office アプリのランチャーである"], "a": 2, "e": "Microsoft Purview ポータルは、旧 Microsoft 365 コンプライアンスセンターと旧 Azure Purview のガバナンス機能を統合した、コンプライアンスとデータガバナンスのための単一ポータルです。", "qEn": "What best describes the Microsoft Purview portal?", "oEn": ["A dedicated tool for managing on-premises file servers", "A portal that only displays Azure billing statements", "A unified portal that combines compliance and data governance capabilities", "An end-user launcher for Office applications"], "eEn": "The Microsoft Purview portal unifies the compliance capabilities of the former Microsoft 365 compliance center with the governance capabilities of the former Azure Purview into a single portal."}, {"d": "D4", "q": "Microsoft Purview ポータルで、ユーザーがどの機能にアクセスできるかを制御する仕組みはどれですか。", "o": ["ロールベースのアクセス制御（ロールとロールグループ）", "全ユーザーへ無条件で管理者権限を付与する仕組み　　　", "IP アドレスによる制限のみ", "デバイスの製造元による制限のみ"], "a": 0, "e": "Microsoft Purview ではロールとロールグループを用いたロールベースアクセス制御（RBAC）により、ユーザーがアクセスできる機能や実行できる操作を制御します。", "qEn": "In the Microsoft Purview portal, what mechanism controls which features a user can access?", "oEn": ["Role-based access control using roles and role groups", "A mechanism that unconditionally grants administrator rights to all users", "Restriction based solely on IP address", "Restriction based solely on device manufacturer"], "eEn": "Microsoft Purview uses role-based access control (RBAC), implemented through roles and role groups, to determine which features and actions a user can access."}, {"d": "D4", "q": "Microsoft Purview ポータルに含まれるソリューションの組み合わせとして適切なものはどれですか。", "o": ["情報保護、データ ライフサイクル管理、内部リスク管理、eDiscovery", "仮想マシンの作成、ネットワークの構成、ロードバランサー管理　　　　　　　　", "給与計算、勤怠管理、経費精算", "ドメイン名の登録、DNS レコードの管理"], "a": 0, "e": "Microsoft Purview には情報保護、データライフサイクル管理、内部リスク管理、eDiscovery、監査、コミュニケーションコンプライアンス、DLP、Compliance Manager など多数のソリューションが含まれます。", "qEn": "Which combination of solutions is included in the Microsoft Purview portal?", "oEn": ["Information protection, data lifecycle management, insider risk management, and eDiscovery", "Creating virtual machines, configuring networks, and managing load balancers", "Payroll processing, attendance tracking, and expense reimbursement", "Domain name registration and DNS record management"], "eEn": "Microsoft Purview includes numerous solutions such as information protection, data lifecycle management, insider risk management, eDiscovery, audit, communication compliance, DLP, and Compliance Manager."}, {"d": "D4", "q": "Microsoft Purview ポータルの「アラート」機能について正しい説明はどれですか。", "o": ["毎月の請求金額を自動的にメールで送付する　　　　　　　　", "ユーザーのパスワードを定期的に変更する", "ポリシー違反や不審な活動が検出された際に管理者へ通知する", "会議の議事録を自動生成する"], "a": 2, "e": "アラート機能は、DLP ポリシー違反やインサイダーリスクの兆候など、コンプライアンス上注意が必要な活動が検出された場合に管理者へ通知します。", "qEn": "Which statement correctly describes the alerts feature in the Microsoft Purview portal?", "oEn": ["It automatically emails the monthly billing amount", "It periodically changes user passwords", "It notifies administrators when policy violations or suspicious activity are detected", "It automatically generates meeting minutes"], "eEn": "The alerts feature notifies administrators when compliance-relevant activity is detected, such as DLP policy violations or signs of insider risk."}, {"d": "D4", "q": "旧称の「Microsoft 365 コンプライアンス センター」に代わって現在使用されているブランド名はどれですか。", "o": ["Microsoft Defender for Cloud", "Microsoft Entra", "Microsoft Purview", "Microsoft Sentinel"], "a": 2, "e": "コンプライアンス関連機能は現在、Microsoft Purview というブランドに統合されています。旧名称の「Microsoft 365 コンプライアンスセンター」は使用されていません。", "qEn": "Which current brand name replaced the former \"Microsoft 365 compliance center\"?", "oEn": ["Microsoft Defender for Cloud", "Microsoft Entra", "Microsoft Purview", "Microsoft Sentinel"], "eEn": "Compliance-related capabilities are now unified under the Microsoft Purview brand; the older name \"Microsoft 365 compliance center\" is no longer used."}, {"d": "D4", "q": "旧称「Azure Purview」の機能は、現在の Microsoft Purview ポータルにおいて主にどの領域を担いますか。", "o": ["仮想マシンの稼働監視", "従業員の勤怠管理", "データガバナンス（データマップやデータカタログなど）", "メールの配信ルーティング　　　　　　　　　　　　　　"], "a": 2, "e": "旧 Azure Purview の機能はデータガバナンス領域に相当し、データマップやデータカタログを通じて組織内のデータ資産を検出・分類・管理します。", "qEn": "In the current Microsoft Purview portal, which area does the functionality formerly known as \"Azure Purview\" primarily cover?", "oEn": ["Monitoring virtual machine uptime", "Employee attendance tracking", "Data governance, such as data map and data catalog capabilities", "Email delivery routing"], "eEn": "The capabilities formerly known as Azure Purview correspond to the data governance area, discovering, classifying, and managing data assets across the organization through the data map and data catalog."}, {"d": "D4", "q": "Microsoft Purview ポータルにアクセスする際の説明として正しいものはどれですか。", "o": ["オンプレミスのサーバーへ直接インストールしなければ利用できない　　　　　", "モバイルアプリからのみアクセス可能である", "専用の Web アドレスからサインインしてアクセスする統合ポータルである", "サインインなしで匿名アクセスできる"], "a": 2, "e": "Microsoft Purview ポータルは、対応する Web アドレスへサインインすることでアクセスするクラウドベースの統合ポータルです。", "qEn": "Which statement correctly describes accessing the Microsoft Purview portal?", "oEn": ["It can only be used after being installed directly onto an on-premises server", "It is accessible only through a mobile app", "It is a unified portal accessed by signing in through its dedicated web address", "It allows anonymous access without signing in"], "eEn": "The Microsoft Purview portal is a cloud-based unified portal accessed by signing in at its dedicated web address."}, {"d": "D4", "q": "Microsoft Purview ポータル内でソリューションが整理されている単位として最も適切なものはどれですか。", "o": ["ソリューションカードごとにまとめられ、各カードから該当機能へ移動できる", "アルファベット順に並んだ単一の巨大なリストのみで構成される　　　　　　", "1つのソリューションしか表示されない", "課金額の高い順にのみ並べ替えられる"], "a": 0, "e": "Microsoft Purview ポータルのホーム画面では、情報保護や DLP などのソリューションがカード形式でまとめられ、それぞれから対応する管理画面に移動できます。", "qEn": "How are solutions typically organized within the Microsoft Purview portal?", "oEn": ["Grouped into solution cards, each linking to its corresponding feature area", "Displayed only as a single large alphabetical list", "Only a single solution is ever displayed", "Sorted solely by billing amount, highest first"], "eEn": "The Purview portal home page groups solutions such as information protection and DLP into cards, each of which links to its corresponding management experience."}, {"d": "D4", "q": "Compliance Manager の「コンプライアンス スコア」が示す内容として最も適切なものはどれですか。", "o": ["組織が実施した改善アクションの進捗状況を数値化したリスクベースの指標", "組織が完全に法令を遵守していることを保証する法的な証明書　　　　　　", "従業員の業務評価スコア", "テナントに割り当てられたライセンス数"], "a": 0, "e": "コンプライアンススコアは、組織が改善アクションをどの程度実施しているかを示すリスクベースの指標であり、法令遵守を保証するものではありません。", "qEn": "What does the Compliance Manager \"compliance score\" represent?", "oEn": ["A risk-based metric that quantifies an organization's progress on completing improvement actions", "A legal certificate guaranteeing full regulatory compliance", "An employee performance evaluation score", "The number of licenses assigned in the tenant"], "eEn": "The compliance score is a risk-based measurement of an organization's progress on improvement actions; it does not guarantee legal compliance."}, {"d": "D4", "q": "Compliance Manager でアセスメントを作成する際の基盤となるものはどれですか。", "o": ["ユーザーの勤続年数", "規制や標準に基づくアセスメントテンプレート", "ハードウェアの製造元一覧　　　　　　　　　", "従業員の評価面談記録"], "a": 1, "e": "Compliance Manager には GDPR や ISO 27001 などの規制・標準に対応するアセスメントテンプレートが用意されており、これを基にアセスメントを作成します。", "qEn": "What forms the basis for creating an assessment in Compliance Manager?", "oEn": ["Employees' years of service", "Assessment templates based on regulations and standards", "A list of hardware manufacturers", "Records of employee performance interviews"], "eEn": "Compliance Manager provides assessment templates corresponding to regulations and standards such as GDPR or ISO 27001, which serve as the basis for creating assessments."}, {"d": "D4", "q": "Compliance Manager における「改善アクション」の役割として正しいものはどれですか。", "o": ["ユーザーのライセンスを自動的に削除する　　　　　　　　　　　　　　　　　　　　　", "テナントのバックアップを自動で取得する", "従業員の給与を自動計算する", "コンプライアンス スコアを向上させるために組織が実施すべき具体的な対応手順を示す"], "a": 3, "e": "改善アクションは、組織がコンプライアンススコアを高めるために実施すべき具体的なタスクを示し、実施状況に応じてスコアへ反映されます。", "qEn": "What role do \"improvement actions\" play in Compliance Manager?", "oEn": ["They automatically remove user licenses", "They automatically back up the tenant", "They automatically calculate employee salaries", "They describe specific steps an organization should take to raise its compliance score"], "eEn": "Improvement actions describe concrete tasks an organization can perform to raise its compliance score, and completion status is reflected in the score."}, {"d": "D4", "q": "Compliance Manager における管理策の分類のうち、Microsoft 自身が実装と検証を担当するものはどれですか。", "o": ["顧客が管理する管理策（Customer-managed controls）　　　　　　　　　", "共有管理策（Shared controls）", "Microsoft が管理する管理策（Microsoft-managed controls）", "第三者ベンダーが管理する管理策"], "a": 2, "e": "Microsoft 管理の管理策は、Microsoft 自身が実装・運用・検証を行う管理策で、クラウドサービス側の対応状況を示します。", "qEn": "In Compliance Manager's control categories, which type is implemented and verified by Microsoft itself?", "oEn": ["Customer-managed controls", "Shared controls", "Microsoft-managed controls", "Controls managed by an independent third-party vendor"], "eEn": "Microsoft-managed controls are implemented, operated, and verified by Microsoft, reflecting the compliance status of the cloud service itself."}, {"d": "D4", "q": "Compliance Manager において、顧客側の設定変更が必要な管理策はどのカテゴリに分類されますか。", "o": ["Microsoft が管理する管理策（Microsoft-managed controls）", "監査済み管理策", "廃止済み管理策", "顧客が管理する管理策（Customer-managed controls）"], "a": 3, "e": "顧客が管理する管理策は、テナント内の設定変更や運用対応など、組織自身が実施する必要がある管理策です。", "qEn": "In Compliance Manager, which category covers controls that require configuration changes by the customer?", "oEn": ["Microsoft-managed controls", "Audited controls", "Deprecated controls", "Customer-managed controls"], "eEn": "Customer-managed controls are those the organization itself must implement, such as tenant configuration changes or operational responses."}, {"d": "D4", "q": "Compliance Manager における「予防的（preventative）」管理策の目的として最も適切なものはどれですか。", "o": ["問題が発生する前にリスクを未然に防ぐこと", "発生したインシデントの原因を事後的に分析すること", "既に起きた被害を修復すること", "従業員の勤務評価を行うこと"], "a": 0, "e": "予防的管理策は、リスクや問題が発生する前にそれを防止することを目的とした管理策です。検知的管理策は問題の発見、是正的管理策は問題への対応を目的とします。", "qEn": "What is the primary purpose of a \"preventative\" control in Compliance Manager?", "oEn": ["To stop risks from occurring in the first place", "To analyze the root cause of an incident after it has happened", "To repair damage that has already occurred", "To evaluate employee work performance"], "eEn": "Preventative controls aim to prevent risks or issues before they occur, whereas detective controls aim to identify issues and corrective controls aim to address them."}, {"d": "D4", "q": "Compliance Manager のコンプライアンス スコアに関する説明として正しいものはどれですか。", "o": ["監督官庁が発行する公式な認定証である", "スコアが100点になれば訴訟リスクが完全になくなることを意味する　　　　　　　　　　　　　", "組織が規制へ完全準拠していることを法的に保証するものではなく、あくまで進捗を示す目安である", "スコアはユーザー数のみに基づいて自動計算される"], "a": 2, "e": "コンプライアンススコアは組織の取り組み状況を示す目安であり、法的な準拠を保証するものではありません。", "qEn": "Which statement correctly describes the Compliance Manager compliance score?", "oEn": ["It is an official certification issued by a regulatory authority", "A score of 100 means all litigation risk is completely eliminated", "It is not a legal guarantee of full regulatory compliance, but rather an indicator of progress", "The score is calculated automatically based solely on the number of users"], "eEn": "The compliance score is an indicator of an organization's progress, not a legal guarantee of compliance with any regulation."}, {"d": "D4", "q": "Compliance Manager のアセスメントは主にどの2つの要素の組み合わせに基づいて構成されますか。", "o": ["対象となる規制または標準と、対象となる Microsoft クラウドサービス", "従業員数と部署名", "デバイスの購入日と保証期間", "アプリケーションのバージョン番号のみ　　　　　　　　　　　　　　　　　　　　"], "a": 0, "e": "アセスメントは、GDPR のような規制・標準と、Microsoft 365 のようなクラウドサービスの組み合わせに基づいて構成されます。", "qEn": "An assessment in Compliance Manager is primarily built around which two elements?", "oEn": ["The target regulation or standard, and the target Microsoft cloud service", "Employee headcount and department name", "Device purchase date and warranty period", "Application version number alone"], "eEn": "An assessment is structured around a combination of a regulation or standard (such as GDPR) and a Microsoft cloud service (such as Microsoft 365)."}, {"d": "D4", "q": "Compliance Manager の管理策のうち、Microsoft と顧客の双方が責任を分担するものはどれですか。", "o": ["Microsoft が管理する管理策のみ　　", "顧客が管理する管理策のみ", "外部監査法人が単独で管理する管理策", "共有管理策（Shared controls）"], "a": 3, "e": "共有管理策は、実装や運用の責任を Microsoft と顧客の双方で分担する管理策です。", "qEn": "Which Compliance Manager control category involves shared responsibility between Microsoft and the customer?", "oEn": ["Microsoft-managed controls only", "Customer-managed controls only", "Controls managed solely by an external audit firm", "Shared controls"], "eEn": "Shared controls are those where implementation and operational responsibility are divided between Microsoft and the customer."}, {"d": "D4", "q": "Compliance Manager の改善アクションのうち、法的な要求事項として必須なものと、組織の任意判断で実施するものを区別する分類はどれですか。", "o": ["必須（Mandatory）と裁量的（Discretionary）", "有料と無料", "国内向けと海外向け", "旧バージョンと新バージョン　　　　　　　　　　　　　　　　　　　"], "a": 0, "e": "改善アクションは、規制上必須とされる「必須」アクションと、組織の判断で追加的に実施する「裁量的」アクションに分類されます。", "qEn": "Which classification distinguishes improvement actions that are legally required from those an organization chooses to implement at its own discretion?", "oEn": ["Mandatory and discretionary", "Paid and free", "Domestic and international", "Legacy version and current version"], "eEn": "Improvement actions are classified as mandatory, meaning they are required by regulation, or discretionary, meaning the organization chooses to implement them additionally."}, {"d": "D4", "q": "Compliance Manager のダッシュボードで確認できる主な情報として適切なものはどれですか。", "o": ["全体のコンプライアンス スコアと、進行中のアセスメントの概要", "従業員個人の医療記録", "競合他社の株価情報", "社内ネットワークの物理的な配線図　　　　　　　　　　　　　　"], "a": 0, "e": "Compliance Manager のダッシュボードでは、全体のコンプライアンススコアや、実施中のアセスメントの概要などを一目で確認できます。", "qEn": "What key information can be viewed on the Compliance Manager dashboard?", "oEn": ["The overall compliance score and a summary of in-progress assessments", "Individual employees' medical records", "Competitors' stock price information", "The physical wiring diagram of the internal network"], "eEn": "The Compliance Manager dashboard provides an at-a-glance view of the overall compliance score and a summary of ongoing assessments."}, {"d": "D4", "q": "Compliance Manager において、管理策が問題の発生を検知することを目的とする場合、その管理策はどのカテゴリに該当しますか。", "o": ["予防的（Preventative）管理策", "検知的（Detective）管理策", "是正的（Corrective）管理策", "廃止された管理策"], "a": 1, "e": "検知的管理策は、既に発生した問題やリスクを発見することを目的とした管理策です。", "qEn": "In Compliance Manager, when a control is intended to identify that an issue has already occurred, which category does it belong to?", "oEn": ["Preventative controls", "Detective controls", "Corrective controls", "Deprecated controls"], "eEn": "Detective controls are designed to identify issues or risks that have already occurred."}, {"d": "D4", "q": "Microsoft Purview の機密ラベル（sensitivity labels）が実行できる操作として適切なものはどれですか。", "o": ["サーバーの CPU 使用率の監視　　　　　　　　　　　　　　　", "ドキュメントやメールの暗号化、視覚的なマーキング、アクセス制限", "ネットワークの帯域幅の割り当て", "ユーザーのライセンス購入手続き"], "a": 1, "e": "機密ラベルは、コンテンツに対する暗号化、ヘッダーやフッターなどの視覚的マーキング、アクセス制限といった保護操作を適用できます。", "qEn": "What actions can Microsoft Purview sensitivity labels perform?", "oEn": ["Monitoring server CPU utilization", "Encrypting documents and email, applying visual markings, and restricting access", "Allocating network bandwidth", "Processing user license purchases"], "eEn": "Sensitivity labels can apply protective actions such as encryption, visual markings like headers or footers, and access restrictions to content."}, {"d": "D4", "q": "作成した機密ラベルをユーザーに実際に使用させるために必要な設定はどれですか。", "o": ["ラベル ポリシーを介してラベルを対象ユーザーやグループに発行する", "ラベルをテナントから完全に削除する", "ラベル名をすべて英数字のみに変更する", "Exchange のメールボックス容量を拡張する　　　　　　　　"], "a": 0, "e": "作成しただけのラベルはそのままでは使用できず、ラベルポリシーを通じて対象のユーザーやグループに発行（公開）する必要があります。", "qEn": "What is required so that users can actually apply a sensitivity label that has been created?", "oEn": ["The label must be published to target users or groups through a label policy", "The label must be permanently deleted from the tenant", "The label name must be changed to contain only alphanumeric characters", "The Exchange mailbox quota must be expanded"], "eEn": "A label that has only been created cannot be used until it is published to target users or groups through a label policy."}, {"d": "D4", "q": "Content explorer の主な機能として最も適切なものはどれですか。", "o": ["過去に実行されたラベル操作の履歴を時系列で表示する　　　　　　　　　", "ネットワークトラフィックの帯域使用状況を表示する", "現在ラベル付けされているコンテンツの実際の内容と分布状況を確認できる", "ユーザーのログイン失敗回数を表示する"], "a": 2, "e": "Content explorer は、現時点でラベルが付与されているコンテンツの実際の内容やその分布状況を確認するための機能です。", "qEn": "What is the primary function of Content explorer?", "oEn": ["Displaying a chronological history of label-related actions taken in the past", "Displaying network traffic bandwidth utilization", "Viewing the actual content and distribution of items currently carrying sensitivity labels", "Displaying the number of failed sign-in attempts by users"], "eEn": "Content explorer lets you view the actual content and current distribution of items that carry sensitivity labels."}, {"d": "D4", "q": "Activity explorer の主な機能として最も適切なものはどれですか。", "o": ["コンテンツの実際の本文をそのまま表示する　　　　　　　　　　　", "サーバーのディスク使用量を表示する", "ユーザーの給与情報を表示する", "ラベルの適用、変更、削除といった活動の履歴を時系列で確認できる"], "a": 3, "e": "Activity explorer は、ラベルの適用や変更、削除といったアクションの履歴を時系列で追跡するための機能です。", "qEn": "What is the primary function of Activity explorer?", "oEn": ["Displaying the actual body content of items as-is", "Displaying server disk usage", "Displaying users' salary information", "Tracking a chronological history of actions such as label application, change, and removal"], "eEn": "Activity explorer is used to track a chronological history of actions such as labels being applied, changed, or removed."}, {"d": "D4", "q": "Content explorer と Activity explorer の違いについて正しい説明はどれですか。", "o": ["両者はまったく同じ情報を異なる画面デザインで表示するだけである", "Content explorer は現在の状態を、Activity explorer は時間経過に伴う活動履歴を示す", "Content explorer はアクセス権限を持たないユーザーには一切表示できない機能である　　　　　　　　　　", "Activity explorer はコンテンツの中身のみを表示し、履歴は表示しない"], "a": 1, "e": "Content explorer はラベル付きコンテンツの現在の状態を、Activity explorer はラベルに関する活動の履歴を時系列で表示するという役割の違いがあります。", "qEn": "What correctly distinguishes Content explorer from Activity explorer?", "oEn": ["They display exactly the same information, just with different screen designs", "Content explorer shows the current state of labeled content, while Activity explorer shows the history of label-related activity over time", "Content explorer is a feature that no user can ever view regardless of permissions", "Activity explorer only displays content bodies and shows no history"], "eEn": "Content explorer focuses on the current state of labeled content, while Activity explorer focuses on the historical timeline of label-related activity."}, {"d": "D4", "q": "機密情報の種類（sensitive information types）に関する説明として正しいものはどれですか。", "o": ["ユーザーが手動で入力した自由なコメント文　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　", "クレジットカード番号やマイナンバーなど、パターンに基づいて機密データを識別する定義済みまたはカスタムのルール", "デバイスの製造番号一覧", "サーバーのIPアドレス範囲のみを示すもの"], "a": 1, "e": "機密情報の種類は、クレジットカード番号や社会保障番号などのパターンに基づいて機密データを検出するための定義済みまたはカスタムの分類子です。", "qEn": "Which statement correctly describes sensitive information types?", "oEn": ["Free-form comments manually entered by a user", "Predefined or custom pattern-based rules used to identify sensitive data, such as credit card numbers or national ID numbers", "A list of device serial numbers", "Only a range of server IP addresses"], "eEn": "Sensitive information types are predefined or custom classifiers that detect sensitive data based on patterns, such as credit card numbers or national identification numbers."}, {"d": "D4", "q": "トレーニング可能な分類子（trainable classifiers）の説明として最も適切なものはどれですか。", "o": ["あらかじめ固定された正規表現のみで動作し、学習は一切行わない　　　　　　　　　　　　　　", "ユーザーのパスワード強度を判定する機能である", "サンプルデータを学習させることで、パターンだけでは検出しにくいコンテンツの種類を識別する", "ネットワーク帯域を自動的に最適化する機能である"], "a": 2, "e": "トレーニング可能な分類子は、サンプル文書を学習させることで、単純なパターンマッチでは識別が難しいコンテンツの種類（契約書や履歴書など）を認識できるようにする分類方法です。", "qEn": "What best describes trainable classifiers?", "oEn": ["They operate solely on fixed regular expressions and never learn from data", "They are a feature for judging the strength of user passwords", "They learn from sample data to identify content types that are difficult to detect using patterns alone", "They automatically optimize network bandwidth"], "eEn": "Trainable classifiers learn from sample documents to recognize types of content, such as contracts or resumes, that are difficult to identify with simple pattern matching alone."}, {"d": "D4", "q": "完全一致データ（Exact Data Match, EDM）分類の特徴として正しいものはどれですか。", "o": ["あいまいなキーワード検索のみを行い、完全一致は考慮しない　　　　　", "画像ファイルの色調のみを分析する", "ネットワークの遅延時間を測定する", "既存のデータベース内の実際のレコードと厳密に一致する値を検出できる"], "a": 3, "e": "EDM 分類は、組織が保有する実際のデータベースの値と厳密に一致するデータを検出するための機密情報検出方式です。", "qEn": "What is a defining characteristic of Exact Data Match (EDM) classification?", "oEn": ["It performs only fuzzy keyword searches and does not consider exact matches", "It only analyzes the color tone of image files", "It measures network latency", "It can detect values that exactly match actual records in an existing database"], "eEn": "EDM classification is a method for detecting sensitive data that exactly matches actual values stored in an organization's existing database."}, {"d": "D4", "q": "データ損失防止（DLP）ポリシーの主な目的として最も適切なものはどれですか。", "o": ["ユーザーのパスワードを定期的に変更させること　　　　　　", "サーバーのハードウェアを自動更新すること", "機密情報が誤って共有・漏えいすることを検出し防止すること", "従業員の勤務時間を記録すること"], "a": 2, "e": "DLP ポリシーは、機密情報を含むコンテンツが不適切に共有・送信されることを検出し、必要に応じてブロックするための仕組みです。", "qEn": "What is the primary purpose of a data loss prevention (DLP) policy?", "oEn": ["To force users to periodically change their passwords", "To automatically update server hardware", "To detect and prevent sensitive information from being accidentally shared or leaked", "To record employees' working hours"], "eEn": "DLP policies detect content containing sensitive information that is being inappropriately shared or transmitted, and block it when necessary."}, {"d": "D4", "q": "Microsoft Purview の DLP ポリシーが適用可能な場所（ロケーション）として適切な組み合わせはどれですか。", "o": ["Exchange Online、SharePoint Online、OneDrive、Teams", "オンプレミスの電力設備、空調システム　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　", "従業員の自宅ネットワークのみ", "外部委託先の紙の書類のみ"], "a": 0, "e": "DLP ポリシーは Exchange Online、SharePoint Online、OneDrive、Microsoft Teams のチャットやチャネルメッセージ、さらにはデバイス上のファイルなど複数のロケーションに適用できます。", "qEn": "Which combination of locations can a Microsoft Purview DLP policy be applied to?", "oEn": ["Exchange Online, SharePoint Online, OneDrive, and Teams", "On-premises electrical systems and HVAC systems", "Only employees' home networks", "Only paper documents at an external contractor"], "eEn": "DLP policies can be applied to multiple locations, including Exchange Online, SharePoint Online, OneDrive, Microsoft Teams chats and channel messages, and even files on devices."}, {"d": "D4", "q": "DLP ポリシーにおける「ポリシーのヒント（policy tips）」の役割として正しいものはどれですか。", "o": ["サーバーのCPU使用率をグラフ表示する　　　　　　　　　　　　　　　　　　　　　", "ユーザーのライセンス残数を通知する", "ユーザーが機密情報を共有しようとした際に、リアルタイムで警告メッセージを表示する", "会議の開始時刻を自動的に変更する"], "a": 2, "e": "ポリシーのヒントは、ユーザーがメールやドキュメントで機密情報を共有しようとした際に、その場で警告や案内を表示する機能です。", "qEn": "What role do \"policy tips\" play in a DLP policy?", "oEn": ["They display a graph of server CPU utilization", "They notify users of their remaining license count", "They display a real-time warning message when a user attempts to share sensitive information", "They automatically change a meeting's start time"], "eEn": "Policy tips display an on-the-spot warning or guidance message when a user attempts to share sensitive information via email or a document."}, {"d": "D4", "q": "ラベル ポリシーで「既定のラベル」を設定した場合の動作として正しいものはどれですか。", "o": ["既存のすべてのファイルが即座に削除される", "対象ユーザーのライセンスが自動的に無効化される", "組織内のすべてのメールが暗号化されずに送信される　　　　　　　　　　　　　　　　　　　", "対象ユーザーが新規に作成したドキュメントやメールに、指定したラベルが自動的に適用される"], "a": 3, "e": "既定のラベルを設定すると、対象ユーザーが新しく作成するドキュメントやメールに、そのラベルが自動的に適用されます。", "qEn": "What happens when a \"default label\" is configured in a label policy?", "oEn": ["All existing files are immediately deleted", "The targeted users' licenses are automatically disabled", "All emails within the organization are sent without encryption", "The specified label is automatically applied to new documents and emails created by targeted users"], "eEn": "Configuring a default label causes it to be automatically applied to new documents and emails created by the targeted users."}, {"d": "D4", "q": "ラベル ポリシーの「ラベル付けを必須にする」設定を有効にした場合の効果として正しいものはどれですか。", "o": ["すべてのファイルが自動的に読み取り専用になる", "対象ユーザーがドキュメントやメールを保存・送信する前に、いずれかのラベルを選択することが求められる", "ユーザーのアカウントが強制的にロックされる", "Microsoft Purview のライセンスが自動更新される　　　　　　　　　　　　　　　　　"], "a": 1, "e": "ラベル付けを必須にする設定を有効にすると、対象ユーザーはドキュメントの保存やメールの送信前に、いずれかのラベルを選択しなければならなくなります。", "qEn": "What effect does enabling \"mandatory labeling\" in a label policy have?", "oEn": ["All files automatically become read-only", "Targeted users must select one of the labels before saving a document or sending an email", "User accounts are forcibly locked", "The Microsoft Purview license renews automatically"], "eEn": "Enabling mandatory labeling requires targeted users to select one of the available labels before saving a document or sending an email."}, {"d": "D4", "q": "ユーザーが機密ラベルをより低い保護レベルへ変更しようとした際に「正当な理由の入力」を要求する設定の目的はどれですか。", "o": ["ユーザーのパスワードを強制的に変更させること", "会議参加者の人数を制限すること", "サーバーのストレージ容量を自動的に拡張すること　　　　　　　　　　　　　　", "ラベルの格下げが不適切に行われないよう、変更理由を記録し監査可能にすること"], "a": 3, "e": "ラベルの格下げ時に理由入力を求める設定は、不適切なラベル変更を抑止するとともに、変更理由を記録して監査に役立てることを目的としています。", "qEn": "What is the purpose of requiring a \"justification\" when a user downgrades a sensitivity label to a lower protection level?", "oEn": ["To force the user to change their password", "To limit the number of meeting participants", "To automatically expand server storage capacity", "To discourage inappropriate label downgrades and record the reason for auditing purposes"], "eEn": "Requiring a justification when downgrading a label helps discourage inappropriate changes and records the stated reason for later audit review."}, {"d": "D4", "q": "機密ラベルを適用できる対象として正しい組み合わせはどれですか。", "o": ["Windows のデスクトップの壁紙のみ　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　　", "Office ファイル、電子メール、Microsoft Teams のチームや SharePoint サイトなどのコンテナー", "プリンターのファームウェアのみ", "ルーターの物理的なポート設定のみ"], "a": 1, "e": "機密ラベルは Office ファイルや電子メールだけでなく、Teams のチームや SharePoint サイト、Microsoft 365 グループのようなコンテナーにも適用できます。", "qEn": "Which combination of items can sensitivity labels be applied to?", "oEn": ["Only the desktop wallpaper on Windows", "Office files, email, and containers such as Microsoft Teams teams or SharePoint sites", "Only printer firmware", "Only the physical port configuration of a router"], "eEn": "Sensitivity labels can be applied not only to Office files and email but also to containers such as Teams teams, SharePoint sites, and Microsoft 365 groups."}, {"d": "D4", "q": "自動ラベル付け（auto-labeling）の説明として最も適切なものはどれですか。", "o": ["ユーザーが手動でラベルを1つずつ選択しなければならない仕組み　　　　　　　　　　　　　　", "ラベルポリシーを完全に無効化する機能", "ラベルの名前をランダムに変更する機能", "定義された条件に一致するコンテンツへ、ユーザーの操作なしにラベルを自動的に適用する仕組み"], "a": 3, "e": "自動ラベル付けは、指定した条件（機密情報の種類など）に一致するコンテンツに対して、ユーザーの操作を必要とせずラベルを自動的に適用する機能です。", "qEn": "What best describes auto-labeling?", "oEn": ["A mechanism that requires users to manually select a label one at a time", "A feature that completely disables label policies", "A feature that randomly renames labels", "A mechanism that automatically applies a label to content matching defined conditions, without requiring user action"], "eEn": "Auto-labeling automatically applies a label to content that matches specified conditions, such as containing a particular sensitive information type, without requiring any user action."}, {"d": "D4", "q": "複数の機密ラベルを作成する際、優先順位（プライオリティ）の考え方として正しいものはどれですか。", "o": ["リストの下位に表示されるラベルほど、より高い優先順位（より機密性の高い分類）を持つ", "ラベルの作成日が新しいものほど必ず優先順位が低くなる　　　　　　　　　　　　　　　", "優先順位はラベルの色によってのみ決まる", "優先順位という概念はラベルには存在しない"], "a": 0, "e": "機密ラベルの一覧では、下位に表示されるラベルほど優先順位が高く設定され、通常はより機密性の高い分類に対応します。", "qEn": "How does label priority work when multiple sensitivity labels are created?", "oEn": ["A label positioned lower in the list has a higher priority, typically corresponding to a more sensitive classification", "A more recently created label always has a lower priority", "Priority is determined solely by the label's color", "The concept of priority does not apply to sensitivity labels"], "eEn": "In the list of sensitivity labels, a label positioned lower has a higher priority, which typically corresponds to a more sensitive classification level."}, {"d": "D4", "q": "Microsoft Purview の保持ラベルの主な目的は何ですか。", "o": ["コンテンツを保持し必要に応じて削除も強制する", "コンテンツの暗号鍵を一元的に管理する　　　　", "デバイスの構成準拠状態を評価する", "外部共有リンクの有効期限を設定する"], "a": 0, "e": "保持ラベルはコンテンツ単位で保持期間や削除規則を適用するための機能です。暗号鍵管理やデバイス評価は保持ラベルの目的ではありません。", "qEn": "What is the primary purpose of a retention label in Microsoft Purview?", "oEn": ["Retain content and optionally enforce deletion afterward", "Centrally manage content encryption keys", "Evaluate device compliance configuration state", "Set expiration dates for external sharing links"], "eEn": "Retention labels apply retention periods and disposition rules at the item level; they are not for key management or device evaluation."}, {"d": "D4", "q": "規制レコード（Regulatory Record）ラベルを適用したコンテンツの特徴として正しいものはどれですか。", "o": ["権限を持つ管理者であればラベルを解除できる", "管理者を含め誰もラベルを解除・変更できない", "ラベルは180日後に自動的に解除される", "ラベル適用後もコンテンツ内容を編集できる"], "a": 1, "e": "規制レコードは最も厳格な保持設定で、保持期間が満了するまで管理者を含め誰も変更・削除できません。", "qEn": "Which statement correctly describes content labeled as a regulatory record in Microsoft Purview?", "oEn": ["An administrator with sufficient permission can remove the label", "No one, including administrators, can remove or alter the label", "The label is automatically removed after 180 days", "The content can still be edited after the label is applied"], "eEn": "A regulatory record is the strictest retention setting; the label cannot be removed or changed by anyone, including admins, until the retention period expires."}, {"d": "D4", "q": "保持ポリシーと保持ラベルの違いとして正しいものはどれですか。", "o": ["保持ポリシーはファイル単位、保持ラベルは場所単位に適用される", "保持ポリシーと保持ラベルはどちらもDLPルールの一種である", "保持ポリシーは場所単位、保持ラベルはアイテム単位に適用できる", "保持ラベルは常に保持ポリシーより優先度が低い"], "a": 2, "e": "保持ポリシーはメールボックスやサイトなど場所単位で適用され、保持ラベルは個々のアイテムに手動または自動で適用できます。", "qEn": "What is a correct difference between a retention policy and a retention label?", "oEn": ["A retention policy applies per file, a retention label applies per location", "Both retention policies and retention labels are types of DLP rules", "A retention policy applies at the location level, a retention label applies at the item level", "Retention labels always have lower priority than retention policies"], "eEn": "Retention policies apply to locations such as mailboxes or sites, while retention labels can be applied manually or automatically to individual items."}, {"d": "D4", "q": "レコード管理のファイルプラン（File Plan）が提供する機能はどれですか。", "o": ["ユーザーのサインインリスクを評価する機能", "外部共有されたファイルを自動的に暗号化する機能", "デバイスのコンプライアンスポリシーを適用する機能　　　　　　　　", "部門や参照番号などの詳細な保持ラベル分類を構造化して管理する機能"], "a": 3, "e": "ファイルプランは保持ラベルに部門、カテゴリ、参照番号などのメタデータを付与し、体系的に管理するための機能です。", "qEn": "What capability does the File Plan feature in records management provide?", "oEn": ["Evaluates sign-in risk for users", "Automatically encrypts externally shared files", "Applies device compliance policies", "Organizes retention labels with structured metadata such as department and reference ID"], "eEn": "File Plan lets you add metadata such as department, category, and reference ID to retention labels for structured records management."}, {"d": "D4", "q": "イベントベースの保持を使用する保持ラベルの動作として正しいものはどれですか。", "o": ["指定したイベントが発生した日を起点に保持期間のカウントが開始する", "ラベル作成日を起点に保持期間のカウントが開始する", "保持期間は常に固定日数でイベントとは無関係に開始する　　　　　　", "イベントが発生するとコンテンツが即座に削除される"], "a": 0, "e": "イベントベースの保持ラベルは、契約終了や従業員退職などの指定イベントの発生日を起点として保持期間の計算を開始します。", "qEn": "How does event-based retention behave for a retention label?", "oEn": ["Retention period counting starts on the date a specified event occurs", "Retention period counting starts on the date the label was created", "The retention period is always a fixed number of days unrelated to any event", "Content is deleted immediately when the event occurs"], "eEn": "Event-based retention starts the retention period clock on the date a specified event, such as contract end or employee departure, occurs."}, {"d": "D4", "q": "保持ラベルの処分レビュー（Disposition Review）の目的は何ですか。", "o": ["保持期間開始前にコンテンツを自動分類すること　　　　　　　　　　　　　　", "保持期間満了時にレビュー担当者が削除や保持延長を判断できるようにすること", "コンテンツの機密ラベルを自動的に変更すること", "監査ログへのアクセス権限を制御すること"], "a": 1, "e": "処分レビューは保持期間が満了したコンテンツについて、指定されたレビュー担当者が削除・保持延長などの最終判断を行うプロセスです。", "qEn": "What is the purpose of disposition review for a retention label?", "oEn": ["To automatically classify content before the retention period begins", "To let assigned reviewers decide whether to delete or extend retention when the period expires", "To automatically change the sensitivity label of content", "To control access permissions to audit logs"], "eEn": "Disposition review lets designated reviewers make the final decision, such as deleting or extending retention, when content reaches the end of its retention period."}, {"d": "D4", "q": "保持ポリシーの適応スコープ（Adaptive Scope）の特徴はどれですか。", "o": ["対象の場所リストを手動で固定し、変更しない　　　　　　　", "常にテナント内のすべての場所を対象にする", "属性やクエリに基づき対象ユーザーやサイトを動的に更新する", "保持ラベルの発行にのみ使用できる"], "a": 2, "e": "適応スコープは、ユーザー属性や条件に基づいて対象を動的に評価し、組織変更に応じて自動的に更新されます。", "qEn": "What characterizes an adaptive scope in a retention policy?", "oEn": ["It fixes the target location list manually and never changes", "It always targets every location in the tenant", "It dynamically updates target users or sites based on attributes or a query", "It can only be used for publishing retention labels"], "eEn": "An adaptive scope dynamically evaluates targets using attributes or query conditions, updating automatically as the organization changes."}, {"d": "D4", "q": "訓練可能な分類子（Trainable Classifier）を使用した保持ラベルの自動適用の説明として正しいものはどれですか。", "o": ["キーワードの完全一致のみでラベルを適用する", "手動でラベルを付与したコンテンツのみに適用される　　　　　　　　　　", "ファイルの拡張子のみを基準にラベルを適用する", "機械学習モデルがコンテンツのパターンを認識して自動でラベルを適用する"], "a": 3, "e": "訓練可能な分類子は機械学習を用いてコンテンツの内容パターンを認識し、条件に一致するコンテンツへ保持ラベルを自動的に適用します。", "qEn": "Which statement correctly describes auto-applying retention labels using a trainable classifier?", "oEn": ["It applies labels based only on exact keyword matches", "It only applies to content that has already been manually labeled", "It applies labels based solely on file extension", "A machine learning model recognizes content patterns and applies labels automatically"], "eEn": "Trainable classifiers use machine learning to recognize patterns in content and automatically apply a retention label to matching items."}, {"d": "D4", "q": "複数の保持ポリシーやラベルが競合した場合の基本原則として正しいものはどれですか。", "o": ["保持が削除より優先される（Retention wins over deletion）", "最も新しく適用されたポリシーが常に優先される", "削除が保持より優先される", "管理者が手動で選択したポリシーのみが有効になる　　　　　　　　　　　　　　　　　　　"], "a": 0, "e": "Microsoft Purview の保持の原則では、コンテンツの保持が必要と判断された場合、削除の指示より保持が優先されます。", "qEn": "What is the fundamental principle when multiple retention policies or labels conflict?", "oEn": ["Retention wins over deletion", "The most recently applied policy always takes precedence", "Deletion always wins over retention", "Only the policy manually selected by an admin applies"], "eEn": "Under Microsoft Purview's retention principles, if any policy requires content to be retained, retention takes precedence over any instruction to delete it."}, {"d": "D4", "q": "保持ラベルをユーザーが利用できるようにするために必要な手順はどれですか。", "o": ["ラベルをレコードとして分類するだけでよい", "ラベルポリシーを作成してラベルを発行する", "監査ログの設定を有効にする", "データ損失防止ポリシーを作成する"], "a": 1, "e": "作成した保持ラベルはそのままでは利用できず、ラベルポリシーで発行することでユーザーやアプリで使用可能になります。", "qEn": "What step is required before users can apply a retention label?", "oEn": ["Simply classifying the label as a record is enough", "Create a label policy to publish the label", "Enable audit log settings", "Create a data loss prevention policy"], "eEn": "A retention label cannot be used as-is; it must be published through a label policy before users or apps can apply it."}, {"d": "D4", "q": "通常の「レコード」ラベル（規制レコードではない）が適用されたコンテンツについて正しい説明はどれですか。", "o": ["誰であってもラベルの解除は一切できない　　　　　　　　", "保持期間に関係なくいつでも削除できる", "十分な権限を持つ管理者であればラベルの解除や変更が可能", "自動的に機密ラベルへ変換される"], "a": 2, "e": "通常のレコードラベルは規制レコードよりも制約が緩く、十分な権限を持つ管理者はラベルを解除・変更できます。", "qEn": "Which statement correctly describes content labeled as a standard record (not a regulatory record)?", "oEn": ["No one can ever remove the label", "It can be deleted at any time regardless of the retention period", "An administrator with sufficient permission can remove or change the label", "It is automatically converted into a sensitivity label"], "eEn": "A standard record label is less restrictive than a regulatory record; an administrator with sufficient permission can remove or modify it."}, {"d": "D4", "q": "Microsoft Purview の保持ポリシーが適用できる対象サービスの組み合わせとして適切なものはどれですか。", "o": ["Azure Active Directory のグループのみ　　　　　　　　　　　　", "Microsoft Defender のデバイスのみ", "Power BI のダッシュボードのみ", "Exchange、SharePoint、OneDrive、Teams など複数の場所"], "a": 3, "e": "保持ポリシーはExchangeメールボックス、SharePointサイト、OneDrive、Teamsのチャットやチャネルなど複数の場所に適用できます。", "qEn": "Which set of locations can a Microsoft Purview retention policy be applied to?", "oEn": ["Only Azure Active Directory groups", "Only Microsoft Defender managed devices", "Only Power BI dashboards", "Multiple locations such as Exchange, SharePoint, OneDrive, and Teams"], "eEn": "A retention policy can apply to multiple locations, including Exchange mailboxes, SharePoint sites, OneDrive, and Teams chats and channels."}, {"d": "D4", "q": "レコード管理の保持ラベルで設定できる項目として正しいものはどれですか。", "o": ["保持期間の長さと期間満了時のアクション（削除、レビューなど）", "ユーザーのライセンス割り当て状況", "デバイスのオペレーティングシステムの種類　　　　　　　　　　", "ネットワークのファイアウォールルール"], "a": 0, "e": "保持ラベルでは保持期間の長さと、満了時に実行するアクション（削除、レビューへの送付など）を設定します。", "qEn": "What can be configured in a records management retention label?", "oEn": ["The length of the retention period and the action to take at expiration, such as deletion or review", "A user's license assignment status", "The operating system type of a device", "Network firewall rules"], "eEn": "A retention label lets you configure the length of the retention period and the action to take when it expires, such as deletion or sending it for review."}, {"d": "D4", "q": "「アンロック済みレコード」ラベルの特徴として正しいものはどれですか。", "o": ["コンテンツの削除が完全に禁止される", "十分な権限があればラベル解除や一部の変更が可能", "ラベルは自動的に規制レコードへ昇格する　　　　", "保持期間が無期限に固定される"], "a": 1, "e": "アンロック済みレコードは、十分な権限を持つユーザーであればラベルの解除や変更ができる、比較的制約の緩いレコード設定です。", "qEn": "What characterizes an unlocked record label?", "oEn": ["Deletion of the content is completely prohibited", "Users with sufficient permission can remove the label or make some changes", "The label automatically upgrades to a regulatory record", "The retention period is fixed as indefinite"], "eEn": "An unlocked record is a relatively less restrictive setting where users with sufficient permission can remove the label or make certain changes."}, {"d": "D4", "q": "Microsoft Teams のチャットやチャネルメッセージに保持ポリシーを適用する場合の説明として正しいものはどれですか。", "o": ["チャットとチャネルメッセージは同一の保持設定しか使えない　　　", "保持ポリシーはTeams会議の録画にのみ適用される", "チャットとチャネルメッセージにそれぞれ別の保持設定を構成できる", "Teamsメッセージには保持ポリシーを適用できない"], "a": 2, "e": "Teamsの保持ポリシーでは、チャットメッセージとチャネルメッセージに対してそれぞれ独立した保持設定を構成できます。", "qEn": "What is true about applying a retention policy to Microsoft Teams chats and channel messages?", "oEn": ["Chats and channel messages must use the exact same retention setting", "The retention policy only applies to Teams meeting recordings", "Separate retention settings can be configured for chats and channel messages", "Retention policies cannot be applied to Teams messages"], "eEn": "A Teams retention policy allows independent retention settings to be configured for chat messages and channel messages."}, {"d": "D4", "q": "Microsoft Purview の内部者リスク管理（Insider Risk Management）の主な目的は何ですか。", "o": ["外部からの不正アクセスをリアルタイムでブロックすること　　　　　　　　", "組織全体のネットワーク帯域を監視すること", "デバイスのマルウェア感染を検出すること", "組織内のシグナルを分析し、リスクの高い内部者の行動を検出・調査すること"], "a": 3, "e": "内部者リスク管理はMicrosoft 365内の様々なシグナルを分析し、データ漏えいや情報窃取などリスクの高い活動を検出・調査するための機能です。", "qEn": "What is the primary purpose of Insider Risk Management in Microsoft Purview?", "oEn": ["To block unauthorized external access in real time", "To monitor the organization's overall network bandwidth", "To detect malware infections on devices", "To analyze signals across the organization to detect and investigate risky insider activity"], "eEn": "Insider Risk Management analyzes signals across Microsoft 365 to detect and investigate risky activities such as data leaks or data theft."}, {"d": "D4", "q": "退職予定の従業員によるデータ持ち出しリスクに対応するために使用するポリシーテンプレートはどれですか。", "o": ["退職予定の従業員によるデータ窃取ポリシー", "セキュリティポリシー違反ポリシー　　　　", "利益相反の検出ポリシー", "データ漏えいポリシー"], "a": 0, "e": "退職予定の従業員によるデータ窃取ポリシーテンプレートは、HRコネクタなどからの退職情報と連動し、退職前後のデータ持ち出しリスクを検出します。", "qEn": "Which policy template addresses the risk of data exfiltration by employees who are about to leave the organization?", "oEn": ["Data theft by departing employees", "Security policy violations", "Conflict of interest detection", "Data leaks"], "eEn": "The data theft by departing employees template works with signals such as resignation dates from an HR connector to detect exfiltration risk around departure."}, {"d": "D4", "q": "内部者リスク管理でデフォルトで有効な、ユーザーのプライバシーを保護する仕組みはどれですか。", "o": ["ユーザーの実名を管理者ポータルに常時表示する　　　　", "ケースが作成されるまでユーザー名を仮名化して表示する", "すべての操作ログを削除して匿名化する", "ユーザーのメール送受信を完全にブロックする"], "a": 1, "e": "内部者リスク管理は既定でプライバシーを重視した設計となっており、調査担当者にはケース作成前はユーザー名が仮名化された状態で表示されます。", "qEn": "What privacy-protecting mechanism is enabled by default in Insider Risk Management?", "oEn": ["The user's real name is always shown in the admin portal", "User names are pseudonymized until a case is opened", "All activity logs are deleted to anonymize users", "The user's email sending and receiving is fully blocked"], "eEn": "Insider Risk Management is privacy-by-design by default, showing pseudonymized user names to investigators until a case is formally opened."}, {"d": "D4", "q": "内部者リスク管理でHRコネクタを使用する目的として正しいものはどれですか。", "o": ["デバイスのソフトウェアインベントリを収集する　　　　　　　　　", "ネットワークトラフィックのログを収集する", "従業員の退職日などの人事情報をポリシーのトリガーとして取り込む", "外部ベンダーの請求情報を同期する"], "a": 2, "e": "HRコネクタは退職日や異動日などの人事情報をインポートし、退職予定の従業員ポリシーなどのトリガーとして利用します。", "qEn": "What is the purpose of using an HR connector in Insider Risk Management?", "oEn": ["To collect a device's software inventory", "To collect network traffic logs", "To import HR data such as resignation dates to trigger policies", "To synchronize billing information from external vendors"], "eEn": "An HR connector imports HR data, such as resignation or termination dates, used to trigger policies like the departing employee template."}, {"d": "D4", "q": "Adaptive Protection（適応型保護）機能の説明として正しいものはどれですか。", "o": ["すべてのユーザーに一律の厳格なDLPルールを適用する　　　　　　", "デバイスのファームウェアを自動更新する", "外部委託先のアクセス権を完全に無効化する", "内部者リスクの評価結果に基づき、DLPなどの制御を動的に調整する"], "a": 3, "e": "Adaptive Protectionは内部者リスク管理の分析結果を利用し、リスクレベルに応じてデータ損失防止ポリシーなどの制御を動的に適用します。", "qEn": "Which statement correctly describes Adaptive Protection?", "oEn": ["It applies the same strict DLP rules uniformly to all users", "It automatically updates device firmware", "It completely disables access for external vendors", "It dynamically adjusts controls such as DLP based on insider risk assessment results"], "eEn": "Adaptive Protection uses insights from Insider Risk Management to dynamically apply controls, such as DLP policies, based on a user's assessed risk level."}, {"d": "D4", "q": "内部者リスク管理のロールグループのうち、ポリシーの作成や設定を行うのはどのロールですか。", "o": ["内部者リスク管理管理者", "内部者リスク管理閲覧者のみ", "コンプライアンス管理者専用の固定ロール", "監査担当者ロール"], "a": 0, "e": "内部者リスク管理管理者ロールに割り当てられたユーザーが、ポリシーの作成、編集、削除などの設定作業を行います。", "qEn": "Which Insider Risk Management role group is responsible for creating and configuring policies?", "oEn": ["Insider Risk Management Admins", "Insider Risk Management Viewers only", "A fixed role exclusive to Compliance Administrators", "The Auditor role"], "eEn": "Users assigned to the Insider Risk Management Admins role group create, edit, and configure policies and settings."}, {"d": "D4", "q": "内部者リスク管理における「シーケンス」機能の役割は何ですか。", "o": ["単一のアラートを重要度別に色分けする", "一連の関連する活動パターンを時系列で結び付けて可視化する", "デバイスのOSバージョンを一覧表示する　　　　　　　　　", "ユーザーのライセンス使用状況を集計する"], "a": 1, "e": "シーケンス機能は、関連する複数のリスク活動を時系列でつなぎ合わせ、一連の行動パターンとして調査担当者に提示します。", "qEn": "What role does the 'sequences' feature play in Insider Risk Management?", "oEn": ["It color-codes a single alert by severity", "It links a series of related risky activities together in chronological order for visualization", "It lists device operating system versions", "It aggregates user license usage statistics"], "eEn": "Sequences connect multiple related risky activities in chronological order, presenting them to investigators as a coherent pattern of behavior."}, {"d": "D4", "q": "内部者リスク管理の「分析」（Analytics）機能について正しい説明はどれですか。", "o": ["ポリシー作成後にのみ実行できる機能である", "特定ユーザーの実名を含む詳細レポートを生成する　　　　　　　　　　　", "ポリシー作成前にテナント全体の潜在的リスクを個人を特定しない形で示す", "外部委託業者向けの請求書を自動生成する"], "a": 2, "e": "分析機能はポリシーを作成する前に、個人を特定しない形でテナント全体の潜在的なリスク傾向を可視化し、導入判断を支援します。", "qEn": "What is true about the Analytics feature in Insider Risk Management?", "oEn": ["It can only be run after a policy has been created", "It generates detailed reports containing specific users' real names", "Before any policy is created, it shows tenant-wide potential risk without identifying individuals", "It automatically generates invoices for external vendors"], "eEn": "Analytics shows tenant-wide potential risk trends without identifying individuals before any policy is created, helping justify policy adoption."}, {"d": "D4", "q": "内部者リスク管理でアラートが生成された後の一般的な流れとして正しいものはどれですか。", "o": ["アラートは自動的に削除され記録は残らない", "アラートは直接ユーザーへ警告メールとして送信される　　　　　", "アラートはDLPポリシーへ即座に変換される", "アラートをトリアージし、必要に応じてケースを作成して調査する"], "a": 3, "e": "生成されたアラートは調査担当者がトリアージし、詳細な調査が必要な場合はケースを作成してさらに調査を進めます。", "qEn": "What is the typical flow after an alert is generated in Insider Risk Management?", "oEn": ["The alert is automatically deleted and no record remains", "The alert is sent directly to the user as a warning email", "The alert is immediately converted into a DLP policy", "The alert is triaged, and a case is created for further investigation if needed"], "eEn": "Generated alerts are triaged by investigators, who create a case for deeper investigation when warranted."}, {"d": "D4", "q": "「データ漏えい」ポリシーテンプレートが検出しようとする活動として正しいものはどれですか。", "o": ["通常と異なる大量のデータ共有や送信などの不審な活動", "ユーザーのパスワード変更頻度　　　　　　　　　　　", "デバイスのバッテリー消費状況", "会議の出席率の低下"], "a": 0, "e": "データ漏えいポリシーテンプレートは、通常のパターンから逸脱した大量のデータ共有や外部送信などの不審な活動を検出します。", "qEn": "What kind of activity does the 'data leaks' policy template aim to detect?", "oEn": ["Unusual activity such as sharing or sending an abnormally large volume of data", "How frequently a user changes their password", "A device's battery consumption pattern", "A decline in meeting attendance rates"], "eEn": "The data leaks policy template detects suspicious activity that deviates from normal patterns, such as sharing or sending unusually large volumes of data."}, {"d": "D4", "q": "eDiscovery（Standard）が標準で含まれるライセンスとして正しいものはどれですか。", "o": ["Microsoft 365 E5 の追加コンプライアンスアドオンのみ", "Microsoft 365 E3 などの主要なプラン", "Windows 11 Enterprise 単体ライセンス", "Azure サブスクリプションの基本層のみ"], "a": 1, "e": "eDiscovery（Standard）はMicrosoft 365 E3を含む多くの主要なライセンスプランに標準で含まれています。", "qEn": "Which license typically includes eDiscovery (Standard) as a standard capability?", "oEn": ["Only the Microsoft 365 E5 compliance add-on", "Major plans such as Microsoft 365 E3", "A standalone Windows 11 Enterprise license", "Only the basic tier of an Azure subscription"], "eEn": "eDiscovery (Standard) is included as a standard capability in many major license plans, including Microsoft 365 E3."}, {"d": "D4", "q": "eDiscovery（Premium）がStandardに加えて提供する機能はどれですか。", "o": ["基本的なコンテンツ検索機能", "保持ラベルの作成機能", "カストディアン管理と法的保留通知の管理機能", "ウイルス対策シグネチャの更新機能　　　　　"], "a": 2, "e": "eDiscovery（Premium）はStandardの機能に加え、カストディアン管理や法的保留通知など、より高度な訴訟対応機能を提供します。", "qEn": "What additional capability does eDiscovery (Premium) provide beyond eDiscovery (Standard)?", "oEn": ["Basic content search functionality", "Creation of retention labels", "Custodian management and legal hold notification management", "Updating antivirus signature definitions"], "eEn": "eDiscovery (Premium) adds advanced litigation capabilities on top of Standard, including custodian management and legal hold notifications."}, {"d": "D4", "q": "Content Search（コンテンツ検索）ツールの役割として正しいものはどれですか。", "o": ["デバイスのコンプライアンス状態を評価する　　　　　　　　　　　　　　　　　　　", "保持ラベルの発行を自動化する", "ユーザーのサインインリスクを算出する", "Microsoft 365全体のコンテンツをクエリで検索する基盤機能を提供する"], "a": 3, "e": "Content Searchはeディスカバリーの基盤となる検索機能で、Microsoft 365全体のメールやファイルをクエリを使って検索できます。", "qEn": "What role does the Content Search tool play?", "oEn": ["It evaluates a device's compliance status", "It automates the publishing of retention labels", "It calculates a user's sign-in risk score", "It provides the underlying capability to query and search content across Microsoft 365"], "eEn": "Content Search is the foundational search capability behind eDiscovery, letting you query mail and files across Microsoft 365."}, {"d": "D4", "q": "eDiscoveryにおける「ケース」の役割として正しいものはどれですか。", "o": ["保留、検索、エクスポートなどの調査作業を関連付けて管理する入れ物", "ユーザーのライセンス割り当てを管理する単位", "デバイスのファームウェア更新をスケジュールする単位　　　　　　　", "外部委託業者との契約書を保管するフォルダー"], "a": 0, "e": "eDiscoveryケースは、保留・検索・エクスポートなど特定の調査に関連する作業をまとめて管理するための入れ物です。", "qEn": "What is the role of a 'case' in eDiscovery?", "oEn": ["A container that organizes and manages related investigation work such as holds, searches, and exports", "A unit for managing user license assignments", "A unit for scheduling device firmware updates", "A folder for storing contracts with external vendors"], "eEn": "An eDiscovery case is a container that groups and manages related investigation activities, such as holds, searches, and exports."}, {"d": "D4", "q": "eDiscovery（Premium）の分析機能が提供するものとして正しいものはどれですか。", "o": ["デバイスのマルウェアスキャン結果　　　　　　　　　　　　　　　　", "類似文書の検出やメールスレッド解析によるレビューセットの絞り込み", "ネットワーク帯域使用量のレポート", "ユーザーのパスワード強度分析"], "a": 1, "e": "eDiscovery（Premium）の分析機能は、類似文書検出やメールスレッド解析を行い、レビューが必要なコンテンツ量を絞り込みます。", "qEn": "What does the analytics capability in eDiscovery (Premium) provide?", "oEn": ["Malware scan results for devices", "Near-duplicate detection and email threading to narrow down the review set", "Reports on network bandwidth usage", "Analysis of user password strength"], "eEn": "eDiscovery (Premium) analytics performs near-duplicate detection and email threading to reduce the volume of content that needs review."}, {"d": "D4", "q": "法的保留（Legal Hold）を適用した場合の効果として正しいものはどれですか。", "o": ["コンテンツが自動的に暗号化される", "コンテンツが即座に別のテナントへ移行される", "ユーザーが削除や変更を試みてもコンテンツが保持される", "コンテンツの機密ラベルが自動的に引き上げられる　　　"], "a": 2, "e": "法的保留を適用すると、ユーザーがコンテンツを削除・変更しようとしても、元の状態がそのまま保持されます。", "qEn": "What is the effect of applying a legal hold?", "oEn": ["The content is automatically encrypted", "The content is immediately migrated to another tenant", "The content is preserved even if a user tries to delete or modify it", "The content's sensitivity label is automatically upgraded"], "eEn": "Applying a legal hold preserves content in its original state even if a user attempts to delete or modify it."}, {"d": "D4", "q": "eDiscovery（Premium）のレビューセットに関する説明として正しいものはどれですか。", "o": ["元データを直接編集するための領域である　　　　　　　　　　　　　　　　　　　　　", "デバイスのハードウェア構成一覧である", "監査ログの保存期間を設定する画面である", "レビュー用にエクスポートされたコンテンツのコピーを保持しタグ付けできる領域である"], "a": 3, "e": "レビューセットは調査対象コンテンツのコピーを格納し、タグ付けやレビューを行うための作業領域です。元データは変更されません。", "qEn": "What is true about a review set in eDiscovery (Premium)?", "oEn": ["It is an area for directly editing the original source data", "It is a list of device hardware configurations", "It is a screen for configuring audit log retention duration", "It holds copies of exported content for review and lets reviewers apply tags"], "eEn": "A review set stores copies of content relevant to an investigation, providing a workspace for tagging and reviewing without altering the original data."}, {"d": "D4", "q": "eDiscoveryにおける「カストディアン」とは何を指しますか。", "o": ["調査対象データに関連する可能性がある人物で、法的保留通知の対象となる", "コンプライアンスポータルの管理者権限を持つロール　　　　　　　　　　", "外部の監査法人が発行する証明書", "自動的に適用される保持ラベルの種類"], "a": 0, "e": "カストディアンとは調査に関連する可能性のあるデータを保有する人物のことで、Premiumでは法的保留通知を通じて連絡できます。", "qEn": "What does a 'custodian' refer to in eDiscovery?", "oEn": ["A person who may hold data relevant to an investigation, and who is notified via legal hold notifications", "An administrative role with permissions in the compliance portal", "A certificate issued by an external audit firm", "A type of automatically applied retention label"], "eEn": "A custodian is a person who may possess data relevant to an investigation; in Premium, custodians can be contacted through legal hold notifications."}, {"d": "D4", "q": "eDiscovery（Standard）で実行できる基本的な作業として正しいものはどれですか。", "o": ["従業員の給与明細を管理する", "ケースの作成、保留の設定、検索、エクスポートを行う", "デバイスのOSライセンスを再割り当てする", "ネットワークファイアウォールのルールを変更する　　"], "a": 1, "e": "eDiscovery（Standard）ではケースを作成し、保留の設定、コンテンツの検索、検索結果のエクスポートといった基本的な調査作業ができます。", "qEn": "What basic tasks can you perform with eDiscovery (Standard)?", "oEn": ["Manage employee payroll statements", "Create cases, place holds, search content, and export results", "Reassign a device's operating system license", "Change network firewall rules"], "eEn": "eDiscovery (Standard) supports basic investigation tasks: creating cases, placing holds, searching content, and exporting search results."}, {"d": "D4", "q": "eDiscovery（Premium）を利用するために一般的に必要となるライセンスはどれですか。", "o": ["Microsoft 365 Business Basic　　　　　　　", "Exchange Online Plan 1 単体", "Microsoft 365 E5 またはコンプライアンス関連のアドオン", "Windows 10 Pro のOEMライセンス"], "a": 2, "e": "eDiscovery（Premium）はMicrosoft 365 E5、またはE3に追加するコンプライアンス関連のアドオンライセンスで利用可能になります。", "qEn": "Which license is typically required to use eDiscovery (Premium)?", "oEn": ["Microsoft 365 Business Basic", "Exchange Online Plan 1 alone", "Microsoft 365 E5, or a related compliance add-on", "An OEM license for Windows 10 Pro"], "eEn": "eDiscovery (Premium) is available with Microsoft 365 E5 or with a compliance-related add-on license applied on top of E3."}, {"d": "D4", "q": "Microsoft Purview の監査（Standard）における監査ログの既定の保持期間はどのくらいですか。", "o": ["30日間　", "90日間", "1年間", "180日間"], "a": 3, "e": "監査（Standard）では監査ログレコードは既定で180日間保持されます。", "qEn": "What is the default retention period for audit log records under Audit (Standard)?", "oEn": ["30 days", "90 days", "One year", "180 days"], "eEn": "Under Audit (Standard), audit log records are retained for 180 days by default."}, {"d": "D4", "q": "Microsoft Purview の監査（Premium）における監査ログの既定の保持期間はどのくらいですか。", "o": ["1年間（追加ライセンスで最大10年まで延長可能）", "30日間で固定", "常に無期限で自動保持　　　　　　　　　　　　　　", "90日間で固定"], "a": 0, "e": "監査（Premium）では既定で1年間ログが保持され、追加のライセンスにより最大10年まで延長できます。", "qEn": "What is the default retention period for audit log records under Audit (Premium)?", "oEn": ["One year (extendable up to 10 years with an additional license)", "A fixed 30 days", "Always indefinite retention automatically", "A fixed 90 days"], "eEn": "Under Audit (Premium), logs are retained for one year by default, extendable up to 10 years with an additional license."}, {"d": "D4", "q": "監査ログの検索は主にどこから実行しますか。", "o": ["Azureポータルのネットワークセクション", "Microsoft Purview コンプライアンスポータルの監査機能", "Windows デバイスマネージャー", "Microsoft Endpoint Manager 管理コンソール　"], "a": 1, "e": "監査ログの検索は主にMicrosoft Purviewコンプライアンスポータルの監査（Audit）機能から実行します。", "qEn": "Where is audit log search typically performed?", "oEn": ["The networking section of the Azure portal", "The Audit feature in the Microsoft Purview compliance portal", "Windows Device Manager", "The Microsoft Endpoint Manager admin console"], "eEn": "Audit log searches are typically performed from the Audit feature within the Microsoft Purview compliance portal."}, {"d": "D4", "q": "監査（Premium）が提供する技術的な利点として正しいものはどれですか。", "o": ["監査ログの保存先を無制限に拡張できる　　　　　　　　　　　　　　　　　　　　　　　　　　", "監査ログを暗号化なしで出力できる", "監査関連のManagement Activity APIへより高い帯域幅でアクセスできる", "すべての監査ログを自動的に削除できる"], "a": 2, "e": "監査（Premium）ではManagement Activity APIへのアクセス帯域幅がStandardより高く設定され、大量のログをより効率的に取得できます。", "qEn": "What technical advantage does Audit (Premium) provide?", "oEn": ["Unlimited expansion of the audit log storage location", "The ability to export audit logs without encryption", "Higher bandwidth access to the audit-related Management Activity API", "Automatic deletion of all audit logs"], "eEn": "Audit (Premium) provides higher bandwidth access to the Management Activity API than Standard, enabling more efficient retrieval of large volumes of logs."}, {"d": "D4", "q": "監査（Premium）で提供される「重要イベント」の例として、メールアクセスのフォレンジック調査に役立つものはどれですか。", "o": ["UserLoggedIn　　　　　", "FileModified", "GroupCreated", "MailItemsAccessed"], "a": 3, "e": "MailItemsAccessedは監査（Premium）で提供される重要イベントの一つで、メールボックス内のアイテムへのアクセスを記録し、フォレンジック調査に役立ちます。", "qEn": "Which crucial event provided by Audit (Premium) is useful for forensic investigation of mailbox access?", "oEn": ["UserLoggedIn", "FileModified", "GroupCreated", "MailItemsAccessed"], "eEn": "MailItemsAccessed is one of the crucial events available in Audit (Premium); it records access to mailbox items and supports forensic investigations."}, {"d": "D4", "q": "監査（Standard）が標準で含まれるライセンスとして正しいものはどれですか。", "o": ["多くの主要なMicrosoft 365およびOffice 365のプラン", "Azure仮想マシンの従量課金プランのみ", "Windowsのボリュームライセンスのみ", "GitHub Enterprise の単体プランのみ　　　　　　　　　　"], "a": 0, "e": "監査（Standard）は多くの主要なMicrosoft 365およびOffice 365プランに標準で含まれています。", "qEn": "Which license typically includes Audit (Standard) as a standard capability?", "oEn": ["Most major Microsoft 365 and Office 365 plans", "Only a pay-as-you-go Azure virtual machine plan", "Only a Windows volume license", "Only a standalone GitHub Enterprise plan"], "eEn": "Audit (Standard) is included as a standard capability in most major Microsoft 365 and Office 365 plans."}, {"d": "D4", "q": "監査（Premium）の機能を利用するために一般的に必要なライセンスはどれですか。", "o": ["Microsoft 365 Business Premium 単体　", "Microsoft 365 E5 またはコンプライアンス関連アドオン", "Exchange Online Kiosk", "Microsoft Defender for IoT のみ"], "a": 1, "e": "監査（Premium）はMicrosoft 365 E5、またはコンプライアンス関連のアドオンライセンスを追加することで利用できます。", "qEn": "Which license is typically required to use Audit (Premium) features?", "oEn": ["Microsoft 365 Business Premium alone", "Microsoft 365 E5, or a related compliance add-on", "Exchange Online Kiosk", "Microsoft Defender for IoT alone"], "eEn": "Audit (Premium) becomes available with Microsoft 365 E5, or by adding a related compliance add-on license."}, {"d": "D4", "q": "Microsoft Purview の監査（Audit）機能の主な目的は何ですか。", "o": ["デバイスのウイルス定義ファイルを更新すること　　　　　　　　　　　　　　　　　", "ネットワークの帯域幅を最適化すること", "Microsoft 365全体のユーザーおよび管理者の操作を記録・追跡すること", "外部委託業者への請求を自動生成すること"], "a": 2, "e": "監査機能はMicrosoft 365サービス全体で行われたユーザーおよび管理者の操作を記録し、追跡できるようにする機能です。", "qEn": "What is the primary purpose of the Audit feature in Microsoft Purview?", "oEn": ["To update antivirus definition files on devices", "To optimize network bandwidth", "To record and track user and administrator activities across Microsoft 365", "To automatically generate invoices for external vendors"], "eEn": "The Audit feature records and enables tracking of user and administrator activities performed across Microsoft 365 services."}, {"d": "D4", "q": "監査（Premium）がフォレンジック調査を支援する方法として正しいものはどれですか。", "o": ["調査対象デバイスを自動的にシャットダウンする　　　　　", "調査担当者の権限を自動的に昇格させる", "調査結果をソーシャルメディアに公開する", "重要イベントなどのインテリジェントな分析情報を提供する"], "a": 3, "e": "監査（Premium）はMailItemsAccessedなどの重要イベントを含むインテリジェントな分析情報を提供し、侵害調査などのフォレンジック分析を支援します。", "qEn": "How does Audit (Premium) support forensic investigations?", "oEn": ["By automatically shutting down the device under investigation", "By automatically elevating an investigator's permissions", "By publishing investigation results to social media", "By providing intelligent insights such as crucial events"], "eEn": "Audit (Premium) supports forensic analysis, such as breach investigations, by providing intelligent insights that include crucial events like MailItemsAccessed."}, {"d": "D4", "q": "コンプライアンス調査において監査ログが役立つ理由として正しいものはどれですか。", "o": ["誰がいつ何を行ったかを記録として確認できるため", "ユーザーのライセンスコストを自動的に削減できるため", "デバイスのバッテリー寿命を延ばせるため", "ネットワーク遅延を自動的に解消できるため"], "a": 0, "e": "監査ログには誰が、いつ、どのような操作を行ったかが記録されており、コンプライアンス調査における証跡として活用できます。", "qEn": "Why are audit logs useful in a compliance investigation?", "oEn": ["Because they provide a record of who did what and when", "Because they automatically reduce user license costs", "Because they extend a device's battery life", "Because they automatically resolve network latency"], "eEn": "Audit logs record who performed what action and when, serving as evidence trails useful in compliance investigations."}, {"d": "D4", "q": "Microsoft Purview のデータマップ（Data Map）の役割として正しいものはどれですか。", "o": ["ユーザーのライセンス使用状況を課金する", "データ資産のメタデータを収集し、ガバナンスの基盤となるカタログを維持する", "デバイスのファームウェアを自動更新する", "ネットワークファイアウォールのルールを構成する　　　　　　　　　　　　　"], "a": 1, "e": "データマップはハイブリッドなデータ資産全体からメタデータを収集し、データガバナンスの基盤となるカタログを維持します。", "qEn": "What role does the Microsoft Purview Data Map play?", "oEn": ["It bills users based on their license usage", "It collects metadata from data assets and maintains the catalog that underpins governance", "It automatically updates device firmware", "It configures network firewall rules"], "eEn": "The Data Map collects metadata across a hybrid data estate and maintains the foundational catalog used for data governance."}, {"d": "D4", "q": "Microsoft Purview のデータカタログ（Data Catalog）を使ってユーザーができることは何ですか。", "o": ["デバイスのセキュリティパッチを適用する", "監査ログの保存期間を延長する", "組織内のデータ資産を検索し発見する", "外部共有リンクの有効期限を管理する"], "a": 2, "e": "データカタログはビジネス用語集やメタデータを活用し、組織内のデータ資産を検索・発見できるようにする機能です。", "qEn": "What can users do with the Microsoft Purview Data Catalog?", "oEn": ["Apply security patches to devices", "Extend the audit log retention period", "Search for and discover data assets across the organization", "Manage expiration dates for external sharing links"], "eEn": "The Data Catalog leverages business glossary terms and metadata to let users search for and discover data assets across the organization."}, {"d": "D4", "q": "Microsoft Purview のガバナンスにおける「データキュレーター」の役割として正しいものはどれですか。", "o": ["デバイスのハードウェア保守を担当する　　　　　　　　　　", "ネットワークの帯域割り当てを管理する", "監査ログの検索クエリを実行する", "コレクション内のデータ資産の管理とアクセス権の付与を行う"], "a": 3, "e": "データキュレーターはコレクション内のデータ資産の管理や、アクセス権限の付与などを担当するロールです。", "qEn": "What is the role of a 'data curator' in Microsoft Purview governance?", "oEn": ["Handling hardware maintenance for devices", "Managing network bandwidth allocation", "Running audit log search queries", "Managing data assets within a collection and granting access permissions"], "eEn": "A data curator is a role responsible for managing data assets within a collection and granting access permissions to them."}, {"d": "D4", "q": "データマップのスキャン機能が行うこととして正しいものはどれですか。", "o": ["データソースを自動的にスキャンして分類し、メタデータを収集する", "ユーザーのパスワードを定期的にリセットする　　　　　　　　　　", "デバイスの位置情報を追跡する", "ネットワークの帯域幅を制限する"], "a": 0, "e": "データマップのスキャン機能は、登録されたデータソースを自動的にスキャンして分類し、資産のメタデータを収集します。", "qEn": "What does scanning in the Data Map accomplish?", "oEn": ["Automatically scans and classifies data sources while collecting metadata", "Periodically resets user passwords", "Tracks a device's geographic location", "Limits network bandwidth"], "eEn": "Scanning in the Data Map automatically scans and classifies registered data sources, collecting metadata about the assets."}, {"d": "D4", "q": "ビジネス用語集（Business Glossary）の目的として正しいものはどれですか。", "o": ["デバイスのライセンスキーを一元管理する", "組織共通の用語を定義し、データ資産と関連付ける", "ネットワークルーティングテーブルを構成する　　", "監査ログのアーカイブ場所を指定する"], "a": 1, "e": "ビジネス用語集は組織全体で共通の用語を定義し、それをデータ資産に関連付けることで、データの意味を統一的に理解できるようにします。", "qEn": "What is the purpose of a business glossary?", "oEn": ["To centrally manage device license keys", "To define common organizational terms and link them to data assets", "To configure network routing tables", "To specify the archive location for audit logs"], "eEn": "A business glossary defines terms common across the organization and links them to data assets, providing a shared understanding of data meaning."}, {"d": "D4", "q": "Microsoft Purview ガバナンスにおける「コレクション」の役割として正しいものはどれですか。", "o": ["デバイスのファームウェアバージョンを分類する　　　　　　", "ネットワークセグメントを暗号化する", "データ資産を階層的に整理し、アクセス権限の境界を定義する", "監査ログの保持期間を延長する"], "a": 2, "e": "コレクションはデータ資産を階層的に整理し、その階層に基づいてアクセス権限の境界を定義するための仕組みです。", "qEn": "What role do 'collections' play in Microsoft Purview governance?", "oEn": ["Classifying device firmware versions", "Encrypting network segments", "Organizing data assets hierarchically and defining access permission boundaries", "Extending the audit log retention period"], "eEn": "Collections organize data assets into a hierarchy and define the boundaries of access permissions based on that hierarchy."}, {"d": "D4", "q": "「データスチュワード」ロールが主に担当する業務として正しいものはどれですか。", "o": ["デバイスのOSアップデートの展開", "ネットワークファイアウォールの監視　　　　", "ユーザーのライセンス発注", "データ品質の管理と用語集項目のメンテナンス"], "a": 3, "e": "データスチュワードはデータ品質の維持や、ビジネス用語集の項目管理などを主な業務とするロールです。", "qEn": "What tasks does the 'data steward' role primarily handle?", "oEn": ["Deploying operating system updates to devices", "Monitoring network firewalls", "Ordering user license procurement", "Managing data quality and maintaining business glossary terms"], "eEn": "A data steward primarily handles maintaining data quality and managing entries in the business glossary."}, {"d": "D4", "q": "Microsoft Purview アカウントの役割として正しいものはどれですか。", "o": ["データマップとカタログを管理するための中心的なリソース", "ユーザーのライセンス割り当てを行う課金アカウント　　　", "ネットワークのVPN接続を確立するリソース", "デバイスの資産管理台帳"], "a": 0, "e": "Microsoft Purview アカウントは、データマップやデータカタログなどのガバナンス機能を管理するための中心的なリソースです。", "qEn": "What is the role of a Microsoft Purview account?", "oEn": ["The central resource used to manage the Data Map and Data Catalog", "A billing account used to assign user licenses", "A resource used to establish network VPN connections", "A ledger for tracking device assets"], "eEn": "A Microsoft Purview account is the central resource used to manage governance capabilities such as the Data Map and Data Catalog."}, {"d": "D4", "q": "データガバナンスにおける「リネージ（Lineage）」が示すものは何ですか。", "o": ["ユーザーのサインイン履歴の一覧　　　　　　　　　　　　", "データがシステム間をどのように流れ、変換されるかの経路", "デバイスの保証期間の残り日数", "ネットワークの帯域使用率の推移"], "a": 1, "e": "リネージはデータがどのシステムを経由してどのように変換され、どこへ流れていくかという経路を可視化します。", "qEn": "What does 'lineage' represent in data governance?", "oEn": ["A list of a user's sign-in history", "The path showing how data flows and transforms across systems", "The number of days remaining on a device's warranty", "Trends in network bandwidth usage over time"], "eEn": "Lineage visualizes the path data takes as it flows through and is transformed across systems."}, {"d": "D4", "q": "Microsoft Purview の「データエステートインサイト」で確認できる情報として正しいものはどれですか。", "o": ["個々のユーザーのパスワード強度", "デバイスのバッテリー残量", "分類の網羅率などガバナンス状況を示すダッシュボード指標", "ネットワークのレイテンシー測定値　　　　　　　　　　　"], "a": 2, "e": "データエステートインサイトは分類の網羅率など、組織全体のデータガバナンス状況を示すダッシュボード指標を提供します。", "qEn": "What kind of information can you check in Microsoft Purview's data estate insights?", "oEn": ["The password strength of individual users", "A device's remaining battery level", "Dashboard metrics showing governance status, such as classification coverage", "Network latency measurements"], "eEn": "Data estate insights provide dashboard metrics reflecting the organization's overall data governance status, such as classification coverage."}];

