const TRIVIA_DATA = {
  "theoretical:phonetics": { trivia: "IPAが定める子音は100以上あるが、どの言語も実際に使うのはそのごく一部だけ。", triviaEn: "Over 100 consonants are catalogued in the IPA, yet any single language typically uses only a small fraction.", realWorld: "音声認識AI・語学教材の発音矯正・言語聴覚士の訓練などに応用されている。", realWorldEn: "Phonetics underlies speech-recognition AI, pronunciation-correction tools in language apps, and speech-language pathology training." },
  "theoretical:phonology": { trivia: "英語話者は無意識に[p]と有気音[pʰ]を使い分けているが、英語では同じ音素として扱われるため区別に気づかない。", triviaEn: "English speakers unconsciously alternate between [p] and aspirated [pʰ], yet English treats them as the same phoneme, so most never notice.", realWorld: "音声合成エンジンの自然な発音生成や、外国語学習者向けの発音矯正メソッド開発に活用されている。", realWorldEn: "Phonology informs how speech-synthesis engines generate natural pronunciation and how pronunciation training methods are designed." },
  "theoretical:morphology": { trivia: "トルコ語は1語に多数の接辞が付き、1単語が英語の文1つ分の意味を表すことがある。", triviaEn: "In Turkish, a single word can carry so many suffixes that it conveys the meaning of an entire English sentence.", realWorld: "形態素解析は日本語入力システム(かな漢字変換)や検索エンジンの語幹処理に不可欠な技術として使われている。", realWorldEn: "Morphological analysis is essential to Japanese kana-to-kanji conversion and to stemming in search engines." },
  "theoretical:syntax": { trivia: "統語論の基本道具である「木構造」は、プログラミング言語の構文解析(パーサー)にも同じ発想が使われている。", triviaEn: "The syntax tree, syntax's core analytical tool, uses the same basic idea as parse trees in programming-language analysis.", realWorld: "統語解析技術は文法チェッカー・機械翻訳・プログラミング言語のコンパイラ設計にまで応用されている。", realWorldEn: "Syntactic parsing techniques are applied in grammar checkers, machine translation, and compiler design." },
  "theoretical:semantics": { trivia: "「bank」という語は「銀行」と「土手」という無関係な意味を持つ同綴異義語の定番例。", triviaEn: "The word 'bank' is a classic example of homonymy, having two unrelated senses.", realWorld: "検索エンジンの意図理解や、AIチャットボットが文脈に応じた応答をする基盤技術に応用されている。", realWorldEn: "Semantic theory underlies how search engines infer intent and how chatbots generate contextual responses." },
  "theoretical:pragmatics": { trivia: "「塩取れる?」への返答は塩を渡すことであり、「はい」とだけ言うのは会話的含意に反すると受け取られる。", triviaEn: "If asked 'Can you pass the salt?', just saying 'yes' without passing it violates the expected implicature.", realWorld: "カスタマーサポートの応対マニュアル設計や、異文化間ビジネスコミュニケーション研修に活用されている。", realWorldEn: "Pragmatics informs customer-service response scripts and cross-cultural business communication training." },
  "historical:historical-ling": { trivia: "英語「knight」のkは昔は実際に発音されていたが、音韻変化で発音されなくなった名残り。", triviaEn: "The silent 'k' in 'knight' was once actually pronounced -- a fossil left by historical sound change.", realWorld: "絶滅危機言語の記録・復元プロジェクトや、語源辞典の編纂に活用されている。", realWorldEn: "Used in documentation projects for endangered languages and in compiling etymological dictionaries." },
  "historical:comparative-ling": { trivia: "英語father・独語Vater・羅語paterは同じ印欧祖語の単語に由来する同根語。", triviaEn: "English 'father,' German 'Vater,' and Latin 'pater' are cognates from the same Proto-Indo-European word.", realWorld: "消滅した古代言語の祖語復元や、DNA解析と組み合わせた人類の移住史研究にも応用される。", realWorldEn: "Used to reconstruct extinct proto-languages and, combined with DNA analysis, to study human migration." },
  "historical:typology": { trivia: "世界の言語の約45%はSOV語順(日本語と同じ)で、実はSVO語順より多いとされる。", triviaEn: "About 45% of the world's languages use SOV word order, actually more common than SVO.", realWorld: "機械翻訳システムが語順の異なる言語間を橋渡しする際のアルゴリズム設計に活用されている。", realWorldEn: "Informs how machine translation systems bridge languages with different word orders." },
  "social:sociolinguistics": { trivia: "同じ人物でも上司と話す時と友人と話す時で無意識に語彙や口調を切り替えるスタイル切り替えは誰もが行う現象。", triviaEn: "Style-shifting -- changing vocabulary and tone with a boss versus a friend -- is something everyone does.", realWorld: "企業のブランドボイス設計や、公共サービスの多言語対応方針の策定に活用されている。", realWorldEn: "Applied in designing corporate brand voice and shaping multilingual public-service policy." },
  "social:anthro-ling": { trivia: "イヌイット語に雪の語が多いとよく言われるが誇張であり、実際は他言語と大差ないという指摘もある。", triviaEn: "The claim that Inuit languages have dozens of words for snow is often exaggerated.", realWorld: "先住民コミュニティとの協働による言語文化継承プロジェクトに活用されている。", realWorldEn: "Used in collaborative language-and-culture revitalization projects with Indigenous communities." },
  "social:dialectology": { trivia: "「かたつむり」の呼び方は地域で「でんでんむし」「まいまい」等大きく異なり、方言周圏論の代表例。", triviaEn: "The Japanese word for 'snail' varies dramatically by region, a textbook example of dialect wave theory.", realWorld: "音声認識AIの地域アクセント対応や、自治体の方言継承・観光PR事業に活用されている。", realWorldEn: "Informs regional-accent handling in speech AI and local dialect-preservation/tourism projects." },
  "psycho:psycholinguistics": { trivia: "「馬が納屋を通り過ぎて走らされた」のようなガーデンパス文は、読み手が途中で解釈をやり直す実験によく使われる。", triviaEn: "Garden-path sentences force readers to mentally reparse mid-sentence, a classic experimental tool.", realWorld: "UI文言の読みやすさ設計や、失語症患者向けリハビリ教材の開発に活用されている。", realWorldEn: "Informs readable UI copy design and rehabilitation materials for aphasia patients." },
  "psycho:neurolinguistics": { trivia: "ブローカ野損傷は理解できても話しにくくなり、ウェルニッケ野損傷は流暢に話せても意味が通じなくなる対照的な症状。", triviaEn: "Broca's-area damage impairs speech while comprehension remains; Wernicke's-area damage allows fluent but nonsensical speech.", realWorld: "脳卒中後のリハビリ計画や、脳波を使った意思疎通支援デバイス(BCI)の開発に応用されている。", realWorldEn: "Informs post-stroke rehabilitation planning and brain-computer interface development." },
  "psycho:l1-acquisition": { trivia: "子どもは「goed」のように規則活用を不規則動詞に当てはめる時期を経て、正しい不規則形に戻っていく。", triviaEn: "Children overgeneralize regular patterns to irregular verbs (saying 'goed'), then later self-correct.", realWorld: "幼児教育カリキュラムの設計や、絵本・知育アプリの言語発達段階への配慮に活用されている。", realWorldEn: "Informs early-childhood curricula and age-appropriate design of picture books and educational apps." },
  "psycho:l2-acquisition": { trivia: "学習者は母語の影響を受けた「中間言語」という独自の体系を作り、単なる誤りの寄せ集めではないとされる。", triviaEn: "Learners build a systematic 'interlanguage' shaped by their native language -- not just random errors.", realWorld: "語学アプリのレベル別カリキュラム設計や、海外赴任者向け語学研修プログラムに活用されている。", realWorldEn: "Informs level-based language-app curricula and corporate language training for overseas assignees." },
  "computational:corpus": { trivia: "英国国民コーパス(BNC)は1億語規模だが、現代の大規模言語モデルは数兆語規模で学習され、その差は1万倍以上。", triviaEn: "The BNC has about 100 million words, while modern LLMs train on trillions -- over 10,000x more.", realWorld: "辞書編纂・教科書の語彙選定・著作権侵害の類似度判定など幅広い場面で使われている。", realWorldEn: "Used in dictionary compilation, textbook vocabulary selection, and copyright-dispute similarity assessment." },
  "computational:nlp": { trivia: "「時蝿は矢を好む」のような文は複数の統語解釈が可能な曖昧文として、NLPの構文解析の難しさを説明する定番例。", triviaEn: "Sentences like 'Time flies like an arrow' are classic examples of why parsing is hard for NLP.", realWorld: "検索エンジン・スマートスピーカー・メールの迷惑メールフィルタなど日常のあらゆる場面で使われている。", realWorldEn: "Powers search engines, smart speakers, and spam filters in everyday technology." },
  "computational:speech-processing": { trivia: "スマートスピーカーの音声認識は雑音・訛り・話速など無数の変動要因を扱う必要があり、実環境では精度が大きく変わる。", triviaEn: "Smart-speaker recognition must handle noise, accent, and rate -- accuracy differs greatly from lab conditions.", realWorld: "音声アシスタント・会議の自動文字起こし・声紋認証に応用されている。", realWorldEn: "Applied in voice assistants, automatic meeting transcription, and voiceprint authentication." },
  "computational:mt": { trivia: "初期の機械翻訳が「精神は強いが肉体は弱い」を「ウォッカは強いが肉は腐っている」と誤訳したという有名な逸話がある。", triviaEn: "A famous (semi-legendary) anecdote claims early MT mistranslated an idiom into something about vodka and rotten meat.", realWorld: "グローバル企業の多言語カスタマーサポートや、海外旅行者向けリアルタイム翻訳アプリに実装されている。", realWorldEn: "Deployed in multilingual customer support and real-time translation apps for travelers." },
  "computational:ir": { trivia: "検索エンジンのランキングは数百の要因を考慮しているとされ、単純な語の一致だけでなくページの信頼性も評価する。", triviaEn: "Search ranking reportedly weighs hundreds of factors beyond simple keyword matching, including page credibility.", realWorld: "Web検索エンジンだけでなく、社内文書検索や法律事務所の判例検索にも使われている。", realWorldEn: "Powers not only web search but internal enterprise search and legal case-law research tools." },
  "computational:llm": { trivia: "大規模言語モデルはパラメータ数が数千億に達するものもあり、学習には家庭数千軒分の電力に相当する資源が使われることがある。", triviaEn: "Some LLMs have hundreds of billions of parameters; training can use as much power as thousands of households.", realWorld: "コード生成支援・カスタマーサポートの自動応答・文書要約など業務効率化の場面で急速に導入されている。", realWorldEn: "Rapidly adopted for code-generation assistance, automated support, and document summarization." },
  "computational:knowledge-rep:ontology": { trivia: "医療分野のオントロジーSNOMED CTには35万以上の医学概念が定義され、電子カルテの標準用語として世界中で使われる。", triviaEn: "The medical ontology SNOMED CT defines over 350,000 concepts, used worldwide in electronic health records.", realWorld: "電子カルテの標準化・製造業の部品管理システム・企業内の知識ベース構築に活用されている。", realWorldEn: "Used to standardize health records, manage manufacturing parts catalogs, and build enterprise knowledge bases." },
  "computational:knowledge-rep:knowledge-graph": { trivia: "Googleの検索結果の「ナレッジパネル」は同社の知識グラフを基に自動生成されている。", triviaEn: "Google's knowledge-panel summary cards are auto-generated from its knowledge graph.", realWorld: "検索エンジンの要約表示だけでなく、レコメンドシステムや医薬品相互作用データベースにも使われている。", realWorldEn: "Powers not only search summaries but recommendation systems and drug-interaction databases." },
  "computational:knowledge-rep:rdf": { trivia: "RDFのトリプルは文の「主語-述語-目的語」構造を模しており、言語学の文法構造から着想を得ている。", triviaEn: "The RDF triple mirrors sentence subject-predicate-object structure, directly inspired by grammar.", realWorld: "図書館の蔵書目録の相互運用や、政府のオープンデータ公開基盤として実際に活用されている。", realWorldEn: "Used for interoperability among library catalogs and as a foundation for government open-data platforms." },
  "computational:knowledge-rep:owl": { trivia: "OWL(Web Ontology Language)は、あえて綴りをフクロウ(owl)と読めるようにして覚えやすくしたという逸話がある。", triviaEn: "OWL was deliberately spelled to read as the bird's name, making the acronym memorable.", realWorld: "製薬企業の化合物データベースや、政府機関の規制文書の整合性チェックに使われている。", realWorldEn: "Used in pharmaceutical compound databases and government regulatory-document consistency checks." },
  "computational:knowledge-rep:semantic-web": { trivia: "セマンティックWebはWeb発明者ティム・バーナーズ=リー自身が2001年の論文で提唱した「次のWeb」の構想。", triviaEn: "The Semantic Web vision was proposed by Web inventor Tim Berners-Lee in a 2001 paper.", realWorld: "レシピサイトのリッチスニペット表示や、ECサイトの商品情報の構造化に使われている。", realWorldEn: "Enables rich snippets on recipe sites and structures product data on e-commerce sites." },
  "computational:knowledge-rep:reasoning": { trivia: "推論エンジンは数百万ルールの知識ベースからでも、人間なら何日もかかる論理的帰結をミリ秒単位で導出できる。", triviaEn: "A reasoning engine can derive conclusions from millions of rules in milliseconds -- days of human work.", realWorld: "保険の契約条件の自動チェックや、法律文書の矛盾検出システムに応用されている。", realWorldEn: "Applied in automatically checking insurance conditions and detecting contradictions in legal documents." },
  "applied:language-education": { trivia: "CEFRのC2レベルはネイティブ並みとされるが、実際には多くのネイティブ話者もC2水準の学術文章に苦労する。", triviaEn: "CEFR's C2 is described as near-native, yet many native speakers struggle to write at that academic level.", realWorld: "語学学校のカリキュラム設計や、企業の多言語研修プログラムの効果測定に活用されている。", realWorldEn: "Informs language-school curricula and evaluation of corporate multilingual training." },
  "applied:translation": { trivia: "聖書は現在2000以上の言語に翻訳されており、世界で最も多くの言語に翻訳された書物とされる。", triviaEn: "The Bible has been translated into more than 2,000 languages, the most-translated book in the world.", realWorld: "特許文書の国際出願手続きや、ゲーム・映画のローカリゼーション品質管理に活用されている。", realWorldEn: "Informs international patent filing and localization quality control for games and films." },
  "applied:interpretation": { trivia: "同時通訳者の認知的負荷は非常に高く、国際会議では疲労防止のため通常15〜30分交代で担当する。", triviaEn: "Simultaneous interpreting is so cognitively demanding that interpreters typically rotate every 15-30 minutes.", realWorld: "国連や国際会議の同時通訳者養成、医療通訳者の認定制度に活用されている。", realWorldEn: "Informs interpreter training for the UN and international conferences, and medical interpreter certification." },
  "applied:lexicography": { trivia: "オックスフォード英語辞典(OED)の初版完成には約70年かかり、その間に編纂方針も大きく変化した。", triviaEn: "Completing the first OED edition took about 70 years, during which editorial policy changed substantially.", realWorld: "電子辞書アプリの語義配列設計や、AI翻訳ツールの訳語データベース構築に活用されている。", realWorldEn: "Informs word-sense ordering in dictionary apps and term databases in AI translation tools." },
  "applied:language-testing": { trivia: "TOEFLやIELTSは毎年数百万人が受験し、採点の一貫性を保つため採点者訓練に多大なコストがかけられている。", triviaEn: "TOEFL and IELTS are taken by millions annually; huge resources go into rater training for consistency.", realWorld: "大学入試・就労ビザの言語要件審査・企業の語学力評価制度の設計に活用されている。", realWorldEn: "Informs university admissions, visa language screening, and corporate proficiency assessment." },
  "applied:forensic-ling": { trivia: "著者推定の技術は、シェイクスピア作品の真の作者をめぐる論争など文学史上の謎の検証にも使われてきた。", triviaEn: "Authorship attribution has even been used to investigate debates over Shakespeare's true authorship.", realWorld: "脅迫状・詐欺メールの著者推定捜査や、商標の類似性をめぐる裁判での鑑定意見に使われている。", realWorldEn: "Used in investigating threatening letters/scam emails and as expert testimony in trademark lawsuits." },
  "applied:medical-business-ling": { trivia: "研究によれば医師の説明時間は平均わずか数十秒とされ、患者が話し始めてすぐ遮られる傾向が問題視されてきた。", triviaEn: "Studies show physicians often interrupt patients within mere seconds, a flagged communication problem.", realWorld: "インフォームド・コンセント文書の平易化や、企業のビジネスメール研修に活用されている。", realWorldEn: "Informs plain-language redesign of informed-consent documents and business-email training." },
  "interdisciplinary:philosophy-language": { trivia: "「宵の明星」と「明けの明星」は指す天体(金星)は同じでも、フレーゲはこれを「意義」の違いの例として有名にした。", triviaEn: "'Evening star' and 'morning star' refer to the same object, and Frege used this to illustrate sense vs. reference.", realWorld: "AIの言語理解の哲学的検討や、法律における文言解釈の理論的基盤に応用されている。", realWorldEn: "Applied in philosophical study of AI language understanding and in statutory-interpretation theory." },
  "interdisciplinary:cognitive-ling": { trivia: "「時間はお金だ」という概念メタファーのおかげで、「時間を節約する」のような表現を自然に使っている。", triviaEn: "Thanks to the metaphor 'time is money,' we naturally say things like 'save time.'", realWorld: "広告コピーのメタファー設計や、UXライティングにおける直感的な表現選びに活用されている。", realWorldEn: "Informs metaphor design in advertising and intuitive wording choices in UX writing." },
  "interdisciplinary:generative-grammar": { trivia: "チョムスキーの生成文法は言語学だけでなく、計算機科学の形式文法・プログラミング言語理論にも影響を与えた。", triviaEn: "Chomsky's generative grammar influenced formal grammar and programming-language theory in computer science.", realWorld: "プログラミング言語のパーサー設計や、文法的に正しい文を生成するテキスト生成システムに応用されている。", realWorldEn: "Applied in parser design and text-generation systems producing grammatically correct sentences." },
  "interdisciplinary:functional-ling": { trivia: "選択体系機能言語学(SFL)は言語教育にも広く応用され、オーストラリアの国語教育カリキュラムに大きな影響を与えている。", triviaEn: "SFL is widely applied in language education and has strongly influenced Australia's language-arts curriculum.", realWorld: "学術ライティング指導や、ジャンル別の文章作法教育プログラムの設計に活用されている。", realWorldEn: "Used in academic writing instruction and genre-specific writing curriculum design." },
  "interdisciplinary:discourse-analysis": { trivia: "「つまり」「ところで」のような一見小さな談話標識も、批判的談話分析では権力関係を読み解く手がかりとされる。", triviaEn: "Small discourse markers like 'in other words' are treated as clues to power relations in critical discourse analysis.", realWorld: "ニュース報道の偏向分析や、政治スピーチのレトリック研究に実際に使われている。", realWorldEn: "Used to analyze bias in news reporting and study the rhetoric of political speeches." },
  "interdisciplinary:conversation-analysis": { trivia: "会話分析では、依頼への「断り」の返答は「はい」より長く間や言い淀みを伴いやすいという規則性が繰り返し確認されている。", triviaEn: "CA research repeatedly confirms refusals tend to be longer and more hesitant than acceptances.", realWorld: "コールセンターの応対品質評価や、AIチャットボットの自然な相槌設計に活用されている。", realWorldEn: "Applied in call-center quality evaluation and designing natural backchanneling for chatbots." },
  "interdisciplinary:stylistics": { trivia: "文体統計分析によって、著者不明とされた文章の真の書き手が語彙頻度パターンから特定された例が複数報告されている。", triviaEn: "Stylometric analysis has repeatedly identified true authors of anonymous texts from word-frequency patterns.", realWorld: "盗作検出ソフトウェアや、SNS上のなりすまし投稿の識別技術に応用されている。", realWorldEn: "Applied in plagiarism-detection software and identifying impersonation posts on social media." },
  "interdisciplinary:semiotics": { trivia: "赤信号が「止まれ」を意味するのは自然な必然性ではなく社会的な取り決め(コード)にすぎない。", triviaEn: "A red light meaning 'stop' is not natural necessity but a social convention (a code).", realWorld: "企業ロゴ・パッケージデザインの意味作用分析や、広告のブランドイメージ戦略設計に活用されている。", realWorldEn: "Used to analyze corporate logo/packaging signification and shape brand strategy in advertising." },
};

